  // One-point sample helpers: pt selects the point, v carries its value.
  task automatic cz_ngen(input int unsigned pt, input logic [3:0] v);
    cz_ngen_t e;
    e = '0;
    case (pt)
      0: begin
        e.dm   = v[1:0];
        e.dm_v = 1'b1;
      end
      1: begin
        e.dl   = v;
        e.dl_v = 1'b1;
      end
      3: begin
        e.dv   = v[2:0];
        e.dv_v = 1'b1;
      end
      default: begin
        e.lp   = v[1:0];
        e.lp_v = 1'b1;
      end
    endcase
