      8'he1,
      8'hf8,
      8'h98,
      8'h11,
      8'h69,
      8'hd9,
      8'h8e,
      8'h94,
      8'h9b,
      8'h1e,
      8'h87,
      8'he9,
      8'hce,
      8'h55,
      8'h28,
      8'hdf,
      8'h8c,
      8'ha1,
      8'h89,
      8'h0d,
      8'hbf,
      8'he6,
      8'h42,
      8'h68,
      8'h41,
      8'h99,
      8'h2d,
      8'h0f,
      8'hb0,
      8'h54,
      8'hbb,
      8'h16
  };
  function automatic logic [7:0] cz_xtime(input logic [7:0] x);
    return {x[6:0], 1'b0} ^ (x[7] ? 8'h1b : 8'h00);
  endfunction
  // FIPS-197 AES-256 forward cipher of one block. Key and block are
  // big-endian: byte 0 is bits [255:248] of the key and [127:120] of the block.
  function automatic logic [127:0] cz_aes256(input logic [255:0] key, input logic [127:0] blk);
    logic [7:0] w[240];
    logic [7:0] s[16];
    logic [7:0] t[16];
    logic [7:0] rc;
    logic [127:0] out;
    rc = 8'h01;
    for (int i = 0; i < 32; i++) w[i] = key[255-8*i-:8];
    for (int i = 8; i < 60; i++) begin
      logic [7:0] tw[4];
      for (int b = 0; b < 4; b++) tw[b] = w[4*(i-1)+b];
      if ((i % 8) == 0) begin
        logic [7:0] r0;
        r0    = tw[0];
        tw[0] = CzAesSbox[tw[1]] ^ rc;
        tw[1] = CzAesSbox[tw[2]];
        tw[2] = CzAesSbox[tw[3]];
        tw[3] = CzAesSbox[r0];
        rc    = cz_xtime(rc);
      end else if ((i % 8) == 4) begin
        for (int b = 0; b < 4; b++) tw[b] = CzAesSbox[tw[b]];
      end
      for (int b = 0; b < 4; b++) w[4*i+b] = w[4*(i-8)+b] ^ tw[b];
    end
    for (int i = 0; i < 16; i++) s[i] = blk[127-8*i-:8] ^ w[i];
    for (int r = 1; r <= 14; r++) begin
      for (int i = 0; i < 16; i++) t[i] = CzAesSbox[s[i]];
      // ShiftRows: the byte of row q and column c is index q + 4c.
      for (int c = 0; c < 4; c++) begin
        for (int q = 0; q < 4; q++) s[q+4*c] = t[q+4*((c+q)%4)];
      end
      if (r != 14) begin
        for (int c = 0; c < 4; c++) begin
          logic [7:0] a0, a1, a2, a3;
          a0 = s[4*c];
          a1 = s[4*c+1];
          a2 = s[4*c+2];
          a3 = s[4*c+3];
          s[4*c]   = cz_xtime(a0) ^ cz_xtime(a1) ^ a1 ^ a2 ^ a3;
          s[4*c+1] = a0 ^ cz_xtime(a1) ^ cz_xtime(a2) ^ a2 ^ a3;
          s[4*c+2] = a0 ^ a1 ^ cz_xtime(a2) ^ cz_xtime(a3) ^ a3;
          s[4*c+3] = cz_xtime(a0) ^ a0 ^ a1 ^ a2 ^ cz_xtime(a3);
        end
      end
      for (int i = 0; i < 16; i++) s[i] = s[i] ^ w[16*r+i];
    end
    for (int i = 0; i < 16; i++) out[127-8*i-:8] = s[i];
    return out;
  endfunction
  // V increment of the CSRNG CTR_DRBG: only V[31:0] counts.
  function automatic logic [127:0] cz_v_inc(input logic [127:0] v);
    return {v[127:32], v[31:0] + 32'd1};
  endfunction
  // CTR_DRBG_Update of provided_data pd from key and v: returns {key, v}.
  function automatic logic [383:0] cz_drbg_update(input logic [383:0] pd, input logic [255:0] key,
                                                  input logic [127:0] v);
    logic [383:0] tmp;
    logic [127:0] vv;
    vv = v;
    for (int k = 0; k < 3; k++) begin
      vv = cz_v_inc(vv);
      tmp[383-128*k-:128] = cz_aes256(key, vv);
    end
    return tmp ^ pd;
  endfunction
  localparam logic [3:0] CzAcmdInsHdr = 4'h1;
  localparam logic [3:0] CzAcmdGenHdr = 4'h3;
  logic [1:0]   cz_kt_st = '0;   // 0 idle, 1 seed words, 2 instantiated, 3 block expected
  logic [3:0]   cz_kt_rem = '0;  // additional-data words of the last header
  logic [3:0]   cz_kt_n = '0;
  logic [383:0] cz_kt_seed = '0;
  logic [383:0] cz_kt_kv = '0;   // {key, v} after the instantiate
  logic [127:0] cz_kt_exp = '0;
  logic [2:0]   cz_kt_rd = '0;
  always @(posedge clk_i) begin
    if (cz_trng || !cy_ip[5]) begin
      cz_kt_st  <= 2'd0;
      cz_kt_rem <= '0;
    end else begin
      if (cy_t(csrng_reg2hw_i.cmd_req.qe) && !$isunknown(csrng_reg2hw_i.cmd_req.q)) begin
        logic [31:0] q;
        q = csrng_reg2hw_i.cmd_req.q;
        if (cz_kt_rem == 4'd0) begin
          cz_kt_rem <= q[7:4];
          if ((q[3:0] == CzAcmdInsHdr) && (q[7:4] == 4'd12) && (q[11:8] == CzMubiTrue)) begin
            cz_kt_st <= 2'd1;
            cz_kt_n  <= '0;
          end else if ((q[3:0] == CzAcmdGenHdr) && (q[7:4] == 4'd0) && (q[23:12] == 12'd1) &&
                       (cz_kt_st == 2'd2)) begin
            cz_kt_exp <= cz_aes256(cz_kt_kv[383:128], cz_v_inc(cz_kt_kv[127:0]));
            cz_kt_st  <= 2'd3;
            cz_kt_rd  <= '0;
          end else begin
            cz_kt_st <= 2'd0;
          end
        end else begin
          cz_kt_rem <= cz_kt_rem - 4'd1;
          if (cz_kt_st == 2'd1) begin
            logic [383:0] sd;
            sd = cz_kt_seed;
            sd[32*cz_kt_n+:32] = q;
            cz_kt_seed <= sd;
            cz_kt_n    <= cz_kt_n + 4'd1;
            if (cz_kt_n == 4'd11) begin
              cz_kt_kv <= cz_drbg_update(sd, 256'h0, 128'h0);
              cz_kt_st <= 2'd2;
            end
          end
        end
      end
      if ((cz_kt_st == 2'd3) && rd_ev && cy_rd_known && (ar_addr_q == CSRNG_GENBITS_REG_ADDR)) begin
        if (rd_data == cz_kt_exp[32*cz_kt_rd+:32]) begin
          if (cz_kt_rd == 3'd3) begin
            if (cy_own_dcmd) cz_ccmd(6, 3'd0);
            cz_kt_st <= 2'd0;
          end
          cz_kt_rd <= cz_kt_rd + 3'd1;
        end else begin
          cz_kt_st <= 2'd0;
        end
      end
    end
  end

  // ---------------------------------------------------------------------
  // sep_csrng_cmd_cg cp_inst_ack_vs_seed. An EDN SW_CMD_REQ write of an
  // instantiate header (acmd 1, clen 0) arms the cell. It samples at the rise
  // of the EDN CMD_ACK set request with CMD_STS 0 when, since the write,
  // CzIaHold clocks passed with no seed handshake and no acknowledge, and a
  // seed handshake (seed_valid and es_ack) came before the acknowledge.
  // ---------------------------------------------------------------------
  localparam int unsigned CzIaHold = 256;
  logic        cz_ia_arm = 1'b0;
  logic        cz_ia_hold = 1'b0;
  logic        cz_ia_seed = 1'b0;
  int unsigned cz_ia_cnt = 0;
  logic        cz_ia_ack_q = 1'b0;
  always @(posedge clk_i) begin
    logic ack_rise;
    logic hs;
    ack_rise = cz_ed_ack_set && !cz_ia_ack_q;
    cz_ia_ack_q <= cz_ed_ack_set;
    hs = (drbg_seed_valid_i === 1'b1) && (drbg_es_ack_i === 1'b1);
    if (cz_trng || !cy_ip[5] || !cy_own_dcmd) begin
      cz_ia_arm <= 1'b0;
    end else if (wr_ev && (aw_addr_q == EDN_SW_CMD_REQ_REG_ADDR)) begin
      cz_ia_arm  <= (wr_data[3:0] == 4'h1) && (wr_data[7:4] == 4'h0);
      cz_ia_hold <= 1'b0;
      cz_ia_seed <= 1'b0;
      cz_ia_cnt  <= 0;
    end else if (cz_ia_arm) begin
      if (hs) cz_ia_seed <= 1'b1;
      if (!cz_ia_seed && !hs) begin
        cz_ia_cnt <= cz_ia_cnt + 1;
        if ((cz_ia_cnt + 1) >= CzIaHold) cz_ia_hold <= 1'b1;
      end
      if (ack_rise) begin
        if (cz_ia_hold && cz_ia_seed && (edn_hw2reg_i.sw_cmd_sts.cmd_sts.d == 3'd0))
          cz_ccmd(7, 3'd0);
        cz_ia_arm <= 1'b0;
      end
    end
  end

  // ---------------------------------------------------------------------
  // sep_crypto_reg_lock_cg cp_esrc_locked_reg, cp_fips_lock_bit and
  // cp_min_entropy_h (ESRC_RDL, the fields whose text states "FIPS_LOCK.LOCK
  // prevents software changes"; FIPS_LOCK; MIN_ENTROPY_H, RECOMMENDED_THRESHOLDS).
  // A locked register class fills when the first OKAY read after a write
  // under the lock equals the last OKAY read before the lock and differs from
  // the written value (DEBUG_CTRL per field). The lock cells are pairs of
  // OKAY FIPS_LOCK reads around a write of 1 with the lock 0, a write of 0 or
  // a CTRL write with RSVD0 set under the lock, and rst_ni. The cutoff cell
  // samples an OKAY RECOMMENDED_THRESHOLDS read whose RCT_LIMIT equals
  // 1 + ceil(20 / H) with the stored H (Q4.4, H > 0; SP 800-90B 4.4.1).
  // ---------------------------------------------------------------------
  localparam logic [3:0] CzLkNone = 4'd15;
  function automatic logic [3:0] cz_lk_cls(input logic [31:0] a);
    case (a)
      ENTROPY_SOURCE_CTRL_REG_ADDR: return 4'd0;
      ENTROPY_SOURCE_FIFO_CTRL_REG_ADDR: return 4'd1;
      ENTROPY_SOURCE_HEALTH_TEST_CTRL_REG_ADDR: return 4'd2;
      ENTROPY_SOURCE_HEALTH_TEST_WINDOW_SIZE_REG_ADDR: return 4'd3;
      ENTROPY_SOURCE_MARKOV_TEST_PROB_THRESHOLDS_REG_ADDR,
      ENTROPY_SOURCE_APT_PROPORTION_1BIT_REG_ADDR,
      ENTROPY_SOURCE_APT_PROPORTION_LO_REG_ADDR: return 4'd4;
      ENTROPY_SOURCE_ALERT_THRESHOLD_REG_ADDR: return 4'd5;
      ENTROPY_SOURCE_DECORRELATOR_CTRL_REG_ADDR,
      ENTROPY_SOURCE_DECORRELATOR_MASK_REG_ADDR: return 4'd6;
      ENTROPY_SOURCE_RING_OSC_ENABLE_REG_ADDR: return 4'd7;
      ENTROPY_SOURCE_RING_OSC_TUNE_REG_ADDR: return 4'd8;
      ENTROPY_SOURCE_RING_OSC_CTRL_REG_ADDR: return 4'd9;
      ENTROPY_SOURCE_MIN_ENTROPY_H_REG_ADDR: return 4'd10;
      ENTROPY_SOURCE_DEBUG_CTRL_REG_ADDR: return 4'd11;
      default: begin
        if ((a >= ENTROPY_SOURCE_GENERATOR_0_SAMPLE_CLK_CONFIG_REG_ADDR) &&
            (a <= ENTROPY_SOURCE_GENERATOR_11_SAMPLE_CLK_CONFIG_REG_ADDR) && (a[1:0] == 2'b00)) begin
          return 4'd13;
        end
        return CzLkNone;
      end
    endcase
  endfunction
  localparam logic [31:0] CzDbgSelMask = 32'(ENTROPY_SOURCE_DEBUG_CTRL_SELECT_SIGNAL_MASK);
  localparam logic [31:0] CzDbgDivMask = 32'(ENTROPY_SOURCE_DEBUG_CTRL_SELECT_FREQ_DIV_MASK);
  localparam logic [31:0] CzFlMask = 32'(ENTROPY_SOURCE_FIPS_LOCK_LOCK_MASK);
  localparam logic [31:0] CzRsvdMask = 32'(ENTROPY_SOURCE_CTRL_RSVD0_MASK);
  localparam logic [31:0] CzRctMask = 32'(ENTROPY_SOURCE_RECOMMENDED_THRESHOLDS_RCT_LIMIT_MASK);
  logic [31:0] cz_lk_pre[logic [31:0]];
  logic [31:0] cz_lk_poke[logic [31:0]];
  logic        cz_fl_v = 1'b0;
  logic        cz_fl_rd = 1'b0;
  logic [1:0]  cz_fl_w = '0;     // 0 none, 1 write of 1 unlocked, 2 write of 0 locked, 3 reserved CTRL write locked
  logic        cz_fl_rst = 1'b0;
  logic        cz_in_reset_q2 = 1'b0;
  always @(posedge clk_i) begin
    cz_in_reset_q2 <= in_reset;
    if (in_reset && !cz_in_reset_q2) begin
      cz_lk_pre.delete();
      cz_lk_poke.delete();
      cz_fl_rst <= 1'b1;
    end
    if (!cz_own_fips) begin
      cz_lk_pre.delete();
      cz_lk_poke.delete();
      cz_fl_v   <= 1'b0;
      cz_fl_w   <= 2'd0;
      cz_fl_rst <= 1'b0;
    end else if (!in_reset) begin
      // Locked register classes.
      if (rd_ev && cy_rd_known && (cz_lk_cls(ar_addr_q) != CzLkNone)) begin
        logic [31:0] a;
        a = ar_addr_q;
        if (!cz_lock) begin
          cz_lk_pre[a] = rd_data;
        end else if (cz_lk_poke.exists(a) && cz_lk_pre.exists(a)) begin
          logic [31:0] pre;
          logic [31:0] pk;
          pre = cz_lk_pre[a];
          pk  = cz_lk_poke[a];
          if (cz_lk_cls(a) == 4'd11) begin
            if ((((rd_data ^ pre) & CzDbgSelMask) == 32'h0) && (((rd_data ^ pk) & CzDbgSelMask) != 32'h0))
              cz_lk(4, 4'd11);
            if ((((rd_data ^ pre) & CzDbgDivMask) == 32'h0) && (((rd_data ^ pk) & CzDbgDivMask) != 32'h0))
              cz_lk(4, 4'd12);
          end else if ((rd_data == pre) && (rd_data != pk)) begin
            cz_lk(4, cz_lk_cls(a));
          end
          cz_lk_poke.delete(a);
        end
      end
      if (wr_ev && cz_aw_lock && (cz_lk_cls(aw_addr_q) != CzLkNone))
        cz_lk_poke[aw_addr_q] = wr_data;
      // FIPS_LOCK.LOCK.
      if (wr_ev && (aw_addr_q == ENTROPY_SOURCE_FIPS_LOCK_REG_ADDR)) begin
        if (((wr_data & CzFlMask) != 32'h0) && !cz_aw_lock) cz_fl_w <= 2'd1;
        else if (((wr_data & CzFlMask) == 32'h0) && cz_aw_lock) cz_fl_w <= 2'd2;
      end
      if (wr_ev && (aw_addr_q == ENTROPY_SOURCE_CTRL_REG_ADDR) && cz_aw_lock &&
          ((wr_data & CzRsvdMask) != 32'h0)) begin
        cz_fl_w <= 2'd3;
      end
      if (rd_ev && cy_rd_known && (ar_addr_q == ENTROPY_SOURCE_FIPS_LOCK_REG_ADDR)) begin
        logic l;
        l = ((rd_data & CzFlMask) != 32'h0);
        if ((cz_fl_w == 2'd1) && l && !cz_fl_rst) cz_lk(5, 4'd0);
        if (cz_fl_v && cz_fl_rd && (cz_fl_w == 2'd2) && l && !cz_fl_rst) cz_lk(5, 4'd1);
        if (cz_fl_v && cz_fl_rd && (cz_fl_w == 2'd3) && l && !cz_fl_rst) cz_lk(5, 4'd2);
        if (cz_fl_v && cz_fl_rd && cz_fl_rst && !l && (cz_fl_w == 2'd0)) cz_lk(5, 4'd3);
        cz_fl_v   <= 1'b1;
        cz_fl_rd  <= l;
        cz_fl_w   <= 2'd0;
        cz_fl_rst <= 1'b0;
      end
      // RCT cutoff against the stored MIN_ENTROPY_H.
      if (rd_ev && cy_rd_known && (ar_addr_q == ENTROPY_SOURCE_RECOMMENDED_THRESHOLDS_REG_ADDR)) begin
        logic [7:0] h;
        logic [31:0] want;
        h = esrc_reg_out_i.MIN_ENTROPY_H.H.value;
        if (!$isunknown(h) && (h != 8'h00)) begin
          want = 32'd1 + ((32'd320 + 32'(h) - 32'd1) / 32'(h));
          if ((rd_data & CzRctMask) == want) begin
            cz_lk(6, (h < 8'h10) ? 4'd0 : ((h < 8'h80) ? 4'd1 : 4'd2));
          end
        end
      end
    end
  end

  // ---------------------------------------------------------------------
  // sep_esrc_startup_health_cg x_ht_arm, cp_ht_unsup and cp_ht_no_rearm
  // (ESRC_RDL HT_WATERMARK_NUM, HT_WATERMARK). The arm value of a selector is
  // 0x0000 for REPCNT_HI, APT_HI and MARKOV_HI and 0xFFFF for APT_LO and
  // MARKOV_LO; an unsupported value selects REPCNT_HI.
  // x_ht_arm: the first OKAY HT_WATERMARK read after a MODULE_ENABLE rise
  // equals the arm value of the stored selector, and the last read before
  // the rise held the other polarity. cp_ht_unsup: a write of a selector of
  // 5 or more, an OKAY HT_WATERMARK_NUM read of 0, then that arm with 0xFFFF
  // before and 0x0000 after. cp_ht_no_rearm: after a selector write whose arm
  // value differs from the last read watermark, the next OKAY HT_WATERMARK
  // read with no MODULE_ENABLE rise between equals that last read.
  // ---------------------------------------------------------------------
  localparam logic [31:0] CzWmMask = 32'(ENTROPY_SOURCE_HT_WATERMARK_WATERMARK_VALUE_MASK);
  localparam logic [31:0] CzWmNumMask = 32'(ENTROPY_SOURCE_HT_WATERMARK_NUM_WATERMARK_NUM_MASK);
  function automatic logic [15:0] cz_wm_arm(input logic [3:0] sel);
    return ((sel == 4'd2) || (sel == 4'd4)) ? 16'hFFFF : 16'h0000;
  endfunction
  logic [15:0] cz_wm_last = '0;
  logic        cz_wm_v = 1'b0;
  logic        cz_wa_arm = 1'b0;
  logic [3:0]  cz_wa_sel = '0;
  logic [15:0] cz_wa_pre = '0;
  logic        cz_wa_pre_v = 1'b0;
  logic        cz_hu_w = 1'b0;   // an unsupported selector write
  logic        cz_hu_rd = 1'b0;  // then a selector read of 0
  logic        cz_hn_arm = 1'b0;
  logic [15:0] cz_hn_pre = '0;
  always @(posedge clk_i) begin
    if (!cz_own_htarm || in_reset || cz_trng) begin
      cz_wm_v   <= 1'b0;
      cz_wa_arm <= 1'b0;
      cz_hu_w   <= 1'b0;
      cz_hu_rd  <= 1'b0;
      cz_hn_arm <= 1'b0;
    end else begin
      if (cz_men_rise) begin
        cz_wa_arm   <= 1'b1;
        cz_wa_sel   <= esrc_reg_out_i.HT_WATERMARK_NUM.WATERMARK_NUM.value;
        cz_wa_pre   <= cz_wm_last;
        cz_wa_pre_v <= cz_wm_v;
        cz_hn_arm   <= 1'b0;
      end
      if (wr_ev && (aw_addr_q == ENTROPY_SOURCE_HT_WATERMARK_NUM_REG_ADDR)) begin
        logic [3:0] sel;
        sel = 4'(wr_data & CzWmNumMask);
        cz_hu_w  <= (sel > 4'd4);
        cz_hu_rd <= 1'b0;
        cz_hn_arm <= cz_wm_v && (cz_wm_arm((sel > 4'd4) ? 4'd0 : sel) != cz_wm_last);
        cz_hn_pre <= cz_wm_last;
      end
      if (rd_ev && cy_rd_known && (ar_addr_q == ENTROPY_SOURCE_HT_WATERMARK_NUM_REG_ADDR) && cz_hu_w) begin
        cz_hu_rd <= ((rd_data & CzWmNumMask) == 32'h0);
      end
      if (rd_ev && cy_rd_known && (ar_addr_q == ENTROPY_SOURCE_HT_WATERMARK_REG_ADDR)) begin
        logic [15:0] w;
        w = 16'(rd_data & CzWmMask);
        if (cz_wa_arm && !cz_men_rise) begin
          if ((cz_wa_sel <= 4'd4) && cz_wa_pre_v && (w == cz_wm_arm(
                  cz_wa_sel
              )) && (cz_wa_pre != cz_wm_arm(
                  cz_wa_sel
              ))) begin
            cz_sth(12, cz_wa_sel);
          end
          if (cz_hu_rd && (cz_wa_sel == 4'd0) && cz_wa_pre_v && (cz_wa_pre == 16'hFFFF) &&
              (w == 16'h0000)) begin
            cz_sth(13, 4'd0);
          end
          cz_wa_arm <= 1'b0;
          cz_hu_w   <= 1'b0;
          cz_hu_rd  <= 1'b0;
        end
        if (cz_hn_arm && !cz_men_rise && !cz_wa_arm && (w == cz_hn_pre)) cz_sth(14, 4'd0);
        cz_hn_arm  <= 1'b0;
        cz_wm_last <= w;
        cz_wm_v    <= 1'b1;
      end
    end
  end

  // ---------------------------------------------------------------------
  // sep_esrc_startup_health_cg cp_component_id reset_value_read: an OKAY
  // read of COMPONENT_ID whose field bits equal the RDL reset value, owned by
  // the LSU alias-window twin test (CHK-TWIN grades the direct read against
  // the RDL reset).
  // ---------------------------------------------------------------------
  always @(posedge clk_i) begin
    if (own_twin && rd_ev && cy_rd_known && (ar_addr_q == ENTROPY_SOURCE_COMPONENT_ID_REG_ADDR) &&
        ((rd_data & CzCidMask) == (32'(ENTROPY_SOURCE_COMPONENT_ID_REG_DEFAULT) & CzCidMask))) begin
      cz_sth(0, 4'd1);
    end
  end

  // =====================================================================
  // eFuse, lifecycle, SEC_DIS and locked-field groups (docs/SEP_FCOV.adoc,
  // eFuse, lifecycle groups). Every point samples only while graded_owner
  // holds the code of a test that owns the point or the cell. Every point
  // that reads shadow-derived state samples with fuse_sense_done_i high,
  // except the SEC_DIS points the group rows name. The settle counts, windows
  // and timeouts below are choices of the environment; the specification
  // gives none.
  // =====================================================================
  wire ef_own_win = (graded_owner == FcovOwnSepEfuseWindowDecodeResetTest);
  wire ef_own_fld = (graded_owner == FcovOwnSepEfuseFieldLayoutRandTest);
  wire ef_own_cw = (graded_owner == FcovOwnSepLccStateCodewordRandTest);
  wire ef_own_fc = (graded_owner == FcovOwnSepLccFeatCtrlStateMatrixRandTest);
  wire ef_own_tr = (graded_owner == FcovOwnSepEfuseTransientRmaRandTest);
  wire ef_own_tch = (graded_owner == FcovOwnSepEfuseTokenChannelRandTest);
  wire ef_own_tf = (graded_owner == FcovOwnSepEfuseTokenFaultMatrixTest);
  wire ef_own_ifs = (graded_owner == FcovOwnSepEfuseInterfaceStatusRandTest);
  wire ef_own_lock = (graded_owner == FcovOwnSepEfuseLockSlotMatrixRandTest);
  wire ef_own_stm = (graded_owner == FcovOwnSepEfuseSecureTmMatrixRandTest);
  wire ef_own_jtag = (graded_owner == FcovOwnSepEfuseJtagAccessRandTest);
  wire ef_own_sdt = (graded_owner == FcovOwnSepSecDisTimingRandTest);
  wire ef_own_shim = (graded_owner == FcovOwnSepEfuseShimResponseFaultTest);

  localparam int unsigned EfFeatSettle = 8;  // feature-change inputs stable
  localparam int unsigned EfTokSettle = 8;  // token-change inputs stable (N)
  localparam int unsigned EfTransWin = 256;  // x_transient outcome window N
  localparam int unsigned EfWrSettle = 8;  // clocks from a write B to its effect
  localparam int unsigned EfRelWin = 4;  // SEC_DIS high this close to a release counts as held
  // Clocks from the B of a go before its idle or refusal outcome counts: a program
  // or read command that has not reached the shim by then is "none".
  localparam int unsigned EfReqWait = 64;
  localparam int unsigned EfBothWin = 1024;  // both_enables sample after the go
  localparam int unsigned EfProgN = 64;  // x_prog_lifecycle N
  localparam int unsigned EfLatchWin = 4096;  // digest replacement after release

  // Windows of 0x1093_0000 to 0x1093_FFFF (memory_map.adoc): shadow map,
  // interface control, its unused tail, token registers, the span between the
  // token registers and 0x1093_0600 (not declared), reserved.
  localparam logic [2:0] EfWShadow = 3'd0;
  localparam logic [2:0] EfWCtrlIn = 3'd1;
  localparam logic [2:0] EfWCtrlPast = 3'd2;
  localparam logic [2:0] EfWTokIn = 3'd3;
  localparam logic [2:0] EfWTokGap = 3'd4;
  localparam logic [2:0] EfWRsvd = 3'd5;
  localparam logic [2:0] EfWNone = 3'd7;
  localparam logic [31:0] EfMapBase = SEP_EFUSE_MAP_REG_MAP_BASE_ADDR;
  localparam logic [31:0] EfMapEnd = EfMapBase + SEP_EFUSE_MAP_REG_MAP_SIZE;
  localparam logic [31:0] EfCtrlBase = EFUSE_INTERFACE_CTRL_REG_MAP_BASE_ADDR;
  localparam logic [31:0] EfCtrlEnd = EfCtrlBase + EFUSE_INTERFACE_CTRL_REG_MAP_SIZE;
  localparam logic [31:0] EfMmrBase = EFUSE_MMR_REG_MAP_BASE_ADDR;
  localparam logic [31:0] EfMmrEnd = EfMmrBase + EFUSE_MMR_REG_MAP_SIZE;
  localparam logic [31:0] EfRsvdBase = EfMapBase + 32'h0000_0600;
  localparam logic [31:0] EfRsvdHigh = EfMapBase + 32'h0000_1000;
  localparam logic [31:0] EfWinEnd = EfMapBase + 32'h0001_0000;

  function automatic logic [2:0] ef_win(input logic [31:0] a);
    if (in_win(a, EfMapBase, EfMapEnd)) return EfWShadow;
    if (in_win(a, EfCtrlBase, EfCtrlEnd)) return EfWCtrlIn;
    if (in_win(a, EfCtrlEnd, EfMmrBase)) return EfWCtrlPast;
    if (in_win(a, EfMmrBase, EfMmrEnd)) return EfWTokIn;
    if (in_win(a, EfMmrEnd, EfRsvdBase)) return EfWTokGap;
    if (in_win(a, EfRsvdBase, EfWinEnd)) return EfWRsvd;
    return EfWNone;
  endfunction

  // Register addresses of the interface control and token blocks.
  localparam logic [31:0] EfStatus = EFUSE_INTERFACE_CTRL_EFUSE_INTERFACE_CTRL_STATUS_REG_ADDR;
  localparam logic [31:0] EfPgCtrl = EFUSE_INTERFACE_CTRL_EFUSE_PROGRAM_CTRL_REG_ADDR;
  localparam logic [31:0] EfRdCtrl = EFUSE_INTERFACE_CTRL_EFUSE_READ_CTRL_REG_ADDR;
  localparam logic [31:0] EfPgData = EFUSE_INTERFACE_CTRL_EFUSE_PROGRAM_INTERFACE_READ_DATA_REG_ADDR;
  localparam logic [31:0] EfRdData = EFUSE_INTERFACE_CTRL_EFUSE_READ_INTERFACE_READ_DATA_REG_ADDR;
  localparam logic [31:0] EfRdTmo = EFUSE_INTERFACE_CTRL_EFUSE_READ_REQ_TIMEOUT_REG_ADDR;
  localparam logic [31:0] EfPgTmo = EFUSE_INTERFACE_CTRL_EFUSE_PROGRAM_REQ_TIMEOUT_REG_ADDR;
  localparam logic [31:0] EfTokSip = EFUSE_MMR_RMA_SIP_TOKEN_I_0__REG_ADDR;
  localparam logic [31:0] EfTokChip = EFUSE_MMR_RMA_CHIPLET_TOKEN_I_0__REG_ADDR;
  localparam logic [31:0] EfTokSec = EFUSE_MMR_SEC_DISABLE_TOKEN_I_0__REG_ADDR;
  localparam logic [31:0] EfTokEop = EFUSE_MMR_TOKEN_EOP_REG_ADDR;
  localparam logic [31:0] EfMatchSip = EFUSE_MMR_RMA_SIP_TOKEN_MATCH_REG_ADDR;
  localparam logic [31:0] EfMatchChip = EFUSE_MMR_RMA_CHIPLET_TOKEN_MATCH_REG_ADDR;
  localparam logic [31:0] EfMatchSec = EFUSE_MMR_SEC_DISABLE_TOKEN_MATCH_REG_ADDR;
  localparam logic [31:0] EfMatchFault = EFUSE_MMR_TOKEN_MATCH_FAULT_REG_ADDR;
  localparam logic [31:0] EfDemote1 = SEP_LIFECYCLE_CTRL_DEMOTE_1_REG_ADDR;
  localparam logic [31:0] EfDemote2 = SEP_LIFECYCLE_CTRL_DEMOTE_2_REG_ADDR;

  // Field masks of the interface control registers (efuse_interface_ctrl.adoc).
  localparam logic [31:0] EfPgAddrMask = EFUSE_INTERFACE_CTRL_EFUSE_PROGRAM_CTRL_EFUSE_ADDR_MASK;
  localparam logic [31:0] EfPgDataMask = EFUSE_INTERFACE_CTRL_EFUSE_PROGRAM_CTRL_EFUSE_DATA_MASK;
  localparam logic [31:0] EfPgGoMask = EFUSE_INTERFACE_CTRL_EFUSE_PROGRAM_CTRL_EFUSE_PROGRAM_GO_MASK;
  localparam logic [31:0] EfPgEnMask = EFUSE_INTERFACE_CTRL_EFUSE_PROGRAM_CTRL_PROGRAM_ENABLE_MASK;
  localparam logic [31:0] EfRdAddrMask = EFUSE_INTERFACE_CTRL_EFUSE_READ_CTRL_EFUSE_ADDR_MASK;
  localparam logic [31:0] EfRdGoMask = EFUSE_INTERFACE_CTRL_EFUSE_READ_CTRL_EFUSE_READ_GO_MASK;
  localparam logic [31:0] EfRdEnMask = EFUSE_INTERFACE_CTRL_EFUSE_READ_CTRL_READ_ENABLE_MASK;
  localparam logic [31:0] EfReqErrMask =
      EFUSE_INTERFACE_CTRL_EFUSE_INTERFACE_CTRL_STATUS_EFUSE_REQ_ERROR_MASK;
  localparam logic [31:0] EfRdAddrClrMask =
      EFUSE_INTERFACE_CTRL_EFUSE_INTERFACE_CTRL_STATUS_EFUSE_READ_ADDR_ERROR_CLEAR_MASK;
  localparam logic [31:0] EfPgAddrClrMask =
      EFUSE_INTERFACE_CTRL_EFUSE_INTERFACE_CTRL_STATUS_EFUSE_PROGRAM_ADDR_ERROR_CLEAR_MASK;
  localparam logic [31:0] EfReqErrClrMask =
      EFUSE_INTERFACE_CTRL_EFUSE_INTERFACE_CTRL_STATUS_EFUSE_REQ_ERROR_CLEAR_MASK;
  localparam logic [31:0] EfPgTmoEnMask =
      EFUSE_INTERFACE_CTRL_EFUSE_PROGRAM_REQ_TIMEOUT_PROGRAM_REQ_TIMEOUT_ENABLE_MASK;
  localparam logic [31:0] EfDemoteMask = 32'(SEP_LIFECYCLE_CTRL_DEMOTE_DEMOTE_MASK);
  localparam logic [31:0] EfDemLockMask = 32'(SEP_LIFECYCLE_CTRL_DEMOTE_LOCK_MASK);
  // The fuse map is 8192 bits (otp_fuse_controller.adoc, Fuse Fields).
  localparam int unsigned EfFuseBits = sep_efuse_pkg::NumEfuseBits;

  // Shadow word index of each field: byte offset / 4 (sep_efuse_map.adoc).
  localparam int unsigned EfWLocks = SEP_EFUSE_MAP_LOCKS_REG_OFFSET / 4;
  localparam int unsigned EfWLocksSp = SEP_EFUSE_MAP_LOCKS_SPARE_REG_OFFSET / 4;
  localparam int unsigned EfWLc = SEP_EFUSE_MAP_LC_STATE_REG_OFFSET / 4;
  localparam int unsigned EfWSboot = SEP_EFUSE_MAP_SBOOT_DIS_REG_OFFSET / 4;
  localparam int unsigned EfWTrans = SEP_EFUSE_MAP_TRANSIENT_RMA_EN_REG_OFFSET / 4;
  localparam int unsigned EfWSipDis = SEP_EFUSE_MAP_SIP_DIS_REG_OFFSET / 4;
  localparam int unsigned EfWSysDis = SEP_EFUSE_MAP_SYS_DIS_REG_OFFSET / 4;
  localparam int unsigned EfWSipDig = SEP_EFUSE_MAP_RMA_SIP_TOKEN_DIGEST_REG_OFFSET / 4;
  localparam int unsigned EfWChipDig = SEP_EFUSE_MAP_RMA_CHIPLET_TOKEN_DIGEST_REG_OFFSET / 4;
  localparam int unsigned EfWRevoke = SEP_EFUSE_MAP_CHIPLET_PUBK_REVOKE_REG_OFFSET / 4;
  localparam int unsigned EfWBl1 = SEP_EFUSE_MAP_BL1_VERSION_REG_OFFSET / 4;
  localparam int unsigned EfWBl2 = SEP_EFUSE_MAP_BL2_VERSION_REG_OFFSET / 4;
  localparam int unsigned EfWStatusRpt = SEP_EFUSE_MAP_STATUS_RPT_REG_OFFSET / 4;
  localparam int unsigned EfWRomCtl = SEP_EFUSE_MAP_ROM_CTL_REG_OFFSET / 4;
  localparam int unsigned EfWSysclk = SEP_EFUSE_MAP_SYSCLK_FREQ_MHZ_REG_OFFSET / 4;
  localparam int unsigned EfWSigners = SEP_EFUSE_MAP_REQUIRED_SIGNERS_REG_OFFSET / 4;
  localparam int unsigned EfWAlgs = SEP_EFUSE_MAP_REQUIRED_ALGS_REG_OFFSET / 4;
  // CHIPLET_PUBK_REVOKE uses bits 25:0 (sep_efuse_map.adoc, CHIPLET_PUBK_REVOKE).
  localparam logic [31:0] EfRevokeAll = 32'h03FF_FFFF;

  // Lock slot n starts at EfSlotOff[n] and ends at EfSlotOff[n+1]
  // (sep_efuse_map.adoc, LOCKS and LOCKS_SPARE: slot 0 LC_STATE to slot 40
  // spare8, in RDL field order). The LOCKS words are not a slot.
  localparam int unsigned EfSlots = 41;
  localparam logic [10:0] EfSlotOff[42] = '{
      11'(SEP_EFUSE_MAP_LC_STATE_REG_OFFSET),
      11'(SEP_EFUSE_MAP_SBOOT_DIS_REG_OFFSET),
      11'(SEP_EFUSE_MAP_TRANSIENT_RMA_EN_REG_OFFSET),
      11'(SEP_EFUSE_MAP_SIP_DIS_REG_OFFSET),
      11'(SEP_EFUSE_MAP_SYS_DIS_REG_OFFSET),
      11'(SEP_EFUSE_MAP_RMA_SIP_TOKEN_DIGEST_REG_OFFSET),
      11'(SEP_EFUSE_MAP_RMA_CHIPLET_TOKEN_DIGEST_REG_OFFSET),
      11'(SEP_EFUSE_MAP_CLASS_KEY_REG_OFFSET),
      11'(SEP_EFUSE_MAP_CHIPLET_PUBK_REVOKE_REG_OFFSET),
      11'(SEP_EFUSE_MAP_BL1_VERSION_REG_OFFSET),
      11'(SEP_EFUSE_MAP_BL2_VERSION_REG_OFFSET),
      11'(SEP_EFUSE_MAP_CHIPLET_UID_REG_OFFSET),
      11'(SEP_EFUSE_MAP_SIP_PUBK_HASH0_REG_OFFSET),
      11'(SEP_EFUSE_MAP_SIP_UID_REG_OFFSET),
      11'(SEP_EFUSE_MAP_SYS_PUBK_HASH_REG_OFFSET),
      11'(SEP_EFUSE_MAP_SYS_UID_REG_OFFSET),
      11'(SEP_EFUSE_MAP_STATUS_RPT_REG_OFFSET),
      11'(SEP_EFUSE_MAP_ROM_CTL_REG_OFFSET),
      11'(SEP_EFUSE_MAP_SYSCLK_FREQ_MHZ_REG_OFFSET),
      11'(SEP_EFUSE_MAP_CHIPLET_PUBK_HASH0_REG_OFFSET),
      11'(SEP_EFUSE_MAP_CHIPLET_PUBK_HASH1_REG_OFFSET),
      11'(SEP_EFUSE_MAP_REQUIRED_SIGNERS_REG_OFFSET),
      11'(SEP_EFUSE_MAP_REQUIRED_ALGS_REG_OFFSET),
      11'(SEP_EFUSE_MAP_CHIPLET_PUBK_PQC_HASH0_REG_OFFSET),
      11'(SEP_EFUSE_MAP_CHIPLET_PUBK_PQC_HASH1_REG_OFFSET),
      11'(SEP_EFUSE_MAP_SIP_PUBK_PQC_HASH0_REG_OFFSET),
      11'(SEP_EFUSE_MAP_SYS_PUBK_PQC_HASH_REG_OFFSET),
      11'(SEP_EFUSE_MAP_SIP_PUBK_HASH1_REG_OFFSET),
      11'(SEP_EFUSE_MAP_SIP_PUBK_PQC_HASH1_REG_OFFSET),
      11'(SEP_EFUSE_MAP_SEP_CHIPLET_ID_REG_OFFSET),
      11'(SEP_EFUSE_MAP_SEP_SIP_ID_REG_OFFSET),
      11'(SEP_EFUSE_MAP_SEP_SYS_ID_REG_OFFSET),
      11'(SEP_EFUSE_MAP_SPARE0_REG_OFFSET),
      11'(SEP_EFUSE_MAP_SPARE1_REG_OFFSET),
      11'(SEP_EFUSE_MAP_SPARE2_REG_OFFSET),
      11'(SEP_EFUSE_MAP_SPARE3_REG_OFFSET),
      11'(SEP_EFUSE_MAP_SPARE4_REG_OFFSET),
      11'(SEP_EFUSE_MAP_SPARE5_REG_OFFSET),
      11'(SEP_EFUSE_MAP_SPARE6_REG_OFFSET),
      11'(SEP_EFUSE_MAP_SPARE7_REG_OFFSET),
      11'(SEP_EFUSE_MAP_SPARE8_REG_OFFSET),
      11'(SEP_EFUSE_MAP_REG_MAP_SIZE)
  };
  localparam logic [5:0] EfNoSlot = 6'd63;
  localparam logic [5:0] EfSlotSipDis = 6'd3;
  localparam logic [5:0] EfSlotSysDis = 6'd4;
  localparam logic [5:0] EfSlotClassKey = 6'd7;
  localparam logic [5:0] EfSlotChipUid = 6'd11;
  localparam logic [5:0] EfSlotSipUid = 6'd13;
  localparam logic [5:0] EfSlotSysUid = 6'd15;
  localparam logic [5:0] EfSlotSigners = 6'd21;
  localparam logic [5:0] EfSlotAlgs = 6'd22;
  localparam logic [5:0] EfSlotSpare0 = 6'd32;

  function automatic logic [5:0] ef_slot_of(input logic [10:0] off);
    for (int s = 0; s < EfSlots; s++) begin
      if ((off >= EfSlotOff[s]) && (off < EfSlotOff[s+1])) return 6'(s);
    end
    return EfNoSlot;
  endfunction

  // Secret fields of the secure test mode mask (test_mode.adoc, Protection
  // While Active): 0 CHIPLET_UID, 1 SIP_UID, 2 SYS_UID, 3 CLASS_KEY; 4 none.
  function automatic logic [2:0] ef_secret_of(input logic [5:0] s);
    case (s)
      EfSlotChipUid: return 3'd0;
      EfSlotSipUid: return 3'd1;
      EfSlotSysUid: return 3'd2;
      EfSlotClassKey: return 3'd3;
      default: return 3'd4;
    endcase
  endfunction

  // Lifecycle raw class (lifecycle_controller.adoc, Per-LC-state Feature
  // Control Profile): 0 TEST_DEV, 1 PROD, 2 PROD_END, 3 RMA_SIP, 4
  // RMA_CHIPLET, 5 INVALID.
  localparam logic [2:0] EfTd = 3'd0;
  localparam logic [2:0] EfProd = 3'd1;
  localparam logic [2:0] EfPe = 3'd2;
  localparam logic [2:0] EfRs = 3'd3;
  localparam logic [2:0] EfRc = 3'd4;
  localparam logic [2:0] EfInv = 3'd5;
  function automatic logic [2:0] ef_cls(input logic [3:0] raw);
    if (raw == 4'b0000) return EfTd;
    if (raw == 4'b0001) return EfProd;
    if (raw == 4'b1000) return EfPe;
    if (raw[3:1] == 3'b001) return EfRs;
    if (raw[3:1] == 3'b011) return EfRc;
    return EfInv;
  endfunction

  // Disable vector groups (lifecycle_controller.adoc, Disable Vector Format):
  // 0 DBG_1 [23:0], 1 DBG_2 [47:24], 2 Function [63:48].
  function automatic logic [23:0] ef_grp(input logic [63:0] v, input int unsigned g);
    case (g)
      0: return v[23:0];
      1: return v[47:24];
      default: return {8'h00, v[63:48]};
    endcase
  endfunction
  function automatic logic [23:0] ef_gmask(input int unsigned g);
    return (g == 2) ? 24'h00_FFFF : 24'hFF_FFFF;
  endfunction

  // Profile rows of the feature control table: TEST_DEV 00/10/01/11 then
  // SEC_DIS (0-4), PROD the same (5-9), PROD_END SEC_DIS 0/1 (10-11),
  // RMA_SIP (12-13), RMA_CHIPLET (14), INVALID (15-16). Demotion is
  // {DEMOTE_1, DEMOTE_2}.
  function automatic logic [4:0] ef_row(input logic [2:0] c, input logic sd, input logic [1:0] dm);
    case (c)
      EfTd: return sd ? 5'd4 : 5'(dm == 2'b00 ? 0 : dm == 2'b10 ? 1 : dm == 2'b01 ? 2 : 3);
      EfProd: return sd ? 5'd9 : 5'(dm == 2'b00 ? 5 : dm == 2'b10 ? 6 : dm == 2'b01 ? 7 : 8);
      EfPe: return sd ? 5'd11 : 5'd10;
      EfRs: return sd ? 5'd13 : 5'd12;
      EfRc: return 5'd14;
      default: return sd ? 5'd16 : 5'd15;
    endcase
  endfunction

  // Class of a group in a profile row, as the table gives it: 0 T (all ones),
  // 1 F (all zeros), 2 ~SIP_DIS, 3 ~(SIP_DIS | SYS_DIS).
  function automatic logic [2:0] ef_prof_cls(input logic [4:0] row, input int unsigned g);
    case (row)
      5'd0: return 3'd3;
      5'd1: return (g == 0) ? 3'd0 : 3'd3;
      5'd2: return (g == 1) ? 3'd0 : 3'd3;
      5'd3: return (g == 2) ? 3'd3 : 3'd0;
      5'd5, 5'd10: return (g == 2) ? 3'd3 : 3'd1;
      5'd6: return (g == 1) ? 3'd1 : 3'd3;
      5'd7: return (g == 0) ? 3'd1 : 3'd3;
      5'd8: return 3'd3;
      5'd12: return 3'd2;
      5'd15: return 3'd1;
      default: return 3'd0;  // SEC_DIS rows and RMA_CHIPLET
    endcase
  endfunction

  // Observed class of feature group g: 0 all ones, 1 all zeros, 2 ~SIP_DIS,
  // 3 ~(SIP_DIS | SYS_DIS), 4 other.
  function automatic logic [2:0] ef_obs_cls(input logic [63:0] f, input logic [63:0] sip,
                                            input logic [63:0] sys, input int unsigned g);
    logic [23:0] m, fv, sv, yv;
    m  = ef_gmask(g);
    fv = ef_grp(f, g);
    sv = ef_grp(sip, g);
    yv = ef_grp(sys, g);
    if (fv == m) return 3'd0;
    if (fv == 24'h0) return 3'd1;
    if (fv == (~sv & m)) return 3'd2;
    if (fv == (~(sv | yv) & m)) return 3'd3;
    return 3'd4;
  endfunction

  // OR of the SEC_DIS 0 profile rows of state class c over every demotion
  // (lifecycle_controller.adoc, Per-LC-state Feature Control Profile).
  function automatic logic [63:0] ef_gate_mask(input logic [2:0] c, input logic [63:0] sip,
                                               input logic [63:0] sys);
    logic [63:0] m;
    logic [4:0] row;
    logic [23:0] g;
    m = '0;
    for (int dm = 0; dm < 4; dm++) begin
      row = ef_row(c, 1'b0, 2'(dm));
      for (int gi = 0; gi < 3; gi++) begin
        case (ef_prof_cls(
            row, gi
        ))
          3'd0: g = ef_gmask(gi);
          3'd1: g = 24'h0;
          3'd2: g = ~ef_grp(sip, gi) & ef_gmask(gi);
          default: g = ~(ef_grp(sip, gi) | ef_grp(sys, gi)) & ef_gmask(gi);
        endcase
        case (gi)
          0: m[23:0] = m[23:0] | g;
          1: m[47:24] = m[47:24] | g;
          default: m[63:48] = m[63:48] | g[15:0];
        endcase
      end
    end
    return m;
  endfunction

  // Token status codes (token_processing.adoc, Token Matching Mechanism).
  localparam logic [5:0] EfCodeIdle = 6'h00;
  localparam logic [5:0] EfCodeMatch = 6'h15;
  localparam logic [5:0] EfCodeMismatch = 6'h2A;
  localparam logic [5:0] EfCodeErr = 6'h3F;

  // ---------------------------------------------------------------------
  // Covergroups. Each sample carries one point; the valid bit is set only
  // when the owner of the point or of the cell is in its window. A field
  // named bad is 1 when the observed outcome is not the outcome the cell
  // allows; those values are illegal_bins.
  // ---------------------------------------------------------------------
  typedef struct packed {
    logic [2:0] wn;
    logic wn_v;  // cp_window: window class
    logic rz;
    logic rz_v;  // cp_rsvd_zone: 0 low, 1 high
    logic [5:0] wr;
    logic wr_v;  // x_win_op_resp: {ignored, window, 0 rd / 1 wr, OKAY}
    logic [3:0] sf;
    logic sf_v;  // cp_shadow_field: register index
    logic [1:0] ea;
    logic ea_v;  // cp_edge_addr
    logic [3:0] cr;
    logic cr_v;  // x_ctrl_reg_op: register and op
    logic [3:0] tb;
    logic tb_v;  // x_token_blk_op: register and op
    logic ji;
    logic ji_v;  // cp_jtag_id_class: 1 nonzero
  } ef_geo_t;

  covergroup sep_efuse_map_geometry_cg with function sample (ef_geo_t s);
    option.per_instance = 1;
    option.name = "sep_efuse_map_geometry_cg";
    // The span between the token registers and 0x1093_0600 is not declared.
    cp_window: coverpoint s.wn iff (s.wn_v) {
      bins shadow = {EfWShadow};
      bins ctrl_in = {EfWCtrlIn};
      bins ctrl_past = {EfWCtrlPast};
      bins tok_in = {EfWTokIn};
      bins rsvd = {EfWRsvd};
    }
    cp_rsvd_zone: coverpoint s.rz iff (s.rz_v) {bins low = {1'b0}; bins high = {1'b1};}
    // Sampled with fuse_sense_done_i high, for the in-extent windows only.
    // The ignored accesses are those whose response no source states: a
    // shadow write, a read-locked shadow read, a STATUS write, a write to an
    // access-R register and a read of TOKEN_EOP.
    x_win_op_resp: coverpoint s.wr iff (s.wr_v) {
      bins shadow_rd_okay = {6'b0_000_0_1};
      bins ctrl_rd_okay = {6'b0_001_0_1};
      bins ctrl_wr_okay = {6'b0_001_1_1};
      bins tok_rd_okay = {6'b0_011_0_1};
      bins tok_wr_okay = {6'b0_011_1_1};
      illegal_bins in_extent_not_okay = {
        6'b0_000_0_0, 6'b0_001_0_0, 6'b0_001_1_0, 6'b0_011_0_0, 6'b0_011_1_0
      };
      ignore_bins response_not_stated = {[6'b1_000_0_0 : 6'b1_111_1_1]};
    }
    cp_shadow_field: coverpoint s.sf iff (s.sf_v) {
      bins lc_state = {4'd0};
      bins sboot_dis = {4'd1};
      bins transient_rma_en = {4'd2};
      bins chiplet_pubk_revoke = {4'd3};
      bins status_rpt = {4'd4};
      bins rom_ctl = {4'd5};
      bins sysclk_freq_mhz = {4'd6};
      bins required_signers = {4'd7};
      bins required_algs = {4'd8};
    }
    cp_edge_addr: coverpoint s.ea iff (s.ea_v) {
      bins last_shadow_word = {2'd0};
      bins last_ctrl_reg = {2'd1};
      bins first_past_extent = {2'd2};
      bins first_reserved = {2'd3};
    }
    // The write cells of the two timeout registers are not declared.
    x_ctrl_reg_op: coverpoint s.cr iff (s.cr_v) {
      bins status_rd = {4'd0};
      bins status_wr = {4'd1};
      bins program_ctrl_rd = {4'd2};
      bins program_ctrl_wr = {4'd3};
      bins read_ctrl_rd = {4'd4};
      bins read_ctrl_wr = {4'd5};
      bins read_req_timeout_rd = {4'd6};
      bins program_req_timeout_rd = {4'd7};
      bins program_if_read_data_rd = {4'd8};
      bins read_if_read_data_rd = {4'd9};
    }
    // The TOKEN_MATCH_FAULT read is not declared.
    x_token_blk_op: coverpoint s.tb iff (s.tb_v) {
      bins sip_token_rd = {4'd0};
      bins sip_token_wr = {4'd1};
      bins chiplet_token_rd = {4'd2};
      bins chiplet_token_wr = {4'd3};
      bins sec_dis_token_rd = {4'd4};
      bins sec_dis_token_wr = {4'd5};
      bins sip_match_rd = {4'd6};
      bins chiplet_match_rd = {4'd7};
      bins sec_dis_match_rd = {4'd8};
      bins token_eop_wr = {4'd9};
    }
    // The zero value is not declared.
    cp_jtag_id_class: coverpoint s.ji iff (s.ji_v) {
      bins nonzero = {1'b1};
    }
  endgroup

  typedef struct packed {
    logic sb;
    logic sb_v;  // cp_sboot_dis
    logic [1:0] rs;
    logic rs_v;  // cp_required_signers
    logic [3:0] al;
    logic al_v;  // x_algs_owner_value: owner * 4 + value
    logic [1:0] sr;
    logic sr_v;  // cp_status_rpt
    logic [3:0] rc;
    logic rc_v;  // cp_rom_ctl: {0, endianness} or {1, swap class}
    logic [1:0] sc;
    logic sc_v;  // cp_sysclk_class: 0 one, 1 middle, 2 max
    logic [1:0] rv;
    logic rv_v;  // cp_revoke_class
    logic [2:0] vb;
    logic vb_v;  // x_version_bit: field * 3 + index class
  } ef_fld_t;

  covergroup sep_efuse_field_value_cg with function sample (ef_fld_t s);
    option.per_instance = 1;
    option.name = "sep_efuse_field_value_cg";
    cp_sboot_dis: coverpoint s.sb iff (s.sb_v) {bins zero = {1'b0}; bins one = {1'b1};}
    cp_required_signers: coverpoint s.rs iff (s.rs_v) {bins value[] = {[2'd0 : 2'd3]};}
    // Owner chiplet [3:0], SiP [7:4], system [11:8] x bits 1:0 of the nibble.
    x_algs_owner_value: coverpoint s.al iff (s.al_v) {
      bins chiplet[] = {[4'd0 : 4'd3]};
      bins sip[] = {[4'd4 : 4'd7]};
      bins system[] = {[4'd8 : 4'd11]};
    }
    cp_status_rpt: coverpoint s.sr iff (s.sr_v) {bins value[] = {[2'd0 : 2'd3]};}
    // Swap class: 0 zero, 1 to 5 the single bit 1 to 5, 6 all five, 7 other.
    cp_rom_ctl: coverpoint s.rc iff (s.rc_v) {
      bins endian_0 = {4'b0_000};
      bins endian_1 = {4'b0_001};
      bins swap_zero = {4'b1_000};
      bins swap_single[] = {[4'b1_001 : 4'b1_101]};
      bins swap_all = {4'b1_110};
      bins swap_other = {4'b1_111};
    }
    // Value 0 is "ignored" and is not drawn, so it has no bin.
    cp_sysclk_class: coverpoint s.sc iff (s.sc_v) {
      bins one = {2'd0}; bins middle = {2'd1}; bins max = {2'd2};
    }
    cp_revoke_class: coverpoint s.rv iff (s.rv_v) {
      bins zero = {2'd0}; bins one_bit = {2'd1}; bins all_26 = {2'd2}; bins other = {2'd3};
    }
    // {BL1_VERSION, BL2_VERSION} x burned bit index {0, 1 to 254, 255}.
    x_version_bit: coverpoint s.vb iff (s.vb_v) {
      bins bl1[] = {[3'd0 : 3'd2]}; bins bl2[] = {[3'd3 : 3'd5]};
    }
  endgroup

  typedef struct packed {
    logic [2:0] sc;
    logic sc_v;  // cp_state_class
    logic [4:0] pr;
    logic pr_v;  // cp_profile_row
    logic [10:0] xr;
    logic xr_v;  // x_row_group_class: {bad, row, group, class}
    logic [2:0] oc;
    logic oc_v;  // cp_or_class: {group, mixed}
    logic rd;
    logic rd_v;  // cp_rma_dis_nonzero: 0 RMA_SIP, 1 RMA_CHIPLET
    logic pz;
    logic pz_v;  // cp_presense_feat: 1 FEAT_CTRL read is not 0
    logic [3:0] gb;
    logic gb_v;  // cp_gate_bound: {extra bit, state class}
  } ef_prof_t;

  covergroup sep_lc_feat_ctrl_profile_cg with function sample (ef_prof_t s);
    option.per_instance = 1;
    option.name = "sep_lc_feat_ctrl_profile_cg";
    cp_state_class: coverpoint s.sc iff (s.sc_v) {
      bins test_dev = {EfTd};
      bins prod = {EfProd};
      bins prod_end = {EfPe};
      bins rma_sip = {EfRs};
      bins rma_chiplet = {EfRc};
      bins invalid = {EfInv};
    }
    cp_profile_row: coverpoint s.pr iff (s.pr_v) {bins row[] = {[5'd0 : 5'd16]};}
    // 17 rows x 3 groups with the class of the table (51 cells). The class is
    // in bits 2:0 of the cell; bad is 1 when the observed class is another.
    x_row_group_class: coverpoint s.xr iff (s.xr_v) {
      bins r0[] = {11'h003, 11'h00B, 11'h013};
      bins r1[] = {11'h020, 11'h02B, 11'h033};
      bins r2[] = {11'h043, 11'h048, 11'h053};
      bins r3[] = {11'h060, 11'h068, 11'h073};
      bins r4[] = {11'h080, 11'h088, 11'h090};
      bins r5[] = {11'h0A1, 11'h0A9, 11'h0B3};
      bins r6[] = {11'h0C3, 11'h0C9, 11'h0D3};
      bins r7[] = {11'h0E1, 11'h0EB, 11'h0F3};
      bins r8[] = {11'h103, 11'h10B, 11'h113};
      bins r9[] = {11'h120, 11'h128, 11'h130};
      bins r10[] = {11'h141, 11'h149, 11'h153};
      bins r11[] = {11'h160, 11'h168, 11'h170};
      bins r12[] = {11'h182, 11'h18A, 11'h192};
      bins r13[] = {11'h1A0, 11'h1A8, 11'h1B0};
      bins r14[] = {11'h1C0, 11'h1C8, 11'h1D0};
      bins r15[] = {11'h1E1, 11'h1E9, 11'h1F1};
      bins r16[] = {11'h200, 11'h208, 11'h210};
      illegal_bins wrong_class = {[11'h400 : 11'h7FF]};
    }
    cp_or_class: coverpoint s.oc iff (s.oc_v) {
      bins dbg_1_zero = {3'b00_0};
      bins dbg_1_mixed = {3'b00_1};
      bins dbg_2_zero = {3'b01_0};
      bins dbg_2_mixed = {3'b01_1};
      bins function_zero = {3'b10_0};
      bins function_mixed = {3'b10_1};
    }
    cp_rma_dis_nonzero: coverpoint s.rd iff (s.rd_v) {
      bins rma_sip = {1'b0}; bins rma_chiplet = {1'b1};
    }
    // A FEAT_CTRL read that completes before sense done: the INVALID
    // profile, all zeros.
    cp_presense_feat: coverpoint s.pz iff (s.pz_v) {
      bins invalid_profile_zero = {1'b0}; illegal_bins nonzero = {1'b1};
    }
    // State class x a 64-bit FEAT_CTRL read with SEC_DIS 0 that sets no bit
    // outside the OR of the SEC_DIS 0 profile rows of the state (every
    // demotion). Sampled only when that OR is not all ones.
    cp_gate_bound: coverpoint s.gb iff (s.gb_v) {
      bins test_dev = {4'b0_000};
      bins prod = {4'b0_001};
      bins prod_end = {4'b0_010};
      bins rma_sip = {4'b0_011};
      bins rma_chiplet = {4'b0_100};
      illegal_bins extra_bit = {[4'b1_000 : 4'b1_111]};
    }
  endgroup

  typedef struct packed {
    logic [3:0] nb;
    logic nb_v;  // x_named_bit_value: {named bit, value}
    logic [4:0] cb;
    logic cb_v;  // x_closed_bit_owner: {bit index, 0 SIP_DIS / 1 SYS_DIS}
    logic [4:0] dg;
    logic dg_v;  // x_demote_group: {0 DEMOTE_1 / 1 DEMOTE_2, 0 TD / 1 PROD, groups}
  } ef_bit_t;

  covergroup sep_lc_feature_bit_semantics_cg with function sample (ef_bit_t s);
    option.per_instance = 1;
    option.name = "sep_lc_feature_bit_semantics_cg";
    // Named bit 0 SEP_DBG, 1 CHIPLET_DBG, 2 SEP_FUSE_DBG, 3 SMC_FUSE_DBG,
    // 4 SIP_DBG.
    x_named_bit_value: coverpoint s.nb iff (s.nb_v) {
      bins sep_dbg[] = {4'b000_0, 4'b000_1};
      bins chiplet_dbg[] = {4'b001_0, 4'b001_1};
      bins sep_fuse_dbg[] = {4'b010_0, 4'b010_1};
      bins smc_fuse_dbg[] = {4'b011_0, 4'b011_1};
      bins sip_dbg[] = {4'b100_0, 4'b100_1};
    }
    // Bit index k of {0, 1, 2, 3, 4, 23, 24, 25, 47, 48, 63} x owner.
    x_closed_bit_owner: coverpoint s.cb iff (s.cb_v) {
      bins cells[] = {[5'd0 : 5'd21]};
    }
    // DEMOTE_1 changes DBG_1 only and DEMOTE_2 changes DBG_2 only. Groups:
    // bit 0 DBG_1, bit 1 DBG_2, bit 2 Function.
    x_demote_group: coverpoint s.dg iff (s.dg_v) {
      bins demote_1_test_dev = {5'b0_0_001};
      bins demote_1_prod = {5'b0_1_001};
      bins demote_2_test_dev = {5'b1_0_010};
      bins demote_2_prod = {5'b1_1_010};
      wildcard illegal_bins demote_1_other_group = {5'b0_?_?1?, 5'b0_?_1??};
      wildcard illegal_bins demote_2_other_group = {5'b1_?_??1, 5'b1_?_1??};
    }
  endgroup

  typedef struct packed {
    logic [2:0] sp;
    logic sp_v;  // x_sep_port: {Case 3, SEP_FUSE_DBG, other than all-open}
    logic [2:0] mp;
    logic mp_v;  // x_smc_port: {Case 2, SMC_FUSE_DBG, other than all-open}
    logic [1:0] ns;
    logic ns_v;  // cp_nesting
    logic [5:0] pc;
    logic pc_v;  // x_path_case: {port differs from the case, path, open}
    logic [2:0] pd;
    logic pd_v;  // x_prod_demote_case3: {DEMOTE_1, DEMOTE_2, Case 3 open}
  } ef_dtp_t;

  covergroup sep_dtp_gating_ladder_cg with function sample (ef_dtp_t s);
    option.per_instance = 1;
    option.name = "sep_dtp_gating_ladder_cg";
    // The port is Case 3 AND SEP_FUSE_DBG: same as the all-open cell only
    // when both hold. No bin names the active level.
    x_sep_port: coverpoint s.sp iff (s.sp_v) {
      bins case3_fuse_same = {3'b11_0};
      bins case3_nofuse_other = {3'b10_1};
      bins nocase3_fuse_other = {3'b01_1};
      bins nocase3_nofuse_other = {3'b00_1};
      illegal_bins opposite = {3'b11_1, 3'b10_0, 3'b01_0, 3'b00_0};
    }
    x_smc_port: coverpoint s.mp iff (s.mp_v) {
      bins case2_fuse_same = {3'b11_0};
      bins case2_nofuse_other = {3'b10_1};
      bins nocase2_fuse_other = {3'b01_1};
      bins nocase2_nofuse_other = {3'b00_1};
      illegal_bins opposite = {3'b11_1, 3'b10_0, 3'b01_0, 3'b00_0};
    }
    // Case 3 implies Case 2 by definition, so no reverse value can occur.
    cp_nesting: coverpoint s.ns iff (s.ns_v) {
      bins case1_only = {2'd1}; bins case2_not_case3 = {2'd2}; bins case3 = {2'd3};
    }
    // dbg_disable path x open (dbg_disable 0) at each FEAT_CTRL read: path 0
    // stap_io, 1 stap_smc, 2 stap_sep, 3 stap_extra, 4 stap_host, 5
    // dft_secure, 6 dft_nonsecure, 7 dfd, 8 smc_jtag2axi follow Case 1, 2
    // or 3 of the DTP path table; 9 smc_otp_jtag2axi and 10
    // sep_otp_jtag2axi are ungated and open only. A port other than the
    // case of the FEAT_CTRL value read is illegal.
    x_path_case: coverpoint s.pc iff (s.pc_v) {
      bins closed[] = {6'b0_0000_0, 6'b0_0001_0, 6'b0_0010_0, 6'b0_0011_0, 6'b0_0100_0, 6'b0_0101_0, 6'b0_0110_0, 6'b0_0111_0, 6'b0_1000_0};
      bins open[] = {6'b0_0000_1, 6'b0_0001_1, 6'b0_0010_1, 6'b0_0011_1, 6'b0_0100_1, 6'b0_0101_1, 6'b0_0110_1, 6'b0_0111_1, 6'b0_1000_1, 6'b0_1001_1, 6'b0_1010_1};
      ignore_bins ungated_closed = {6'b0_1001_0, 6'b0_1010_0};
      illegal_bins port_differs = {[6'b1_0000_0 : 6'b1_1111_1]};
    }
    // PROD with SEC_DIS 0: {DEMOTE_1, DEMOTE_2} x Case 3 open. One demotion
    // leaves a Case 3 path closed.
    x_prod_demote_case3: coverpoint s.pd iff (s.pd_v) {
      bins d10_closed = {3'b10_0};
      bins d01_closed = {3'b01_0};
      bins d11_closed = {3'b11_0};
      bins d11_open = {3'b11_1};
      illegal_bins one_demotion_open = {3'b10_1, 3'b01_1};
    }
  endgroup

  typedef struct packed {
    logic [4:0] rs;
    logic rs_v;  // x_raw16_sigint: {lc_sigint_i, raw}
    logic [4:0] ss;
    logic ss_v;  // x_sigint_state_secdis_out: {bad, state * 2 + SEC_DIS}
  } ef_sig_t;

  covergroup sep_lc_sigint_failclosed_cg with function sample (ef_sig_t s);
    option.per_instance = 1;
    option.name = "sep_lc_sigint_failclosed_cg";
    x_raw16_sigint: coverpoint s.rs iff (s.rs_v) {
      bins raw[] = {[5'd0 : 5'd15]}; illegal_bins sigint_at_sense_done = {[5'd16 : 5'd31]};
    }
    // State TEST_DEV, PROD, PROD_END, RMA_SIP, RMA_CHIPLET x SEC_DIS: SEC_DIS
    // 0 gives all zeros, SEC_DIS 1 all ones. INVALID is not declared.
    x_sigint_state_secdis_out: coverpoint s.ss iff (s.ss_v) {
      bins cells[] = {[5'd0 : 5'd9]}; illegal_bins wrong_output = {[5'd16 : 5'd25]};
    }
  endgroup

  typedef struct packed {
    logic [5:0] tr;
    logic tr_v;  // x_transient: {bad, (enable * 2 + channel) * 5 + old class}
    logic [1:0] sm;
    logic sm_v;  // cp_simultaneous_match: {LC_STATE word changed, start PROD}
    logic rr;
    logic rr_v;  // cp_reset_restore: 1 the transient LC_STATE byte kept
  } ef_trn_t;

  covergroup sep_lc_illegal_transition_cg with function sample (ef_trn_t s);
    option.per_instance = 1;
    option.name = "sep_lc_illegal_transition_cg";
    // Old class 0 TEST_DEV, 1 PROD, 2 RMA_SIP, 3 RMA_CHIPLET, 4 INVALID;
    // channel 0 SIP, 1 CHIPLET. Updated is legal for enable 1 with SIP from
    // TEST_DEV or PROD and with CHIPLET from RMA_SIP; unchanged elsewhere.
    x_transient: coverpoint s.tr iff (s.tr_v) {
      bins cells[] = {[6'd0 : 6'd19]}; illegal_bins wrong_outcome = {[6'd32 : 6'd51]};
    }
    // A SIP match while a CHIPLET match is held, from TEST_DEV or PROD with
    // TRANSIENT_RMA_EN set: the chiplet path has priority and blocks the
    // transition, so the LC_STATE word does not change.
    cp_simultaneous_match: coverpoint s.sm iff (s.sm_v) {
      bins blocked_from_test_dev = {2'b0_0};
      bins blocked_from_prod = {2'b0_1};
      illegal_bins fell_through = {2'b1_0, 2'b1_1};
    }
    // A cold reset with the LC_STATE byte changed by a transient update:
    // the next sense loads the byte of the earlier sense.
    cp_reset_restore: coverpoint s.rr iff (s.rr_v) {
      bins sensed_word_restored = {1'b0}; illegal_bins transient_kept = {1'b1};
    }
  endgroup

  typedef struct packed {
    logic [7:0] sp;
    logic sp_v;  // x_slot_prog: {bad, (slot - 1) * 2 + write-lock}
    logic [7:0] sr;
    logic sr_v;  // x_slot_read: {bad, (slot - 1) * 2 + read-lock}
    logic [3:0] ko;
    logic ko_v;  // x_kind_op: {bad, kind * 2 + op}
    logic [1:0] nf;
    logic nf_v;  // x_neighbor_free: {0 previous / 1 next, 0 program / 1 read}
    logic [1:0] ex;
    logic ex_v;  // x_exempt: 0 LC_STATE, 1 LOCKS, 2 LOCKS_SPARE
    logic sl;
    logic sl_v;  // cp_sense_fills_locked: 0 secret, 1 other
    logic [3:0] sw;
    logic sw_v;  // x_shadow_write_lock: {bad, field * 2 + write-lock}
    logic [1:0] lo;
    logic lo_v;  // cp_lock_order
    logic pv;
    logic pv_v;  // cp_prog_visibility
    logic [2:0] rc;
    logic rc_v;  // cp_round_count
    logic [2:0] lp;
    logic lp_v;  // x_lc_prog_gate: {bit 2, other channel only, landed}
    logic [1:0] xw;
    logic xw_v;  // x_exempt_write
    logic [2:0] lf;
    logic lf_v;  // cp_locked_field_irq: {write, locked, pulse}
  } ef_lock_t;

  covergroup sep_efuse_lock_policy_cg with function sample (ef_lock_t s);
    option.per_instance = 1;
    option.name = "sep_efuse_lock_policy_cg";
    // Lock clear: the program lands; lock set: it is refused.
    x_slot_prog: coverpoint s.sp iff (s.sp_v) {
      bins cells[] = {[8'd0 : 8'd79]}; illegal_bins wrong_outcome = {[8'd128 : 8'd207]};
    }
    // Lock clear: the frontdoor read returns the sensed word; lock set: the
    // read-interface request sets efuse_req_error.
    x_slot_read: coverpoint s.sr iff (s.sr_v) {
      bins cells[] = {[8'd0 : 8'd79]}; illegal_bins wrong_outcome = {[8'd128 : 8'd207]};
    }
    // Kind 0 none, 1 write, 2 read, 3 write and read; op 0 program, 1 read.
    x_kind_op: coverpoint s.ko iff (s.ko_v) {
      bins cells[] = {[4'd0 : 4'd7]}; illegal_bins wrong_outcome = {[4'd8 : 4'd15]};
    }
    x_neighbor_free: coverpoint s.nf iff (s.nf_v) {
      bins previous_program = {2'b0_0};
      bins previous_read = {2'b0_1};
      bins next_program = {2'b1_0};
      bins next_read = {2'b1_1};
    }
    x_exempt: coverpoint s.ex iff (s.ex_v) {
      bins lc_state = {2'd0}; bins locks = {2'd1}; bins locks_spare = {2'd2};
    }
    cp_sense_fills_locked: coverpoint s.sl iff (s.sl_v) {
      bins secret_field = {1'b0}; bins other_field = {1'b1};
    }
    // Field 0 SIP_DIS, 1 SYS_DIS, 2 REQUIRED_SIGNERS, 3 REQUIRED_ALGS: lock
    // clear changes the shadow (OR), lock set leaves it unchanged.
    x_shadow_write_lock: coverpoint s.sw iff (s.sw_v) {
      bins cells[] = {[4'd0 : 4'd7]}; illegal_bins wrong_outcome = {[4'd8 : 4'd15]};
    }
    cp_lock_order: coverpoint s.lo iff (s.lo_v) {
      bins write_before_lock_lands = {2'd0};
      bins write_after_lock_blocked = {2'd1};
      bins zero_write_keeps_lock = {2'd2};
    }
    cp_prog_visibility: coverpoint s.pv iff (s.pv_v) {
      bins shadow_unchanged_after_program = {1'b0}; bins resense_shows_program = {1'b1};
    }
    cp_round_count: coverpoint s.rc iff (s.rc_v) {bins k[] = {[3'd1 : 3'd4]};}
    // (bit 2, other channel matched only) is not a bin.
    x_lc_prog_gate: coverpoint s.lp iff (s.lp_v) {
      bins bit1_own_landed = {3'b0_0_1};
      bins bit1_other_refused = {3'b0_1_0};
      bins bit2_own_landed = {3'b1_0_1};
      illegal_bins wrong_outcome = {3'b0_0_0, 3'b0_1_1, 3'b1_0_0};
    }
    // LC_STATE bit 0 or bit 3 programmed from TEST_DEV with every lock bit
    // burned: the program lands and the resensed LC_STATE reads PROD or
    // PROD_END. A refused program or another resensed value is illegal.
    x_exempt_write: coverpoint s.xw iff (s.xw_v) {
      bins bit0_prog_prod = {2'd0};
      bins bit3_prog_prod_end = {2'd1};
      illegal_bins refused = {2'd2};
      illegal_bins other_result = {2'd3};
    }
    // Frontdoor shadow-map access with secure_tm_o 0: {write, the write-lock
    // (write) or read-lock (read) of the slot, PIC source 34 pulsed between
    // the request handshake and the response}.
    cp_locked_field_irq: coverpoint s.lf iff (s.lf_v) {
      bins wlocked_write_pulse = {3'b1_1_1};
      bins rlocked_read_pulse = {3'b0_1_1};
      bins unlocked_write_no_pulse = {3'b1_0_0};
      bins unlocked_read_no_pulse = {3'b0_0_0};
      illegal_bins pulse_on_unlocked = {3'b1_0_1, 3'b0_0_1};
      illegal_bins no_pulse_on_locked = {3'b1_1_0, 3'b0_1_0};
    }
  endgroup

  typedef struct packed {
    logic [4:0] sc;
    logic sc_v;  // x_state_combo: state * 4 + {DEMOTE_1, DEMOTE_2}
    logic ao;
    logic ao_v;  // cp_assert_order: 0 DEMOTE_1 first, 1 DEMOTE_2 first
    logic [3:0] rv;
    logic rv_v;  // cp_reset_vector: {demote 1, lock 1, demote 2, lock 2}
    logic [4:0] oi;
    logic oi_v;  // x_otp_invariant: state * 4 + {DEMOTE_1, DEMOTE_2}
    logic [1:0] ec;
    logic ec_v;  // x_export_codeword: {register, non-complementary}
    logic ex;
    logic ex_v;  // cp_export_changes: register
  } ef_dem_t;

  covergroup sep_lc_demotion_cg with function sample (ef_dem_t s);
    option.per_instance = 1;
    option.name = "sep_lc_demotion_cg";
    x_state_combo: coverpoint s.sc iff (s.sc_v) {bins cells[] = {[5'd0 : 5'd23]};}
    cp_assert_order: coverpoint s.ao iff (s.ao_v) {
      bins demote_1_first = {1'b0}; bins demote_2_first = {1'b1};
    }
    // A reset of a clear state has nothing to clear.
    cp_reset_vector: coverpoint s.rv iff (s.rv_v) {
      bins vector[] = {[4'd1 : 4'd15]}; ignore_bins clear_state = {4'd0};
    }
    // A change to demotion 00 needs a cleared DEMOTE register. Only a reset
    // clears one, and the reset also ends the compare.
    x_otp_invariant: coverpoint s.oi iff (s.oi_v) {
      bins cells[] = {[5'd0 : 5'd23]};
      ignore_bins to_undemoted = {5'd0, 5'd4, 5'd8, 5'd12, 5'd16, 5'd20};
    }
    // No bin names a polarity.
    x_export_codeword: coverpoint s.ec iff (s.ec_v) {
      bins demote_1_complementary = {2'b0_0};
      bins demote_2_complementary = {2'b1_0};
      illegal_bins non_complementary = {2'b0_1, 2'b1_1};
    }
    cp_export_changes: coverpoint s.ex iff (s.ex_v) {
      bins demote_1 = {1'b0}; bins demote_2 = {1'b1};
    }
  endgroup

  typedef struct packed {
    logic [4:0] rl;
    logic rl_v;  // x_reg_lock_write: {register, old lock, write, changed}
    logic [3:0] cn;
    logic cn_v;  // x_committed_next: {register, demote, 0 set / 1 zero, changed}
    logic ci;
    logic ci_v;  // cp_independence: register written while the other is locked
    logic pu;
    logic pu_v;  // cp_profile_unchanged: register
  } ef_dlk_t;

  covergroup sep_lc_demote_lock_cg with function sample (ef_dlk_t s);
    option.per_instance = 1;
    option.name = "sep_lc_demote_lock_cg";
    // Write 0 set demote (0x1), 1 set lock (0x2), 2 zero. With lock 0, set
    // demote and set lock change and zero is unchanged; with lock 1 every
    // write is unchanged.
    x_reg_lock_write: coverpoint s.rl iff (s.rl_v) {
      bins r1_open_set_demote = {5'b0_0_00_1};
      bins r1_open_set_lock = {5'b0_0_01_1};
      bins r1_open_zero = {5'b0_0_10_0};
      bins r1_locked_set_demote = {5'b0_1_00_0};
      bins r1_locked_set_lock = {5'b0_1_01_0};
      bins r1_locked_zero = {5'b0_1_10_0};
      bins r2_open_set_demote = {5'b1_0_00_1};
      bins r2_open_set_lock = {5'b1_0_01_1};
      bins r2_open_zero = {5'b1_0_10_0};
      bins r2_locked_set_demote = {5'b1_1_00_0};
      bins r2_locked_set_lock = {5'b1_1_01_0};
      bins r2_locked_zero = {5'b1_1_10_0};
      wildcard illegal_bins change_while_locked = {5'b?_1_??_1};
    }
    x_committed_next: coverpoint s.cn iff (s.cn_v) {
      bins unchanged[] = {4'd0, 4'd2, 4'd4, 4'd6, 4'd8, 4'd10, 4'd12, 4'd14};
      illegal_bins changed = {4'd1, 4'd3, 4'd5, 4'd7, 4'd9, 4'd11, 4'd13, 4'd15};
    }
    cp_independence: coverpoint s.ci iff (s.ci_v) {
      bins r2_write_while_r1_locked = {1'b1}; bins r1_write_while_r2_locked = {1'b0};
    }
    cp_profile_unchanged: coverpoint s.pu iff (s.pu_v) {
      bins demote_1 = {1'b0}; bins demote_2 = {1'b1};
    }
  endgroup

  typedef struct packed {
    logic [2:0] cv;
    logic cv_v;  // x_ch_verdict: {channel, 0 Match / 1 Mismatch}
    logic [5:0] cd;
    logic cd_v;  // cp_code
    logic [4:0] cs;
    logic cs_v;  // x_ch_shape: {bad, channel * 3 + shape}
    logic [2:0] ph;
    logic ph_v;  // x_rma_go_phase: {channel, 0 before / 1 after sense done}
    logic [1:0] ci;
    logic ci_v;  // cp_independence: channel
    logic [1:0] hw;
    logic hw_v;  // cp_hold_word_write: channel
    logic [1:0] gi;
    logic gi_v;  // cp_go_idle_first: channel
    logic [1:0] rt;
    logic rt_v;  // cp_retention
    logic th;
    logic th_v;  // cp_token_hmac_overlap: 0 Match, 1 Mismatch
    logic [1:0] gw;
    logic gw_v;  // cp_go_while_busy: channel
  } ef_tch_t;

  covergroup sep_token_channel_cg with function sample (ef_tch_t s);
    option.per_instance = 1;
    option.name = "sep_token_channel_cg";
    // Channel 0 RMA_SIP, 1 RMA_CHIPLET, 2 SEC_DIS.
    x_ch_verdict: coverpoint s.cv iff (s.cv_v) {
      bins rma_sip[] = {3'b00_0, 3'b00_1};
      bins rma_chiplet[] = {3'b01_0, 3'b01_1};
      bins sec_dis[] = {3'b10_0, 3'b10_1};
    }
    cp_code: coverpoint s.cd iff (s.cd_v) {
      bins idle = {EfCodeIdle};
      bins match = {EfCodeMatch};
      bins mismatch = {EfCodeMismatch};
      bins error = {EfCodeErr};
      illegal_bins other = {[6'h01 : 6'h14], [6'h16 : 6'h29], [6'h2B : 6'h3E]};
    }
    // Shape 0 all zeros, 1 all ones, 2 the token words of another channel (the
    // words of a go on that channel that gave Match since the last reset, with
    // its array unchanged from the go to the result). The legal verdict is
    // Mismatch. (SEC_DIS, all zeros) is not declared.
    x_ch_shape: coverpoint s.cs iff (s.cs_v) {
      bins cells[] = {5'd0, 5'd1, 5'd2, 5'd3, 5'd4, 5'd5, 5'd7, 5'd8};
      illegal_bins match = {[5'd16 : 5'd24]};
    }
    x_rma_go_phase: coverpoint s.ph iff (s.ph_v) {
      bins sip_before_sense_idle = {3'b00_0};
      bins sip_after_sense_match = {3'b00_1};
      bins chiplet_before_sense_idle = {3'b01_0};
      bins chiplet_after_sense_match = {3'b01_1};
    }
    cp_independence: coverpoint s.ci iff (s.ci_v) {bins channel[] = {[2'd0 : 2'd2]};}
    cp_hold_word_write: coverpoint s.hw iff (s.hw_v) {bins channel[] = {[2'd0 : 2'd2]};}
    cp_go_idle_first: coverpoint s.gi iff (s.gi_v) {bins channel[] = {[2'd0 : 2'd2]};}
    cp_retention: coverpoint s.rt iff (s.rt_v) {
      bins words_kept = {2'd0}; bins idle_before_sense = {2'd1}; bins match_after_sense = {2'd2};
    }
    // A go with the HMAC engine busy (STATUS.hmac_idle 0): the verdict, with
    // HMAC still busy, and an HMAC done after the verdict.
    cp_token_hmac_overlap: coverpoint s.th iff (s.th_v) {
      bins match_hmac_busy = {1'b0}; bins mismatch_hmac_busy = {1'b1};
    }
    // A second go on a channel while its first go runs, with the token words
    // unchanged: the verdict comes at the time of the first go and is Match,
    // and the code holds Match to twice that time.
    cp_go_while_busy: coverpoint s.gw iff (s.gw_v) {
      bins channel[] = {[2'd0 : 2'd2]};
    }
  endgroup

  typedef struct packed {
    logic [4:0] kc;
    logic kc_v;  // x_ch_kind_copy: channel * 6 + kind * 3 + copy
    logic [1:0] cf;
    logic cf_v;  // x_ch_common_flip: {sticky rose, 0 Match->Mismatch / 1 back}
    logic [3:0] fe;
    logic fe_v;  // x_ch_forced_err: {channel, sticky, interrupt}
    logic [2:0] rt;
    logic rt_v;  // x_ch_retry
    logic [1:0] nc;
    logic nc_v;  // cp_no_clear: channel
    logic [1:0] rc;
    logic rc_v;  // cp_reset_clear: channel
    logic so;
    logic so_v;  // cp_secdis_off_under_fault
    logic [2:0] lf;
    logic lf_v;  // x_ch_latch_freeze: {0 RMA_CHIPLET / 1 SEC_DIS, released, bad}
    logic [2:0] il;
    logic il_v;  // cp_irq_line: {sticky channel, line differs from the OR}
  } ef_tf_t;

  covergroup sep_token_fault_cg with function sample (ef_tf_t s);
    option.per_instance = 1;
    option.name = "sep_token_fault_cg";
    // Kind 0 collapsed pair, 1 one copy dissents. The copy-0 collapsed cells
    // and the copy-0 RMA_SIP dissent cell are not declared.
    x_ch_kind_copy: coverpoint s.kc iff (s.kc_v) {
      bins rma_sip[] = {5'd1, 5'd2, 5'd4, 5'd5};
      bins rma_chiplet[] = {5'd7, 5'd8, 5'd9, 5'd10, 5'd11};
      bins sec_dis[] = {5'd13, 5'd14, 5'd15, 5'd16, 5'd17};
    }
    // RMA_CHIPLET only: a unanimous legal flip with no go raises no sticky bit.
    x_ch_common_flip: coverpoint s.cf iff (s.cf_v) {
      bins match_to_mismatch = {2'b0_0};
      bins mismatch_to_match = {2'b0_1};
      illegal_bins sticky_rose = {2'b1_0, 2'b1_1};
    }
    x_ch_forced_err: coverpoint s.fe iff (s.fe_v) {
      bins rma_sip = {4'b00_1_1};
      bins rma_chiplet = {4'b01_1_1};
      bins sec_dis = {4'b10_1_1};
      wildcard illegal_bins error_without_sticky = {4'b??_0_?};
    }
    // 0 RMA_SIP Match, 1 RMA_SIP Mismatch, 2 RMA_CHIPLET Match, 3 RMA_CHIPLET
    // Mismatch, 4 SEC_DIS Match. (SEC_DIS, Mismatch) is not declared.
    x_ch_retry: coverpoint s.rt iff (s.rt_v) {
      bins cells[] = {[3'd0 : 3'd4]};
    }
    cp_no_clear: coverpoint s.nc iff (s.nc_v) {bins channel[] = {[2'd0 : 2'd2]};}
    cp_reset_clear: coverpoint s.rc iff (s.rc_v) {bins channel[] = {[2'd0 : 2'd2]};}
    cp_secdis_off_under_fault: coverpoint s.so iff (s.so_v) {bins sec_dis_low = {1'b1};}
    // Under the freeze the sticky digest and valid bit keep their values;
    // after the release the digest is replaced. The RMA_SIP cells and the
    // result code under the freeze are not declared.
    x_ch_latch_freeze: coverpoint s.lf iff (s.lf_v) {
      bins chiplet_frozen_kept = {3'b0_0_0};
      bins chiplet_released_replaced = {3'b0_1_0};
      bins sec_dis_frozen_kept = {3'b1_0_0};
      bins sec_dis_released_replaced = {3'b1_1_0};
      illegal_bins changed_under_freeze = {3'b0_0_1, 3'b1_0_1};
    }
    // Single-channel sticky values 001, 010, 100. Multi-channel values are
    // not declared.
    cp_irq_line: coverpoint s.il iff (s.il_v) {
      bins sip_only = {3'b00_0};
      bins chiplet_only = {3'b01_0};
      bins sec_dis_only = {3'b10_0};
      illegal_bins line_differs = {3'b00_1, 3'b01_1, 3'b10_1};
    }
  endgroup

  typedef struct packed {
    logic [1:0] mp;
    logic mp_v;  // cp_match_phase: 0 before, 1 during, 2 after sense
    logic [2:0] vo;
    logic vo_v;  // x_verdict_out: {0 Match / 1 Mismatch / 2 Error, sec_dis_i}
    logic [4:0] df;
    logic df_v;  // x_state_demote_forced: {bad, cell}
  } ef_act_t;

  covergroup sep_sec_dis_activation_cg with function sample (ef_act_t s);
    option.per_instance = 1;
    option.name = "sep_sec_dis_activation_cg";
    cp_match_phase: coverpoint s.mp iff (s.mp_v) {
      bins before_sense = {2'd0}; bins during_sense = {2'd1}; bins after_sense = {2'd2};
    }
    x_verdict_out: coverpoint s.vo iff (s.vo_v) {
      bins match_on = {3'b00_1};
      bins mismatch_off = {3'b01_0};
      bins error_off = {3'b10_0};
      illegal_bins wrong_output = {3'b00_0, 3'b01_1, 3'b10_1};
    }
    // Cells 0-3 TEST_DEV x {00, 10, 01, 11}, 4-7 PROD x the same, 8
    // PROD_END, 9 RMA_SIP, 10 INVALID. The RMA_CHIPLET cell is not declared.
    x_state_demote_forced: coverpoint s.df iff (s.df_v) {
      bins cells[] = {[5'd0 : 5'd10]}; illegal_bins feat_not_all_ones = {[5'd16 : 5'd26]};
    }
  endgroup

  typedef struct packed {
    logic [2:0] dr;
    logic dr_v;  // x_digest_replay: {channel, Match}
    logic ss;
    logic ss_v;  // cp_stops_sense: 0 match during sense, 1 before sense
    logic [2:0] sf;
    logic sf_v;  // x_state_strap_feat: state * 2 + strap
    logic rv;
    logic rv_v;  // cp_reset_values_hold
    logic xs;
    logic xs_v;  // x_secdis_stm_feat: secure_tm_o
  } ef_rob_t;

  covergroup sep_sec_dis_robustness_cg with function sample (ef_rob_t s);
    option.per_instance = 1;
    option.name = "sep_sec_dis_robustness_cg";
    x_digest_replay: coverpoint s.dr iff (s.dr_v) {
      bins rma_sip_mismatch = {3'b00_0};
      bins rma_chiplet_mismatch = {3'b01_0};
      bins sec_dis_mismatch = {3'b10_0};
      illegal_bins match = {3'b00_1, 3'b01_1, 3'b10_1};
    }
    cp_stops_sense: coverpoint s.ss iff (s.ss_v) {
      bins match_during_sense = {1'b0}; bins match_before_sense = {1'b1};
    }
    // State 0 TEST_DEV, 1 PROD, 2 RMA_SIP.
    x_state_strap_feat: coverpoint s.sf iff (s.sf_v) {
      bins cells[] = {[3'd0 : 3'd5]};
    }
    // The LC_STATE word is excluded.
    cp_reset_values_hold: coverpoint s.rv iff (s.rv_v) {
      bins shadow_at_reset_values = {1'b1};
    }
    // secure_tm_o while SEC_DIS is asserted and the FEAT_CTRL probe is all
    // ones: SECURE_TM is not a term of feature control.
    x_secdis_stm_feat: coverpoint s.xs iff (s.xs_v) {
      bins secure_tm_0 = {1'b0}; bins secure_tm_1 = {1'b1};
    }
  endgroup

  typedef struct packed {
    logic [2:0] ca;
    logic ca_v;  // cp_case
    logic [3:0] fl;
    logic fl_v;  // cp_flags: {read_status, read_addr, program_addr, req}
    logic [6:0] cf;
    logic cf_v;  // x_case_flags: {case, flags}
    logic [2:0] cc;
    logic cc_v;  // x_case_cmd: {cell, forbidden command seen}
    logic [1:0] fc;
    logic fc_v;  // cp_flag_clear
    logic ss;
    logic ss_v;  // cp_sense_status_word
    logic [1:0] pl;
    logic pl_v;  // x_prog_lifecycle: {0 withheld / 1 released, bad}
    logic at;
    logic at_v;  // cp_accepted_twin: 0 read, 1 program
    logic sh;
    logic sh_v;  // cp_sense_shape
  } ef_ifs_t;

  covergroup sep_efuse_if_status_cg with function sample (ef_ifs_t s);
    option.per_instance = 1;
    option.name = "sep_efuse_if_status_cg";
    cp_case: coverpoint s.ca iff (s.ca_v) {
      bins pre_sense_prog = {3'd0};
      bins read_no_enable = {3'd1};
      bins read_oob = {3'd2};
      bins prog_oob = {3'd3};
      bins prog_wlocked = {3'd4};
      bins read_rlocked = {3'd5};
      bins both_enables = {3'd6};
      bins prog_data0 = {3'd7};
    }
    // Sampled for read_no_enable, read_oob, prog_oob, prog_wlocked and the
    // accepted twins.
    cp_flags: coverpoint s.fl iff (s.fl_v) {
      bins f0000 = {4'b0000};
      bins f1000 = {4'b1000};
      bins f1100 = {4'b1100};
      bins f0010 = {4'b0010};
      bins f0001 = {4'b0001};
      illegal_bins other = {4'b0011, [4'b0100 : 4'b0111], [4'b1001 : 4'b1011], [4'b1101 : 4'b1111]};
    }
    // read_rlocked grades req_error only. The RDL does not state the flags of
    // pre_sense_prog, both_enables and prog_data0.
    x_case_flags: coverpoint s.cf iff (s.cf_v) {
      bins read_no_enable_1000 = {7'b001_1000};
      bins read_oob_1100 = {7'b010_1100};
      bins prog_oob_0010 = {7'b011_0010};
      bins prog_wlocked_0001 = {7'b100_0001};
      wildcard bins read_rlocked_req = {7'b101_???1};
      illegal_bins wrong_flags = {
        [7'b001_0000 : 7'b001_0111], [7'b001_1001 : 7'b001_1111],
        [7'b010_0000 : 7'b010_1011], [7'b010_1101 : 7'b010_1111],
        [7'b011_0000 : 7'b011_0001], [7'b011_0011 : 7'b011_1111],
        7'b100_0000, [7'b100_0010 : 7'b100_1111]
      };
      wildcard illegal_bins read_rlocked_no_req = {7'b101_???0};
      ignore_bins flags_not_stated = {[7'b000_0000 : 7'b000_1111], [7'b110_0000 : 7'b111_1111]};
    }
    // Cell 0 pre_sense_prog with no program command, 1 read_rlocked and 2
    // both_enables with no read command.
    x_case_cmd: coverpoint s.cc iff (s.cc_v) {
      bins pre_sense_prog_no_program = {3'b00_0};
      bins read_rlocked_no_read = {3'b01_0};
      bins both_enables_no_read = {3'b10_0};
      illegal_bins forbidden_command = {3'b00_1, 3'b01_1, 3'b10_1};
    }
    cp_flag_clear: coverpoint s.fc iff (s.fc_v) {
      bins read_addr_error = {2'd0}; bins program_addr_error = {2'd1}; bins req_error = {2'd2};
    }
    // Words 0 to 9 and 255 are not declared.
    cp_sense_status_word: coverpoint s.ss iff (s.ss_v) {
      bins word_10_to_254 = {1'b1};
    }
    // The outcome with the program timeout enabled is not a bin.
    x_prog_lifecycle: coverpoint s.pl iff (s.pl_v) {
      bins withheld = {2'b0_0};
      bins released = {2'b1_0};
      illegal_bins wrong_status = {2'b0_1, 2'b1_1};
    }
    cp_accepted_twin: coverpoint s.at iff (s.at_v) {
      bins valid_read = {1'b0}; bins landed_program = {1'b1};
    }
    // The sense from the reset release to the sense-done rise: exactly one
    // READ command on the post-guard shim port (0), and the sense-done rise
    // at least one clock after the response strobe of the last word (1).
    cp_sense_shape: coverpoint s.sh iff (s.sh_v) {
      bins one_read_cmd = {1'b0}; bins done_after_last_strobe = {1'b1};
    }
  endgroup

  typedef struct packed {
    logic [4:0] pb;
    logic pb_v;  // x_prog_block: {bad, class * 2 + strap}
    logic [2:0] sp;
    logic sp_v;  // x_secret_probe: {field, nonzero}
    logic [1:0] sk;
    logic sk_v;  // x_secret_read_kept: field
  } ef_stm_t;

  covergroup sep_efuse_secure_tm_cg with function sample (ef_stm_t s);
    option.per_instance = 1;
    option.name = "sep_efuse_secure_tm_cg";
    // Class 0 256-bit field, 1 32-bit field, 2 DIS bit, 3 LOCKS bit, 4 spare
    // word. Strap 0: the command reaches the shim; strap 1: none.
    x_prog_block: coverpoint s.pb iff (s.pb_v) {
      bins cells[] = {[5'd0 : 5'd9]}; illegal_bins wrong_outcome = {[5'd16 : 5'd25]};
    }
    // Field 0 CHIPLET_UID, 1 SIP_UID, 2 SYS_UID, 3 CLASS_KEY, at strap 1.
    x_secret_probe: coverpoint s.sp iff (s.sp_v) {
      bins chiplet_uid_zero = {3'b00_0};
      bins sip_uid_zero = {3'b01_0};
      bins sys_uid_zero = {3'b10_0};
      bins class_key_zero = {3'b11_0};
      illegal_bins nonzero = {3'b00_1, 3'b01_1, 3'b10_1, 3'b11_1};
    }
    x_secret_read_kept: coverpoint s.sk iff (s.sk_v) {
      bins chiplet_uid = {2'd0};
      bins sip_uid = {2'd1};
      bins sys_uid = {2'd2};
      bins class_key = {2'd3};
    }
  endgroup

  typedef struct packed {
    logic [2:0] st;
    logic st_v;  // cp_state: 0 PROD, 1 RMA_SIP, 2 integrity error, 3 PROD_END, 4 RMA_CHIPLET
    logic [2:0] cl;
    logic cl_v;  // cp_class
    logic rp;
    logic rp_v;  // cp_resp: 0 OKAY, 1 not OKAY
    logic [5:0] so;
    logic so_v;  // x_state_class_op: {bad, state * 8 + class-op}
    logic gi;
    logic gi_v;  // cp_gate_independent_of_feat: 0 PROD, 1 RMA_SIP
    logic [1:0] jr;
    logic jr_v;  // x_jtag_rlock
    logic [1:0] jp;
    logic jp_v;  // x_jtag_presense
  } ef_jtg_t;

  covergroup sep_efuse_jtag_policy_cg with function sample (ef_jtg_t s);
    option.per_instance = 1;
    option.name = "sep_efuse_jtag_policy_cg";
    cp_state: coverpoint s.st iff (s.st_v) {
      bins prod = {3'd0};
      bins rma_sip = {3'd1};
      bins integrity_error = {3'd2};
      bins prod_end = {3'd3};
      bins rma_chiplet = {3'd4};
    }
    // TOKEN_MATCH_FAULT is not declared.
    cp_class: coverpoint s.cl iff (s.cl_v) {
      bins shadow_word = {3'd0};
      bins ctrl_reg = {3'd1};
      bins token_word = {3'd2};
      bins token_eop = {3'd3};
      bins match_reg = {3'd4};
    }
    cp_resp: coverpoint s.rp iff (s.rp_v) {bins okay = {1'b0}; bins not_okay = {1'b1};}
    // Class-op 0 token word read, 1 token word write, 2 TOKEN_EOP write,
    // 3 match read (allowed, OKAY); 4 shadow read, 5 shadow write, 6 control
    // read, 7 control write (denied, not OKAY). (PROD, token word read) and
    // (PROD, token word write) are ignored.
    x_state_class_op: coverpoint s.so iff (s.so_v) {
      bins cells[] = {[6'd2 : 6'd23]};
      ignore_bins prod_token_word = {6'd0, 6'd1, 6'd32, 6'd33};
      illegal_bins wrong_response = {[6'd34 : 6'd55]};
    }
    cp_gate_independent_of_feat: coverpoint s.gi iff (s.gi_v) {
      bins prod = {1'b0}; bins rma_sip = {1'b1};
    }
    // TEST_DEV JTAG read of a shadow word with a non-zero staged value: a
    // read-locked word does not return the staged value (0); its unlocked
    // twin returns OKAY and the staged value (1). A read-locked word that
    // returns the staged value is illegal (2).
    x_jtag_rlock: coverpoint s.jr iff (s.jr_v) {
      bins locked_data_differs = {2'd0};
      bins twin_okay_equal = {2'd1};
      illegal_bins locked_data_equal = {2'd2};
    }
    // JTAG access from the reset release to the sense-done rise: a shadow-map
    // read is not OKAY (0); a program go sends no PROGRAM command before the
    // rise (1). An OKAY map read (2) or a command (3) is illegal.
    x_jtag_presense: coverpoint s.jp iff (s.jp_v) {
      bins map_rd_refused = {2'd0};
      bins prog_no_command = {2'd1};
      illegal_bins map_rd_okay = {2'd2};
      illegal_bins prog_command = {2'd3};
    }
  endgroup

  sep_efuse_map_geometry_cg       u_sep_efuse_map_geometry_cg       = new();
  sep_efuse_field_value_cg        u_sep_efuse_field_value_cg        = new();
  sep_lc_feat_ctrl_profile_cg     u_sep_lc_feat_ctrl_profile_cg     = new();
  sep_lc_feature_bit_semantics_cg u_sep_lc_feature_bit_semantics_cg = new();
  sep_dtp_gating_ladder_cg        u_sep_dtp_gating_ladder_cg        = new();
  sep_lc_sigint_failclosed_cg     u_sep_lc_sigint_failclosed_cg     = new();
  sep_lc_illegal_transition_cg    u_sep_lc_illegal_transition_cg    = new();
  sep_efuse_lock_policy_cg        u_sep_efuse_lock_policy_cg        = new();
  sep_lc_demotion_cg              u_sep_lc_demotion_cg              = new();
  sep_lc_demote_lock_cg           u_sep_lc_demote_lock_cg           = new();
  sep_token_channel_cg            u_sep_token_channel_cg            = new();
  sep_token_fault_cg              u_sep_token_fault_cg              = new();
  sep_sec_dis_activation_cg       u_sep_sec_dis_activation_cg       = new();
  sep_sec_dis_robustness_cg       u_sep_sec_dis_robustness_cg       = new();
  sep_efuse_if_status_cg          u_sep_efuse_if_status_cg          = new();
  sep_efuse_secure_tm_cg          u_sep_efuse_secure_tm_cg          = new();
  sep_efuse_jtag_policy_cg        u_sep_efuse_jtag_policy_cg        = new();

  // ---------------------------------------------------------------------
  // Common levels, decodes and snapshots.
  // ---------------------------------------------------------------------
  wire ef_live = !in_reset && !skip_fuse_sense_q;
  wire ef_sensed = ef_live && (fuse_sense_done_i === 1'b1);
  wire ef_sd = (sec_dis_i === 1'b1);
  wire ef_sig = (lc_sigint_i === 1'b1);
  wire [2:0] ef_lc = ef_cls(efuse_lc_raw_i);
  wire ef_d1 = (demote_1_i == 2'b01);
  wire ef_d2 = (demote_2_i == 2'b01);
  wire [1:0] ef_dm = {ef_d1, ef_d2};
  wire [63:0] ef_locks = efuse_shadow_i[32*EfWLocks+:64];
  wire [31:0] ef_locks_sp = efuse_shadow_i[32*EfWLocksSp+:32];
  wire [31:0] ef_lc_word = efuse_shadow_i[32*EfWLc+:32];
  wire [63:0] ef_sip_dis = efuse_shadow_i[32*EfWSipDis+:64];
  wire [63:0] ef_sys_dis = efuse_shadow_i[32*EfWSysDis+:64];
  wire ef_trans_en = efuse_shadow_i[32*EfWTrans];
  // Assigned lock bits: LOCKS [63:0] and LOCKS_SPARE [17:0] (sep_efuse_map.adoc).
  wire ef_all_locked = (ef_locks == '1) && (ef_locks_sp[17:0] == '1);

  function automatic logic ef_wlock(input logic [5:0] s);
    if (s < 6'd32) return ef_locks[2*s];
    if (s < 6'(EfSlots)) return ef_locks_sp[2*(s-6'd32)];
    return 1'b0;
  endfunction
  function automatic logic ef_rlock(input logic [5:0] s);
    if (s < 6'd32) return ef_locks[2*s+1];
    if (s < 6'(EfSlots)) return ef_locks_sp[2*(s-6'd32)+1];
    return 1'b0;
  endfunction
  function automatic logic [31:0] ef_word(input logic [9:0] byte_off);
    return efuse_shadow_i[32*byte_off[9:2]+:32];
  endfunction
  function automatic logic ef_field_nz(input logic [5:0] s);
    for (int w = int'(EfSlotOff[s][10:2]); w < int'(EfSlotOff[s+1][10:2]); w++) begin
      if (efuse_shadow_i[32*w+:32] != 32'h0) return 1'b1;
    end
    return 1'b0;
  endfunction

  // Post-guard shim command (READ 2'b00, PROGRAM 2'b01, PROGRAM_READ_BACK
  // 2'b10, interface.adoc Fuse Command Protocol) and response.
  wire ef_cmd_v = (shim_cmd_i.valid === 1'b1);
  wire ef_cmd_rd = ef_cmd_v && (shim_cmd_i.command == efuse_pkg::FUSE_COMMAND_READ);
  // A program command is PROGRAM or PROGRAM_READ_BACK: the read-back flag of
  // EFUSE_PROGRAM_CTRL selects the second, and both burn the bit.
  wire ef_cmd_pg = ef_cmd_v && ((shim_cmd_i.command == efuse_pkg::FUSE_COMMAND_PROGRAM) ||
                                (shim_cmd_i.command == efuse_pkg::FUSE_COMMAND_PROGRAM_READ_BACK));
  wire [12:0] ef_cmd_addr = 13'(shim_cmd_i.address);
  wire ef_resp_v = (shim_resp_i.valid === 1'b1);

  // Frontdoor completions with any response (rd_okay and wr_okay are OKAY
  // only). One outstanding single-beat transaction, as for the Phase 1 bins.
  wire ef_wr_cmpl = !in_reset && b_hs && (aw_out_q == 4'd1) && (w_beats_q == 2'd1);
  wire ef_rd_cmpl = rd_cmpl;
  wire [2:0] ef_wr_win = ef_win(aw_addr_q);
  wire [2:0] ef_rd_win = ef_win(ar_addr_q);

  // State at the AW handshake of each write, before the write takes effect.
  logic [EfFuseBits-1:0] ef_aw_shadow = '0;
  logic [63:0] ef_aw_feat = '0;
  logic [1:0] ef_aw_d1 = 2'b10, ef_aw_d2 = 2'b10;
  logic ef_aw_l1 = 1'b0, ef_aw_l2 = 1'b0;
  logic [2:0] ef_aw_fault = '0;
  logic [2:0] ef_aw_flags = '0;  // {read_addr, program_addr, req} errors
  logic ef_aw_flx = 1'b0;  // a status flag (read_status included) has an X or Z bit
  logic ef_aw_rderr = 1'b0;  // read_status
  logic ef_aw_dx = 1'b0;  // a DEMOTE or lock output has an X or Z bit
  logic ef_aw_pcmd_v = 1'b0;  // a PROGRAM command reached the shim since the AW
  logic [12:0] ef_aw_pcmd_addr = '0;
  always @(posedge clk_i) begin
    if (aw_hs) begin
      ef_aw_shadow <= efuse_shadow_i;
      ef_aw_feat <= feat_ctrl_i;
      ef_aw_d1 <= demote_1_i;
      ef_aw_d2 <= demote_2_i;
      ef_aw_l1 <= (demote_lock_1_i === 1'b1);
      ef_aw_l2 <= (demote_lock_2_i === 1'b1);
      ef_aw_fault <= tok_fault_i;
      ef_aw_flags <= {rd_addr_err_i === 1'b1, pg_addr_err_i === 1'b1, req_err_i === 1'b1};
      ef_aw_flx <= $isunknown({efuse_read_error_i, rd_addr_err_i, pg_addr_err_i, req_err_i});
      ef_aw_rderr <= (efuse_read_error_i === 1'b1);
      ef_aw_dx <= $isunknown({demote_1_i, demote_2_i, demote_lock_1_i, demote_lock_2_i});
      ef_aw_pcmd_v <= ef_cmd_pg;
      ef_aw_pcmd_addr <= ef_cmd_addr;
    end else if (ef_cmd_pg) begin
      ef_aw_pcmd_v <= 1'b1;
      ef_aw_pcmd_addr <= ef_cmd_addr;
    end
  end

  // Program and read enables, as the last frontdoor write left them.
  logic ef_pen_q = 1'b0;
  logic ef_pg_tmo_en_q = 1'b0;
  always @(posedge clk_i) begin
    if (in_reset) begin
      ef_pen_q <= 1'b0;
      ef_pg_tmo_en_q <= 1'b0;
    end else if (wr_okay && (aw_addr_q == EfPgCtrl)) begin
      ef_pen_q <= |(wr_data & EfPgEnMask);
    end else if (wr_okay && (aw_addr_q == EfPgTmo)) begin
      ef_pg_tmo_en_q <= |(wr_data & EfPgTmoEnMask);
    end
  end

  // Sense-done rise and the first reset-release clock.
  logic ef_fuse_q = 1'b0;
  logic ef_rst_q = 1'b1;
  always @(posedge clk_i) begin
    ef_fuse_q <= (fuse_sense_done_i === 1'b1);
    ef_rst_q  <= in_reset;
  end
  wire ef_sense_rise = fuse_sense;  // rising edge, +skip_fuse_sense excluded
  wire ef_rel = ef_rst_q && !in_reset;
  wire ef_rst_fall = !ef_rst_q && in_reset;

  // Feature change: any change of the profile inputs, sampled once they have
  // been stable for EfFeatSettle clocks (the specification gives no decode
  // latency). The sense-done rise also starts a settle. ef_fs_* is the state
  // at the previous settled sample, for the points that compare two samples.
  localparam int unsigned EfFvW = 4 + 1 + 2 + 2 + 64 + 64 + 64 + 1;
  wire [EfFvW-1:0] ef_fv = {
    efuse_lc_raw_i, sec_dis_i, demote_1_i, demote_2_i, ef_sip_dis, ef_sys_dis, feat_ctrl_i,
    lc_sigint_i
  };
  logic [EfFvW-1:0] ef_fv_q = '0;
  logic ef_sensed_q = 1'b0;
  logic ef_fv_pend = 1'b0;
  int unsigned ef_fv_cnt = 0;
  wire ef_feat_ev = ef_sensed && ef_fv_pend && (ef_fv_cnt == EfFeatSettle) && (ef_fv === ef_fv_q);
  always @(posedge clk_i) begin
    ef_fv_q <= ef_fv;
    ef_sensed_q <= ef_sensed;
    if (!ef_sensed) begin
      ef_fv_pend <= 1'b0;
      ef_fv_cnt  <= 0;
    end else if ((ef_fv !== ef_fv_q) || !ef_sensed_q) begin
      ef_fv_pend <= 1'b1;
      ef_fv_cnt  <= 0;
    end else if (ef_fv_pend) begin
      if (ef_fv_cnt == EfFeatSettle) ef_fv_pend <= 1'b0;
      else ef_fv_cnt <= ef_fv_cnt + 1;
    end
  end
  // The inputs that select a feature cell (state code, SEC_DIS, the demote
  // outputs, the DIS vectors, the integrity error) are known. A cell is never
  // chosen from an X or Z input; the profile output itself may be unknown and
  // then counts as a wrong value.
  wire ef_fin_k = !$isunknown(
      {efuse_lc_raw_i, sec_dis_i, demote_1_i, demote_2_i, ef_sip_dis, ef_sys_dis, lc_sigint_i}
  );
  logic ef_fs_v = 1'b0;
  logic [2:0] ef_fs_lc = '0;
  logic ef_fs_sd = 1'b0, ef_fs_sig = 1'b0;
  logic [1:0] ef_fs_d1 = 2'b10, ef_fs_d2 = 2'b10;
  logic [63:0] ef_fs_feat = '0, ef_fs_sip = '0, ef_fs_sys = '0;
  logic [31:0] ef_fs_lcw = '0;
  logic [3:0] ef_fs_raw = '0;
  always @(posedge clk_i) begin
    if (!ef_sensed) begin
      ef_fs_v <= 1'b0;
    end else if (ef_feat_ev && !ef_fin_k) begin
      ef_fs_v <= 1'b0;
    end else if (ef_feat_ev) begin
      ef_fs_v    <= 1'b1;
      ef_fs_lc   <= ef_lc;
      ef_fs_raw  <= efuse_lc_raw_i;
      ef_fs_sd   <= ef_sd;
      ef_fs_sig  <= ef_sig;
      ef_fs_d1   <= demote_1_i;
      ef_fs_d2   <= demote_2_i;
      ef_fs_feat <= feat_ctrl_i;
      ef_fs_sip  <= ef_sip_dis;
      ef_fs_sys  <= ef_sys_dis;
      ef_fs_lcw  <= ef_lc_word;
    end
  end

  // Token change: a change of a status code, SEC_DIS, a sticky bit, the
  // interrupt line or a go pulse, sampled once they have been stable for
  // EfTokSettle clocks (N), so a cell that compares two of them samples at a
  // settled point. ef_ts_* holds the previous settled sample.
  localparam int unsigned EfTvW = 6 + 6 + 6 + 1 + 3 + 1 + 3;
  wire ef_irq = (irq_token_fault_i === 1'b1);
  wire [EfTvW-1:0] ef_tv = {
    tok_sip_i, tok_chp_i, tok_sdis_i, sec_dis_i, tok_fault_i, irq_token_fault_i, token_go_i
  };
  logic [EfTvW-1:0] ef_tv_q = '0;
  logic ef_tv_pend = 1'b0;
  int unsigned ef_tv_cnt = 0;
  wire ef_tok_ev = ef_live && ef_tv_pend && (ef_tv_cnt == EfTokSettle) && (ef_tv === ef_tv_q);
  always @(posedge clk_i) begin
    ef_tv_q <= ef_tv;
    if (!ef_live) begin
      ef_tv_pend <= 1'b0;
      ef_tv_cnt  <= 0;
    end else if (ef_tv !== ef_tv_q) begin
      ef_tv_pend <= 1'b1;
      ef_tv_cnt  <= 0;
    end else if (ef_tv_pend) begin
      if (ef_tv_cnt == EfTokSettle) ef_tv_pend <= 1'b0;
      else ef_tv_cnt <= ef_tv_cnt + 1;
    end
  end
  wire [2:0][5:0] ef_code = {tok_sdis_i, tok_chp_i, tok_sip_i};
  logic ef_ts_v = 1'b0;
  logic [2:0][5:0] ef_ts_code = '0;
  logic [2:0] ef_ts_fault = '0;
  always @(posedge clk_i) begin
    if (!ef_live) ef_ts_v <= 1'b0;
    else if (ef_tok_ev) begin
      ef_ts_v     <= 1'b1;
      ef_ts_code  <= ef_code;
      ef_ts_fault <= tok_fault_i;
    end
  end

  // One-point sample helpers.
  task automatic ef_geo(input int unsigned which, input logic [5:0] v);
    ef_geo_t e;
    e = '0;
    case (which)
      0: begin
        e.wn = v[2:0];
        e.wn_v = 1'b1;
      end
      1: begin
        e.rz = v[0];
        e.rz_v = 1'b1;
      end
      2: begin
        e.wr = v;
        e.wr_v = 1'b1;
      end
      3: begin
        e.sf = v[3:0];
        e.sf_v = 1'b1;
      end
      4: begin
        e.ea = v[1:0];
        e.ea_v = 1'b1;
      end
      5: begin
        e.cr = v[3:0];
        e.cr_v = 1'b1;
      end
      6: begin
        e.tb = v[3:0];
        e.tb_v = 1'b1;
      end
      default: begin
        e.ji = v[0];
        e.ji_v = 1'b1;
      end
    endcase
    u_sep_efuse_map_geometry_cg.sample(e);
  endtask

  task automatic ef_lk(input int unsigned which, input logic [7:0] v);
    ef_lock_t e;
    e = '0;
    case (which)
      0: begin
        e.sp = v;
        e.sp_v = 1'b1;
      end
      1: begin
        e.sr = v;
        e.sr_v = 1'b1;
      end
      2: begin
        e.ko = v[3:0];
        e.ko_v = 1'b1;
      end
      3: begin
        e.nf = v[1:0];
        e.nf_v = 1'b1;
      end
      4: begin
        e.ex = v[1:0];
        e.ex_v = 1'b1;
      end
      5: begin
        e.sl = v[0];
        e.sl_v = 1'b1;
      end
      6: begin
        e.sw = v[3:0];
        e.sw_v = 1'b1;
      end
      7: begin
        e.lo = v[1:0];
        e.lo_v = 1'b1;
      end
      8: begin
        e.pv = v[0];
        e.pv_v = 1'b1;
      end
      9: begin
        e.rc = v[2:0];
        e.rc_v = 1'b1;
      end
      11: begin
        e.xw = v[1:0];
        e.xw_v = 1'b1;
      end
      12: begin
        e.lf = v[2:0];
        e.lf_v = 1'b1;
      end
      default: begin
        e.lp = v[2:0];
        e.lp_v = 1'b1;
      end
    endcase
    u_sep_efuse_lock_policy_cg.sample(e);
  endtask

  task automatic ef_tc(input int unsigned which, input logic [5:0] v);
    ef_tch_t e;
    e = '0;
    case (which)
      0: begin
        e.cv = v[2:0];
        e.cv_v = 1'b1;
      end
      1: begin
        e.cd = v;
        e.cd_v = 1'b1;
      end
      2: begin
        e.cs = v[4:0];
        e.cs_v = 1'b1;
      end
      3: begin
        e.ph = v[2:0];
        e.ph_v = 1'b1;
      end
      4: begin
        e.ci = v[1:0];
        e.ci_v = 1'b1;
      end
      5: begin
        e.hw = v[1:0];
        e.hw_v = 1'b1;
      end
      6: begin
        e.gi = v[1:0];
        e.gi_v = 1'b1;
      end
      8: begin
        e.th = v[0];
        e.th_v = 1'b1;
      end
      9: begin
        e.gw = v[1:0];
        e.gw_v = 1'b1;
      end
      default: begin
        e.rt = v[1:0];
        e.rt_v = 1'b1;
      end
    endcase
    u_sep_token_channel_cg.sample(e);
  endtask

  task automatic ef_tfs(input int unsigned which, input logic [4:0] v);
    ef_tf_t e;
    e = '0;
    case (which)
      0: begin
        e.kc = v;
        e.kc_v = 1'b1;
      end
      1: begin
        e.cf = v[1:0];
        e.cf_v = 1'b1;
      end
      2: begin
        e.fe = v[3:0];
        e.fe_v = 1'b1;
      end
      3: begin
        e.rt = v[2:0];
        e.rt_v = 1'b1;
      end
      4: begin
        e.nc = v[1:0];
        e.nc_v = 1'b1;
      end
      5: begin
        e.rc = v[1:0];
        e.rc_v = 1'b1;
      end
      6: begin
        e.so = v[0];
        e.so_v = 1'b1;
      end
      7: begin
        e.lf = v[2:0];
        e.lf_v = 1'b1;
      end
      default: begin
        e.il = v[2:0];
        e.il_v = 1'b1;
      end
    endcase
    u_sep_token_fault_cg.sample(e);
  endtask

  task automatic ef_ifs(input int unsigned which, input logic [6:0] v);
    ef_ifs_t e;
    e = '0;
    case (which)
      0: begin
        e.ca = v[2:0];
        e.ca_v = 1'b1;
      end
      1: begin
        e.fl = v[3:0];
        e.fl_v = 1'b1;
      end
      2: begin
        e.cf = v;
        e.cf_v = 1'b1;
      end
      3: begin
        e.cc = v[2:0];
        e.cc_v = 1'b1;
      end
      4: begin
        e.fc = v[1:0];
        e.fc_v = 1'b1;
      end
      5: begin
        e.ss = v[0];
        e.ss_v = 1'b1;
      end
      6: begin
        e.pl = v[1:0];
        e.pl_v = 1'b1;
      end
      default: begin
        e.at = v[0];
        e.at_v = 1'b1;
      end
    endcase
    u_sep_efuse_if_status_cg.sample(e);
  endtask

  task automatic ef_act(input int unsigned which, input logic [4:0] v);
    ef_act_t e;
    e = '0;
    case (which)
      0: begin
        e.mp = v[1:0];
        e.mp_v = 1'b1;
      end
      1: begin
        e.vo = v[2:0];
        e.vo_v = 1'b1;
      end
      default: begin
        e.df = v;
        e.df_v = 1'b1;
      end
    endcase
    u_sep_sec_dis_activation_cg.sample(e);
  endtask

  task automatic ef_rob(input int unsigned which, input logic [2:0] v);
    ef_rob_t e;
    e = '0;
    case (which)
      0: begin
        e.dr = v;
        e.dr_v = 1'b1;
      end
      1: begin
        e.ss = v[0];
        e.ss_v = 1'b1;
      end
      2: begin
        e.sf = v;
        e.sf_v = 1'b1;
      end
      4: begin
        e.xs = v[0];
        e.xs_v = 1'b1;
      end
      default: begin
        e.rv = v[0];
        e.rv_v = 1'b1;
      end
    endcase
    u_sep_sec_dis_robustness_cg.sample(e);
  endtask

  // ---------------------------------------------------------------------
  // sep_efuse_map_geometry_cg: frontdoor completions in 0x1093_0000 to
  // 0x1093_FFFF, and the JTAG ID at sense done.
  // ---------------------------------------------------------------------
  task automatic ef_geo_access(input logic [31:0] a, input logic wr, input logic ok,
                               input logic [2:0] size);
    logic [2:0] w;
    logic [10:0] off;
    logic ign;
    w   = ef_win(a);
    off = 11'(a - EfMapBase);
    if (ef_own_win) begin
      ef_geo(0, 6'(w));
      if (w == EfWRsvd) ef_geo(1, 6'(a >= EfRsvdHigh));
      if ((fuse_sense_done_i === 1'b1) && (w inside {EfWShadow, EfWCtrlIn, EfWTokIn})) begin
        ign = ((w == EfWShadow) && wr) || ((w == EfWShadow) && !wr && ef_rlock(ef_slot_of(off))) ||
            (wr && (a == EfStatus)) || (wr && (a inside {EfPgData, EfRdData, EfMatchSip,
                                                         EfMatchChip, EfMatchSec, EfMatchFault})) ||
            (!wr && (a == EfTokEop));
        ef_geo(2, {ign, w, wr, ok});
      end
      if (a == EfMapEnd - 32'd4) ef_geo(4, 6'd0);
      if (a == EfCtrlEnd - 32'd4) ef_geo(4, 6'd1);
      if (a == EfCtrlEnd) ef_geo(4, 6'd2);
      if (a == EfRsvdBase) ef_geo(4, 6'd3);
      case (a)
        EfStatus: ef_geo(5, wr ? 6'd1 : 6'd0);
        EfPgCtrl: ef_geo(5, wr ? 6'd3 : 6'd2);
        EfRdCtrl: ef_geo(5, wr ? 6'd5 : 6'd4);
        EfRdTmo: if (!wr) ef_geo(5, 6'd6);
        EfPgTmo: if (!wr) ef_geo(5, 6'd7);
        EfPgData: if (!wr) ef_geo(5, 6'd8);
        EfRdData: if (!wr) ef_geo(5, 6'd9);
        default: ;
      endcase
      if (in_win(a, EfTokSip, EfTokChip)) ef_geo(6, wr ? 6'd1 : 6'd0);
      if (in_win(a, EfTokChip, EfTokSec)) ef_geo(6, wr ? 6'd3 : 6'd2);
      if (in_win(a, EfTokSec, EfTokEop)) ef_geo(6, wr ? 6'd5 : 6'd4);
    end
    if (ef_own_tch) begin
      if (!wr && (a == EfMatchSip)) ef_geo(6, 6'd6);
      if (!wr && (a == EfMatchChip)) ef_geo(6, 6'd7);
      if (!wr && (a == EfMatchSec)) ef_geo(6, 6'd8);
      if (wr && (a == EfTokEop)) ef_geo(6, 6'd9);
    end
    // The used-bit leg reads each narrow register with a 32-bit OKAY read.
    if (ef_own_fld && !wr && ok && (size == 3'd2) && (fuse_sense_done_i === 1'b1)) begin
      case (a)
        SEP_EFUSE_MAP_LC_STATE_REG_ADDR: ef_geo(3, 6'd0);
        SEP_EFUSE_MAP_SBOOT_DIS_REG_ADDR: ef_geo(3, 6'd1);
        SEP_EFUSE_MAP_TRANSIENT_RMA_EN_REG_ADDR: ef_geo(3, 6'd2);
        SEP_EFUSE_MAP_CHIPLET_PUBK_REVOKE_REG_ADDR: ef_geo(3, 6'd3);
        SEP_EFUSE_MAP_STATUS_RPT_REG_ADDR: ef_geo(3, 6'd4);
        SEP_EFUSE_MAP_ROM_CTL_REG_ADDR: ef_geo(3, 6'd5);
        SEP_EFUSE_MAP_SYSCLK_FREQ_MHZ_REG_ADDR: ef_geo(3, 6'd6);
        SEP_EFUSE_MAP_REQUIRED_SIGNERS_REG_ADDR: ef_geo(3, 6'd7);
        SEP_EFUSE_MAP_REQUIRED_ALGS_REG_ADDR: ef_geo(3, 6'd8);
        default: ;
      endcase
    end
  endtask

  always @(posedge clk_i) begin
    if (ef_wr_cmpl && (ef_wr_win != EfWNone)) begin
      ef_geo_access(aw_addr_q, 1'b1, lsu_b_resp_i === AxiOkay, aw_size_q);
    end
    if (ef_rd_cmpl && (ef_rd_win != EfWNone)) begin
      ef_geo_access(ar_addr_q, 1'b0, lsu_r_resp_i === AxiOkay, ar_size_q);
    end
    if (ef_sense_rise && ef_own_fld && (jtag_id_i !== '0) && !$isunknown(jtag_id_i)) begin
      ef_geo(7, 6'd1);
    end
  end

  // ---------------------------------------------------------------------
  // sep_efuse_field_value_cg: narrow fields at sense done; x_version_bit
  // from the new set bit of BL1_VERSION or BL2_VERSION at the first sense
  // done after a program. The previous sensed copy survives the cold reset
  // between the program and the resense.
  // ---------------------------------------------------------------------
  logic [511:0] ef_vb_prev = '0;
  logic ef_vb_pv = 1'b0;
  logic ef_vb_prog = 1'b0;
  function automatic logic [1:0] ef_bitcls(input logic [255:0] v);
    for (int i = 0; i < 256; i++) begin
      if (v[i]) return (i == 0) ? 2'd0 : (i == 255) ? 2'd2 : 2'd1;
    end
    return 2'd0;
  endfunction
  always @(posedge clk_i) begin
    ef_fld_t e;
    logic [31:0] w;
    logic [4:0] sw;
    logic [10:0] clk;
    logic [511:0] cur, gain;
    if (ef_cmd_pg) ef_vb_prog <= 1'b1;
    if (ef_sense_rise) begin
      if (ef_own_fld) begin
        e = '0;
        e.sb = efuse_shadow_i[32*EfWSboot];
        e.sb_v = 1'b1;
        e.rs = efuse_shadow_i[32*EfWSigners+:2];
        e.rs_v = 1'b1;
        e.sr = efuse_shadow_i[32*EfWStatusRpt+:2];
        e.sr_v = 1'b1;
        w = efuse_shadow_i[32*EfWRevoke+:32];
        e.rv = (w == 32'h0) ? 2'd0 : ($countones(w) == 1) ? 2'd1 : (w == EfRevokeAll) ? 2'd2 : 2'd3;
        e.rv_v = 1'b1;
        clk = efuse_shadow_i[32*EfWSysclk+:11];
        e.sc = (clk == 11'd1) ? 2'd0 : (clk == 11'h7FF) ? 2'd2 : 2'd1;
        e.sc_v = (clk != 11'd0);
        w = efuse_shadow_i[32*EfWRomCtl+:32];
        e.rc = {1'b0, 2'b00, w[0]};
        e.rc_v = 1'b1;
        u_sep_efuse_field_value_cg.sample(e);
        sw = w[5:1];
        e = '0;
        e.rc = (sw == 5'd0) ? 4'b1_000 : (sw == 5'h1F) ? 4'b1_110 : 4'b1_111;
        for (int i = 0; i < 5; i++) begin
          if (sw == (5'd1 << i)) e.rc = {1'b1, 3'(i + 1)};
        end
        e.rc_v = 1'b1;
        u_sep_efuse_field_value_cg.sample(e);
        w = efuse_shadow_i[32*EfWAlgs+:32];
        for (int o = 0; o < 3; o++) begin
          e = '0;
          e.al = 4'(o * 4) + 4'(w[4*o+:2]);
          e.al_v = 1'b1;
          u_sep_efuse_field_value_cg.sample(e);
        end
      end
      cur = {efuse_shadow_i[32*EfWBl2+:256], efuse_shadow_i[32*EfWBl1+:256]};
      gain = cur & ~ef_vb_prev;
      if (ef_own_lock && ef_vb_pv && ef_vb_prog) begin
        if ($countones(gain[255:0]) == 1) begin
          e = '0;
          e.vb = 3'(ef_bitcls(gain[255:0]));
          e.vb_v = 1'b1;
          u_sep_efuse_field_value_cg.sample(e);
        end
        if ($countones(gain[511:256]) == 1) begin
          e = '0;
          e.vb = 3'd3 + 3'(ef_bitcls(gain[511:256]));
          e.vb_v = 1'b1;
          u_sep_efuse_field_value_cg.sample(e);
        end
      end
      ef_vb_prev <= cur;
      ef_vb_pv   <= 1'b1;
      ef_vb_prog <= 1'b0;
    end
  end

  // ---------------------------------------------------------------------
  // Feature-change points: sep_lc_feat_ctrl_profile_cg,
  // sep_lc_feature_bit_semantics_cg, sep_dtp_gating_ladder_cg,
  // x_sigint_state_secdis_out, the feature points of sep_lc_demotion_cg,
  // x_state_demote_forced and x_state_strap_feat.
  // ---------------------------------------------------------------------
  // Bits of x_closed_bit_owner (in that order) and the named feature bits
  // (lifecycle_controller.adoc, Disable Vector Format).
  localparam int unsigned EfClosedBit[11] = '{0, 1, 2, 3, 4, 23, 24, 25, 47, 48, 63};
  localparam int unsigned EfBitSepDbg = 0;
  localparam int unsigned EfBitChipDbg = 1;
  localparam int unsigned EfBitSepFuseDbg = 2;
  localparam int unsigned EfBitSmcFuseDbg = 3;
  localparam int unsigned EfBitSipDbg = 24;
  localparam int unsigned EfNamedBit[5] = '{
      EfBitSepDbg,
      EfBitChipDbg,
      EfBitSepFuseDbg,
      EfBitSmcFuseDbg,
      EfBitSipDbg
  };
  logic ef_dtp_ref_v = 1'b0;
  logic ef_dtp_ref_sep = 1'b0, ef_dtp_ref_smc = 1'b0;

  always @(posedge clk_i) begin
    ef_prof_t pe;
    ef_bit_t be;
    ef_dtp_t de;
    ef_sig_t se;
    ef_dem_t me;
    logic [4:0] row;
    logic [2:0] oc;
    logic [23:0] sg, yg, og, m;
    logic c1, c2, c3, ao, all_open, sep_p, smc_p, ref_sep, ref_smc, ref_v;
    logic [1:0] fs_dm;
    logic [2:0] chg;
    int unsigned b;
    // x_export_codeword: an X or Z bit on a DEMOTE output is not a
    // complementary codeword.
    if (ef_feat_ev && ef_own_fc) begin
      me = '0;
      me.ec = {1'b0, $isunknown(demote_1_i) || !(demote_1_i inside {2'b10, 2'b01})};
      me.ec_v = 1'b1;
      u_sep_lc_demotion_cg.sample(me);
      me = '0;
      me.ec = {1'b1, $isunknown(demote_2_i) || !(demote_2_i inside {2'b10, 2'b01})};
      me.ec_v = 1'b1;
      u_sep_lc_demotion_cg.sample(me);
    end
    if (ef_feat_ev && ef_fin_k) begin
      fs_dm = {ef_fs_d1 == 2'b01, ef_fs_d2 == 2'b01};
      if (ef_own_fc) begin
        // sep_lc_feat_ctrl_profile_cg. The row and class points need a state
        // code that passes the integrity check.
        row = ef_row(ef_lc, ef_sd, ef_dm);
        pe = '0;
        pe.sc = ef_lc;
        pe.sc_v = 1'b1;
        pe.pr = row;
        pe.pr_v = !ef_sig;
        pe.rd = (ef_lc == EfRc);
        pe.rd_v = (ef_lc inside {EfRs, EfRc}) && ((ef_sip_dis | ef_sys_dis) != 64'h0);
        u_sep_lc_feat_ctrl_profile_cg.sample(pe);
        for (int g = 0; g < 3; g++) begin
          m  = ef_gmask(g);
          sg = ef_grp(ef_sip_dis, g);
          yg = ef_grp(ef_sys_dis, g);
          og = sg | yg;
          pe = '0;
          pe.oc = {2'(g), og != 24'h0};
          pe.oc_v = (og != m);
          // Guard: SIP_DIS slice nonzero, SYS_DIS has a bit outside SIP_DIS,
          // OR neither zero nor all ones, so the four classes differ.
          if (!ef_sig && (sg != 24'h0) && ((yg & ~sg) != 24'h0) && (og != 24'h0) && (og != m)) begin
            oc = ef_obs_cls(feat_ctrl_i, ef_sip_dis, ef_sys_dis, g);
            pe.xr = {oc != ef_prof_cls(row, g), row, 2'(g), oc};
            pe.xr_v = 1'b1;
          end
          u_sep_lc_feat_ctrl_profile_cg.sample(pe);
        end

        // sep_lc_feature_bit_semantics_cg.
        for (int k = 0; k < 5; k++) begin
          be = '0;
          be.nb = {3'(k), feat_ctrl_i[EfNamedBit[k]]};
          be.nb_v = 1'b1;
          u_sep_lc_feature_bit_semantics_cg.sample(be);
        end
        if (ef_fs_v && (ef_fs_lc == ef_lc) && (ef_fs_sd == ef_sd) && (ef_fs_sig == ef_sig) &&
            (fs_dm == ef_dm)) begin
          for (int k = 0; k < 11; k++) begin
            b = EfClosedBit[k];
            if (ef_fs_feat[b] && !feat_ctrl_i[b] && !(ef_fs_sip[b] || ef_fs_sys[b]) &&
                (ef_sip_dis[b] || ef_sys_dis[b])) begin
              be = '0;
              be.cb = 5'(k * 2) + 5'(!(ef_sip_dis[b] && !ef_fs_sip[b]));
              be.cb_v = 1'b1;
              u_sep_lc_feature_bit_semantics_cg.sample(be);
            end
          end
        end
        if (ef_fs_v && (ef_fs_lc == ef_lc) && (ef_lc inside {EfTd, EfProd}) && (ef_fs_sd == ef_sd) &&
            (ef_fs_sig == ef_sig) && (ef_fs_sip == ef_sip_dis) && (ef_fs_sys == ef_sys_dis) &&
            (((fs_dm == 2'b00) && (ef_dm == 2'b10)) || ((fs_dm == 2'b00) && (ef_dm == 2'b01)) ||
             ((fs_dm == 2'b01) && (ef_dm == 2'b11)) || ((fs_dm == 2'b10) && (ef_dm == 2'b11)))) begin
          chg = {
            ef_grp(ef_fs_feat, 2) != ef_grp(feat_ctrl_i, 2),
            ef_grp(ef_fs_feat, 1) != ef_grp(feat_ctrl_i, 1),
            ef_grp(ef_fs_feat, 0) != ef_grp(feat_ctrl_i, 0)
          };
          be = '0;
          be.dg = {ef_d2 && (fs_dm[0] == 1'b0), ef_lc == EfProd, chg};
          be.dg_v = 1'b1;
          u_sep_lc_feature_bit_semantics_cg.sample(be);
        end

        // sep_dtp_gating_ladder_cg. The port value enters only as "same as"
        // or "other than" its value in the all-open cell of the leaf. The
        // all-open cell sets the reference and is not sampled into the port
        // points, so a "same" cell fills only from another combination of the
        // same class and never from a compare of the reference with itself.
        c1 = feat_ctrl_i[EfBitSipDbg];
        c2 = c1 && feat_ctrl_i[EfBitChipDbg];
        c3 = c2 && feat_ctrl_i[EfBitSepDbg];
        // A port with an X or Z value is "other than" the reference, and the
        // reference is taken only from known port values.
        sep_p = (sep_fuse_dft_disable_i === 1'b1);
        smc_p = (smc_fuse_dft_disable_i === 1'b1);
        ref_v = ef_dtp_ref_v;
        ref_sep = ef_dtp_ref_sep;
        ref_smc = ef_dtp_ref_smc;
        all_open = c3 && feat_ctrl_i[EfBitSepFuseDbg] && feat_ctrl_i[EfBitSmcFuseDbg];
        if (all_open && !$isunknown({sep_fuse_dft_disable_i, smc_fuse_dft_disable_i})) begin
          ef_dtp_ref_v <= 1'b1;
          ef_dtp_ref_sep <= sep_p;
          ef_dtp_ref_smc <= smc_p;
        end
        de = '0;
        de.sp = {
          c3, feat_ctrl_i[EfBitSepFuseDbg], $isunknown(sep_fuse_dft_disable_i) || (sep_p != ref_sep)
        };
        de.sp_v = ref_v && !all_open;
        de.mp = {
          c2, feat_ctrl_i[EfBitSmcFuseDbg], $isunknown(smc_fuse_dft_disable_i) || (smc_p != ref_smc)
        };
        de.mp_v = ref_v && !all_open;
        de.ns = c3 ? 2'd3 : c2 ? 2'd2 : 2'd1;
        de.ns_v = c1;
        u_sep_dtp_gating_ladder_cg.sample(de);

        // sep_lc_demotion_cg feature points.
        me = '0;
        me.sc = 5'(ef_lc * 4) + 5'(ef_dm);
        me.sc_v = 1'b1;
        if (ef_fs_v && (fs_dm != ef_dm) && (ef_fs_raw == efuse_lc_raw_i) && (ef_fs_lcw == ef_lc_word)) begin
          me.oi = 5'(ef_lc * 4) + 5'(ef_dm);
          me.oi_v = 1'b1;
        end
        u_sep_lc_demotion_cg.sample(me);

        // x_state_demote_forced: cells 0-3 TEST_DEV and 4-7 PROD in the
        // order 00, 10, 01, 11 of {DEMOTE_1, DEMOTE_2}.
        if (ef_sd && (ef_lc != EfRc)) begin
          logic [3:0] dcell;
          case (ef_lc)
            EfTd: dcell = 4'(ef_dm == 2'b00 ? 0 : ef_dm == 2'b10 ? 1 : ef_dm == 2'b01 ? 2 : 3);
            EfProd: dcell = 4'(ef_dm == 2'b00 ? 4 : ef_dm == 2'b10 ? 5 : ef_dm == 2'b01 ? 6 : 7);
            EfPe: dcell = 4'd8;
            EfRs: dcell = 4'd9;
            default: dcell = 4'd10;
          endcase
          ef_act(2, {feat_ctrl_i !== '1, dcell});
        end
        // x_state_strap_feat: sampled with sec_dis_i 0.
        if (!ef_sd && (ef_lc inside {EfTd, EfProd, EfRs}) && !$isunknown(secure_tm_i)) begin
          ef_rob(2,
                 3'((ef_lc == EfTd ? 0 : ef_lc == EfProd ? 1 : 2) * 2) + 3'(secure_tm_i === 1'b1));
        end
      end

      // x_sigint_state_secdis_out: lc_sigint_i high, INVALID excluded.
      if (ef_own_cw && ef_sig && (ef_lc != EfInv)) begin
        oc = (feat_ctrl_i === 64'h0) ? 3'd0 : (feat_ctrl_i === '1) ? 3'd1 : 3'd2;
        se = '0;
        se.ss = {oc != {2'b00, ef_sd}, 4'(ef_lc * 2) + 4'(ef_sd)};
        se.ss_v = 1'b1;
        u_sep_lc_sigint_failclosed_cg.sample(se);
      end
    end
  end

  // x_raw16_sigint: a complementary state byte {~r, r} at sense done.
  always @(posedge clk_i) begin
    ef_sig_t se;
    if (ef_sense_rise && ef_own_fc && !$isunknown(
            ef_lc_word[7:0]
        ) && (ef_lc_word[7:4] == ~ef_lc_word[3:0])) begin
      se = '0;
      // An X or Z on lc_sigint_i at sense done counts as the error.
      se.rs = {lc_sigint_i !== 1'b0, ef_lc_word[3:0]};
      se.rs_v = 1'b1;
      u_sep_lc_sigint_failclosed_cg.sample(se);
    end
  end

  // ---------------------------------------------------------------------
  // x_transient: a match code on RMA_SIP or RMA_CHIPLET, the old class at
  // the match rise, and the LC_STATE word outcome within EfTransWin clocks
  // (a sampler parameter at most the window W of the owning test).
  // ---------------------------------------------------------------------
  logic ef_tr_arm = 1'b0;
  logic ef_tr_en = 1'b0, ef_tr_ch = 1'b0;
  logic [2:0] ef_tr_cls = '0;
  logic [31:0] ef_tr_lcw = '0;
  int unsigned ef_tr_cnt = 0;
  logic [5:0] ef_sip_q = '0, ef_chp_q = '0;
  always @(posedge clk_i) begin
    ef_trn_t e;
    logic [2:0] ci;
    logic upd, exp_upd, rise_s, rise_c;
    ef_sip_q <= tok_sip_i;
    ef_chp_q <= tok_chp_i;
    rise_s = (tok_sip_i == EfCodeMatch) && (ef_sip_q != EfCodeMatch);
    rise_c = (tok_chp_i == EfCodeMatch) && (ef_chp_q != EfCodeMatch);
    if (!ef_sensed || !ef_own_tr) begin
      ef_tr_arm <= 1'b0;
      // A SIP rise while a CHIPLET match is held is a cell of
      // cp_simultaneous_match, not of x_transient.
    end else if (!ef_tr_arm && (rise_s || rise_c) && (ef_lc != EfPe) &&
                 !(rise_s && (tok_chp_i == EfCodeMatch)) && !$isunknown(
            {efuse_lc_raw_i, ef_trans_en, ef_lc_word}
        )) begin
      ef_tr_arm <= 1'b1;
      ef_tr_en  <= ef_trans_en;
      ef_tr_ch  <= !rise_s;
      ef_tr_cls <= (ef_lc == EfTd) ? 3'd0 : (ef_lc == EfProd) ? 3'd1 : (ef_lc == EfRs) ? 3'd2 :
          (ef_lc == EfRc) ? 3'd3 : 3'd4;
      ef_tr_lcw <= ef_lc_word;
      ef_tr_cnt <= 0;
    end else if (ef_tr_arm) begin
      // An X or Z bit in the LC_STATE word counts as an update and as a wrong
      // outcome.
      upd = (ef_lc_word !== ef_tr_lcw);
      if (upd || (ef_tr_cnt == EfTransWin)) begin
        exp_upd = ef_tr_en && ((!ef_tr_ch && (ef_tr_cls <= 3'd1)) || (ef_tr_ch && (ef_tr_cls == 3'd2)));
        e = '0;
        e.tr = {
          (upd != exp_upd) || $isunknown(ef_lc_word),
          5'((32'(ef_tr_en) * 2 + 32'(ef_tr_ch)) * 5 + 32'(ef_tr_cls))
        };
        e.tr_v = 1'b1;
        u_sep_lc_illegal_transition_cg.sample(e);
        ef_tr_arm <= 1'b0;
      end else begin
        ef_tr_cnt <= ef_tr_cnt + 1;
      end
    end
  end

  // ---------------------------------------------------------------------
  // Program and read requests: a frontdoor go on EFUSE_PROGRAM_CTRL or
  // EFUSE_READ_CTRL. A program lands when a PROGRAM command to its bit
  // address reaches the shim (shim_cmd_i) after the AW of the go.
  // ---------------------------------------------------------------------
  logic ef_pg_v = 1'b0;  // a program request is open
  logic [15:0] ef_pg_addr = '0;
  logic ef_pg_data = 1'b0, ef_pg_en = 1'b0, ef_pg_sensed = 1'b0, ef_pg_stm = 1'b0;
  logic ef_pg_rqe = 1'b0;  // efuse_req_error at the AW of the go (X or Z counts as set)
  logic ef_pg_stmk = 1'b0;  // secure_tm_i known at the go
  logic ef_pg_clean = 1'b0;  // the four status flags known and 0 at the AW of the go
  logic [1:0] ef_pg_tok = '0;  // {RMA_CHIPLET, RMA_SIP} matched at the go
  logic ef_pg_seen = 1'b0;
  logic [31:0] ef_pg_pre = '0;  // sensed word of the target before the program
  logic ef_pg_lock_open = 1'b0;  // waits for the STATUS read that ends it
  logic ef_pg_idle_open = 1'b0;  // waits for the idle interface
  int unsigned ef_pg_cnt = 0;
  logic ef_rg_v = 1'b0;
  logic [15:0] ef_rg_addr = '0;
  logic ef_rg_en = 1'b0, ef_rg_pen = 1'b0;
  logic ef_rg_rqe = 1'b0;  // efuse_req_error at the AW of the go (X or Z counts as set)
  logic ef_rg_clean = 1'b0;  // the four status flags known and 0 at the AW of the go
  logic ef_rg_rcmd = 1'b0;  // a READ command reached the shim since the AW of the go
  logic ef_rg_lock_open = 1'b0, ef_rg_idle_open = 1'b0, ef_rg_win_open = 1'b0;
  int unsigned ef_rg_cnt = 0;
  logic ef_aw_rcmd_v = 1'b0;
  always @(posedge clk_i) begin
    if (aw_hs) ef_aw_rcmd_v <= ef_cmd_rd;
    else if (ef_cmd_rd) ef_aw_rcmd_v <= 1'b1;
  end
  wire ef_pg_go = wr_okay && (aw_addr_q == EfPgCtrl) && |(wr_data & EfPgGoMask);
  wire ef_rg_go = wr_okay && (aw_addr_q == EfRdCtrl) && |(wr_data & EfRdGoMask);
  wire ef_status_rd = rd_okay && (ar_addr_q == EfStatus);
  wire ef_idle = (efuse_read_busy_i === 1'b0) && (efuse_program_busy_i === 1'b0);
  // Observed flags {read_status, read_addr, program_addr, req}. A flag with an X or Z
  // bit gives 4'b1110, which is a wrong value in every case of cp_flags and
  // x_case_flags.
  wire [3:0] ef_flags = $isunknown({efuse_read_error_i, rd_addr_err_i, pg_addr_err_i, req_err_i}) ?
      4'b1110 : {efuse_read_error_i, rd_addr_err_i, pg_addr_err_i, req_err_i};

  // Case of a request (efuse_interface_ctrl.adoc): 0 pre_sense_prog,
  // 1 read_no_enable, 2 read_oob, 3 prog_oob, 4 prog_wlocked, 5
  // read_rlocked, 6 both_enables, 7 prog_data0, 8 accepted twin, 15 none.
  function automatic logic [3:0] ef_pg_case(input logic [15:0] a, input logic d, input logic en,
                                            input logic sensed);
    if (!sensed) return 4'd0;
    if (a >= 16'(EfFuseBits)) return 4'd3;
    if (ef_wlock(ef_slot_of(11'(a[12:3])))) return 4'd4;
    if (!d) return 4'd7;
    if (en) return 4'd8;
    return 4'd15;
  endfunction
  function automatic logic [3:0] ef_rg_case(input logic [15:0] a, input logic en, input logic pen);
    if (!en) return 4'd1;
    if (pen) return 4'd6;
    if (a >= 16'(EfFuseBits)) return 4'd2;
    if (ef_rlock(ef_slot_of(11'(a[12:3])))) return 4'd5;
    return 4'd8;
  endfunction
  logic [3:0] ef_pg_cs = 4'd15, ef_rg_cs = 4'd15;

  // Window of x_case_cmd for pre_sense_prog: reset release to sense done.
  logic ef_ps_go = 1'b0, ef_ps_prog = 1'b0;
  // both_enables: from the go to the next cold reset.
  logic ef_be_arm = 1'b0, ef_be_rcmd = 1'b0;

  // x_exempt_write: a landed program of LC_STATE bit 0 or 3 waits for the
  // resensed LC_STATE read. ef_xw_req counts the landed programs; the
  // tracker below takes each one.
  int unsigned ef_xw_req = 0;
  logic ef_xw_req_bit3 = 1'b0;
  // Lock policy, if-status and secure test mode sampling of a program end.
  task automatic ef_prog_lock_end();
    logic [5:0] s, sn;
    logic wl, rl, landed;
    logic [9:0] off;
    off = ef_pg_addr[12:3];
    s = ef_slot_of({1'b0, off});
    landed = ef_pg_seen;
    // A refusal cell fills only when the write-lock is the one cause left: the go
    // carries program_enable, efuse_req_error is known 0 at the go, sense is done and
    // secure test mode is known off. The outcome is taken at least EfReqWait clocks
    // after the go, so a late program command still counts as landed.
    if (ef_own_lock && ef_pg_data && ef_pg_en && !ef_pg_rqe && ef_pg_sensed && ef_pg_stmk &&
        !ef_pg_stm &&
        (ef_pg_addr < 16'(EfFuseBits)) && (s != EfNoSlot) && (s != 6'd0)) begin
      wl = ef_wlock(s);
      rl = ef_rlock(s);
      ef_lk(0, {landed == wl, 7'((s - 6'd1) * 2) + 7'(wl)});
      ef_lk(2, 8'({landed == wl, rl, wl, 1'b0}));
      if (!wl && !rl && landed) begin
        if (ef_wlock(s - 6'd1) || ef_rlock(s - 6'd1)) ef_lk(3, 8'd0);
        sn = s + 6'd1;
        if ((sn < 6'(EfSlots)) && (ef_wlock(sn) || ef_rlock(sn))) ef_lk(3, 8'd2);
      end
      // cp_prog_visibility bin 0: the programmed bit was 0 before the program.
      if (landed && !ef_pg_pre[ef_pg_addr[4:0]] && (ef_word(off) === ef_pg_pre)) ef_lk(8, 8'd0);
    end
    // x_lc_prog_gate: LC_STATE bit 1 is gated by the RMA_SIP match, bit 2 by
    // the RMA_CHIPLET match (otp_fuse_controller.adoc, Fuse Programming and
    // RMA Authorization).
    // The same qualification: only the token gate can refuse the program.
    if (ef_own_tr && ef_pg_data && ef_pg_en && !ef_pg_rqe && ef_pg_sensed && ef_pg_stmk &&
        !ef_pg_stm) begin
      if (ef_pg_addr == 16'(SEP_EFUSE_MAP_LC_STATE_REG_OFFSET * 8 + 1)) begin
        if (ef_pg_tok[0]) ef_lk(10, {5'd0, 1'b0, 1'b0, landed});
        else if (ef_pg_tok[1]) ef_lk(10, {5'd0, 1'b0, 1'b1, landed});
      end else if (ef_pg_addr == 16'(SEP_EFUSE_MAP_LC_STATE_REG_OFFSET * 8 + 2)) begin
        if (ef_pg_tok[1]) ef_lk(10, {5'd0, 1'b1, 1'b0, landed});
      end
    end
    // x_exempt_write: LC_STATE ignores its lock bits, so with every lock bit
    // burned a program of bit 0 or bit 3 from TEST_DEV lands.
    if (ef_own_lock && ef_pg_data && ef_pg_en && !ef_pg_rqe && ef_pg_sensed && ef_pg_stmk &&
        !ef_pg_stm && ef_all_locked && (ef_lc == EfTd) &&
        ((ef_pg_addr == 16'(SEP_EFUSE_MAP_LC_STATE_REG_OFFSET * 8)) ||
         (ef_pg_addr == 16'(SEP_EFUSE_MAP_LC_STATE_REG_OFFSET * 8 + 3)))) begin
      if (!landed) begin
        ef_lk(11, 8'd2);
      end else begin
        ef_xw_req <= ef_xw_req + 1;
        ef_xw_req_bit3 <= (ef_pg_addr == 16'(SEP_EFUSE_MAP_LC_STATE_REG_OFFSET * 8 + 3));
      end
    end
  endtask

  // cp_prog_visibility bin 1: the next sense done after a landed program of a bit
  // that read 0 before the program.
  logic ef_pv_pend = 1'b0;
  logic [7:0] ef_pv_word = '0;
  logic [4:0] ef_pv_bit = '0;
  logic [31:0] ef_pv_pre = '0;

  always @(posedge clk_i) begin
    ef_stm_t te;
    logic [5:0] s;
    logic [9:0] off;
    logic [2:0] cls;
    if (in_reset) begin
      ef_pg_v <= 1'b0;
      ef_pg_lock_open <= 1'b0;
      ef_pg_idle_open <= 1'b0;
      ef_rg_v <= 1'b0;
      ef_rg_lock_open <= 1'b0;
      ef_rg_idle_open <= 1'b0;
      ef_rg_win_open <= 1'b0;
    end else begin
      // Program go.
      if (ef_pg_go) begin
        ef_pg_v <= 1'b1;
        ef_pg_addr <= 16'(wr_data & EfPgAddrMask);
        ef_pg_data <= |(wr_data & EfPgDataMask);
        ef_pg_en <= |(wr_data & EfPgEnMask);
        ef_pg_sensed <= (fuse_sense_done_i === 1'b1);
        ef_pg_stm <= (secure_tm_i === 1'b1);
        ef_pg_stmk <= !$isunknown(secure_tm_i);
        ef_pg_rqe <= ef_aw_flags[0] || ef_aw_flx;
        ef_pg_clean <= !ef_aw_flx && !ef_aw_rderr && (ef_aw_flags == 3'b000);
        ef_pg_tok <= {tok_chp_i == EfCodeMatch, tok_sip_i == EfCodeMatch};
        ef_pg_seen <= ef_aw_pcmd_v && (13'(wr_data & EfPgAddrMask) == ef_aw_pcmd_addr) &&
            ((wr_data & EfPgAddrMask) < 32'(EfFuseBits));
        ef_pg_pre <= ef_aw_shadow[32*(wr_data[12:5])+:32];
        ef_pg_lock_open <= 1'b1;
        ef_pg_idle_open <= 1'b1;
        ef_pg_cnt <= 0;
        ef_pg_cs <= ef_pg_case(16'(wr_data & EfPgAddrMask), |(wr_data & EfPgDataMask),
                               |(wr_data & EfPgEnMask), fuse_sense_done_i === 1'b1);
        if (fuse_sense_done_i !== 1'b1) ef_ps_go <= 1'b1;
      end else if (ef_pg_v) begin
        if (ef_cmd_pg && (16'(ef_cmd_addr) == ef_pg_addr)) ef_pg_seen <= 1'b1;
        if (ef_pg_cnt < EfBothWin) ef_pg_cnt <= ef_pg_cnt + 1;
        // The STATUS read that ends the request counts only EfReqWait clocks or
        // more after the go.
        if (ef_pg_lock_open && ef_status_rd && (efuse_program_busy_i === 1'b0) &&
            (ef_pg_cnt >= EfReqWait)) begin
          ef_pg_lock_open <= 1'b0;
          ef_prog_lock_end();
          if (ef_own_lock && ef_pg_data && ef_pg_seen) begin
            ef_pv_pend <= 1'b1;
            ef_pv_word <= ef_pg_addr[12:5];
            ef_pv_bit <= ef_pg_addr[4:0];
            ef_pv_pre <= ef_pg_pre;
          end
        end
        if (ef_pg_idle_open && (ef_pg_cnt >= EfReqWait) && ef_idle) begin
          ef_pg_idle_open <= 1'b0;
          // sep_efuse_if_status_cg program cases and twin. The flags are sampled
          // only for a go whose four flags were known and 0 at its AW, so a flag
          // left set by an earlier request never stands for this one.
          if (ef_own_ifs && (ef_pg_cs != 4'd15)) begin
            if (ef_pg_cs == 4'd8) begin
              if (ef_pg_clean) begin
                ef_ifs(1, 7'(ef_flags));
                if (ef_pg_seen && (ef_flags == 4'b0000)) ef_ifs(7, 7'd1);
              end
            end else begin
              ef_ifs(0, 7'(ef_pg_cs));
              if (ef_pg_clean) begin
                ef_ifs(2, {ef_pg_cs[2:0], ef_flags});
                if (ef_pg_cs inside {4'd3, 4'd4}) ef_ifs(1, 7'(ef_flags));
              end
            end
          end
          // x_prog_block: program class at the strap of the go. LC_STATE is
          // gated by the token and is not a class.
          off = ef_pg_addr[12:3];
          s = ef_slot_of({1'b0, off});
          cls = 3'd7;
          if (off < 10'(SEP_EFUSE_MAP_LC_STATE_REG_OFFSET)) cls = 3'd3;
          else if (s inside {EfSlotSipDis, EfSlotSysDis}) cls = 3'd2;
          else if ((s >= EfSlotSpare0) && (s < 6'(EfSlots))) cls = 3'd4;
          else if ((s != 6'd0) && (s != EfNoSlot) && ((EfSlotOff[s+1] - EfSlotOff[s]) == 11'd32))
            cls = 3'd0;
          else if ((s != 6'd0) && (s != EfNoSlot) && ((EfSlotOff[s+1] - EfSlotOff[s]) == 11'd4))
            cls = 3'd1;
          // Only the strap can refuse the program: program_enable at the go, no
          // efuse_req_error at the go and no write-lock on the slot.
          if (ef_own_stm && ef_pg_data && ef_pg_en && !ef_pg_rqe && ef_pg_sensed && ef_pg_stmk &&
              (ef_pg_addr < 16'(EfFuseBits)) && (cls != 3'd7) &&
              ((s == EfNoSlot) || !ef_wlock(
                  s
              ))) begin
            te = '0;
            te.pb = {ef_pg_seen == ef_pg_stm, 4'(cls * 2) + 4'(ef_pg_stm)};
            te.pb_v = 1'b1;
            u_sep_efuse_secure_tm_cg.sample(te);
          end
        end
        if (!ef_pg_lock_open && !ef_pg_idle_open) ef_pg_v <= 1'b0;
      end

      // Read go.
      if (ef_rg_go) begin
        ef_rg_v <= 1'b1;
        ef_rg_addr <= 16'(wr_data & EfRdAddrMask);
        ef_rg_en <= |(wr_data & EfRdEnMask);
        ef_rg_pen <= ef_pen_q;
        ef_rg_rqe <= ef_aw_flags[0] || ef_aw_flx;
        ef_rg_clean <= !ef_aw_flx && !ef_aw_rderr && (ef_aw_flags == 3'b000);
        ef_rg_rcmd <= ef_aw_rcmd_v;
        ef_rg_lock_open <= 1'b1;
        ef_rg_idle_open <= 1'b1;
        ef_rg_win_open <= 1'b0;
        ef_rg_cnt <= 0;
        ef_rg_cs <= ef_rg_case(16'(wr_data & EfRdAddrMask), |(wr_data & EfRdEnMask), ef_pen_q);
        if (ef_rg_case(
                16'(wr_data & EfRdAddrMask), |(wr_data & EfRdEnMask), ef_pen_q
            ) == 4'd6) begin
          ef_be_arm <= 1'b1;
          ef_be_rcmd <= ef_aw_rcmd_v;
        end
      end else if (ef_rg_v) begin
        if (ef_cmd_rd) ef_rg_rcmd <= 1'b1;
        if (ef_rg_cnt < EfBothWin) ef_rg_cnt <= ef_rg_cnt + 1;
        // x_slot_read and x_kind_op, read-locked kind: the STATUS read that
        // ends the request carries efuse_req_error. The flag is 0 at the go,
        // so only this request can have set it.
        if (ef_rg_lock_open && ef_status_rd && (efuse_read_busy_i === 1'b0)) begin
          ef_rg_lock_open <= 1'b0;
          s = ef_slot_of(11'(ef_rg_addr[12:3]));
          if (ef_own_lock && ef_rg_en && !ef_rg_pen && !ef_rg_rqe && (ef_rg_addr < 16'(EfFuseBits)) &&
              (s != EfNoSlot) && (s != 6'd0) && ef_rlock(
                  s
              )) begin
            // Refused only on a known efuse_req_error of 1.
            ef_lk(1, {(rd_data & EfReqErrMask) !== EfReqErrMask, 7'((s - 6'd1) * 2 + 1)});
            ef_lk(2, 8'({(rd_data & EfReqErrMask) !== EfReqErrMask, 1'b1, ef_wlock(s), 1'b1}));
          end
        end
        if (ef_rg_idle_open && (((ef_rg_cnt >= EfReqWait) && ef_idle && (ef_rg_cs != 4'd6)) ||
                                ((ef_rg_cs == 4'd6) && (ef_rg_cnt == EfBothWin)))) begin
          ef_rg_idle_open <= 1'b0;
          ef_rg_win_open <= (ef_rg_cs == 4'd5);
          ef_rg_cnt <= 0;
          if (ef_own_ifs) begin
            if (ef_rg_cs == 4'd8) begin
              if (ef_rg_clean) begin
                ef_ifs(1, 7'(ef_flags));
                if ((efuse_read_done_i === 1'b1) && (efuse_read_error_i === 1'b0)) ef_ifs(7, 7'd0);
              end
            end else begin
              ef_ifs(0, 7'(ef_rg_cs));
              if (ef_rg_clean) begin
                ef_ifs(2, {ef_rg_cs[2:0], ef_flags});
                if (ef_rg_cs inside {4'd1, 4'd2}) ef_ifs(1, 7'(ef_flags));
              end
            end
          end
        end
        // x_case_cmd read_rlocked: no READ command from the go to the first
        // STATUS read after the idle sample. The owner makes that read at the end
        // of the window W, so the sampled window covers W.
        if (ef_rg_win_open && !ef_rg_idle_open && ef_status_rd) begin
          ef_rg_win_open <= 1'b0;
          if (ef_own_ifs) ef_ifs(3, {4'd0, 2'd1, ef_rg_rcmd || ef_cmd_rd});
        end
        if (!ef_rg_lock_open && !ef_rg_idle_open && !ef_rg_win_open) ef_rg_v <= 1'b0;
      end
    end
  end

  // x_case_cmd pre_sense_prog and both_enables windows; cp_prog_visibility
  // bin 1. These span a reset, so they do not clear on it.
  always @(posedge clk_i) begin
    if (ef_rel) begin
      ef_ps_go   <= 1'b0;
      ef_ps_prog <= 1'b0;
    end else if (!in_reset && ef_cmd_pg && (fuse_sense_done_i !== 1'b1)) begin
      ef_ps_prog <= 1'b1;
    end
    if (ef_sense_rise) begin
      if (ef_ps_go && ef_own_ifs) ef_ifs(3, {4'd0, 2'd0, ef_ps_prog});
      if (ef_pv_pend && ef_own_lock) begin
        if (!ef_pv_pre[ef_pv_bit] && (efuse_shadow_i[32*ef_pv_word+ef_pv_bit] === 1'b1) &&
            ((efuse_shadow_i[32*ef_pv_word+:32] & ef_pv_pre) === ef_pv_pre)) begin
          ef_lk(8, 8'd1);
        end
      end
      ef_pv_pend <= 1'b0;
    end
    if (ef_be_arm) begin
      if (ef_cmd_rd && !in_reset) ef_be_rcmd <= 1'b1;
      if (ef_rst_fall) begin
        if (ef_own_ifs) ef_ifs(3, {4'd0, 2'd2, ef_be_rcmd});
        ef_be_arm <= 1'b0;
      end
    end
  end

  // ---------------------------------------------------------------------
  // Frontdoor reads of the shadow map: x_slot_read and x_kind_op (lock
  // clear), x_neighbor_free (read), x_exempt, x_secret_probe and
  // x_secret_read_kept.
  // ---------------------------------------------------------------------
  always @(posedge clk_i) begin
    ef_stm_t te;
    logic [10:0] off;
    logic [5:0] s, sn;
    logic [2:0] f;
    logic bad;
    if (ef_rd_cmpl && (ef_rd_win == EfWShadow) && (fuse_sense_done_i === 1'b1)) begin
      off = 11'(ar_addr_q - EfMapBase);
      s = ef_slot_of(off);
      f = ef_secret_of(s);
      // Lock leaf reads at strap 0, where the frontdoor and the sensed-shadow
      // output carry the same word. A read that is not blocked earns its cell
      // only on a known non-zero sensed word, because a blocked read that
      // returns 0 equals a zero word. A known mismatch still reaches the
      // wrong-outcome bins.
      if (rd_okay && ef_own_lock && (secure_tm_i === 1'b0) && !$isunknown(
              rd_data
          ) && !$isunknown(
              ef_word(off[9:0])
          )) begin
        if ((s != EfNoSlot) && (s != 6'd0) && !ef_rlock(s)) begin
          bad = (rd_data != ef_word(off[9:0]));
          if (bad || (ef_word(off[9:0]) != 32'h0)) begin
            ef_lk(1, {bad, 7'((s - 6'd1) * 2)});
            ef_lk(2, 8'({bad, 1'b0, ef_wlock(s), 1'b1}));
            if (!ef_wlock(s) && !bad) begin
              if (ef_wlock(s - 6'd1) || ef_rlock(s - 6'd1)) ef_lk(3, 8'd1);
              sn = s + 6'd1;
              if ((sn < 6'(EfSlots)) && (ef_wlock(sn) || ef_rlock(sn))) ef_lk(3, 8'd3);
            end
          end
        end
        if (ef_all_locked && (ef_word(off[9:0]) != 32'h0) && (rd_data == ef_word(off[9:0]))) begin
          if (ar_addr_q == SEP_EFUSE_MAP_LC_STATE_REG_ADDR) ef_lk(4, 8'd0);
          if (ar_addr_q inside {SEP_EFUSE_MAP_LOCKS_REG_ADDR, SEP_EFUSE_MAP_LOCKS_REG_ADDR + 32'd4})
            ef_lk(4, 8'd1);
          if (ar_addr_q == SEP_EFUSE_MAP_LOCKS_SPARE_REG_ADDR) ef_lk(4, 8'd2);
        end
      end
      if (ef_own_stm && (secure_tm_i === 1'b1) && (f != 3'd4)) begin
        te = '0;
        // A probe word with an X or Z bit counts as nonzero.
        if (stored_shadow_i[32*off[9:2]+:32] != 32'h0) begin
          te.sp = {f[1:0], ef_word(off[9:0]) !== 32'h0};
          te.sp_v = 1'b1;
        end
        if (rd_okay && !ef_rlock(s) && (rd_data != 32'h0)) begin
          te.sk = f[1:0];
          te.sk_v = 1'b1;
        end
        u_sep_efuse_secure_tm_cg.sample(te);
      end
    end
  end

  // cp_sense_fills_locked and cp_round_count at sense done. The previous
  // sensed copy survives the cold reset between two senses.
  logic [EfFuseBits-1:0] ef_rc_prev = '0;
  logic ef_rc_pv = 1'b0;
  int unsigned ef_rc_k = 0;
  always @(posedge clk_i) begin
    logic sec, oth;
    int unsigned k;
    if (ef_sense_rise) begin
      sec = 1'b0;
      oth = 1'b0;
      for (int s = 1; s < EfSlots; s++) begin
        if (ef_rlock(6'(s)) && ef_field_nz(6'(s))) begin
          if (ef_secret_of(6'(s)) != 3'd4) sec = 1'b1;
          else oth = 1'b1;
        end
      end
      if (ef_own_lock && sec) ef_lk(5, 8'd0);
      if (ef_own_lock && oth) ef_lk(5, 8'd1);
      k = (ef_rc_pv && ((efuse_shadow_i & ~ef_rc_prev) != '0)) ? ef_rc_k + 1 : 0;
      if (ef_own_lock && (k >= 1) && (k <= 4)) ef_lk(9, 8'(k));
      ef_rc_k <= k;
      ef_rc_prev <= efuse_shadow_i;
      ef_rc_pv <= 1'b1;
    end
  end

  // ---------------------------------------------------------------------
  // Write effects, EfWrSettle clocks after the B of a frontdoor write, against
  // the state at its AW: x_shadow_write_lock, cp_lock_order,
  // cp_export_changes, sep_lc_demote_lock_cg, cp_no_clear and cp_flag_clear.
  // A second write that completes inside the settle drops the first (a
  // missed hit, never a false one).
  // ---------------------------------------------------------------------
  logic ef_pw_v = 1'b0;
  int unsigned ef_pw_cnt = 0;
  logic [31:0] ef_pw_addr = '0, ef_pw_data = '0;
  logic ef_pw_ok = 1'b0;
  logic [EfFuseBits-1:0] ef_pw_shadow = '0;
  logic [63:0] ef_pw_feat = '0;
  logic [1:0] ef_pw_d1 = 2'b10, ef_pw_d2 = 2'b10;
  logic ef_pw_l1 = 1'b0, ef_pw_l2 = 1'b0;
  logic [2:0] ef_pw_fault = '0, ef_pw_flags = '0;
  logic ef_pw_flx = 1'b0, ef_pw_dx = 1'b0;

  always @(posedge clk_i) begin
    ef_dem_t me;
    ef_dlk_t ke;
    logic [10:0] off;
    logic [5:0] s;
    logic [31:0] pre, now, pre_l, now_l;
    logic [1:0] f;
    logic wl, wr_ok, chg, r, ol, od, nd, nl, l_other, d_other_pre, d_other_now, nx;
    logic [23:0] dis_grp;
    logic [1:0] wcls;
    logic [2:0] clr, now_flags;
    if (in_reset) begin
      ef_pw_v <= 1'b0;
    end else if (ef_wr_cmpl) begin
      ef_pw_v <= 1'b1;
      ef_pw_cnt <= 0;
      ef_pw_addr <= aw_addr_q;
      ef_pw_data <= wr_data;
      ef_pw_ok <= (lsu_b_resp_i === AxiOkay);
      ef_pw_shadow <= ef_aw_shadow;
      ef_pw_feat <= ef_aw_feat;
      ef_pw_d1 <= ef_aw_d1;
      ef_pw_d2 <= ef_aw_d2;
      ef_pw_l1 <= ef_aw_l1;
      ef_pw_l2 <= ef_aw_l2;
      ef_pw_fault <= ef_aw_fault;
      ef_pw_flags <= ef_aw_flags;
      ef_pw_flx <= ef_aw_flx;
      ef_pw_dx <= ef_aw_dx;
    end else if (ef_pw_v && (ef_pw_cnt < EfWrSettle)) begin
      ef_pw_cnt <= ef_pw_cnt + 1;
    end else if (ef_pw_v) begin
      ef_pw_v <= 1'b0;
      // Shadow writes (sensed shadow before and after).
      if (ef_win(ef_pw_addr) == EfWShadow) begin
        off = 11'(ef_pw_addr - EfMapBase);
        s = ef_slot_of(off);
        pre = ef_pw_shadow[32*off[9:2]+:32];
        now = ef_word(off[9:0]);
        // Write-lock as the LOCKS words of the shadow held at the AW.
        wl = (s < 6'd32) ? ef_pw_shadow[32*EfWLocks+2*s] :
            (s < 6'(EfSlots)) ? ef_pw_shadow[32*EfWLocksSp+2*(s-6'd32)] : 1'b0;
        f = (s == EfSlotSipDis) ? 2'd0 : (s == EfSlotSysDis) ? 2'd1 : (s == EfSlotSigners) ? 2'd2 : 2'd3;
        // An open write lands as the OR of the shadow and the write data; a locked
        // write leaves the shadow unchanged. Any other value, or an X or Z bit
        // after the write, is a wrong outcome for either lock value.
        if (ef_own_lock && (s inside {EfSlotSipDis, EfSlotSysDis, EfSlotSigners, EfSlotAlgs}) &&
            !$isunknown(
                pre
            ) && !$isunknown(
                ef_pw_data
            ) && ((ef_pw_data & ~pre) != 32'h0)) begin
          wr_ok = wl ? (now === pre) : (now === (pre | ef_pw_data));
          ef_lk(6, 8'({!wr_ok, f, wl}));
          if (!wl && wr_ok) ef_lk(7, 8'd0);
          if (wl && wr_ok) ef_lk(7, 8'd1);
        end
        // A write that clears a set lock bit leaves every set bit set.
        if (ef_own_lock && (s == EfNoSlot) && (pre != 32'h0) && ((ef_pw_data & pre) != pre) &&
            ((now & pre) == pre)) begin
          ef_lk(7, 8'd2);
        end
      end
      // DEMOTE_1 / DEMOTE_2 (sep_lifecycle_ctrl.adoc, DEMOTE_1: demote bit 0,
      // lock bit 1).
      // The demote and lock outputs are known at the AW. An X or Z output after
      // the write counts as a change: a wrong outcome for a locked register, and
      // no cell for an open one.
      if (ef_pw_ok && !ef_pw_dx && (ef_pw_addr inside {EfDemote1, EfDemote2})) begin
        r = (ef_pw_addr == EfDemote2);
        od = r ? (ef_pw_d2 == 2'b01) : (ef_pw_d1 == 2'b01);
        ol = r ? ef_pw_l2 : ef_pw_l1;
        nd = r ? (demote_2_i == 2'b01) : (demote_1_i == 2'b01);
        nl = r ? (demote_lock_2_i === 1'b1) : (demote_lock_1_i === 1'b1);
        l_other = r ? ef_pw_l1 : ef_pw_l2;
        d_other_pre = r ? (ef_pw_d1 == 2'b01) : (ef_pw_d2 == 2'b01);
        d_other_now = r ? (demote_1_i == 2'b01) : (demote_2_i == 2'b01);
        chg = (od != nd) || (ol != nl);
        nx = r ? $isunknown({demote_2_i, demote_lock_2_i}) : $isunknown({demote_1_i, demote_lock_1_i});
        if (nx) chg = 1'b1;
        wcls = (ef_pw_data == EfDemoteMask) ? 2'd0 : (ef_pw_data == EfDemLockMask) ? 2'd1 :
            (ef_pw_data == 32'h0) ? 2'd2 : 2'd3;
        if (ef_own_fc) begin
          if (|(ef_pw_data & EfDemoteMask) && !nx) begin
            me = '0;
            me.ex = r;
            me.ex_v = r ? (demote_2_i != ef_pw_d2) : (demote_1_i != ef_pw_d1);
            u_sep_lc_demotion_cg.sample(me);
          end
          ke = '0;
          if ((wcls != 2'd3) && !((wcls == 2'd0) && od) && !(nx && !ol)) begin
            ke.rl = {r, ol, wcls, chg};
            ke.rl_v = 1'b1;
          end
          if (ol && (wcls inside {2'd0, 2'd2})) begin
            ke.cn = {r, od, wcls == 2'd2, chg};
            ke.cn_v = 1'b1;
          end
          if (!ol && chg && !nx && l_other) begin
            ke.ci = r;
            ke.ci_v = 1'b1;
          end
          // cp_profile_unchanged: a set-demote write to a locked register that would
          // change the profile if the register were open. The old demote is 0,
          // SEC_DIS is off and the state is TEST_DEV or PROD; the DIS group the
          // register governs is non-zero in TEST_DEV (the demote forces it open) and
          // not all ones in PROD (the demote relaxes it to the DIS vectors)
          // (lifecycle_controller.adoc, Per-LC-state Feature Control Profile).
          dis_grp = ef_grp(ef_pw_shadow[32*EfWSipDis+:64] | ef_pw_shadow[32*EfWSysDis+:64], r);
          if (ol && |(ef_pw_data & EfDemoteMask) && !od && (sec_dis_i === 1'b0) && !$isunknown(
                  efuse_lc_raw_i
              ) && !$isunknown(
                  feat_ctrl_i
              ) && !$isunknown(
                  dis_grp
              ) && (feat_ctrl_i == ef_pw_feat) && (d_other_pre == d_other_now) &&
                  (((ef_lc == EfTd) && (dis_grp != 24'h0)) ||
                   ((ef_lc == EfProd) && (dis_grp != ef_gmask(
                  int'(r)
              ))))) begin
            ke.pu = r;
            ke.pu_v = 1'b1;
          end
          u_sep_lc_demote_lock_cg.sample(ke);
        end
      end
      // TOKEN_MATCH_FAULT (efuse_mmr.adoc): an accepted (OKAY) write of 1 to a set
      // bit. A write the bus refuses never reaches the register, so it shows no
      // "no clear".
      if ((ef_pw_addr == EfMatchFault) && ef_pw_ok && ef_own_tf) begin
        if (|(ef_pw_data & EFUSE_MMR_TOKEN_MATCH_FAULT_RMA_SIP_TOKEN_FAULT_MASK) && ef_pw_fault[0] &&
            (tok_fault_i[0] === 1'b1))
          ef_tfs(4, 5'd0);
        if (|(ef_pw_data & EFUSE_MMR_TOKEN_MATCH_FAULT_RMA_CHIPLET_TOKEN_FAULT_MASK) && ef_pw_fault[1] &&
            (tok_fault_i[1] === 1'b1))
          ef_tfs(4, 5'd1);
        if (|(ef_pw_data & EFUSE_MMR_TOKEN_MATCH_FAULT_SECURE_DISABLE_TOKEN_FAULT_MASK) &&
            ef_pw_fault[2] && (tok_fault_i[2] === 1'b1))
          ef_tfs(4, 5'd2);
      end
      // EFUSE_INTERFACE_CTRL_STATUS: one clear bit written over a set flag;
      // the flag falls and the other flags keep their values.
      if ((ef_pw_addr == EfStatus) && ef_own_ifs) begin
        clr = {|(ef_pw_data & EfRdAddrClrMask), |(ef_pw_data & EfPgAddrClrMask),
               |(ef_pw_data & EfReqErrClrMask)};
        now_flags = {rd_addr_err_i === 1'b1, pg_addr_err_i === 1'b1, req_err_i === 1'b1};
        // The flags are known at the AW and after the settle, so an X or Z never
        // reads as a fall or as an unchanged flag.
        if (($countones(
                clr
            ) == 1) && !ef_pw_flx && !$isunknown(
                {rd_addr_err_i, pg_addr_err_i, req_err_i}
            )) begin
          if (clr[2] && ef_pw_flags[2] && !now_flags[2] && (now_flags[1:0] == ef_pw_flags[1:0]))
            ef_ifs(4, 7'd0);
          if (clr[1] && ef_pw_flags[1] && !now_flags[1] &&
              ({now_flags[2], now_flags[0]} == {ef_pw_flags[2], ef_pw_flags[0]}))
            ef_ifs(4, 7'd1);
          if (clr[0] && ef_pw_flags[0] && !now_flags[0] && (now_flags[2:1] == ef_pw_flags[2:1]))
            ef_ifs(4, 7'd2);
        end
      end
    end
  end

  // ---------------------------------------------------------------------
  // sep_lc_demotion_cg clocked points: cp_assert_order and cp_reset_vector.
  // The reset vector is taken on the last clock before rst_ni falls and
  // checked at the next sense done, so the tracker does not clear on reset.
  // ---------------------------------------------------------------------
  logic [1:0] ef_ao_first = 2'd0;  // 1 DEMOTE_1 first, 2 DEMOTE_2 first
  logic ef_ao_both_q = 1'b0;
  logic [3:0] ef_rv_last = '0, ef_rv_vec = '0;
  logic ef_rv_pend = 1'b0;
  always @(posedge clk_i) begin
    ef_dem_t me;
    logic [3:0] vec;
    // An X or Z demote or lock output keeps its unknown bit in the vector.
    vec = {ef_d1, demote_lock_1_i, ef_d2, demote_lock_2_i};
    if (!in_reset) begin
      ef_rv_last <= vec;
      ef_ao_both_q <= ef_d1 && ef_d2;
      if (!ef_d1 && !ef_d2) ef_ao_first <= 2'd0;
      else if ((ef_ao_first == 2'd0) && ef_d1 && !ef_d2) ef_ao_first <= 2'd1;
      else if ((ef_ao_first == 2'd0) && ef_d2 && !ef_d1) ef_ao_first <= 2'd2;
      if (ef_d1 && ef_d2 && !ef_ao_both_q && (ef_ao_first != 2'd0) && ef_own_fc && ef_sensed) begin
        me = '0;
        me.ao = (ef_ao_first == 2'd2);
        me.ao_v = 1'b1;
        u_sep_lc_demotion_cg.sample(me);
      end
    end else begin
      ef_ao_first <= 2'd0;
      ef_ao_both_q <= 1'b0;
    end
    if (ef_rst_fall) begin
      // The reset starts inside the graded window of the owner.
      ef_rv_pend <= ef_own_fc && !$isunknown(ef_rv_last);
      ef_rv_vec  <= ef_rv_last;
    end
    if (ef_sense_rise && ef_rv_pend) begin
      ef_rv_pend <= 1'b0;
      if (ef_own_fc && (vec == 4'h0) && !$isunknown(
              {demote_1_i, demote_2_i, demote_lock_1_i, demote_lock_2_i}
          )) begin
        me = '0;
        me.rv = ef_rv_vec;
        me.rv_v = 1'b1;
        u_sep_lc_demotion_cg.sample(me);
      end
    end
  end

  // ---------------------------------------------------------------------
  // Token channels. A go on channel c arms a tracker; its verdict is the
  // first non-idle code after the code has read idle at least once since
  // the go (token_processing.adoc, Token Submission: a start clears digest
  // validity, so the comparison reads idle until the new digest is there).
  // Channel 0 RMA_SIP, 1 RMA_CHIPLET, 2 SEC_DIS.
  // ---------------------------------------------------------------------
  logic [2:0] ef_go_arm = '0, ef_go_idle = '0, ef_go_busy0 = '0, ef_go_sensed = '0;
  logic [2:0] ef_go_others_ok = '0, ef_go_fault = '0, ef_go_replay = '0;
  logic [2:0][1:0] ef_go_shape = '0;
  logic [2:0] ef_go_shape_v = '0;
  logic [2:0] ef_pre_arm = '0, ef_pre_bad = '0;  // RMA go before sense done
  // An RMA go before sense done whose code read idle until a reset ended the
  // epoch with sense done still low: the result waits for a later sense.
  logic [1:0] ef_pre_carry = '0, ef_pre_csd = '0;
  // Token words of the last go of each channel, and the words of a go that
  // gave Match since the last reset (the token of that channel, as the DUT
  // itself judged it).
  logic [2:0][7:0][31:0] ef_go_words = '0, ef_match_words = '0;
  logic [2:0] ef_match_v = '0;
  logic [2:0][5:0] ef_code_q = '0;
  logic [2:0][7:0][31:0] ef_words_q = '0;
  // Array c changed since its last go.
  logic [2:0] ef_arr_dirty = '1;
  logic [2:0] ef_hw_arm = '0;
  logic [2:0][5:0] ef_hw_code = '0;
  int unsigned ef_hw_cnt[3] = '{0, 0, 0};
  logic [2:0] ef_fault_q = '0;
  logic [7:0][31:0] ef_ret_words = '0, ef_last_sipw = '0;
  logic [5:0] ef_last_sipc = '0;
  logic ef_ret_pend = 1'b0, ef_ret_wait = 1'b0, ef_ret_nogo = 1'b0;
  wire [2:0][255:0] ef_dig = {
    sec_disable_expected_i, efuse_shadow_i[32*EfWChipDig+:256], efuse_shadow_i[32*EfWSipDig+:256]
  };

  // A code with an X or Z bit is neither idle nor non-idle.
  function automatic logic ef_nonidle(input logic [5:0] c);
    return (c != EfCodeIdle) && !$isunknown(c);
  endfunction
  function automatic logic ef_isidle(input logic [5:0] c);
    return (c === EfCodeIdle);
  endfunction
  // Words equal to a 256-bit value, in either word order. An X or Z bit on
  // either side is not equal, so an unwritten array never labels a replay.
  function automatic logic ef_words_eq(input logic [7:0][31:0] w, input logic [255:0] d);
    logic rev;
    if ($isunknown(w) || $isunknown(d)) return 1'b0;
    rev = 1'b1;
    for (int i = 0; i < 8; i++) if (w[i] !== d[32*(7-i)+:32]) rev = 1'b0;
    return (w === d) || rev;
  endfunction

  always @(posedge clk_i) begin
    logic [5:0] code, v;
    logic [1:0] o1, o2;
    if (!ef_live) begin
      ef_go_arm <= '0;
      ef_pre_arm <= '0;
      ef_hw_arm <= '0;
      ef_match_v <= '0;
      // A pre-sense go carries over a reset only while sense done is still low
      // and the code has read idle since the go; a carried one stays carried.
      if (ef_rst_fall) begin
        for (int c = 0; c < 2; c++) begin
          ef_pre_carry[c] <= (ef_pre_arm[c] && !ef_pre_bad[c]) || (ef_pre_carry[c] && !ef_pre_csd[c]);
        end
        ef_pre_csd <= '0;
      end
    end else begin
      for (int c = 0; c < 3; c++) begin
        code = ef_code[c];
        o1 = 2'((c + 1) % 3);
        o2 = 2'((c + 2) % 3);
        // cp_code: every new status value of each channel.
        if ((code !== ef_code_q[c]) && !$isunknown(code)) begin
          if ((code == EfCodeErr) ? ef_own_tf : (ef_own_tch || ((code != EfCodeIdle) &&
              (code != EfCodeMatch) && (code != EfCodeMismatch) && ef_own_tf))) begin
            ef_tc(1, code);
          end
        end
        if (token_go_i[c] === 1'b1) begin
          ef_go_arm[c] <= 1'b1;
          ef_go_idle[c] <= ef_isidle(code);
          ef_go_busy0[c] <= ef_nonidle(code);
          ef_go_sensed[c] <= (fuse_sense_done_i === 1'b1);
          ef_go_others_ok[c] <= ef_nonidle(ef_code[o1]) && ef_nonidle(ef_code[o2]);
          ef_go_fault[c] <= (tok_fault_i[c] === 1'b1);
          ef_go_replay[c] <= ef_words_eq(tok_words_i[c], ef_dig[c]);
          ef_go_words[c] <= tok_words_i[c];
          ef_go_shape_v[c] <= 1'b1;
          if (tok_words_i[c] == '0) ef_go_shape[c] <= 2'd0;
          else if (tok_words_i[c] == '1) ef_go_shape[c] <= 2'd1;
          else if ((ef_match_v[o1] && (tok_words_i[c] === ef_match_words[o1])) ||
                   (ef_match_v[o2] && (tok_words_i[c] === ef_match_words[o2])))
            ef_go_shape[c] <= 2'd2;
          else ef_go_shape_v[c] <= 1'b0;
          // A new go on an RMA channel ends a carried pre-sense go.
          if (c < 2) ef_pre_carry[c] <= 1'b0;
          if ((c < 2) && (fuse_sense_done_i !== 1'b1)) begin
            ef_pre_arm[c] <= 1'b1;
            ef_pre_bad[c] <= 1'b0;
          end
        end else if (ef_go_arm[c]) begin
          if (ef_isidle(code)) ef_go_idle[c] <= 1'b1;
          if ((ef_code[o1] !== ef_code_q[o1]) || (ef_code[o2] !== ef_code_q[o2]))
            ef_go_others_ok[c] <= 1'b0;
          if (ef_go_idle[c] && ef_nonidle(code)) begin
            ef_go_arm[c] <= 1'b0;
            if ((code == EfCodeMatch) && !ef_arr_dirty[c] && !$isunknown(ef_go_words[c])) begin
              ef_match_v[c] <= 1'b1;
              ef_match_words[c] <= ef_go_words[c];
            end
            if (ef_own_tch) begin
              if (code inside {EfCodeMatch, EfCodeMismatch}) begin
                ef_tc(0, {1'b0, 2'(c), code == EfCodeMismatch});
                if (ef_go_shape_v[c] && !((c == 2) && (ef_go_shape[c] == 2'd0)))
                  ef_tc(2, {1'b0, code == EfCodeMatch, 4'(c * 3) + 4'(ef_go_shape[c])});
                if ((c < 2) && ef_go_sensed[c] && (code == EfCodeMatch))
                  ef_tc(3, {3'd0, 2'(c), 1'b1});
                if (ef_go_replay[c]) ef_rob(0, {2'(c), code == EfCodeMatch});
              end
              if (ef_go_others_ok[c] && (ef_code[o1] === ef_code_q[o1]) &&
                  (ef_code[o2] === ef_code_q[o2]))
                ef_tc(4, 6'(c));
              if (ef_go_busy0[c]) ef_tc(6, 6'(c));
            end
            // x_ch_retry: a valid go after a fault, with the sticky bit and
            // the interrupt line still high.
            if (ef_own_tf && ef_go_fault[c] && (tok_fault_i[c] === 1'b1) && ef_irq &&
                (code inside {EfCodeMatch, EfCodeMismatch}) && !((c == 2) && (code == EfCodeMismatch))) begin
              ef_tfs(3, 5'(c * 2) + 5'(code == EfCodeMismatch));
            end
          end
        end
        // x_rma_go_phase, before sense: the code reads idle (known) on every clock
        // until sense done.
        if (ef_pre_arm[c] && (fuse_sense_done_i !== 1'b1) && !ef_isidle(code))
          ef_pre_bad[c] <= 1'b1;
        if (ef_pre_arm[c] && ef_sense_rise) begin
          ef_pre_arm[c] <= 1'b0;
          if (ef_own_tch && !ef_pre_bad[c] && ef_isidle(code)) ef_tc(3, {3'd0, 2'(c), 1'b0});
        end
        // x_rma_go_phase, before sense, carried over a reset: the first non-idle
        // code after a later sense done, with no new go on the channel, is the
        // Match of the retained digest. A code other than a known idle before
        // sense done (an X or Z included), or a non-idle code other than Match
        // after it, ends the carry with no sample.
        if ((c < 2) && ef_pre_carry[c] && (token_go_i[c] !== 1'b1)) begin
          if (fuse_sense_done_i === 1'b1) ef_pre_csd[c] <= 1'b1;
          if ((fuse_sense_done_i !== 1'b1) && !ef_isidle(code)) begin
            ef_pre_carry[c] <= 1'b0;
          end else if (ef_nonidle(code)) begin
            ef_pre_carry[c] <= 1'b0;
            if (ef_own_tch && (fuse_sense_done_i === 1'b1) && (code == EfCodeMatch))
              ef_tc(3, {3'd0, 2'(c), 1'b0});
          end
        end
        // cp_hold_word_write: a token word changes while a non-idle code is
        // held, and the code is unchanged EfTokSettle clocks later.
        if ((tok_words_i[c] !== ef_words_q[c]) && ef_nonidle(code) && !ef_go_arm[c]) begin
          ef_hw_arm[c] <= 1'b1;
          ef_hw_code[c] <= code;
          ef_hw_cnt[c] <= 0;
        end else if (ef_hw_arm[c]) begin
          if ((token_go_i[c] === 1'b1) || (code !== ef_hw_code[c])) begin
            ef_hw_arm[c] <= 1'b0;
          end else if (ef_hw_cnt[c] == EfTokSettle) begin
            ef_hw_arm[c] <= 1'b0;
            if (ef_own_tch) ef_tc(5, 6'(c));
          end else begin
            ef_hw_cnt[c] <= ef_hw_cnt[c] + 1;
          end
        end
      end
    end
    ef_code_q <= ef_code;
    ef_words_q <= tok_words_i;
    for (int c = 0; c < 3; c++) begin
      if (token_go_i[c] === 1'b1) ef_arr_dirty[c] <= 1'b0;
      else if (tok_words_i[c] !== ef_words_q[c]) ef_arr_dirty[c] <= 1'b1;
    end
  end

  // cp_retention: a cold reset with an RMA_SIP Match held. The words and the
  // code are taken on the last clock before rst_ni falls. Bins 0 and 1 sample
  // EfTokSettle clocks after the release, not on the release clock. Bin 2 waits
  // for the first non-idle RMA_SIP code; a further reset that falls while the
  // code still reads idle and sense done has stayed low carries the wait into
  // the next epoch.
  logic ef_ret_chk = 1'b0, ef_ret_sd = 1'b0;
  int unsigned ef_ret_cnt = 0;
  always @(posedge clk_i) begin
    if (!in_reset) begin
      ef_last_sipw <= tok_words_i[0];
      ef_last_sipc <= tok_sip_i;
    end
    if (ef_rst_fall) begin
      ef_ret_pend  <= ef_own_tch && (ef_last_sipc === EfCodeMatch);
      ef_ret_words <= ef_last_sipw;
      ef_ret_wait  <= ef_ret_wait && !ef_ret_sd && ef_isidle(ef_last_sipc);
      ef_ret_chk   <= 1'b0;
    end
    if (ef_rel && ef_ret_pend) begin
      ef_ret_pend <= 1'b0;
      ef_ret_chk  <= 1'b1;
      ef_ret_cnt  <= 0;
      ef_ret_nogo <= 1'b1;
    end else if (ef_ret_chk && !in_reset) begin
      if (token_go_i[0] === 1'b1) ef_ret_nogo <= 1'b0;
      if (ef_ret_cnt == EfTokSettle) begin
        ef_ret_chk  <= 1'b0;
        ef_ret_wait <= 1'b1;
        ef_ret_sd   <= (fuse_sense_done_i === 1'b1);
        if (ef_own_tch && !skip_fuse_sense_q) begin
          if (tok_words_i[0] === ef_ret_words) ef_tc(7, 6'd0);
          if (ef_isidle(tok_sip_i) && (fuse_sense_done_i === 1'b0)) ef_tc(7, 6'd1);
        end
      end else begin
        ef_ret_cnt <= ef_ret_cnt + 1;
      end
    end else if (ef_ret_wait && !in_reset) begin
      if (token_go_i[0] === 1'b1) ef_ret_nogo <= 1'b0;
      if (fuse_sense_done_i === 1'b1) ef_ret_sd <= 1'b1;
      if (ef_nonidle(tok_sip_i)) begin
        ef_ret_wait <= 1'b0;
        if (ef_own_tch && ef_ret_nogo && (token_go_i[0] !== 1'b1) && (fuse_sense_done_i === 1'b1) &&
            (tok_sip_i == EfCodeMatch))
          ef_tc(7, 6'd2);
      end
    end
  end

  // ---------------------------------------------------------------------
  // sep_token_fault_cg.
  // ---------------------------------------------------------------------
  logic ef_cf_arm = 1'b0, ef_cf_dir = 1'b0, ef_cf_go = 1'b0;
  // cp_secdis_off_under_fault: sec_dis_i rose since the last reset release (the
  // control that the output can rise), and is 0 from the SEC_DIS fault on.
  logic ef_so_arm = 1'b0, ef_so_bad = 1'b0, ef_sd_seen = 1'b0;
  logic [2:0] ef_rc_fault_last = '0;
  logic [2:0] ef_rc_pend = '0;
  logic ef_rc_chk = 1'b0;
  int unsigned ef_rc_cnt = 0;
  logic [1:0] ef_lf_te_q = '0, ef_lf_go = '0, ef_lf_chg = '0, ef_lf_rel = '0, ef_lf_rel_go = '0;
  logic [1:0][255:0] ef_lf_dig = '0;
  logic [1:0] ef_lf_vld = '0;
  logic [1:0] ef_lf_own = '0;  // the freeze started inside the graded window
  int unsigned ef_lf_cnt[2] = '{0, 0};

  // Copy and kind of a fault on channel c from its gated rails: a collapsed
  // pair is match_p[i] == match_n[i]; a dissent is one copy whose legal pair
  // differs from the other two. 5'd31 when neither.
  function automatic logic [4:0] ef_kind_copy(input int unsigned c);
    logic [2:0] p, n, col;
    p = cmp_match_p_i[3*c+:3];
    n = cmp_match_n_i[3*c+:3];
    col = ~(p ^ n);
    for (int i = 0; i < 3; i++) begin
      if (col == (3'b001 << i)) return 5'(c * 6 + i);
    end
    if (col == 3'b000) begin
      for (int i = 0; i < 3; i++) begin
        if ((p == (3'b001 << i)) || (p == ~(3'b001 << i))) return 5'(c * 6 + 3 + i);
      end
    end
    return 5'd31;
  endfunction

  always @(posedge clk_i) begin
    logic [4:0] kc;
    int unsigned c1;
    if (!in_reset) begin
      ef_fault_q <= tok_fault_i;
      ef_rc_fault_last <= tok_fault_i;
    end
    if (ef_live) begin
      if (ef_sd) ef_sd_seen <= 1'b1;
      if (ef_so_arm && (sec_dis_i !== 1'b0)) ef_so_bad <= 1'b1;
      for (int c = 0; c < 3; c++) begin
        if ((tok_fault_i[c] === 1'b1) && !ef_fault_q[c] && ef_own_tf) begin
          kc = ef_kind_copy(c);
          if (kc != 5'd31) ef_tfs(0, kc);
          if ((c == 2) && ef_sd_seen && (sec_dis_i === 1'b0)) begin
            ef_so_arm <= 1'b1;
            ef_so_bad <= 1'b0;
          end
        end
      end
      // x_ch_common_flip on RMA_CHIPLET: a flip between Match and Mismatch with
      // no go since the last code change, taken only while the RMA_CHIPLET sticky
      // bit is known 0, so a sticky bit that rises at the flip can show.
      if (token_go_i[1] === 1'b1) ef_cf_go <= 1'b1;
      if (tok_chp_i != ef_chp_q) begin
        ef_cf_go <= 1'b0;
        if (ef_own_tf && !ef_cf_go && (token_go_i[1] !== 1'b1) && (ef_fault_q[1] === 1'b0) &&
            (((ef_chp_q == EfCodeMatch) && (tok_chp_i == EfCodeMismatch)) ||
             ((ef_chp_q == EfCodeMismatch) && (tok_chp_i == EfCodeMatch)))) begin
          ef_cf_arm <= 1'b1;
          ef_cf_dir <= (tok_chp_i == EfCodeMatch);
        end
      end
      if (ef_tok_ev) begin
        // An X or Z on the sticky bit counts as a rise.
        if (ef_cf_arm) begin
          ef_cf_arm <= 1'b0;
          if (ef_own_tf) ef_tfs(1, {3'd0, tok_fault_i[1] !== 1'b0, ef_cf_dir});
        end
        if (ef_so_arm) begin
          ef_so_arm <= 1'b0;
          if (ef_own_tf && !ef_so_bad && (sec_dis_i === 1'b0)) ef_tfs(6, 5'd1);
        end
        if (ef_own_tf) begin
          // x_ch_forced_err: the error code and the sticky bit are new since the
          // previous settled sample (or since the reset release), so a sticky bit
          // left by an earlier fault never stands for this error.
          for (int c = 0; c < 3; c++) begin
            if ((ef_code[c] == EfCodeErr) && (!ef_ts_v || ((ef_ts_fault[c] === 1'b0) &&
                                                           (ef_ts_code[c] != EfCodeErr))))
              ef_tfs(2, {1'b0, 2'(c), tok_fault_i[c] === 1'b1, ef_irq});
          end
          for (int c = 0; c < 3; c++) begin
            if (tok_fault_i === (3'b001 << c)) ef_tfs(8, {2'b00, 2'(c), !ef_irq});
          end
        end
      end
    end else begin
      ef_cf_arm <= 1'b0;
      ef_so_arm <= 1'b0;
      ef_sd_seen <= 1'b0;
    end
    // cp_reset_clear: the sticky bit and the line are 0 EfTokSettle clocks after
    // the release of a reset that a set sticky bit entered.
    if (ef_rst_fall) begin
      ef_rc_pend <= ef_own_tf ? ef_rc_fault_last : 3'b000;
      ef_rc_chk  <= 1'b0;
    end
    if (ef_rel) begin
      ef_rc_chk <= (ef_rc_pend != '0);
      ef_rc_cnt <= 0;
    end else if (ef_rc_chk && ef_live) begin
      if (ef_rc_cnt == EfTokSettle) begin
        ef_rc_chk  <= 1'b0;
        ef_rc_pend <= '0;
        for (int c = 0; c < 3; c++) begin
          if (ef_rc_pend[c] && ef_own_tf && (tok_fault_i[c] === 1'b0) && (irq_token_fault_i === 1'b0))
            ef_tfs(5, 5'(c));
        end
      end else begin
        ef_rc_cnt <= ef_rc_cnt + 1;
      end
    end else if (ef_rc_chk) begin
      ef_rc_chk <= 1'b0;
    end
    // x_ch_latch_freeze on RMA_CHIPLET (index 0) and SEC_DIS (index 1).
    for (int i = 0; i < 2; i++) begin
      c1 = i + 1;
      ef_lf_te_q[i] <= (latch_test_en_i[c1] === 1'b1);
      if (in_reset) begin
        ef_lf_rel[i] <= 1'b0;
      end else if ((latch_test_en_i[c1] === 1'b1) && !ef_lf_te_q[i]) begin
        ef_lf_dig[i] <= latch_sticky_i[c1];
        ef_lf_vld[i] <= latch_valid_i[c1];
        ef_lf_own[i] <= ef_own_tf;
        ef_lf_go[i] <= 1'b0;
        ef_lf_chg[i] <= 1'b0;
        ef_lf_rel[i] <= 1'b0;
      end else if (latch_test_en_i[c1] === 1'b1) begin
        if ((token_go_i[c1] === 1'b1) && ef_lf_own[i]) ef_lf_go[i] <= 1'b1;
        if ((latch_sticky_i[c1] !== ef_lf_dig[i]) || (latch_valid_i[c1] !== ef_lf_vld[i]))
          ef_lf_chg[i] <= 1'b1;
      end else if (ef_lf_te_q[i]) begin
        if (ef_lf_go[i] && ef_own_tf) ef_tfs(7, {2'b00, 1'(i), 1'b0, ef_lf_chg[i]});
        // The replaced cell compares with the digest at the release.
        ef_lf_dig[i] <= latch_sticky_i[c1];
        ef_lf_rel[i] <= ef_lf_go[i] && !$isunknown(latch_sticky_i[c1]);
        ef_lf_rel_go[i] <= 1'b0;
        ef_lf_cnt[i] <= 0;
      end else if (ef_lf_rel[i]) begin
        if (token_go_i[c1] === 1'b1) ef_lf_rel_go[i] <= 1'b1;
        if (ef_lf_rel_go[i] && !$isunknown(
                latch_sticky_i[c1]
            ) && (latch_sticky_i[c1] !== ef_lf_dig[i])) begin
          ef_lf_rel[i] <= 1'b0;
          if (ef_own_tf) ef_tfs(7, {2'b00, 1'(i), 1'b1, 1'b0});
        end else if (ef_lf_cnt[i] == EfLatchWin) begin
          ef_lf_rel[i] <= 1'b0;
        end else begin
          ef_lf_cnt[i] <= ef_lf_cnt[i] + 1;
        end
      end
    end
  end

  // ---------------------------------------------------------------------
  // sep_sec_dis_activation_cg: cp_match_phase and x_verdict_out.
  // sep_sec_dis_robustness_cg: cp_stops_sense and cp_reset_values_hold.
  // ---------------------------------------------------------------------
  // cp_stops_sense bound (clk_i edges), outcome-bound rule of the graded
  // window: sep_sec_dis_timing_rand_test writes its window W (three times
  // the sense time it measures in the run) and writes 0 when its wait ends.
  // The bin fills only for a hold of W clocks. Monitor-only; it gates a
  // sample and is never a bin value.
  int unsigned efuse_sdis_hold_bound = 0;
  logic ef_sd_q = 1'b0;
  logic ef_ss_arm = 1'b0, ef_ss_phase = 1'b0, ef_ss_bad = 1'b0;
  logic [EfFuseBits-1:0] ef_ss_snap = '0;
  int unsigned ef_ss_cnt = 0;
  // Clocks since the last reset release; a SEC_DIS that is high within
  // EfRelWin clocks of the release counts as held at the release.
  int unsigned ef_since_rel = 0;
  logic ef_mp_before_done = 1'b0;
  wire ef_rel_win = !in_reset && (ef_since_rel <= EfRelWin);
  always @(posedge clk_i) begin
    if (in_reset) ef_since_rel <= 0;
    else if (ef_since_rel <= EfRelWin) ef_since_rel <= ef_since_rel + 1;
  end
  localparam logic [EfFuseBits-1:0] EfLcWordMask = EfFuseBits'(32'hFFFF_FFFF) << (32 * EfWLc);
  always @(posedge clk_i) begin
    logic open;
    ef_sd_q <= ef_sd && !in_reset;
    open = ef_live && ef_sd && (fuse_sense_done_i !== 1'b1);
    if (ef_live) begin
      if (ef_rel) ef_mp_before_done <= 1'b0;
      if (ef_rel_win && ef_sd && !ef_mp_before_done && (fuse_sense_done_i !== 1'b1)) begin
        ef_mp_before_done <= 1'b1;
        if (ef_own_sdt) ef_act(0, 5'd0);
      end
      if (!ef_rel_win && ef_sd && !ef_sd_q) begin
        if ((fuse_sense_done_i !== 1'b1) && ef_own_sdt) ef_act(0, 5'd1);
        if ((fuse_sense_done_i === 1'b1) && ef_own_fc) ef_act(0, 5'd2);
      end
      // x_verdict_out at a settled token change with a non-idle SEC_DIS code. An X
      // or Z on sec_dis_i is the wrong output for every code.
      if (ef_tok_ev) begin
        if ((tok_sdis_i == EfCodeMatch) && ef_own_fc) ef_act(1, {2'b00, 2'd0, sec_dis_i === 1'b1});
        if ((tok_sdis_i == EfCodeMismatch) && ef_own_fc)
          ef_act(1, {2'b00, 2'd1, sec_dis_i !== 1'b0});
        if ((tok_sdis_i == EfCodeErr) && ef_own_tf) ef_act(1, {2'b00, 2'd2, sec_dis_i !== 1'b0});
      end
    end
    // cp_stops_sense: phase 0 from a SEC_DIS rise during sense, phase 1 from
    // a reset release with SEC_DIS already high.
    if (!open) begin
      ef_ss_arm <= 1'b0;
    end else if (!ef_ss_arm && !ef_sd_q) begin
      ef_ss_arm <= 1'b1;
      ef_ss_phase <= ef_rel_win;
      ef_ss_bad <= 1'b0;
      ef_ss_snap <= efuse_shadow_i;
      ef_ss_cnt <= 0;
    end else if (ef_ss_arm) begin
      if (efuse_shadow_i !== ef_ss_snap) ef_ss_bad <= 1'b1;
      ef_ss_cnt <= ef_ss_cnt + 1;
      if ((efuse_sdis_hold_bound != 0) && (ef_ss_cnt + 1 == efuse_sdis_hold_bound)) begin
        if (ef_own_sdt && !ef_ss_bad && (efuse_shadow_i === ef_ss_snap)) begin
          ef_rob(1, {2'b00, ef_ss_phase});
          // cp_reset_values_hold: at the end of the same bounded hold, in the
          // window that starts at a reset release, when every shadow word
          // except the LC_STATE word read 0 at the release and on every clock
          // of the hold. A design that senses under the match loads a word
          // inside the bound, so the bin cannot fill on the release clock.
          if (ef_ss_phase && ((ef_ss_snap & ~EfLcWordMask) == '0)) ef_rob(3, 3'd1);
        end
      end
    end
  end

  // ---------------------------------------------------------------------
  // sep_efuse_if_status_cg shim points: cp_sense_status_word and
  // x_prog_lifecycle.
  // ---------------------------------------------------------------------
  // Word index of a sense response: the start word (bits [12:5] of the bit
  // address) of the READ command that the response answers, plus the number
  // of earlier responses to that command. The sense is one READ command at
  // address 0 that streams one response per word, and the request holds
  // valid high for the whole sense. So a READ command starts only on a clock
  // where valid is known 1 and was not known 1 on the clock before.
  logic [7:0] ef_ssw_base = '0;
  logic ef_ssw_v_q = 1'b0;  // shim_cmd_i.valid known 1 on the previous clock
  logic [8:0] ef_ssw_idx = '0;
  logic ef_ssw_cv = 1'b0;  // a READ command with a known address in this epoch
  logic ef_ssw_pend = 1'b0;
  // The status response carried known non-zero data, so a shadow word left at 0
  // shows the data was dropped and not that the image word was 0.
  logic ef_ssw_nz = 1'b0;
  logic [7:0] ef_ssw_w = '0;
  typedef enum logic [1:0] {
    EF_PL_IDLE,
    EF_PL_WAIT,
    EF_PL_HELD,
    EF_PL_REL
  } ef_pl_e;
  ef_pl_e ef_pl_st = EF_PL_IDLE;
  int unsigned ef_pl_cnt = 0;
  logic ef_pl_done_seen = 1'b0, ef_pdone_q = 1'b0, ef_cmd_pg_q = 1'b0;
  always @(posedge clk_i) begin
    logic [8:0] w;
    ef_pdone_q <= (efuse_program_done_i === 1'b1);
    ef_cmd_pg_q <= ef_cmd_pg;
    ef_ssw_v_q <= ef_cmd_v;
    if (ef_rst_fall) begin
      ef_ssw_pend <= 1'b0;
      ef_ssw_cv   <= 1'b0;
    end
    if (ef_live && (fuse_sense_done_i !== 1'b1)) begin
      // A response on the clock of a new READ command answers the earlier one.
      if (ef_resp_v && ef_ssw_cv) begin
        ef_ssw_idx <= ef_ssw_idx + 9'd1;
        w = {1'b0, ef_ssw_base} + ef_ssw_idx;
        if ((shim_resp_i.status === 1'b1) && (w >= 9'd10) && (w <= 9'd254)) begin
          ef_ssw_pend <= 1'b1;
          ef_ssw_w <= w[7:0];
          ef_ssw_nz <= !$isunknown(shim_resp_i.data) && (shim_resp_i.data != '0);
        end
      end
      if (ef_cmd_rd && !ef_ssw_v_q) begin
        ef_ssw_base <= ef_cmd_addr[12:5];
        ef_ssw_idx  <= '0;
        ef_ssw_cv   <= !$isunknown(ef_cmd_addr);
      end
    end
    if (ef_sense_rise && ef_ssw_pend) begin
      ef_ssw_pend <= 1'b0;
      if (ef_own_shim && ef_ssw_nz && (efuse_shadow_i[32*ef_ssw_w+:32] === 32'h0)) ef_ifs(5, 7'd1);
    end
    // x_prog_lifecycle: a PROGRAM command with the program timeout off.
    if (in_reset) begin
      ef_pl_st <= EF_PL_IDLE;
    end else begin
      case (ef_pl_st)
        EF_PL_IDLE: begin
          if (ef_cmd_pg && !ef_cmd_pg_q && !ef_pg_tmo_en_q) begin
            ef_pl_st  <= EF_PL_WAIT;
            ef_pl_cnt <= 0;
          end
        end
        EF_PL_WAIT: begin
          if (ef_resp_v) begin
            ef_pl_st <= EF_PL_IDLE;
          end else if (ef_pl_cnt == EfProgN) begin
            if (ef_own_shim) begin
              ef_ifs(
                  6, {
                  5'd0, 1'b0, !((efuse_program_busy_i === 1'b1) && (efuse_program_done_i === 1'b0))
                  });
            end
            ef_pl_st <= EF_PL_HELD;
          end else begin
            ef_pl_cnt <= ef_pl_cnt + 1;
          end
        end
        EF_PL_HELD: begin
          if (ef_resp_v) begin
            ef_pl_st <= EF_PL_REL;
            ef_pl_done_seen <= 1'b0;
            ef_pl_cnt <= 0;
          end
        end
        default: begin
          if (!ef_pl_done_seen) begin
            if ((efuse_program_done_i === 1'b1) && !ef_pdone_q) ef_pl_done_seen <= 1'b1;
          end else if (ef_pl_cnt == EfProgN) begin
            if (ef_own_shim) begin
              ef_ifs(6, {
                     5'd0,
                     1'b1,
                     !((efuse_program_done_i === 1'b1) &&
                                        (efuse_program_error_i === 1'b0) &&
                                        (efuse_program_busy_i === 1'b0))
                     });
            end
            ef_pl_st <= EF_PL_IDLE;
          end else begin
            ef_pl_cnt <= ef_pl_cnt + 1;
          end
        end
      endcase
    end
  end

  // ---------------------------------------------------------------------
  // sep_efuse_jtag_policy_cg: completion of a JTAG AXI-Lite access, class
  // from the address. The policy before sense done is not declared.
  // ---------------------------------------------------------------------
  logic [31:0] ef_j_aw = '0, ef_j_ar = '0;
  always @(posedge clk_i) begin
    ef_jtg_t je;
    logic [31:0] a;
    logic wr, ok, rx, allowed, fire;
    logic [2:0] cl, cop;
    logic [2:0] st;
    if ((jtag_req_i.aw_valid === 1'b1) && (jtag_resp_i.aw_ready === 1'b1))
      ef_j_aw <= 32'(jtag_req_i.aw.addr);
    if ((jtag_req_i.ar_valid === 1'b1) && (jtag_resp_i.ar_ready === 1'b1))
      ef_j_ar <= 32'(jtag_req_i.ar.addr);
    fire = 1'b0;
    wr = 1'b0;
    ok = 1'b0;
    rx = 1'b0;
    a = '0;
    if ((jtag_resp_i.b_valid === 1'b1) && (jtag_req_i.b_ready === 1'b1)) begin
      fire = 1'b1;
      wr = 1'b1;
      ok = (jtag_resp_i.b.resp === AxiOkay);
      rx = $isunknown(jtag_resp_i.b.resp);
      a = ef_j_aw;
    end else if ((jtag_resp_i.r_valid === 1'b1) && (jtag_req_i.r_ready === 1'b1)) begin
      fire = 1'b1;
      ok = (jtag_resp_i.r.resp === AxiOkay);
      rx = $isunknown(jtag_resp_i.r.resp);
      a = ef_j_ar;
    end
    // The state needs a known filter integrity flag; a response with an X or Z bit
    // is a wrong response in every cell.
    if (fire && ef_sensed && !$isunknown(jtag_filt_sigint_i)) begin
      cl = in_win(a, EfMapBase, EfMapEnd) ? 3'd0 : in_win(a, EfCtrlBase, EfCtrlEnd) ? 3'd1 :
          in_win(a, EfTokSip, EfTokEop) ? 3'd2 : (a == EfTokEop) ? 3'd3 :
          in_win(a, EfMatchSip, EfMatchFault) ? 3'd4 : 3'd7;
      // 7: no cell (integrity error outside TEST_DEV, TEST_DEV, INVALID).
      st = ((jtag_filt_sigint_i === 1'b1) && (ef_lc == EfTd)) ? 3'd2 :
          (jtag_filt_sigint_i === 1'b1) ? 3'd7 : (ef_lc == EfProd) ? 3'd0 : (ef_lc == EfRs) ? 3'd1 :
          (ef_lc == EfPe) ? 3'd3 : (ef_lc == EfRc) ? 3'd4 : 3'd7;
      case (cl)
        3'd2: cop = wr ? 3'd1 : 3'd0;
        3'd3: cop = 3'd2;  // TOKEN_EOP read is not declared
        3'd4: cop = 3'd3;  // match write is not declared
        3'd0: cop = wr ? 3'd5 : 3'd4;
        3'd1: cop = wr ? 3'd7 : 3'd6;
        default: cop = 3'd7;
      endcase
      allowed = (cop < 3'd4);
      // PROD_END and RMA_CHIPLET: cp_state only, for the secure test mode
      // matrix owner. The class, response and cross points keep the
      // restricted states and the integrity error.
      if ((cl != 3'd7) && ((st == 3'd3) || (st == 3'd4)) && ef_own_stm) begin
        je = '0;
        je.st = st;
        je.st_v = 1'b1;
        u_sep_efuse_jtag_policy_cg.sample(je);
      end
      if ((cl != 3'd7) && (st <= 3'd2) && ((st == 3'd2) ? ef_own_cw : ef_own_jtag)) begin
        je = '0;
        je.st = st;
        je.st_v = 1'b1;
        je.cl = cl;
        je.cl_v = 1'b1;
        je.rp = !ok;
        je.rp_v = !rx;
        if (!((cl == 3'd3) && !wr) && !((cl == 3'd4) && wr)) begin
          je.so = {rx || (allowed ? !ok : ok), 5'(st * 8) + 5'(cop)};
          je.so_v = 1'b1;
        end
        je.gi = st[0];
        je.gi_v = allowed && ok && (st != 3'd2) && (feat_ctrl_i[47:0] == 48'h0);
        u_sep_efuse_jtag_policy_cg.sample(je);
      end
    end
  end

  // ---------------------------------------------------------------------
  // Trackers of the added eFuse and lifecycle points: cp_presense_feat,
  // cp_gate_bound, x_path_case, x_prod_demote_case3, x_secdis_stm_feat,
  // cp_simultaneous_match, cp_reset_restore, x_exempt_write,
  // cp_locked_field_irq, x_jtag_rlock, x_jtag_presense,
  // cp_token_hmac_overlap, cp_go_while_busy, cp_sense_shape and the
  // test_dev_to_prod_prog cell of sep_lc_transition_cg.
  // ---------------------------------------------------------------------
  wire ef_own_lfi = (graded_owner == FcovOwnSepLockedFieldAccessIrqPathTest);
  wire ef_own_img = (graded_owner == FcovOwnSepEfuseImageTest);
  wire ef_own_dem = (graded_owner == FcovOwnSepLccDemoteFeatCtrlMatrixTest);
  wire ef_own_ovr = (graded_owner == FcovOwnSepSecDisOverrideTest);
  wire ef_own_stmss = (graded_owner == FcovOwnSepSecureTmStrapSamplingTest);
  wire ef_own_stitch = (graded_owner == FcovOwnSepEfuseLccLcStateStitchTest);
  localparam logic [31:0] EfFeatCtrl = SEP_LIFECYCLE_CTRL_FEAT_CTRL_REG_ADDR;
  localparam int unsigned EfSenseWords = EfFuseBits / 32;
  localparam int unsigned EfHmacWin = 200_000;  // clk_i cycles from a verdict to the HMAC done
  localparam int unsigned EfGoTol = 4;  // clk_i cycles of verdict-time tolerance
  // Case of each dbg_disable path (DTP path table): 1, 2 or 3; 0 ungated.
  localparam int unsigned EfPathCase[11] = '{1, 2, 3, 2, 1, 3, 2, 1, 2, 0, 0};

  // FEAT_CTRL reads: cp_presense_feat, cp_gate_bound, x_path_case and
  // x_prod_demote_case3.
  wire ef_feat_rd = rd_okay && ((ar_addr_q == EfFeatCtrl) || (ar_addr_q == EfFeatCtrl + 32'd4));
  always @(posedge clk_i) begin
    ef_prof_t pe;
    ef_dtp_t de;
    logic [31:0] lo;
    logic lo_v, full_v, c1, c2, c3, open;
    logic [63:0] gm;
    full_v = ef_feat_rd && (ar_addr_q == EfFeatCtrl) && (ar_size_q == 3'd3);
    lo_v = ef_feat_rd && (ar_addr_q == EfFeatCtrl) && ((ar_size_q == 3'd3) || (ar_size_q == 3'd2));
    lo = (ar_size_q == 3'd3) ? lsu_r_data_i[31:0] : rd_data;
    if (ef_feat_rd && ef_own_img && !in_reset && !skip_fuse_sense_q &&
        (fuse_sense_done_i === 1'b0)) begin
      pe = '0;
      pe.pz = (ar_size_q == 3'd3) ? (lsu_r_data_i !== 64'h0) : (rd_data !== 32'h0);
      pe.pz_v = 1'b1;
      u_sep_lc_feat_ctrl_profile_cg.sample(pe);
    end
    if (full_v && ef_own_fc && ef_sensed && ef_fin_k && !ef_sd && !ef_sig && (ef_lc != EfInv) &&
        !$isunknown(
            lsu_r_data_i
        )) begin
      gm = ef_gate_mask(ef_lc, ef_sip_dis, ef_sys_dis);
      if (gm != '1) begin
        pe = '0;
        pe.gb = {(lsu_r_data_i & ~gm) != 64'h0, ef_lc};
        pe.gb_v = 1'b1;
        u_sep_lc_feat_ctrl_profile_cg.sample(pe);
      end
    end
    if (lo_v && ef_own_dem && ef_sensed && ef_fin_k && !$isunknown(lo)) begin
      c1 = lo[EfBitSipDbg];
      c2 = c1 && lo[EfBitChipDbg];
      c3 = c2 && lo[EfBitSepDbg];
      for (int p = 0; p < 11; p++) begin
        open = (EfPathCase[p] == 0) ? 1'b1 : (EfPathCase[p] == 1) ? c1 :
            (EfPathCase[p] == 2) ? c2 : c3;
        de = '0;
        de.pc = {dbg_dis_i[p] !== !open, 4'(p), open};
        de.pc_v = 1'b1;
        u_sep_dtp_gating_ladder_cg.sample(de);
      end
      if ((ef_lc == EfProd) && !ef_sd && !ef_sig && (ef_dm != 2'b00)) begin
        de = '0;
        de.pd = {ef_dm, c3};
        de.pd_v = 1'b1;
        u_sep_dtp_gating_ladder_cg.sample(de);
      end
    end
  end

  // x_secdis_stm_feat: on entry to (SEC_DIS 1, FEAT_CTRL probe all ones) and
  // on a change of secure_tm_o inside it.
  logic ef_xs_q = 1'b0, ef_xs_stm_q = 1'b0;
  always @(posedge clk_i) begin
    logic cond;
    cond = !in_reset && (sec_dis_i === 1'b1) && (feat_ctrl_i === '1) && !$isunknown(secure_tm_i);
    ef_xs_q <= cond;
    ef_xs_stm_q <= (secure_tm_i === 1'b1);
    if (cond && (!ef_xs_q || ((secure_tm_i === 1'b1) != ef_xs_stm_q))) begin
      if ((secure_tm_i === 1'b1) ? ef_own_stmss : ef_own_ovr)
        ef_rob(4, {2'b00, secure_tm_i === 1'b1});
    end
  end

  // cp_simultaneous_match: a SIP Match rise while the CHIPLET code holds
  // Match, and the LC_STATE word over EfTransWin clocks.
  logic ef_sm_arm = 1'b0, ef_sm_prod = 1'b0;
  logic [31:0] ef_sm_lcw = '0;
  int unsigned ef_sm_cnt = 0;
  logic [5:0] ef_sm_sip_q = '0;
  always @(posedge clk_i) begin
    ef_trn_t e;
    logic upd;
    ef_sm_sip_q <= tok_sip_i;
    if (!ef_sensed || !ef_own_tr) begin
      ef_sm_arm <= 1'b0;
    end else if (!ef_sm_arm && (tok_sip_i == EfCodeMatch) && (ef_sm_sip_q != EfCodeMatch) &&
                 (tok_chp_i == EfCodeMatch) && ef_trans_en && (ef_lc inside {EfTd, EfProd}) &&
                 !$isunknown(
            ef_lc_word
        )) begin
      ef_sm_arm  <= 1'b1;
      ef_sm_prod <= (ef_lc == EfProd);
      ef_sm_lcw  <= ef_lc_word;
      ef_sm_cnt  <= 0;
    end else if (ef_sm_arm) begin
      upd = (ef_lc_word !== ef_sm_lcw);
      if (upd || (ef_sm_cnt == EfTransWin)) begin
        e = '0;
        e.sm = {upd, ef_sm_prod};
        e.sm_v = 1'b1;
        u_sep_lc_illegal_transition_cg.sample(e);
        ef_sm_arm <= 1'b0;
      end else begin
        ef_sm_cnt <= ef_sm_cnt + 1;
      end
    end
  end

  // cp_reset_restore: armed at a rst_ni fall when the LC_STATE byte of the
  // last clock before the fall differs from the byte of the last sense.
  logic [7:0] ef_rr_sensed = '0, ef_rr_last = '0;
  logic ef_rr_sv = 1'b0, ef_rr_arm = 1'b0;
  always @(posedge clk_i) begin
    ef_trn_t e;
    if (!in_reset) ef_rr_last <= ef_lc_word[7:0];
    if (ef_sense_rise) begin
      if (ef_rr_arm && ef_own_tr) begin
        e = '0;
        e.rr = (ef_lc_word[7:0] !== ef_rr_sensed);
        e.rr_v = 1'b1;
        u_sep_lc_illegal_transition_cg.sample(e);
      end
      ef_rr_arm <= 1'b0;
      ef_rr_sensed <= ef_lc_word[7:0];
      ef_rr_sv <= 1'b1;
    end else if (ef_rst_fall) begin
      ef_rr_arm <= ef_own_tr && ef_rr_sv && (ef_rr_last !== ef_rr_sensed);
    end
  end

  // x_exempt_write: the resensed LC_STATE read after a landed program.
  int unsigned ef_xw_seen = 0;
  logic ef_xw_pend = 1'b0, ef_xw_sensed = 1'b0, ef_xw_bit3 = 1'b0;
  always @(posedge clk_i) begin
    logic [3:0] r;
    if (ef_xw_req != ef_xw_seen) begin
      ef_xw_seen <= ef_xw_req;
      ef_xw_pend <= 1'b1;
      ef_xw_sensed <= 1'b0;
      ef_xw_bit3 <= ef_xw_req_bit3;
    end else if (ef_xw_pend) begin
      if (ef_sense_rise) ef_xw_sensed <= 1'b1;
      if (ef_xw_sensed && rd_okay && (ar_addr_q == SEP_EFUSE_MAP_LC_STATE_REG_ADDR)) begin
        r = ef_xw_bit3 ? 4'b1000 : 4'b0001;
        if (ef_own_lock) ef_lk(11, (rd_data[7:0] == {~r, r}) ? {7'd0, ef_xw_bit3} : 8'd3);
        ef_xw_pend <= 1'b0;
      end
    end
  end

  // cp_locked_field_irq: PIC source 34 (vector bit 33) from the request
  // handshake to the response of a single outstanding frontdoor access.
  logic ef_lf_wp = 1'b0, ef_lf_rp = 1'b0;
  always @(posedge clk_i) begin
    logic [10:0] off;
    logic [5:0] sl;
    logic wp, rp, p33;
    p33 = (vec_i[33] === 1'b1);
    wp = ef_lf_wp || p33;
    rp = ef_lf_rp || p33;
    ef_lf_wp <= aw_hs ? p33 : wp;
    ef_lf_rp <= ar_hs ? p33 : rp;
    if (ef_own_lfi && ef_sensed && (secure_tm_i === 1'b0)) begin
      if (ef_wr_cmpl && (ef_wr_win == EfWShadow)) begin
        off = 11'(aw_addr_q - EfMapBase);
        sl = ef_slot_of(off);
        if (sl != EfNoSlot) ef_lk(12, {5'd0, 1'b1, ef_wlock(sl), wp});
      end
      if (ef_rd_cmpl && (ef_rd_win == EfWShadow)) begin
        off = 11'(ar_addr_q - EfMapBase);
        sl = ef_slot_of(off);
        if (sl != EfNoSlot) ef_lk(12, {5'd0, 1'b0, ef_rlock(sl), rp});
      end
    end
  end

  // x_jtag_rlock and x_jtag_presense.
  logic [31:0] ef_jw_data = '0;
  logic ef_jp_arm = 1'b0, ef_jp_cmd = 1'b0;
  always @(posedge clk_i) begin
    ef_jtg_t je;
    logic [31:0] a, st, rdj;
    logic [10:0] off;
    logic [5:0] sl;
    logic pre_sense_q_win;
    pre_sense_q_win = !in_reset && !skip_fuse_sense_q && (fuse_sense_done_i !== 1'b1);
    if ((jtag_req_i.w_valid === 1'b1) && (jtag_resp_i.w_ready === 1'b1))
      ef_jw_data <= 32'(jtag_req_i.w.data);
    if ((jtag_resp_i.r_valid === 1'b1) && (jtag_req_i.r_ready === 1'b1)) begin
      a = ef_j_ar;
      rdj = 32'(jtag_resp_i.r.data);
      if (in_win(a, EfMapBase, EfMapEnd)) begin
        if (pre_sense_q_win && ef_own_ifs) begin
          je = '0;
          je.jp = (jtag_resp_i.r.resp === AxiOkay) ? 2'd2 : 2'd0;
          je.jp_v = 1'b1;
          u_sep_efuse_jtag_policy_cg.sample(je);
        end
        if (ef_sensed && ef_own_lock && (ef_lc == EfTd)) begin
          off = 11'(a - EfMapBase);
          sl = ef_slot_of(off);
          st = stored_shadow_i[32*off[9:2]+:32];
          if ((sl != EfNoSlot) && (sl != 6'd0) && (st != 32'h0) && !$isunknown(st)) begin
            je = '0;
            if (ef_rlock(sl)) begin
              je.jr = (rdj === st) ? 2'd2 : 2'd0;
              je.jr_v = 1'b1;
            end else if ((jtag_resp_i.r.resp === AxiOkay) && (rdj === st)) begin
              je.jr = 2'd1;
              je.jr_v = 1'b1;
            end
            if (je.jr_v) u_sep_efuse_jtag_policy_cg.sample(je);
          end
        end
      end
    end
    if ((jtag_resp_i.b_valid === 1'b1) && (jtag_req_i.b_ready === 1'b1) && (ef_j_aw == EfPgCtrl) &&
        pre_sense_q_win && ((ef_jw_data & EfPgGoMask) != 32'h0)) begin
      ef_jp_arm <= 1'b1;
      ef_jp_cmd <= 1'b0;
    end else if (ef_jp_arm) begin
      if (ef_sense_rise) begin
        if (ef_own_ifs) begin
          je = '0;
          je.jp = (ef_jp_cmd || ef_cmd_pg) ? 2'd3 : 2'd1;
          je.jp_v = 1'b1;
          u_sep_efuse_jtag_policy_cg.sample(je);
        end
        ef_jp_arm <= 1'b0;
      end else if (in_reset) begin
        ef_jp_arm <= 1'b0;
      end else if (ef_cmd_pg) begin
        ef_jp_cmd <= 1'b1;
      end
    end
  end

  // cp_token_hmac_overlap and cp_go_while_busy. The verdict of a go is the
  // first non-idle code after the code has read idle since the go.
  logic [2:0] ef_ho_arm = '0, ef_ho_idle = '0, ef_ho_busy = '0;
  logic ef_ho_wait = 1'b0, ef_ho_mm = 1'b0;
  int unsigned ef_ho_cnt = 0;
  logic [2:0][1:0] ef_gw_st = '0;  // 0 idle, 1 first go, 2 second go, 3 Match hold
  logic [2:0] ef_gw_idle = '0, ef_gw_lat_v = '0;
  longint unsigned ef_gw_t1[3] = '{default: 0};
  longint unsigned ef_gw_lat[3] = '{default: 0};
  longint unsigned ef_gw_end[3] = '{default: 0};
  logic [2:0][7:0][31:0] ef_gw_words = '0;
  always @(posedge clk_i) begin
    logic [5:0] code;
    longint unsigned dt;
    if (!ef_live) begin
      ef_ho_arm <= '0;
      ef_ho_wait <= 1'b0;
      ef_gw_st <= '0;
    end else begin
      for (int c = 0; c < 3; c++) begin
        code = ef_code[c];
        if (token_go_i[c] === 1'b1) begin
          ef_ho_arm[c] <= 1'b1;
          ef_ho_idle[c] <= ef_isidle(code);
          ef_ho_busy[c] <= cy_ip[3] && !cy_h_idle;
        end else if (ef_ho_arm[c]) begin
          if (ef_isidle(code)) ef_ho_idle[c] <= 1'b1;
          if (ef_ho_idle[c] && ef_nonidle(code)) begin
            ef_ho_arm[c] <= 1'b0;
            if (ef_ho_busy[c] && cy_ip[3] && !cy_h_idle && !ef_ho_wait &&
                (code inside {EfCodeMatch, EfCodeMismatch})) begin
              ef_ho_wait <= 1'b1;
              ef_ho_mm <= (code == EfCodeMismatch);
              ef_ho_cnt <= 0;
            end
          end
        end
        if (token_go_i[c] === 1'b1) begin
          dt = mr_cyc - ef_gw_t1[c];
          if ((ef_gw_st[c] == 2'd1) && ef_gw_lat_v[c] && (tok_words_i[c] === ef_gw_words[c]) &&
              (dt * 4 >= ef_gw_lat[c]) && (dt * 4 <= 3 * ef_gw_lat[c])) begin
            ef_gw_st[c] <= 2'd2;
          end else begin
            ef_gw_st[c] <= 2'd1;
            ef_gw_t1[c] <= mr_cyc;
            ef_gw_words[c] <= tok_words_i[c];
            ef_gw_idle[c] <= ef_isidle(code);
          end
        end else if (ef_gw_st[c] == 2'd1) begin
          if (ef_isidle(code)) begin
            ef_gw_idle[c] <= 1'b1;
          end else if (ef_gw_idle[c] && ef_nonidle(code)) begin
            if (code inside {EfCodeMatch, EfCodeMismatch}) begin
              ef_gw_lat[c] <= mr_cyc - ef_gw_t1[c];
              ef_gw_lat_v[c] <= 1'b1;
            end
            ef_gw_st[c] <= 2'd0;
          end
        end else if (ef_gw_st[c] == 2'd2) begin
          if (ef_isidle(code)) begin
            ef_gw_idle[c] <= 1'b1;
          end else if (ef_gw_idle[c] && ef_nonidle(code)) begin
            dt = mr_cyc - ef_gw_t1[c];
            if ((code == EfCodeMatch) && (dt + EfGoTol >= ef_gw_lat[c]) &&
                (dt <= ef_gw_lat[c] + EfGoTol)) begin
              ef_gw_st[c] <= 2'd3;
              ef_gw_end[c] <= ef_gw_t1[c] + 2 * ef_gw_lat[c] + EfTokSettle;
            end else begin
              ef_gw_st[c] <= 2'd0;
            end
          end
        end else if (ef_gw_st[c] == 2'd3) begin
          if (code !== EfCodeMatch) begin
            ef_gw_st[c] <= 2'd0;
          end else if (mr_cyc >= ef_gw_end[c]) begin
            if (ef_own_tch) ef_tc(9, 6'(c));
            ef_gw_st[c] <= 2'd0;
          end
        end
      end
      if (ef_ho_wait) begin
        if (cy_h_done_ev) begin
          if (ef_own_tch) ef_tc(8, {5'd0, ef_ho_mm});
          ef_ho_wait <= 1'b0;
        end else if ((ef_ho_cnt == EfHmacWin) || !cy_ip[3]) begin
          ef_ho_wait <= 1'b0;
        end else begin
          ef_ho_cnt <= ef_ho_cnt + 1;
        end
      end
    end
  end

  // cp_sense_shape: READ commands (first clock of a valid run, or a clock
  // where the command changes while valid stays 1) and response strobes from
  // the reset release to the sense-done rise.
  int unsigned ef_sh_rd = 0, ef_sh_rsp = 0;
  longint unsigned ef_sh_tlast = 0;
  sep_efuse_pkg::fuse_command_req_t ef_sh_cmd_q = '0;
  logic ef_sh_on = 1'b0;
  always @(posedge clk_i) begin
    ef_ifs_t e;
    ef_sh_cmd_q <= shim_cmd_i;
    if (in_reset) begin
      ef_sh_on <= 1'b0;
    end else if (ef_rel) begin
      ef_sh_on <= !skip_fuse_sense_q;
      ef_sh_rd <= 0;
      ef_sh_rsp <= 0;
    end else if (ef_sh_on) begin
      if (ef_cmd_rd && ((ef_sh_cmd_q.valid !== 1'b1) || (shim_cmd_i !== ef_sh_cmd_q)))
        ef_sh_rd <= ef_sh_rd + 1;
      if (ef_resp_v) begin
        ef_sh_rsp <= ef_sh_rsp + 1;
        if (ef_sh_rsp + 1 == EfSenseWords) ef_sh_tlast <= mr_cyc;
      end
      if (ef_sense_rise) begin
        ef_sh_on <= 1'b0;
        if (ef_own_shim) begin
          if (ef_sh_rd == 1) begin
            e = '0;
            e.sh = 1'b0;
            e.sh_v = 1'b1;
            u_sep_efuse_if_status_cg.sample(e);
          end
          if ((ef_sh_rsp >= EfSenseWords) && (mr_cyc > ef_sh_tlast)) begin
            e = '0;
            e.sh = 1'b1;
            e.sh_v = 1'b1;
            u_sep_efuse_if_status_cg.sample(e);
          end
        end
      end
    end
  end

  // test_dev_to_prod_prog of sep_lc_transition_cg: a TEST_DEV LC_STATE read,
  // a PROGRAM command to LC_STATE bit 0, a sense, then an LC_STATE read of
  // PROD, in the window of the LC_STATE stitch leaf.
  logic ef_st_td = 1'b0, ef_st_prog = 1'b0, ef_st_sensed = 1'b0;
  always @(posedge clk_i) begin
    if (lc_diff_ok && ef_own_stitch) begin
      if (ef_st_prog && ef_st_sensed) begin
        if (lc_raw == LcProd) u_sep_lc_transition_cg.sample(LcTestDev, LcProd);
        ef_st_prog <= 1'b0;
        ef_st_sensed <= 1'b0;
      end
      ef_st_td <= (lc_raw == LcTestDev);
    end
    if (!in_reset && ef_cmd_pg && ef_st_td &&
        (16'(ef_cmd_addr) == 16'(SEP_EFUSE_MAP_LC_STATE_REG_OFFSET * 8))) begin
      ef_st_prog <= 1'b1;
      ef_st_sensed <= 1'b0;
    end else if (ef_sense_rise && ef_st_prog) begin
      ef_st_sensed <= 1'b1;
    end
  end

  // =====================================================================
  // Key Manager groups (docs/SEP_FCOV.adoc, Key Manager groups). Every
  // point samples only while graded_owner holds the code of a test that
  // owns the point or the bin. The KM groups do not use the in_reset gate:
  // the reset points sample across a reset, so their state flops have no
  // reset and every input compare is X-safe. The settle counts and windows
  // below are choices of the environment; the specification gives none.
  //
  // Every covergroup takes sample(pt, v): pt selects the coverpoint, v is
  // its value, and a call is made only when the owner of the bin is in its
  // window.
  // =====================================================================
  wire km_own_csr = (graded_owner == FcovOwnSepKmKmcsrResetRandTest);
  wire km_own_kpv = (graded_owner == FcovOwnSepKmKpvRandTest);
  wire km_own_cpu = (graded_owner == FcovOwnSepKmCpuProtectRandTest);
  wire km_own_xbar = (graded_owner == FcovOwnSepKmCrossbarEfuseWindowRandTest);
  wire km_own_mbx = (graded_owner == FcovOwnSepKmMailboxKmSideRandTest);
  wire km_own_smp = (graded_owner == FcovOwnSepKmDrbgSamplerRandTest);
  wire km_own_otp = (graded_owner == FcovOwnSepKmOtpInterfaceRandTest);
  wire km_own_bank = (graded_owner == FcovOwnSepKmKeyBankRegisterRandTest);
  wire km_own_scr = (graded_owner == FcovOwnSepKmSramScramblerKeyRandTest);
  wire km_own_cp = (graded_owner == FcovOwnSepKmCommandProtocolRandTest);
  wire km_own_xf = (graded_owner == FcovOwnSepKmKeyTransferRandTest);
  wire km_own_br = (graded_owner == FcovOwnSepKmBootResetRandTest);
  wire km_own_ho = (graded_owner == FcovOwnSepKmHandoverRandTest);
  wire km_own_fi = (graded_owner == FcovOwnSepKmFaultInjectRandTest);
  wire km_own_smpto = (graded_owner == FcovOwnSepKmDrbgSamplerTimeoutResetTest);
  wire km_own_hot = (graded_owner == FcovOwnSepKmHandoverTest);
  wire km_own_crc = (graded_owner == FcovOwnSepKmCrcPcpiKatTest);
  wire km_own_romw = (graded_owner == FcovOwnSepKmRomWriteErrTest);
  wire km_own_pubid = (graded_owner == FcovOwnSepEfuseKmPublicIdTest);

  localparam int unsigned KmSettle = 2;  // clocks from a B or a reset release to its effect
  localparam int unsigned KmStoreWin = 6;  // clocks a store has to reach the SRAM macro
  localparam int unsigned KmQuietWin = 64;  // quiet window of the no-effect bins
  localparam int unsigned KmRunWin = 1000;  // KM run time before a steady-state bin
  localparam int unsigned KmErrHoldWin = 5000;  // km_unrecoverable_err_o high time before a reset
  localparam int unsigned KmPgWin = 8192;  // eFuse program window after the go
  localparam int unsigned KmLevelWin = 100;  // wipe level held high for many cycles
  localparam logic [1:0] KmOkay = 2'b00;
  localparam logic [1:0] KmSlverr = 2'b10;
  localparam logic [1:0] KmDecerr = 2'b11;

  // --- KM memory map (hw/ip/key_manager/regs/gen/adoc/memory_map.adoc) ---
  localparam logic [31:0] KmRomBase = 32'(key_manager_addrmap_pkg::KEY_MANAGER_ROM_BASE_ADDR);
  localparam logic [31:0] KmRomEnd = KmRomBase + 32'(key_manager_addrmap_pkg::KEY_MANAGER_ROM_SIZE);
  localparam logic [31:0] KmSramBase = 32'(key_manager_addrmap_pkg::KEY_MANAGER_SRAM_BASE_ADDR);
  localparam logic [31:0] KmSramEnd = KmSramBase +
      32'(key_manager_addrmap_pkg::KEY_MANAGER_SRAM_SIZE);
  localparam logic [31:0] KmMbxBase = 32'(key_manager_addrmap_pkg::KEY_MANAGER_MAILBOX_KM_BASE_ADDR);
  localparam logic [31:0] KmEfMapBase =
      32'(key_manager_addrmap_pkg::KEY_MANAGER_OTP_EFUSE_MAP_BASE_ADDR);
  localparam logic [31:0] KmEfCtrlBase =
      32'(key_manager_addrmap_pkg::KEY_MANAGER_OTP_EFUSE_CTRL_BASE_ADDR);
  localparam logic [31:0] KmEfMmrBase =
      32'(key_manager_addrmap_pkg::KEY_MANAGER_OTP_EFUSE_MMR_BASE_ADDR);
  localparam logic [31:0] KmKpvBase = 32'(key_manager_addrmap_pkg::KEY_MANAGER_KPV_BASE_ADDR);
  // CTRL[0] follows the 64 key entries.
  localparam logic [31:0] KmKpvCtrl0 = KmKpvBase +
      32'(key_manager_addrmap_pkg::KEY_MANAGER_KPV_KEY_ENTRY_TOTAL_SIZE);
  localparam logic [31:0] KmKpvScrKey =
      32'(key_manager_addrmap_pkg::KEY_MANAGER_KPV_KPV_SCRAMBLER_KEY_BASE_ADDR);
  localparam logic [31:0] KmKpvScrCtrl =
      32'(key_manager_addrmap_pkg::KEY_MANAGER_KPV_KPV_SCRAMBLER_CTRL_BASE_ADDR);
  localparam logic [31:0] KmCsrBase = 32'(key_manager_addrmap_pkg::KEY_MANAGER_KMCSR_BASE_ADDR);
  localparam logic [31:0] KmSmpBase =
      32'(key_manager_addrmap_pkg::KEY_MANAGER_DRBG_SAMPLER_BASE_ADDR);
  localparam logic [31:0] KmOtbnBase =
      32'(key_manager_addrmap_pkg::KEY_MANAGER_OTBN_WRAPPER_KEY_BASE_ADDR);
  localparam logic [31:0] KmAesBase = 32'(key_manager_addrmap_pkg::KEY_MANAGER_AES_WRAPPER_KEY_BASE_ADDR);
  localparam logic [31:0] KmKmacBase =
      32'(key_manager_addrmap_pkg::KEY_MANAGER_KMAC_WRAPPER_KEY_BASE_ADDR);
  localparam logic [31:0] KmHmacBase =
      32'(key_manager_addrmap_pkg::KEY_MANAGER_HMAC_WRAPPER_KEY_BASE_ADDR);
  localparam logic [31:0] KmAbrBase = 32'(key_manager_addrmap_pkg::KEY_MANAGER_ABR_WRAPPER_KEY_BASE_ADDR);
  // VROM window base (hw/ip/key_manager/doc/architecture.adoc:663).
  localparam logic [31:0] KmVromBase = 32'h1000_0000;
  // KMCSR registers.
  localparam logic [31:0] KmCsrVersion =
      32'(key_manager_addrmap_pkg::KEY_MANAGER_KMCSR_VERSION_BASE_ADDR);
  localparam logic [31:0] KmCsrCtrl = 32'(key_manager_addrmap_pkg::KEY_MANAGER_KMCSR_CTRL_BASE_ADDR);
  localparam logic [31:0] KmCsrSoftRst =
      32'(key_manager_addrmap_pkg::KEY_MANAGER_KMCSR_SOFT_RST_CODE_BASE_ADDR);
  localparam logic [31:0] KmCsrIrqStatus =
      32'(key_manager_addrmap_pkg::KEY_MANAGER_KMCSR_IRQ_STATUS_BASE_ADDR);
  localparam logic [31:0] KmCsrScrKey =
      32'(key_manager_addrmap_pkg::KEY_MANAGER_KMCSR_SCRAMBLER_KEY_BASE_ADDR);
  localparam logic [31:0] KmCsrScrCtrl =
      32'(key_manager_addrmap_pkg::KEY_MANAGER_KMCSR_SCRAMBLER_CTRL_BASE_ADDR);
  localparam logic [31:0] KmCsrSramLock =
      32'(key_manager_addrmap_pkg::KEY_MANAGER_KMCSR_SRAM_LOCK_BASE_ADDR);
  localparam logic [31:0] KmCsrExecMode =
      32'(key_manager_addrmap_pkg::KEY_MANAGER_KMCSR_SRAM_EXEC_MODE_BASE_ADDR);
  localparam logic [31:0] KmCsrEntryAddr =
      32'(key_manager_addrmap_pkg::KEY_MANAGER_KMCSR_IRQ_ENTRY_ADDR_BASE_ADDR);
  localparam logic [31:0] KmCsrEntryLock =
      32'(key_manager_addrmap_pkg::KEY_MANAGER_KMCSR_IRQ_ENTRY_LOCK_BASE_ADDR);
  localparam logic [31:0] KmCsrDebug = 32'(key_manager_addrmap_pkg::KEY_MANAGER_KMCSR_DEBUG_BASE_ADDR);
  localparam logic [31:0] KmCsrLifeCycle =
      32'(key_manager_addrmap_pkg::KEY_MANAGER_KMCSR_OTP_LIFE_CYCLE_BASE_ADDR);
  localparam logic [31:0] KmCsrDemotion =
      32'(key_manager_addrmap_pkg::KEY_MANAGER_KMCSR_OTP_DEMOTION_STATE_BASE_ADDR);
  localparam logic [31:0] KmCsrReadLock =
      32'(key_manager_addrmap_pkg::KEY_MANAGER_KMCSR_OTP_READ_LOCK_BASE_ADDR);
  localparam logic [31:0] KmCsrReadLockCold =
      32'(key_manager_addrmap_pkg::KEY_MANAGER_KMCSR_OTP_READ_LOCK_COLD_BASE_ADDR);
  localparam logic [31:0] KmCsrChgStatus =
      32'(key_manager_addrmap_pkg::KEY_MANAGER_KMCSR_OTP_CHANGE_STATUS_BASE_ADDR);
  // The 7 dual-rail readout fields in OTP_READ_LOCK bit order 2 to 8, each 8
  // value words then 8 complement words (km_csr.adoc).
  localparam logic [31:0] KmCsrOtpChipletUid = KmCsrBase + 32'h200;
  localparam logic [31:0] KmCsrOtpSepChipletId = KmCsrBase + 32'h400;
  // DRBG sampler registers.
  localparam logic [31:0] KmSmpData = 32'(key_manager_addrmap_pkg::KEY_MANAGER_DRBG_SAMPLER_DATA_BASE_ADDR);
  localparam logic [31:0] KmSmpCfg = 32'(key_manager_addrmap_pkg::KEY_MANAGER_DRBG_SAMPLER_CFG_BASE_ADDR);
  localparam logic [31:0] KmSmpStatus =
      32'(key_manager_addrmap_pkg::KEY_MANAGER_DRBG_SAMPLER_STATUS_BASE_ADDR);
  localparam logic [31:0] KmSmpPfData =
      32'(key_manager_addrmap_pkg::KEY_MANAGER_DRBG_SAMPLER_PREFETCH_DATA_BASE_ADDR);
  // Mailbox KM side.
  localparam logic [31:0] KmMbxIrqStatus =
      32'(key_manager_addrmap_pkg::KEY_MANAGER_MAILBOX_KM_KM_IRQ_STATUS_BASE_ADDR);
  // ABR shared key.
  localparam logic [31:0] KmSkKeyCtrl =
      32'(key_manager_addrmap_pkg::KEY_MANAGER_ABR_WRAPPER_KEY_MLKEM_SHARED_KEY_KEY_CTRL_BASE_ADDR);
  localparam logic [31:0] KmSkIrqStatus =
      32'(key_manager_addrmap_pkg::KEY_MANAGER_ABR_WRAPPER_KEY_MLKEM_SHARED_KEY_IRQ_STATUS_BASE_ADDR);
  localparam logic [31:0] KmSkIrqEnable =
      32'(key_manager_addrmap_pkg::KEY_MANAGER_ABR_WRAPPER_KEY_MLKEM_SHARED_KEY_IRQ_ENABLE_BASE_ADDR);
  // Reset values from km_csr.adoc: VERSION major 1, minor 0, patch 0;
  // DEBUG magic; IRQ_ENTRY_ADDR 0x10. SOFT_RST_CODE accepts 'SRST'.
  localparam logic [31:0] KmVersionReset = 32'h0001_0000;
  localparam logic [31:0] KmDebugMagic = 32'hCAFE_BEEF;
  localparam logic [31:0] KmEntryReset = 32'h0000_0010;
  localparam logic [31:0] KmSoftRstCode = 32'h5352_5354;
  // KM DRBG sampler CFG reset (km_drbg_sampler.adoc, CFG: timeout 0x100,
  // prefetch 0) and the bad response data of the eFuse gaps.
  localparam logic [16:0] KmSmpCfgReset = {16'h0100, 1'b0};
  localparam logic [31:0] KmBadcab = 32'hBADC_AB1E;
  // eFuse program control (efuse_interface_ctrl.adoc), at its SEP address.
  localparam logic [31:0] KmEfPgCtrl = EFUSE_INTERFACE_CTRL_EFUSE_PROGRAM_CTRL_REG_ADDR;
  localparam logic [31:0] KmEfPgGo = EFUSE_INTERFACE_CTRL_EFUSE_PROGRAM_CTRL_EFUSE_PROGRAM_GO_MASK;
  // DRBG sampler DATA-read states (architecture.adoc, table "Key Manager
  // DRBG sampler states"): idle, request, byte assembly, respond, timeout,
  // stream error.
  localparam logic [2:0] KmStIdle = 3'd0;
  localparam logic [2:0] KmStRequest = 3'd1;
  localparam logic [2:0] KmStTimeout = 3'd4;
  localparam logic [2:0] KmStStreamErr = 3'd5;
  // Release write of km_sw_rst_n: the leaf raises AWVALID of the SW_RESET_N
  // write that sets bit 0 W host clocks after the km_sw_rst_n fall
  // (cp_rd_hold). The bins hold W.

  function automatic logic km_in(logic [31:0] a, logic [31:0] lo, logic [31:0] size);
    return (a >= lo) && (a < lo + size);
  endfunction

  // Engine key bank of a KM address, in DEST_VALID bit order (0 HMAC, 1 KMAC,
  // 2 AES, 3 OTBN, 4 MLDSA_SEED, 5 MLKEM_SEED_D, 6 MLKEM_SEED_Z, 7 MLKEM_MSG),
  // and the bank base; 4'hF when the address is in no bank.
  function automatic logic [3:0] km_bank(logic [31:0] a);
    if (km_in(a, KmHmacBase, 32'h44)) return 4'd0;
    if (km_in(a, KmKmacBase, 32'h44)) return 4'd1;
    if (km_in(a, KmAesBase, 32'h44)) return 4'd2;
    if (km_in(a, KmOtbnBase, 32'h64)) return 4'd3;
    if (km_in(a, KmAbrBase + 32'h000, 32'h44)) return 4'd4;
    if (km_in(a, KmAbrBase + 32'h100, 32'h44)) return 4'd5;
    if (km_in(a, KmAbrBase + 32'h200, 32'h44)) return 4'd6;
    if (km_in(a, KmAbrBase + 32'h300, 32'h44)) return 4'd7;
    return 4'hF;
  endfunction

  function automatic logic [31:0] km_bank_base(logic [3:0] b);
    case (b)
      4'd0: return KmHmacBase;
      4'd1: return KmKmacBase;
      4'd2: return KmAesBase;
      4'd3: return KmOtbnBase;
      4'd4: return KmAbrBase;
      4'd5: return KmAbrBase + 32'h100;
      4'd6: return KmAbrBase + 32'h200;
      default: return KmAbrBase + 32'h300;
    endcase
  endfunction

  // Share-word count of a bank: OTBN 12 words per share, the others 8
  // (otbn_wrapper_key.adoc, the *_wrapper_key.adoc maps).
  function automatic logic [4:0] km_bank_words(logic [3:0] b);
    return (b == 4'd3) ? 5'd12 : 5'd8;
  endfunction

  // Byte offset of KEY_CTRL in a bank: after the two shares.
  function automatic logic [31:0] km_bank_ctl_off(logic [3:0] b);
    return 32'(km_bank_words(b)) << 3;
  endfunction

  // OTP readout field of a KMCSR address: 0 life cycle, 1 demotion, 2..8 the
  // dual-rail fields in OTP_READ_LOCK order; rail 1 is the complement half.
  // field 4'hF when the address is not a readout word.
  function automatic logic [8:0] km_otp_word(logic [31:0] a);
    logic [31:0] off;
    if (a == KmCsrLifeCycle) return {4'd0, 5'd16};
    if (a == KmCsrDemotion) return {4'd1, 5'd16};
    if (km_in(a, KmCsrOtpChipletUid, 32'h100)) begin
      off = a - KmCsrOtpChipletUid;
      return {4'(2 + off[7:6]), 1'b0, off[5:2]};
    end
    if (km_in(a, KmCsrOtpSepChipletId, 32'hC0)) begin
      off = a - KmCsrOtpSepChipletId;
      return {4'(6 + off[7:6]), 1'b0, off[5:2]};
    end
    return {4'hF, 5'd0};
  endfunction

  // --- KM CPU AXI master: one transaction in flight ----------------------
  // The PicoRV32 AXI adapter waits for each response before the next
  // request, so the address and the data latched at the start belong to the
  // response. A write event fires one clock after its B handshake, so the
  // taps show the stored result; a read event fires on its R handshake.
  wire km_rst_cold_n = (km_rst_i[2] !== 1'b0);
  wire km_rst_warm_n = (km_rst_i[3] !== 1'b0);
  wire km_soft_n = (km_rst_i[1] !== 1'b0);
  wire km_swrst_n = (km_rst_i[0] !== 1'b0);
  wire kx_aw_v = (km_axi_req_i.aw_valid === 1'b1);
  wire kx_ar_v = (km_axi_req_i.ar_valid === 1'b1);
  wire kx_w_hs = (km_axi_req_i.w_valid === 1'b1) && (km_axi_resp_i.w_ready === 1'b1);
  wire kx_b_hs = (km_axi_resp_i.b_valid === 1'b1) && (km_axi_req_i.b_ready === 1'b1);
  wire kx_r_hs = (km_axi_resp_i.r_valid === 1'b1) && (km_axi_req_i.r_ready === 1'b1);
  logic kx_wbusy = 1'b0, kx_rbusy = 1'b0;
  logic [31:0] kx_waddr = '0, kx_wdata = '0, kx_raddr = '0;
  logic [3:0] kx_wstrb = '0;
  wire kx_wstart = kx_aw_v && !kx_wbusy;
  wire kx_rstart = kx_ar_v && !kx_rbusy;
  // Write event, one clock after the B handshake.
  logic kw_ev = 1'b0;
  logic [31:0] kw_addr = '0, kw_data = '0;
  logic [1:0] kw_resp = '0;
  // Snapshots at the start of the write and of the read (pre values).
  logic [11:0] kwp_irq_status = '0, krp_irq_status = '0;
  logic [11:0] kwp_irq_enable = '0;
  logic [31:0] kwp_scr_key = '0, kwp_sram_lock = '0, kwp_entry_addr = '0, kwp_sram_viol = '0;
  logic [1:0] kwp_scr_ctrl = '0;
  logic kwp_scr_lock = 1'b0, kwp_scr_en = 1'b0, kwp_entry_lock = 1'b0, kwp_exec = 1'b0;
  logic krp_scr_lock = 1'b0, krp_scr_en = 1'b0, krp_pf = 1'b0, krp_tvalid = 1'b0;
  logic [8:0] kwp_rlock = '0, kwp_rlock_cold = '0, kwp_chg = '0;
  logic [8:0] krp_rlock = '0, krp_rlock_cold = '0;
  logic [255:0] kwp_kpv_ctrl = '0, krp_kpv_ctrl = '0;
  logic [1:0] kwp_kpv_scr = '0;
  logic [1:0] kwp_smp_sticky = '0;
  logic [15:0] kwp_good = '0;
  logic [7:0] kwp_bad = '0;
  logic [2:0] kwp_mbx_km_irq = '0;
  logic kwp_sk_valid = 1'b0, kwp_sk_irq = 1'b0;
  logic [7:0] kwp_key_valid = '0;
  logic kwp_engaged = 1'b0;
  logic [32767:0] kwp_kpv_words = '0;
  logic krp_secure_tm = 1'b0, krp_sigint = 1'b0;
  // ROM lockout (architecture.adoc, ROM Lockout): armed by
  // SRAM_EXEC_MODE.enable, engaged on the first committed instruction fetch
  // from a write-locked SRAM address, cleared by a warm or cold reset.
  logic km_engaged = 1'b0;
  // The demotion state at the KM OTP input differs from its value at the
  // last KM cold release (a DEMOTE write since the boot).
  logic km_dem_changed = 1'b0;

  always @(posedge clk_i) begin
    kw_ev <= 1'b0;
    if (!km_rst_warm_n || !km_rst_cold_n) begin
      kx_wbusy <= 1'b0;
      kx_rbusy <= 1'b0;
    end else begin
      if (kx_wstart) begin
        kx_wbusy <= 1'b1;
        kx_waddr <= 32'(km_axi_req_i.aw.addr);
        kwp_irq_status <= km_irq_status_i;
        kwp_irq_enable <= km_irq_enable_i;
        kwp_scr_key <= km_scr_key_i;
        kwp_scr_ctrl <= km_scr_ctrl_i;
        kwp_scr_lock <= (km_scr_lock_i === 1'b1);
        kwp_scr_en <= (km_scr_en_i === 1'b1);
        kwp_sram_lock <= km_sram_lock_i;
        kwp_sram_viol <= km_sram_viol_i;
        kwp_entry_addr <= km_irq_entry_addr_i;
        kwp_entry_lock <= (km_irq_entry_lock_i === 1'b1);
        kwp_exec <= (km_sram_exec_mode_i === 1'b1);
        kwp_rlock <= km_otp_rlock_i;
        kwp_rlock_cold <= km_otp_rlock_cold_i;
        kwp_chg <= km_otp_chg_i;
        kwp_kpv_ctrl <= km_kpv_ctrl_i;
        kwp_kpv_scr <= km_kpv_scr_ctrl_i;
        kwp_kpv_words <= km_kpv_words_i;
        kwp_smp_sticky <= km_smp_sticky_i;
        kwp_good <= km_smp_count_good_i;
        kwp_bad <= km_smp_count_bad_i;
        kwp_mbx_km_irq <= km_mbx_km_irq_i;
        kwp_sk_valid <= (km_sk_valid_i === 1'b1);
        kwp_sk_irq <= (km_sk_irq_status_i === 1'b1);
        kwp_key_valid <= km_key_valid_i;
        kwp_engaged <= km_engaged;
      end
      if (kx_w_hs) begin
        kx_wdata <= 32'(km_axi_req_i.w.data);
        kx_wstrb <= 4'(km_axi_req_i.w.strb);
      end
      if (kx_b_hs && kx_wbusy) begin
        kx_wbusy <= 1'b0;
        kw_ev <= 1'b1;
        kw_addr <= kx_waddr;
        kw_data <= kx_w_hs ? 32'(km_axi_req_i.w.data) : kx_wdata;
        kw_resp <= 2'(km_axi_resp_i.b.resp);
      end
      if (kx_rstart) begin
        kx_rbusy <= 1'b1;
        kx_raddr <= 32'(km_axi_req_i.ar.addr);
        krp_irq_status <= km_irq_status_i;
        krp_scr_lock <= (km_scr_lock_i === 1'b1);
        krp_scr_en <= (km_scr_en_i === 1'b1);
        krp_rlock <= km_otp_rlock_i;
        krp_rlock_cold <= km_otp_rlock_cold_i;
        krp_kpv_ctrl <= km_kpv_ctrl_i;
        krp_pf <= (km_smp_prefetched_i === 1'b1);
        krp_tvalid <= (km_smp_tvalid_i === 1'b1);
        krp_secure_tm <= (km_secure_tm_i === 1'b1);
        krp_sigint <= (km_irq_status_i[9] === 1'b1);
      end
      if (kx_r_hs && kx_rbusy) kx_rbusy <= 1'b0;
    end
  end
  wire kr_ev = kx_r_hs && kx_rbusy && km_rst_warm_n && km_rst_cold_n;
  wire [31:0] kr_addr = kx_raddr;
  wire [31:0] kr_data = 32'(km_axi_resp_i.r.data);
  wire [1:0] kr_resp = 2'(km_axi_resp_i.r.resp);

  // --- KM CPU memory bus (ROM, SRAM, fetches) ---------------------------
  // A native access starts on the first clock of mem_valid and completes on
  // mem_ready. The fields are taken at the start.
  logic km_mb_busy = 1'b0;
  wire km_mb_v = (km_mem_valid_i === 1'b1);
  wire km_mb_rdy = (km_mem_ready_i === 1'b1);
  wire km_mb_start = km_mb_v && !km_mb_busy;
  wire km_mb_instr = (km_mem_instr_i === 1'b1);
  wire km_mb_wr = (km_mem_wstrb_i !== 4'h0) && !$isunknown(km_mem_wstrb_i);
  wire km_mb_rom = km_in(km_mem_addr_i, KmRomBase, KmRomEnd - KmRomBase);
  wire km_mb_sram = km_in(km_mem_addr_i, KmSramBase, KmSramEnd - KmSramBase);
  wire [4:0] km_mb_region = 5'((km_mem_addr_i - KmSramBase) >> 10);
  // Committed fetch: an instruction fetch that completes.
  wire km_fetch_done = km_mb_v && km_mb_rdy && km_mb_instr;
  always @(posedge clk_i) begin
    if (!km_rst_warm_n || !km_rst_cold_n) begin
      km_mb_busy <= 1'b0;
      km_engaged <= 1'b0;
    end else begin
      if (km_mb_start && !km_mb_rdy) km_mb_busy <= 1'b1;
      else if (km_mb_v && km_mb_rdy) km_mb_busy <= 1'b0;
      if (km_fetch_done && (km_sram_exec_mode_i === 1'b1) && km_mb_sram &&
          (km_sram_lock_i[km_mb_region] === 1'b1))
        km_engaged <= 1'b1;
    end
  end

  // --- KM reset edges ----------------------------------------------------
  // A warm reset is rst_warm_sync_n low with rst_cold_aasd_n high. A release
  // event fires KmSettle clocks after the reset net rises. The pre values
  // are the copies of the clock before the reset net fell.
  logic km_cold_q = 1'b1, km_warm_q = 1'b1, km_soft_q = 1'b1, km_swrst_q = 1'b1;
  logic km_warm_only = 1'b0;  // the reset in progress is a warm reset
  logic km_warm_soft = 1'b0;  // the warm reset in progress came from SOFT_RST_CODE
  logic [3:0] km_rel_cnt = '0;
  logic km_rel_cold = 1'b0;  // the release in progress is a cold release
  logic km_rel_ev = 1'b0;  // KmSettle clocks after a reset release
  // Previous-clock copies and the pre-reset record.
  logic [255:0] km_ctrl_q = '0, km_rst_pre_ctrl = '0;
  logic [1:0] km_kpv_scr_q = '0, km_rst_pre_kpv_scr = '0;
  logic [1:0] km_scr_ctrl_q = '0, km_rst_pre_scr_ctrl = '0;
  logic [31:0] km_sram_lock_q = '0, km_rst_pre_sram_lock = '0;
  logic [8:0]
      km_rlock_q = '0, km_rlock_cold_q = '0, km_rst_pre_rlock = '0, km_rst_pre_rlock_cold = '0;
  logic km_cbd_q = 1'b0, km_rst_pre_cbd = 1'b0;
  logic km_exec_q = 1'b0, km_rst_pre_exec = 1'b0, km_rst_pre_engaged = 1'b0;
  logic [16:0] km_smp_cfg_q = '0;
  logic km_unrec_q = 1'b0;
  wire km_cold_fall = km_cold_q && !km_rst_cold_n;
  wire km_warm_fall = km_warm_q && !km_rst_warm_n && km_rst_cold_n;
  wire km_any_rel = (!km_cold_q && km_rst_cold_n) || (!km_warm_q && km_rst_warm_n && km_rst_cold_n);
  always @(posedge clk_i) begin
    km_cold_q <= km_rst_cold_n;
    km_warm_q <= km_rst_warm_n;
    km_soft_q <= km_soft_n;
    km_swrst_q <= km_swrst_n;
    km_ctrl_q <= km_kpv_ctrl_i;
    km_kpv_scr_q <= km_kpv_scr_ctrl_i;
    km_scr_ctrl_q <= km_scr_ctrl_i;
    km_sram_lock_q <= km_sram_lock_i;
    km_rlock_q <= km_otp_rlock_i;
    km_rlock_cold_q <= km_otp_rlock_cold_i;
    km_cbd_q <= (km_cold_boot_done_i === 1'b1);
    km_exec_q <= (km_sram_exec_mode_i === 1'b1);
    km_smp_cfg_q <= km_smp_cfg_i;
    km_unrec_q <= (km_unrec_err_i === 1'b1);
    km_rel_ev <= 1'b0;
    if (km_cold_fall || km_warm_fall) begin
      // The copies of the last clock before the fall are the pre values.
      km_rst_pre_ctrl <= km_ctrl_q;
      km_rst_pre_kpv_scr <= km_kpv_scr_q;
      km_rst_pre_scr_ctrl <= km_scr_ctrl_q;
      km_rst_pre_sram_lock <= km_sram_lock_q;
      km_rst_pre_rlock <= km_rlock_q;
      km_rst_pre_rlock_cold <= km_rlock_cold_q;
      km_rst_pre_cbd <= km_cbd_q;
      km_rst_pre_exec <= km_exec_q;
      km_rst_pre_engaged <= km_engaged;
      km_warm_only <= !km_cold_fall;
      km_warm_soft <= !km_cold_fall && !km_soft_q;
    end
    if (!km_rst_cold_n) km_warm_only <= 1'b0;
    if (km_warm_fall && !km_soft_n) km_warm_soft <= 1'b1;
    if (km_any_rel) begin
      km_rel_cnt <= 4'd1;
      km_rel_cold <= !km_warm_only;
    end else if (km_rel_cnt != 4'd0) begin
      if (km_rel_cnt == 4'(KmSettle)) begin
        km_rel_cnt <= 4'd0;
        km_rel_ev <= 1'b1;
      end else km_rel_cnt <= km_rel_cnt + 4'd1;
    end
  end

  // ---------------------------------------------------------------------
  // Covergroups. sample(pt, v): pt selects the coverpoint, v is its value.
  // ---------------------------------------------------------------------
  covergroup sep_km_mailbox_fault_cg with function sample (logic [4:0] pt, logic [15:0] v);
    option.per_instance = 1;
    option.name = "sep_km_mailbox_fault_cg";
    // 0 KM inbound underflow, 1 KM outbound overflow.
    cp_mbf_cond: coverpoint v[0] iff (pt == 5'd0) {
      bins km_inbound_underflow = {1'b0}; bins km_outbound_overflow = {1'b1};
    }
    // {condition, response bit}.
    cp_mbf_resp_cfg: coverpoint v[1:0] iff (pt == 5'd1) {
      bins underflow_resp0 = {2'b00};
      bins underflow_resp1 = {2'b01};
      bins overflow_resp0 = {2'b10};
      bins overflow_resp1 = {2'b11};
    }
    // {bit (0 KM inbound underflow, 1 KM outbound overflow, 2 KM
    // flushed_by_sep, 3 SEP flushed_by_km), action (0 W1C clears, 1 write 0
    // keeps, 2 persists after its cause)}.
    cp_mbf_sticky_clear: coverpoint v[3:0] iff (pt == 5'd2) {
      bins km_in_underflow[] = {4'b00_00, 4'b00_01, 4'b00_10};
      bins km_out_overflow[] = {4'b01_00, 4'b01_01, 4'b01_10};
      bins km_flushed_by_sep[] = {4'b10_00, 4'b10_01, 4'b10_10};
      bins sep_flushed_by_km[] = {4'b11_00, 4'b11_01, 4'b11_10};
    }
    // {initiator (0 SEP, 1 KM), fill (0 both empty, 1 one non-empty, 2
    // both non-empty)}.
    cp_mbf_flush: coverpoint v[2:0] iff (pt == 5'd3) {
      bins sep_both_empty = {3'b0_00};
      bins sep_one_nonempty = {3'b0_01};
      bins sep_both_nonempty = {3'b0_10};
      bins km_both_empty = {3'b1_00};
      bins km_one_nonempty = {3'b1_01};
      bins km_both_nonempty = {3'b1_10};
    }
    // A frame with a header CRC fault (0), an invalid command ID (1) or a
    // PAYLOAD_LEN that contradicts the wire (2), answered by its RESP_CMD.
    cp_mbf_raw_transport: coverpoint v[1:0] iff (pt == 5'd4) {
      bins bad_header_crc = {2'd0};
      bins illegal_command_id = {2'd1};
      bins inconsistent_length = {2'd2};
    }
    // {response (0 OKAY, 1 SLVERR), condition (0 KM inbound underflow, 1 KM
    // outbound overflow)}: the KM access that caused the error completes with
    // the response that the KM_CTRL response bit selects, and the sticky
    // KM_IRQ_STATUS bit of the condition is set.
    cp_mbf_sticky_x_resp: coverpoint v[1:0] iff (pt == 5'd5) {
      bins underflow_okay_sticky = {2'b0_0};
      bins overflow_okay_sticky = {2'b0_1};
      bins underflow_slverr_sticky = {2'b1_0};
      bins overflow_slverr_sticky = {2'b1_1};
    }
  endgroup

  covergroup sep_km_mailbox_transport_cg with function sample (logic [4:0] pt, logic [15:0] v);
    option.per_instance = 1;
    option.name = "sep_km_mailbox_transport_cg";
    // {requester (0 SEP, 1 KM), access (0 write own FIFO, 1 read other FIFO)}.
    cp_mbt_access: coverpoint v[1:0] iff (pt == 5'd0) {
      bins sep_write_own = {2'b00};
      bins sep_read_other = {2'b01};
      bins km_write_own = {2'b10};
      bins km_read_other = {2'b11};
    }
    // {direction (0 inbound, 1 outbound), class (0 empty, 1 one word, 2 15
    // words, 3 16 words, 4 an empty or full flag that disagrees with the
    // depth)}.
    cp_mbt_occupancy: coverpoint v[3:0] iff (pt == 5'd1) {
      bins inbound_empty = {4'b0_000};
      bins inbound_one = {4'b0_001};
      bins inbound_fifteen = {4'b0_010};
      bins inbound_full = {4'b0_011};
      bins outbound_empty = {4'b1_000};
      bins outbound_one = {4'b1_001};
      bins outbound_fifteen = {4'b1_010};
      bins outbound_full = {4'b1_011};
      illegal_bins flag_disagrees_with_depth = {4'b0_100, 4'b1_100};
    }
    // 0 arm then write, 1 write without arm, 2 read a word with the separator
    // set, 3 read a word with it clear, 4 separator words passed in both
    // directions, 5 the set bit self-clears at its write.
    cp_mbt_separator: coverpoint v[2:0] iff (pt == 5'd2) {
      bins arm_then_write = {3'd0};
      bins write_without_arm = {3'd1};
      bins read_separator_set = {3'd2};
      bins read_separator_clear = {3'd3};
      bins both_directions = {3'd4};
      bins set_self_clears = {3'd5};
    }
    // KM side {source, enable}: sources 0 data available, 1 write space,
    // 2 inbound underflow, 3 outbound overflow, 4 flushed by SEP. The SEP-side
    // cells are added with their owner.
    cp_mbt_irq_src_x_en: coverpoint v[3:0] iff (pt == 5'd3) {
      bins km_data_avail_en0 = {4'b000_0};
      bins km_data_avail_en1 = {4'b000_1};
      bins km_write_space_en0 = {4'b001_0};
      bins km_write_space_en1 = {4'b001_1};
      bins km_in_underflow_en0 = {4'b010_0};
      bins km_in_underflow_en1 = {4'b010_1};
      bins km_out_overflow_en0 = {4'b011_0};
      bins km_out_overflow_en1 = {4'b011_1};
      bins km_flushed_by_sep_en0 = {4'b100_0};
      bins km_flushed_by_sep_en1 = {4'b100_1};
    }
    // KM aggregate: 0 rises with (status AND enable) non-zero, 1 falls when a
    // level cause clears, 2 a sticky source holds it until its W1C. The SEP
    // aggregate on PIC source 15 is added with its owner.
    cp_mbt_irq_aggregate: coverpoint v[1:0] iff (pt == 5'd4) {
      bins aggregate_rises = {2'd0};
      bins level_source_falls = {2'd1};
      bins sticky_source_held_until_w1c = {2'd2};
    }
  endgroup

  covergroup sep_km_memory_boot_cg with function sample (logic [4:0] pt, logic [15:0] v);
    option.per_instance = 1;
    option.name = "sep_km_memory_boot_cg";
    cp_mem_iface_req: coverpoint v[1:0] iff (pt == 5'd0) {
      bins rom_read = {2'd0};
      bins sram_read = {2'd1};
      bins sram_write = {2'd2};
      bins rom_write_at_cpu_bus = {2'd3};
    }
    cp_mem_scr_key_access: coverpoint v[1:0] iff (pt == 5'd1) {
      bins write_unlocked_accepted = {2'd0};
      bins read_unlocked_value = {2'd1};
      bins write_locked_ignored = {2'd2};
      bins read_locked_zero = {2'd3};
    }
    cp_mem_scr_ctrl: coverpoint v[2:0] iff (pt == 5'd2) {
      bins enable0 = {3'd0};
      bins enable1 = {3'd1};
      bins lock_write_once_with_enable1 = {3'd2};
      bins lock_write0_no_effect = {3'd3};
      bins kept_by_warm_reset = {3'd4};
      bins cleared_by_cold_reset = {3'd5};
      bins lock_with_enable0_forces_scrambling = {3'd6};
    }
    // Region 1 to 31 set by a write of 1 and kept by a later write of 0.
    cp_km_sram_region: coverpoint v[4:0] iff (pt == 5'd3) {
      bins region[] = {[5'd1 : 5'd31]};
    }
    cp_mem_r31: coverpoint v[0] iff (pt == 5'd4) {
      bins locked_store_dropped = {1'b0}; bins unlocked_store_accepted = {1'b1};
    }
    cp_km_scr_key: coverpoint v[1:0] iff (pt == 5'd5) {
      bins key_write_enabled_unlocked_resident = {2'd0};
      bins old_key_written_back = {2'd1};
      bins key_write_after_lock = {2'd2};
    }
    cp_mem_boot_order: coverpoint v[0] iff (pt == 5'd6) {
      bins cold_boot_done_before_ready = {1'b0}; bins ready_first_with_seq0 = {1'b1};
    }
    cp_mem_boot_type: coverpoint v[0] iff (pt == 5'd7) {
      bins cold_boot_writes_key = {1'b0}; bins warm_boot_writes_no_key = {1'b1};
    }
    // Grant-to-rvalid latency 1 to 4; 9: two different delayed latencies in
    // one run.
    cp_km_sram_latency: coverpoint v[3:0] iff (pt == 5'd8) {
      bins latency[] = {[4'd1 : 4'd4]};
      bins two_values_in_one_run = {4'd9};
      illegal_bins latency0 = {4'd0};
    }
  endgroup

  covergroup sep_km_kpv_slot_cg with function sample (logic [4:0] pt, logic [15:0] v);
    option.per_instance = 1;
    option.name = "sep_km_kpv_slot_cg";
    cp_kpv_slot_index: coverpoint v[5:0] iff (pt == 5'd0) {bins slot[] = {[6'd0 : 6'd63]};}
    cp_kpv_word_index: coverpoint v[3:0] iff (pt == 5'd1) {bins word[] = {[4'd0 : 4'd15]};}
    cp_kpv_post_reset: coverpoint v[0] iff (pt == 5'd2) {
      bins all_ctrl_zero_after_cold = {1'b0}; bins all_ctrl_zero_after_warm = {1'b1};
    }
    // {field (0 lock_write, 1 lock_use, 2 erase, 3 seal), rule (0 write 1
    // sets, 1 write 0 leaves, 2 three identical writes)}.
    cp_kpv_ctrl_write: coverpoint v[3:0] iff (pt == 5'd3) {
      bins lock_write[] = {4'b00_00, 4'b00_01, 4'b00_10};
      bins lock_use[] = {4'b01_00, 4'b01_01, 4'b01_10};
      bins erase[] = {4'b10_00, 4'b10_01, 4'b10_10};
      bins seal[] = {4'b11_00, 4'b11_01, 4'b11_10};
    }
    cp_kpv_lock_write: coverpoint v[2:0] iff (pt == 5'd4) {
      bins set_by_write1 = {3'd0};
      bins key_write_lands_while_clear = {3'd1};
      bins ctrl_writable_while_set = {3'd2};
      bins cleared_by_warm_reset = {3'd3};
      bins cleared_by_cold_reset = {3'd4};
      bins held_while_sealed = {3'd5};
    }
    cp_kpv_lock_use: coverpoint v[2:0] iff (pt == 5'd5) {
      bins set_by_write1 = {3'd0};
      bins read_while_clear_returns_data = {3'd1};
      bins set_by_hw_on_sealed_erase = {3'd2};
      bins cleared_by_warm_reset = {3'd3};
      bins key_write_lands_while_set = {3'd4};
    }
    cp_kpv_erase: coverpoint v[1:0] iff (pt == 5'd6) {
      bins in_flight_self_clears = {2'd0};
      bins unsealed_slot_freed = {2'd1};
      bins sealed_slot_retired = {2'd2};
      bins never_blocked_by_locks = {2'd3};
    }
    cp_kpv_seal: coverpoint v[2:0] iff (pt == 5'd7) {
      bins seal_sets_seal_and_lock_write = {3'd0};
      bins key_read_on_sealed_slot = {3'd1};
      bins write0_no_effect = {3'd2};
      bins cleared_by_warm_reset = {3'd3};
      bins seal_during_erase_retires = {3'd4};
    }
    cp_kpv_scramble_mode: coverpoint v[2:0] iff (pt == 5'd8) {
      bins enable0_write = {3'd0};
      bins enable1_one_stored_word_changes = {3'd1};
      bins kept_by_warm_reset = {3'd2};
      bins cleared_by_cold_reset = {3'd3};
      bins cleared_by_wipe = {3'd4};
    }
    cp_kpv_trailing: coverpoint v[0] iff (pt == 5'd9) {
      bins unwritten_word_kept = {1'b0}; bins unwritten_word_zero_with_lock_use = {1'b1};
    }
  endgroup

  covergroup sep_km_kpv_locked_access_cg with function sample (logic [4:0] pt, logic [15:0] v);
    option.per_instance = 1;
    option.name = "sep_km_kpv_locked_access_cg";
    // {state (0 free, 1 write-locked, 2 read-locked, 3 both, 4 sealed, 5
    // retired), op (0 key read, 1 key write, 2 erase)}. The write-locked key
    // write and erase are controls of their owner and are not cells.
    cp_kpv_state_x_op: coverpoint v[4:0] iff (pt == 5'd0) {
      bins free[] = {5'b000_00, 5'b000_01, 5'b000_10};
      bins write_locked_read = {5'b001_00};
      bins read_locked[] = {5'b010_00, 5'b010_01, 5'b010_10};
      bins both_locked[] = {5'b011_00, 5'b011_01, 5'b011_10};
      bins sealed[] = {5'b100_00, 5'b100_01, 5'b100_10};
      bins retired[] = {5'b101_00, 5'b101_01, 5'b101_10};
    }
    cp_kpv_locked_write: coverpoint v[1:0] iff (pt == 5'd1) {
      bins write_locked_slot_slverr = {2'd0};
      bins write0_lock_write_no_effect = {2'd1};
      bins other_ctrl_bit_lands = {2'd2};
    }
    cp_kpv_locked_read: coverpoint v[0] iff (pt == 5'd2) {
      bins read_locked_slot_slverr_zero = {1'b0}; bins lock_use_set_by_sealed_erase = {1'b1};
    }
    cp_kpv_retired: coverpoint v[0] iff (pt == 5'd3) {
      bins refused_before_repeat_erase = {1'b0}; bins refused_after_repeat_erase = {1'b1};
    }
    // {state (0 locked, 1 sealed, 2 retired), slot (0 slot 0, 1 slot 63)}.
    cp_kpv_boundary: coverpoint v[2:0] iff (pt == 5'd4) {
      bins locked_slot0 = {3'b00_0};
      bins locked_slot63 = {3'b00_1};
      bins sealed_slot0 = {3'b01_0};
      bins sealed_slot63 = {3'b01_1};
      bins retired_slot0 = {3'b10_0};
      bins retired_slot63 = {3'b10_1};
    }
  endgroup

  covergroup sep_km_secret_nonexposure_cg with function sample (logic [4:0] pt, logic [15:0] v);
    option.per_instance = 1;
    option.name = "sep_km_secret_nonexposure_cg";
    // {bank[2:0] in DEST_VALID order, share, word[3:0]}: 8 words per share,
    // 12 for OTBN (bank 3).
    cp_nx_share_read: coverpoint v[7:0] iff (pt == 5'd0) {
      bins hmac[] = {[8'h00 : 8'h07], [8'h10 : 8'h17]};
      bins kmac[] = {[8'h20 : 8'h27], [8'h30 : 8'h37]};
      bins aes[] = {[8'h40 : 8'h47], [8'h50 : 8'h57]};
      bins otbn[] = {[8'h60 : 8'h6B], [8'h70 : 8'h7B]};
      bins mldsa_seed[] = {[8'h80 : 8'h87], [8'h90 : 8'h97]};
      bins mlkem_seed_d[] = {[8'hA0 : 8'hA7], [8'hB0 : 8'hB7]};
      bins mlkem_seed_z[] = {[8'hC0 : 8'hC7], [8'hD0 : 8'hD7]};
      bins mlkem_msg[] = {[8'hE0 : 8'hE7], [8'hF0 : 8'hF7]};
    }
    // Before the handover: VAL_0 of CHIPLET_UID, SIP_UID, SYS_UID and
    // CLASS_KEY reads non-zero (0 to 3). At the jump of the handover:
    // OTP_READ_LOCK bits 2 to 5 read 1 (4 to 7).
    cp_nx_epoch_secret: coverpoint v[2:0] iff (pt == 5'd1) {
      bins chiplet_uid_nonzero_pre_handover = {3'd0};
      bins sip_uid_nonzero_pre_handover = {3'd1};
      bins sys_uid_nonzero_pre_handover = {3'd2};
      bins class_key_nonzero_pre_handover = {3'd3};
      bins chiplet_uid_locked_post_handover = {3'd4};
      bins sip_uid_locked_post_handover = {3'd5};
      bins sys_uid_locked_post_handover = {3'd6};
      bins class_key_locked_post_handover = {3'd7};
    }
    // 1 CMD_KEY_LOAD, 2 CMD_KEY_TRANSFER: a RESP_CMD of 3 or 4 payload
    // words. The CMD_KEY_GENERATE and CMD_ABR_SK_TRANSFER cells are blocked
    // (docs/SEP_FCOV.adoc).
    cp_nx_resp_payload: coverpoint v[1:0] iff (pt == 5'd2) {
      bins key_load = {2'd1}; bins key_transfer = {2'd2};
    }
    cp_nx_permitted_channel: coverpoint v[0] iff (pt == 5'd3) {
      bins sep_write_data_accepted = {1'b0};
    }
  endgroup

  covergroup sep_km_kmcsr_status_cg with function sample (logic [4:0] pt, logic [15:0] v);
    option.per_instance = 1;
    option.name = "sep_km_kmcsr_status_cg";
    cp_csr_version: coverpoint v[0] iff (pt == 5'd0) {bins version_1_0_0 = {1'b1};}
    cp_csr_irq_source: coverpoint v[3:0] iff (pt == 5'd1) {bins source[] = {[4'd0 : 4'd11]};}
    // {source[3:0], rule (0 W1C clears, 1 write 0 keeps, 2 W1C of other bits
    // keeps)}.
    cp_csr_status_semantics: coverpoint v[5:0] iff (pt == 5'd2) {
      wildcard bins w1c_clears[] = {6'b0000_00, 6'b0001_00, 6'b0010_00, 6'b0011_00,
                                    6'b0100_00, 6'b0101_00, 6'b0110_00, 6'b0111_00,
                                    6'b1000_00, 6'b1001_00, 6'b1010_00, 6'b1011_00};
      wildcard bins zero_keeps[] = {6'b0000_01, 6'b0001_01, 6'b0010_01, 6'b0011_01,
                                    6'b0100_01, 6'b0101_01, 6'b0110_01, 6'b0111_01,
                                    6'b1000_01, 6'b1001_01, 6'b1010_01, 6'b1011_01};
      wildcard bins other_w1c_keeps[] = {6'b0000_10, 6'b0001_10, 6'b0010_10, 6'b0011_10,
                                         6'b0100_10, 6'b0101_10, 6'b0110_10, 6'b0111_10,
                                         6'b1000_10, 6'b1001_10, 6'b1010_10, 6'b1011_10};
    }
    // {source[3:0], enable}.
    cp_csr_src_x_en: coverpoint v[4:0] iff (pt == 5'd3) {
      bins en0[] = {5'b0000_0, 5'b0001_0, 5'b0010_0, 5'b0011_0, 5'b0100_0, 5'b0101_0,
                    5'b0110_0, 5'b0111_0, 5'b1000_0, 5'b1001_0, 5'b1010_0, 5'b1011_0};
      bins en1[] = {5'b0000_1, 5'b0001_1, 5'b0010_1, 5'b0011_1, 5'b0100_1, 5'b0101_1,
                    5'b0110_1, 5'b0111_1, 5'b1000_1, 5'b1001_1, 5'b1010_1, 5'b1011_1};
    }
    cp_csr_aggregate: coverpoint v[1:0] iff (pt == 5'd4) {
      bins rises = {2'd0}; bins falls_on_last_clear = {2'd1}; bins reset_all_masked = {2'd2};
    }
    cp_csr_entry_vector: coverpoint v[1:0] iff (pt == 5'd5) {
      bins reset_0x10 = {2'd0};
      bins aligned = {2'd1};
      bins unaligned = {2'd2};
      bins all_ones = {2'd3};
    }
    // 4: at the jump of the handover, address 0x10 and lock 0.
    cp_csr_entry_lock: coverpoint v[2:0] iff (pt == 5'd6) {
      bins lock0_allows_write = {3'd0};
      bins lock_write_once = {3'd1};
      bins lock_write0_no_effect = {3'd2};
      bins locked_addr_write_ignored = {3'd3};
      bins after_handover_0x10_lock0 = {3'd4};
    }
    cp_csr_debug_ctrl_read: coverpoint v[0] iff (pt == 5'd7) {
      bins debug_cafebeef = {1'b0}; bins ctrl_zero = {1'b1};
    }
    cp_csr_recov_err: coverpoint v[1:0] iff (pt == 5'd8) {
      bins set_after_fault = {2'd0};
      bins cleared_by_recov_ack = {2'd1};
      bins cleared_by_warm_reset = {2'd2};
      bins visible_on_pic_bit31 = {2'd3};
    }
    // {rank of the winner (kq_rank_bit order), a lower-ranked source set}.
    // (wipe_state, alone) is a control of the owner and is not a bin.
    cp_csr_isr_winner: coverpoint v[4:0] iff (pt == 5'd9) {
      bins wipe_state_with_lower = {5'h01};
      bins rom_parity[] = {5'h02, 5'h03};
      bins sram_parity[] = {5'h04, 5'h05};
      bins rom_write[] = {5'h06, 5'h07};
      bins sram_write_lock[] = {5'h08, 5'h09};
      bins axi_decerr[] = {5'h0A, 5'h0B};
      bins drbg_err[] = {5'h0C, 5'h0D};
      bins axi_slverr[] = {5'h0E, 5'h0F};
      bins otp_sigint[] = {5'h10, 5'h11};
      bins exec[] = {5'h12, 5'h13};
      bins rom_access_alone = {5'h14};
      ignore_bins rom_access_with_lower = {5'h15};
    }
    // An IRQ_SET write of a non-zero mask to a clear IRQ_STATUS sets exactly
    // the mask bits.
    cp_csr_irq_set: coverpoint v[0] iff (pt == 5'd10) {
      bins mask_sets_exactly = {1'b1};
    }
  endgroup

  covergroup sep_km_otp_readout_cg with function sample (logic [4:0] pt, logic [15:0] v);
    option.per_instance = 1;
    option.name = "sep_km_otp_readout_cg";
    cp_otp_field: coverpoint v[3:0] iff (pt == 5'd0) {
      bins life_cycle = {4'd0};
      bins demotion = {4'd1};
      bins chiplet_uid = {4'd2};
      bins sip_uid = {4'd3};
      bins sys_uid = {4'd4};
      bins class_key = {4'd5};
      bins sep_chiplet_id = {4'd6};
      bins sep_sip_id = {4'd7};
      bins sep_sys_id = {4'd8};
    }
    // {field[3:0] 2 to 8, value word 0-7 / complement word 8-15}, and the two
    // decoded status registers.
    cp_otp_word_index: coverpoint v[8:0] iff (pt == 5'd1) {
      bins chiplet_uid[] = {[9'h040 : 9'h04F]};
      bins sip_uid[] = {[9'h060 : 9'h06F]};
      bins sys_uid[] = {[9'h080 : 9'h08F]};
      bins class_key[] = {[9'h0A0 : 9'h0AF]};
      bins sep_chiplet_id[] = {[9'h0C0 : 9'h0CF]};
      bins sep_sip_id[] = {[9'h0E0 : 9'h0EF]};
      bins sep_sys_id[] = {[9'h100 : 9'h10F]};
      bins life_cycle_reg = {9'h010};
      bins demotion_reg = {9'h030};
    }
    cp_otp_read_through: coverpoint v[1:0] iff (pt == 5'd2) {
      bins lc_test_dev = {2'd0};
      bins lc_prod = {2'd1};
      bins demotion_before_demote = {2'd2};
      bins demotion_after_demote = {2'd3};
    }
    // 0-8 a field changes with both rails consistent, 9 a stable value sets
    // nothing, 10 the demotion state kept by a KM warm reset sets nothing, 11
    // several fields change together, 12 W1C of a bit.
    cp_otp_change: coverpoint v[3:0] iff (pt == 5'd3) {
      bins field_change[] = {[4'd0 : 4'd8]};
      bins stable_sets_nothing = {4'd9};
      bins demotion_after_warm_reset_sets_nothing = {4'd10};
      bins several_fields_together = {4'd11};
      bins w1c_clears = {4'd12};
    }
    // {field[3:0], lock (0 neither, 1 warm only, 2 cold only, 3 both)}.
    cp_otp_lock_matrix: coverpoint v[5:0] iff (pt == 5'd4) {
      bins neither[] = {6'h00, 6'h04, 6'h08, 6'h0C, 6'h10, 6'h14, 6'h18, 6'h1C, 6'h20};
      bins warm_only[] = {6'h01, 6'h05, 6'h09, 6'h0D, 6'h11, 6'h15, 6'h19, 6'h1D, 6'h21};
      bins cold_only[] = {6'h02, 6'h06, 6'h0A, 6'h0E, 6'h12, 6'h16, 6'h1A, 6'h1E, 6'h22};
      bins both[] = {6'h03, 6'h07, 6'h0B, 6'h0F, 6'h13, 6'h17, 6'h1B, 6'h1F, 6'h23};
    }
    cp_otp_lock_reg: coverpoint v[2:0] iff (pt == 5'd5) {
      bins warm_reg_write1_sets = {3'd0};
      bins cold_reg_write1_sets = {3'd1};
      bins write0_no_effect = {3'd2};
      bins warm_reset_clears_warm_only = {3'd3};
      bins cold_reset_clears_both = {3'd4};
      bins three_identical_writes = {3'd5};
    }
    cp_otp_secure_tm: coverpoint v[1:0] iff (pt == 5'd6) {
      bins strap0_secret_staged = {2'd0};
      bins strap1_secret_masked_quiet = {2'd1};
      bins strap_stable_while_km_runs = {2'd2};
    }
    // {class (0 shadow map, 1 interface control, 2 token registers, 3 gap
    // 0x1141C, 4 gap 0x11574, 5 reserved 0x11600), response (0 OKAY, 1 SLVERR
    // with 0xBADCAB1E)}.
    cp_efw_read_class: coverpoint v[3:0] iff (pt == 5'd7) {
      bins shadow_okay = {4'b000_0};
      bins ctrl_okay = {4'b001_0};
      bins token_okay = {4'b010_0};
      bins gap_1141c_slverr = {4'b011_1};
      bins gap_11574_slverr = {4'b100_1};
      bins reserved_11600_slverr = {4'b101_1};
      ignore_bins no_such_response = {4'b000_1, 4'b001_1, 4'b010_1, 4'b011_0, 4'b100_0, 4'b101_0};
    }
    // {path (0 KM, 1 host), class (0 unlocked spare, 1 write-locked field, 2
    // secure test strap set)}.
    cp_efw_program: coverpoint v[2:0] iff (pt == 5'd8) {
      bins km_unlocked_spare = {3'b0_00};
      bins km_write_locked = {3'b0_01};
      bins km_strap_set = {3'b0_10};
      bins host_strap_set = {3'b1_10};
    }
    // The shadow-map class whose field alone differs between two cold boots,
    // with the KM OTP input equal in both boots: 0 BL1_VERSION or
    // BL2_VERSION, 1 an RMA token digest, 3 a public-key hash.
    cp_otp_notkm_class: coverpoint v[1:0] iff (pt == 5'd9) {
      bins arbc = {2'd0}; bins rma_digest = {2'd1}; bins pk_hash = {2'd3};
    }
    // A public identity with its eFuse read-lock bit set (LOCKS[59], [61],
    // [63]) on the KM OTP input as {~id, id} of the sensed field.
    cp_otp_efuse_lock_port: coverpoint v[1:0] iff (pt == 5'd10) {
      bins chiplet_id = {2'd0}; bins sip_id = {2'd1}; bins sys_id = {2'd2};
    }
  endgroup

  covergroup sep_km_integrity_fault_cg with function sample (logic [4:0] pt, logic [15:0] v);
    option.per_instance = 1;
    option.name = "sep_km_integrity_fault_cg";
    // Window index of km_window().
    cp_if_window: coverpoint v[4:0] iff (pt == 5'd0) {
      bins rom = {5'd0};
      bins rsv_4000 = {5'd1};
      bins sram = {5'd2};
      bins mailbox = {5'd3};
      bins rsv_10020 = {5'd4};
      bins efuse_map = {5'd5};
      bins efuse_ctrl = {5'd6};
      bins efuse_token = {5'd7};
      bins rsv_11600 = {5'd8};
      bins kpv = {5'd9};
      bins kmcsr = {5'd10};
      bins rsv_14800 = {5'd11};
      bins drbg = {5'd12};
      bins rsv_15010 = {5'd13};
      bins otbn = {5'd14};
      bins aes = {5'd15};
      bins kmac = {5'd16};
      bins hmac = {5'd17};
      bins abr = {5'd18};
      bins rsv_18080 = {5'd19};
      bins rsv_19080 = {5'd20};
      bins rsv_1a080 = {5'd21};
      bins rsv_1b080 = {5'd22};
      bins rsv_1c800 = {5'd23};
      bins vrom = {5'd24};
    }
    // {outcome (0 DECERR on reserved, 1 SLVERR past extent, 2 SLVERR with
    // 0xBADCAB1E in an eFuse gap), direction (0 read, 1 write)}.
    cp_if_decode_outcome: coverpoint v[2:0] iff (pt == 5'd1) {
      bins reserved_decerr_rd = {3'b00_0};
      bins reserved_decerr_wr = {3'b00_1};
      bins past_extent_slverr_rd = {3'b01_0};
      bins past_extent_slverr_wr = {3'b01_1};
      bins efuse_gap_slverr_rd = {3'b10_0};
      bins efuse_gap_slverr_wr = {3'b10_1};
    }
    // {row[3:0] of km_row(), class (0 first word, 1 last decoded word, 2
    // first hole word, 3 first word past the extent, 4 last word of the
    // span)}. The first word of the mailbox, the DRBG sampler and the five
    // key windows are not cells.
    cp_if_offset_class: coverpoint v[6:0] iff (pt == 5'd2) {
      bins rom[] = {7'h00, 7'h01, 7'h04};
      bins sram[] = {7'h08, 7'h09, 7'h0C};
      bins mailbox[] = {7'h11, 7'h13, 7'h14};
      bins efuse_map[] = {7'h18, 7'h19, 7'h1C};
      bins efuse_ctrl[] = {7'h20, 7'h21, 7'h23, 7'h24};
      bins efuse_token[] = {7'h28, 7'h29, 7'h2B, 7'h2C};
      bins kpv[] = {7'h30, 7'h31, 7'h33, 7'h34};
      bins kmcsr[] = {7'h38, 7'h39, 7'h3A, 7'h3B, 7'h3C};
      bins drbg[] = {7'h41, 7'h44};
      bins otbn[] = {7'h49, 7'h4B, 7'h4C};
      bins aes[] = {7'h51, 7'h53, 7'h54};
      bins kmac[] = {7'h59, 7'h5B, 7'h5C};
      bins hmac[] = {7'h61, 7'h63, 7'h64};
      bins abr[] = {7'h6A, 7'h69, 7'h6B, 7'h6C};
      ignore_bins class_not_in_row = {7'h02, 7'h03, 7'h0A, 7'h0B, 7'h12, 7'h1A, 7'h1B, 7'h22,
                                      7'h2A, 7'h32, 7'h42, 7'h43, 7'h4A, 7'h52, 7'h5A, 7'h62};
    }
    cp_if_efuse_remap: coverpoint v[0] iff (pt == 5'd3) {
      bins low12_equal_km_offset = {1'b0}; bins upper_constant_over_three_maps = {1'b1};
    }
    // {region[4:0] 1 to 31, store (0 to a locked region: dropped, violation
    // bit and IRQ bit set; 1 to an unlocked region: accepted, no bit)}.
    cp_if_sram_lock_violation: coverpoint v[5:0] iff (pt == 5'd4) {
      bins locked[] = {[6'b00001_0 : 6'b11111_0]} with (item[0] == 1'b0);
      bins unlocked[] = {[6'b00001_1 : 6'b11111_1]} with (item[0] == 1'b1);
    }
    // {field[3:0], class (0 complement correct, 1 value-rail flip, 2
    // complement-rail flip)}.
    cp_if_otp_dual_rail: coverpoint v[5:0] iff (pt == 5'd5) {
      bins value_change[] = {6'h00, 6'h04, 6'h08, 6'h0C, 6'h10, 6'h14, 6'h18, 6'h1C, 6'h20};
      bins value_rail_flip[] = {6'h01, 6'h05, 6'h09, 6'h0D, 6'h11, 6'h15, 6'h19, 6'h1D, 6'h21};
      bins complement_rail_flip[] = {6'h02, 6'h06, 6'h0A, 6'h0E, 6'h12, 6'h16, 6'h1A, 6'h1E, 6'h22};
    }
    // 0: a ROM write before the lockout is dropped with ROM_WRITE_ERR and no
    // AXI error bit; 1: a ROM write after the lockout.
    cp_if_rom_write: coverpoint v[0] iff (pt == 5'd6) {
      bins rom_write_pre_lockout_dropped = {1'b0}; bins rom_write_after_lockout = {1'b1};
    }
    // {memory (0 ROM, 1 SRAM), byte lane}.
    cp_if_parity: coverpoint v[2:0] iff (pt == 5'd7) {
      bins rom_lane[] = {[3'b0_00 : 3'b0_11]}; bins sram_lane[] = {[3'b1_00 : 3'b1_11]};
    }
    // A load (0) or a store (1) in the VROM window 0x10000000 to 0x1000FFFF
    // completes with DECERR and IRQ_STATUS.axi_decerr set.
    cp_if_vrom_outcome: coverpoint v[0] iff (pt == 5'd8) {
      bins load_decerr = {1'b0}; bins store_decerr = {1'b1};
    }
  endgroup

  covergroup sep_km_exec_protection_cg with function sample (logic [4:0] pt, logic [15:0] v);
    option.per_instance = 1;
    option.name = "sep_km_exec_protection_cg";
    // {enable, target[2:0] (0 ROM, 1 write-locked SRAM, 2 unlocked SRAM, 3
    // peripheral window, 4 0x10000000), outcome[1:0] (0 permitted, 1
    // EXEC_VIOLATION, 2 ROM_ACCESS_VIOLATION)}.
    cp_ex_mode_x_target: coverpoint v[5:0] iff (pt == 5'd0) {
      wildcard bins en0_rom = {6'b0_000_??};
      wildcard bins en0_locked_sram = {6'b0_001_??};
      wildcard bins en0_unlocked_sram = {6'b0_010_??};
      wildcard bins en0_periph = {6'b0_011_??};
      wildcard bins en0_vrom = {6'b0_100_??};
      wildcard bins en1_rom = {6'b1_000_??};
      wildcard bins en1_locked_sram = {6'b1_001_??};
      wildcard bins en1_unlocked_sram = {6'b1_010_??};
      wildcard bins en1_periph = {6'b1_011_??};
      wildcard bins en1_vrom = {6'b1_100_??};
      wildcard ignore_bins en0_rom_access_violation = {6'b0_???_10};
    }
    cp_ex_mode_enable: coverpoint v[1:0] iff (pt == 5'd1) {
      bins write1_sets = {2'd0};
      bins write0_no_effect = {2'd1};
      bins cleared_by_warm_reset = {2'd2};
      bins cleared_by_cold_reset = {2'd3};
    }
    // {lockout (0 enable 0, 1 enable 1 not engaged, 2 engaged), access (0 ROM
    // fetch, 1 ROM data read, 2 ROM write)}. The ROM write before the lockout
    // is a control of its owner and is not a cell.
    cp_ex_lockout_x_access: coverpoint v[3:0] iff (pt == 5'd2) {
      bins en0_fetch = {4'b00_00};
      bins en0_data_read = {4'b00_01};
      bins armed_fetch = {4'b01_00};
      bins armed_data_read = {4'b01_01};
      bins engaged_fetch = {4'b10_00};
      bins engaged_data_read = {4'b10_01};
      bins engaged_rom_write = {4'b10_10};
    }
    cp_ex_lockout_order: coverpoint v[0] iff (pt == 5'd3) {bins violation_before_trap = {1'b1};}
    cp_ex_lockout_irreversible: coverpoint v[0] iff (pt == 5'd4) {
      bins write0_after_engage_keeps = {1'b0}; bins reset_clears = {1'b1};
    }
  endgroup

  covergroup sep_km_drbg_sampler_cg with function sample (logic [4:0] pt, logic [15:0] v);
    option.per_instance = 1;
    option.name = "sep_km_drbg_sampler_cg";
    cp_smp_read_service: coverpoint v[0] iff (pt == 5'd0) {
      bins prefetched_word_at_once = {1'b0}; bins tready_and_wait = {1'b1};
    }
    // The delayed-arrival bins need the PROPOSED drive HK-STRM-PAT and are
    // not declared.
    cp_smp_tvalid_arrival: coverpoint v[0] iff (pt == 5'd1) {
      bins tvalid_high_at_read_start = {1'b1};
    }
    // Every TSTRB value other than 0xF needs the PROPOSED drive HK-STRM-PAT
    // and is not declared.
    cp_smp_strb: coverpoint v[3:0] iff (pt == 5'd2) {
      bins strb_f = {4'hF}; ignore_bins strb_0_not_stated = {4'h0};
    }
    cp_smp_freshness: coverpoint v[0] iff (pt == 5'd3) {bins new_word_per_read = {1'b1};}
    cp_smp_prefetch_mode: coverpoint v[2:0] iff (pt == 5'd4) {
      bins prefetch0 = {3'd0};
      bins prefetch1 = {3'd1};
      bins word_held_after_read = {3'd2};
      bins disable_clears_held_word = {3'd3};
      bins stalled_prefetch_no_timeout = {3'd4};
    }
    cp_smp_prefetch_mirror: coverpoint v[1:0] iff (pt == 5'd5) {
      bins equals_next_data_read = {2'd0};
      bins repeated_reads_one_value = {2'd1};
      bins cleared_when_disabled = {2'd2};
    }
    cp_smp_count_good: coverpoint v[2:0] iff (pt == 5'd6) {
      bins count0 = {3'd0};
      bins count1 = {3'd1};
      bins count_ffff = {3'd2};
      bins saturated_no_wrap = {3'd3};
      bins prefetched_not_counted = {3'd4};
      bins nonzero_write_clears = {3'd5};
      bins zero_write_keeps = {3'd6};
    }
    cp_smp_count_bad: coverpoint v[2:0] iff (pt == 5'd7) {
      bins count0 = {3'd0};
      bins count1 = {3'd1};
      bins count_ff = {3'd2};
      bins saturated_no_wrap = {3'd3};
      bins nonzero_write_clears = {3'd4};
      bins zero_write_keeps = {3'd5};
    }
    cp_smp_reset_defaults: coverpoint v[0] iff (pt == 5'd8) {
      bins after_cold_reset = {1'b0}; bins after_warm_reset = {1'b1};
    }
    cp_smp_ready: coverpoint v[0] iff (pt == 5'd9) {
      bins stalled_reads0 = {1'b0}; bins valid_reads1 = {1'b1};
    }
    // 0: a DATA read with prefetch 1 and no prefetched word takes the first
    // handshaken beat, alone; 1: a withdrawal while the prefetch path holds a
    // partial word discards it, the next DATA read returns the next live
    // beat, and CHK-SMP-PRE-WITHDRAW passed (label km_pwd_pass).
    cp_smp_prefetch_active_read: coverpoint v[0] iff (pt == 5'd10) {
      bins active_read_took_beat = {1'b0}; bins withdraw_discards_prefetch = {1'b1};
    }
    // 0: a DATA write answers SLVERR; 1: a PREFETCH_DATA write answers SLVERR;
    // 2: the held prefetched word stays after a PREFETCH_DATA write.
    cp_smp_write_refused: coverpoint v[1:0] iff (pt == 5'd11) {
      bins data_slverr = {2'd0};
      bins prefetch_data_slverr = {2'd1};
      bins prefetch_data_kept = {2'd2};
    }
  endgroup

  covergroup sep_km_drbg_fault_cg with function sample (logic [4:0] pt, logic [15:0] v);
    option.per_instance = 1;
    option.name = "sep_km_drbg_fault_cg";
    cp_df_timeout_value: coverpoint v[0] iff (pt == 5'd0) {
      bins timeout1 = {1'b0}; bins timeout65535 = {1'b1};
    }
    // The timeout from ST_BYTE_ASSEMBLY needs the PROPOSED drive HK-STRM-PAT
    // and is not declared.
    cp_df_entry_state: coverpoint v[0] iff (pt == 5'd1) {
      bins from_request = {1'b0};
    }
    cp_df_timeout_outcome: coverpoint v[1:0] iff (pt == 5'd2) {
      bins slverr_data0 = {2'd0};
      bins timeout_err_set = {2'd1};
      bins count_bad_plus1 = {2'd2};
      bins irq_drbg_err_set = {2'd3};
    }
    cp_df_stream_violation: coverpoint v[0] iff (pt == 5'd3) {
      bins no_read_active = {1'b0}; bins first_active_cycle_tready_low = {1'b1};
    }
    cp_df_offset_race: coverpoint v[0] iff (pt == 5'd4) {
      bins timeout1_same_cycle = {1'b0}; bins timeout2_before_expiry = {1'b1};
    }
    // {bit (0 TIMEOUT_ERR, 1 STREAM_ERR), write (0 W1C clears, 1 write 0
    // keeps)}.
    cp_df_status_clear: coverpoint v[1:0] iff (pt == 5'd5) {
      bins timeout_err_w1c = {2'b00};
      bins timeout_err_w0_keeps = {2'b01};
      bins stream_err_w1c = {2'b10};
      bins stream_err_w0_keeps = {2'b11};
    }
    cp_df_trng_reset: coverpoint v[0] iff (pt == 5'd6) {
      bins first_read_clean_after_trng_reset = {1'b1};
    }
    // A KM reset while a DATA read waits (TREADY high): TREADY falls, stays low
    // while the reset holds, and the read takes no beat.
    cp_df_warm_cancel: coverpoint v[0] iff (pt == 5'd7) {
      bins pending_read_dropped = {1'b1};
    }
    // A stalled read with CFG.TIMEOUT 40: TREADY high for exactly 40 clocks with
    // no handshake, then SLVERR with data 0.
    cp_df_exact_budget: coverpoint v[0] iff (pt == 5'd8) {
      bins t40_exact = {1'b1};
    }
  endgroup

  covergroup sep_km_fault_report_cg with function sample (logic [4:0] pt, logic [15:0] v);
    option.per_instance = 1;
    option.name = "sep_km_fault_report_cg";
    cp_fr_err_out: coverpoint v[2:0] iff (pt == 5'd0) {
      bins low_in_normal_operation = {3'd0};
      bins high_on_trap = {3'd1};
      bins stays_high_until_reset = {3'd2};
      bins cleared_by_warm_reset = {3'd3};
      bins cleared_by_cold_reset = {3'd4};
      bins no_command_answered_while_high = {3'd5};
      bins port_equals_pic = {3'd6};
    }
    cp_km_trap_cause: coverpoint v[2:0] iff (pt == 5'd1) {
      bins ebreak_masked = {3'd0};
      bins illegal_instruction = {3'd1};
      bins misaligned_access = {3'd2};
      bins ebreak_in_handler = {3'd3};
      bins illegal_in_handler = {3'd4};
      bins undefined_crc_encoding = {3'd5};
    }
    // The sign-extended code byte of RESP_UNRECOVERABLE_FAULT.
    cp_fr_unrec_code: coverpoint v[7:0] iff (pt == 5'd2) {
      bins rom_parity = {8'hFE};
      bins sram_parity = {8'hFD};
      bins rom_write = {8'hFC};
      bins sram_write_lock = {8'hFB};
      bins axi_decerr = {8'hFA};
      bins axi_slverr = {8'hF9};
      bins drbg_err = {8'hF8};
      bins otp_sigint = {8'hF3};
      bins fw_crc = {8'hF2};
      bins exec = {8'hEF};
      bins rom_access = {8'hEE};
    }
    cp_fr_code_encoding: coverpoint v[1:0] iff (pt == 5'd3) {
      bins recoverable_sign_extended = {2'd0};
      bins unrecoverable_sign_extended = {2'd1};
      bins drbg_not_slverr_in_same_set = {2'd2};
    }
    cp_fr_flow_order: coverpoint v[1:0] iff (pt == 5'd4) {
      bins key_valid_cleared_before_report = {2'd0};
      bins mailbox_flushed_before_report = {2'd1};
      bins report_before_sram_burst = {2'd2};
      bins sram_burst_before_err_out = {2'd3};
    }
    cp_fr_wipe_predicate: coverpoint v[0] iff (pt == 5'd5) {
      bins predicate_on_both_shreds = {1'b0}; bins predicate_off_keys_stay = {1'b1};
    }
    cp_fr_rec_code: coverpoint v[1:0] iff (pt == 5'd6) {
      bins key_slot_crc = {2'd0}; bins rx_buff_oflow = {2'd1}; bins flushed_by_sep = {2'd2};
    }
    cp_fr_resp_pairing: coverpoint v[0] iff (pt == 5'd7) {
      bins fault_then_failure_resp_cmd = {1'b0}; bins fault_frame_alone = {1'b1};
    }
    // {cause (0 rx_buff_oflow, 1 flushed_by_sep), step (0 no paired RESP_CMD,
    // 1 first response sequence 0, 2 gated command refused, 3 CMD_RECOV_ACK
    // then recov_fault 0, 4 gated command accepted)}.
    cp_fr_recovery_handshake: coverpoint v[3:0] iff (pt == 5'd8) {
      bins rx_oflow[] = {[4'b0_000 : 4'b0_100]};
      bins flush[] = {4'b1_000, 4'b1_001, 4'b1_010, 4'b1_100};
    }
    // Halting handlers by rank (kq_rank_bit order) with IRQ_STATUS still set
    // after the halt; 11 the informational shared-key handler.
    cp_fr_isr_disposition: coverpoint v[3:0] iff (pt == 5'd9) {
      bins halting[] = {[4'd0 : 4'd10]}; bins informational_shared_key = {4'd11};
    }
  endgroup

  covergroup sep_km_reset_domain_cg with function sample (logic [4:0] pt, logic [15:0] v);
    option.per_instance = 1;
    option.name = "sep_km_reset_domain_cg";
    cp_rd_source: coverpoint v[1:0] iff (pt == 5'd0) {
      bins km_sw_rst_n_while_running = {2'd0};
      bins cold_reset = {2'd1};
      bins soft_rst_code_accepted = {2'd2};
    }
    cp_rd_soft_wrong: coverpoint v[1:0] iff (pt == 5'd1) {
      bins zero = {2'd0}; bins all_ones = {2'd1}; bins one_bit_neighbour = {2'd2};
    }
    // {witness (0 SRAM_LOCK, 1 OTP_READ_LOCK, 2 OTP_READ_LOCK_COLD, 3
    // COLD_BOOT_DONE), flavour (0 cold, 1 warm)}.
    cp_rd_matrix: coverpoint v[2:0] iff (pt == 5'd2) {
      bins sram_lock_cold = {3'b00_0};
      bins sram_lock_warm = {3'b00_1};
      bins otp_read_lock_cold = {3'b01_0};
      bins otp_read_lock_warm = {3'b01_1};
      bins otp_read_lock_cold_reg_cold = {3'b10_0};
      bins otp_read_lock_cold_reg_warm = {3'b10_1};
      bins cold_boot_done_cold = {3'b11_0};
      bins cold_boot_done_warm = {3'b11_1};
    }
    cp_rd_cbd_history: coverpoint v[1:0] iff (pt == 5'd3) {
      bins zero_after_cold_reset = {2'd0};
      bins one_after_rom_sets = {2'd1};
      bins one_after_soft_reset = {2'd2};
      bins zero_after_next_cold_reset = {2'd3};
    }
    // Host hold W of km_sw_rst_n, with the warm reset held at least 10
    // clocks after the release.
    cp_rd_hold: coverpoint v[4:0] iff (pt == 5'd4) {
      bins hold1 = {5'd1}; bins hold2 = {5'd2}; bins hold5 = {5'd5}; bins hold12 = {5'd12};
    }
    cp_rd_isolation: coverpoint v[1:0] iff (pt == 5'd5) {
      bins hmac_stays0 = {2'd0}; bins kmac_stays0 = {2'd1}; bins abr_stays0 = {2'd2};
    }
  endgroup

  covergroup sep_km_sideload_delivery_cg with function sample (logic [4:0] pt, logic [15:0] v);
    option.per_instance = 1;
    option.name = "sep_km_sideload_delivery_cg";
    // The clear by the engine SW_RESET_N reset is not stated as a KM-side
    // key register effect (docs/SEP_FCOV.adoc, Bins not graded).
    cp_sd_key_valid_semantics: coverpoint v[2:0] iff (pt == 5'd0) {
      bins reset_value0 = {3'd0};
      bins write1_sets = {3'd1};
      bins write1_twice = {3'd2};
      bins write0_clears = {3'd3};
      ignore_bins cleared_by_engine_reset = {3'd4};
    }
    cp_sd_mask_shape: coverpoint v[1:0] iff (pt == 5'd1) {
      bins single_bit = {2'd0}; bins bit_with_others = {2'd1}; bins all_eight = {2'd2};
    }
    // {command (1 CMD_KEY_TRANSFER, 2 CMD_ENGINE_SHRED, 3 CMD_KEY_LOAD),
    // DEST_VALID bit}. The CMD_KEY_GENERATE (0) and CMD_ABR_SK_TRANSFER (4)
    // rows are blocked (docs/SEP_FCOV.adoc).
    cp_sd_dest_x_cmd: coverpoint v[5:0] iff (pt == 5'd2) {
      bins key_transfer[] = {[6'b001_000 : 6'b001_111]};
      bins engine_shred[] = {[6'b010_000 : 6'b010_111]};
      bins key_load[] = {[6'b011_000 : 6'b011_111]};
    }
    // {DEST_VALID bit (0 HMAC, 1 KMAC, 2 AES, 3 OTBN, 4 ABR ML-DSA seed),
    // size against the share width (0 below, 1 equal, 2 above)}.
    cp_km_size_vs_width: coverpoint v[4:0] iff (pt == 5'd3) {
      bins hmac[] = {5'b000_00, 5'b000_01, 5'b000_10};
      bins kmac[] = {5'b001_00, 5'b001_01, 5'b001_10};
      bins aes[] = {5'b010_00, 5'b010_01, 5'b010_10};
      bins otbn[] = {5'b011_00, 5'b011_01, 5'b011_10};
      bins mldsa_seed[] = {5'b100_00, 5'b100_01, 5'b100_10};
    }
    // A shred of a bank: 0 the KEY_CTRL write first, 1 at least 2 x width
    // share-word writes, 2 a bank that held no key.
    cp_sd_shred_order: coverpoint v[1:0] iff (pt == 5'd4) {
      bins key_valid0_first = {2'd0};
      bins share_words_after = {2'd1};
      bins bank_without_key = {2'd2};
    }
    // After a KM wipe of an AES bank whose two shares held non-zero words, only
    // share 0 (0) or only share 1 (1) is written; at the key_valid rise the
    // written share is non-zero and the other share is zero.
    cp_sd_single_share: coverpoint v[0] iff (pt == 5'd5) {
      bins share0_only = {1'b0}; bins share1_only = {1'b1};
    }
  endgroup

  covergroup sep_km_abr_shared_key_cg with function sample (logic [4:0] pt, logic [15:0] v);
    option.per_instance = 1;
    option.name = "sep_km_abr_shared_key_cg";
    cp_sk_delivery_state: coverpoint v[1:0] iff (pt == 5'd0) {
      bins no_key_pending = {2'd0};
      bins abr_delivers = {2'd1};
      bins firmware_consumes = {2'd2};
      bins second_delivery_reloads = {2'd3};
    }
    cp_sk_write_dir: coverpoint v[0] iff (pt == 5'd1) {
      bins write0_accepted = {1'b0}; bins set_refused = {1'b1};
    }
    cp_sk_interrupt: coverpoint v[2:0] iff (pt == 5'd2) {
      bins set_by_hardware = {3'd0};
      bins enable0_line_low = {3'd1};
      bins enable1_line_high = {3'd2};
      bins w1c_clears = {3'd3};
      bins write0_keeps = {3'd4};
      bins second_delivery_sets_again = {3'd5};
    }
  endgroup

  covergroup sep_km_vault_wipe_cg with function sample (logic [4:0] pt, logic [15:0] v);
    option.per_instance = 1;
    option.name = "sep_km_vault_wipe_cg";
    cp_vw_pre_contents: coverpoint v[2:0] iff (pt == 5'd0) {
      bins empty = {3'd0};
      bins keys_in_unsealed_slots = {3'd1};
      bins keys_in_sealed_slots = {3'd2};
      bins retired_slots = {3'd3};
      bins kpv_scrambler_locked = {3'd4};
    }
    cp_vw_effect: coverpoint v[1:0] iff (pt == 5'd1) {
      bins sep_bit_vault_cleared = {2'd0};
      bins sep_bit_scrambler_cleared = {2'd1};
      bins cpu_trap_vault_cleared = {2'd2};
    }
    cp_vw_edge: coverpoint v[2:0] iff (pt == 5'd2) {
      bins rise_left_high = {3'd0};
      bins fall_rise_second_wipe = {3'd1};
      bins write1_while_high_no_wipe = {3'd2};
      bins level_held_high = {3'd3};
      bins high_one_clock_or_more = {3'd4};
    }
    cp_vw_scope: coverpoint v[1:0] iff (pt == 5'd3) {
      bins cpu_not_halted = {2'd0};
      bins sram_words_kept = {2'd1};
      bins mailbox_word_kept = {2'd2};
      bins engine_key_valid_cleared = {2'd3};
    }
    cp_vw_isr_flow: coverpoint v[1:0] iff (pt == 5'd4) {
      bins sideload_purged_before_report = {2'd0};
      bins sram_shred_after_report = {2'd1};
      bins wipe_state_left_set = {2'd2};
    }
    // 0 to 7: a bank in DEST_VALID order that held a key; 8: a bank that
    // held none; 9: the shared key with a delivery pending; 10: with none.
    cp_vw_handover_shred: coverpoint v[3:0] iff (pt == 5'd5) {
      bins bank_with_key[] = {[4'd0 : 4'd7]};
      bins bank_without_key = {4'd8};
      bins shared_key_pending = {4'd9};
      bins shared_key_none = {4'd10};
    }
    // A KM key-path write of the HMAC KEY_CTRL in the clock of an SEP wipe
    // pulse: key_valid of the HMAC bank reads 0 after the write. No open test
    // aligns a KM write with the wipe clear in one cycle, so the point is not
    // graded (docs/SEP_FCOV.adoc, Key Manager bins not graded). The sampler
    // makes 0 unreachable, so every value is an ignore bin.
    cp_vw_sideload_clear: coverpoint v[0] iff (pt == 5'd6) {
      option.weight = 0;
      ignore_bins km_write_same_cycle_loses = {1'b1};
      ignore_bins unreachable_no_clear = {1'b0};
    }
  endgroup

  sep_km_mailbox_fault_cg      u_sep_km_mailbox_fault_cg      = new();
  sep_km_mailbox_transport_cg  u_sep_km_mailbox_transport_cg  = new();
  sep_km_memory_boot_cg        u_sep_km_memory_boot_cg        = new();
  sep_km_kpv_slot_cg           u_sep_km_kpv_slot_cg           = new();
  sep_km_kpv_locked_access_cg  u_sep_km_kpv_locked_access_cg  = new();
  sep_km_secret_nonexposure_cg u_sep_km_secret_nonexposure_cg = new();
  sep_km_kmcsr_status_cg       u_sep_km_kmcsr_status_cg       = new();
  sep_km_otp_readout_cg        u_sep_km_otp_readout_cg        = new();
  sep_km_integrity_fault_cg    u_sep_km_integrity_fault_cg    = new();
  sep_km_exec_protection_cg    u_sep_km_exec_protection_cg    = new();
  sep_km_drbg_sampler_cg       u_sep_km_drbg_sampler_cg       = new();
  sep_km_drbg_fault_cg         u_sep_km_drbg_fault_cg         = new();
  sep_km_fault_report_cg       u_sep_km_fault_report_cg       = new();
  sep_km_reset_domain_cg       u_sep_km_reset_domain_cg       = new();
  sep_km_sideload_delivery_cg  u_sep_km_sideload_delivery_cg  = new();
  sep_km_abr_shared_key_cg     u_sep_km_abr_shared_key_cg     = new();
  sep_km_vault_wipe_cg         u_sep_km_vault_wipe_cg         = new();

  // ---------------------------------------------------------------------
  // KMCSR, KPV, scrambler, OTP and execute-protection points that a KM CPU
  // register write or read decides.
  // ---------------------------------------------------------------------
  // SCRAMBLER_KEY values before the last two key writes (cp_km_scr_key).
  logic [31:0] km_key_prev = '0, km_key_prev2 = '0;
  logic km_key_prev_v = 1'b0, km_key_prev2_v = 1'b0;
  // Scrambled SRAM writes since the KM cold reset (resident words).
  logic km_scr_resident = 1'b0;
  // A lock written with the enable at 0, waiting for the next SRAM write.
  logic km_lock_en0_pend = 1'b0;
  // SRAM_LOCK bits set by a write of 1 in this boot (cp_km_sram_region).
  logic [31:0] km_region_set = '0;
  // IRQ_ENTRY_ADDR written since the last KM reset.
  logic km_entry_written = 1'b0;
  // Identical consecutive writes: CTRL[s] (cp_kpv_ctrl_write) and the OTP
  // lock registers (cp_otp_lock_reg).
  logic [31:0] km_rep_addr = '0, km_rep_data = '0;
  logic [3:0] km_rep_post = '0;
  logic [8:0] km_rep_lock_post = '0;
  logic [1:0] km_rep_cnt = '0;
  // Per-slot state: retired-slot refusals before and after a repeated
  // erase, the seal-during-erase try, and the trailing-word record.
  logic [63:0] km_ret_rerased = '0;
  logic [63:0] km_ret_rd_ref0 = '0, km_ret_wr_ref0 = '0, km_ret_rd_ref1 = '0, km_ret_wr_ref1 = '0;
  logic [63:0] km_race_armed = '0, km_race_seen = '0;
  logic [63:0] km_tr_erased = '0, km_tr_wrote = '0;
  logic [15:0] km_tr_wmask[64];
  logic [15:0] km_tr_have[64];
  logic [31:0] km_tr_val[64][16];
  // The last key write for cp_kpv_scramble_mode.
  logic [31:0] km_scr_last_addr = '0, km_scr_last_data = '0;
  logic km_scr_last_v = 1'b0;
  // Engine KEY_CTRL written since the KM release (reset value bin).
  logic [7:0] km_bank_ctrl_written = '0;
  // A delivery of the shared key consumed in this boot, and W1C of its IRQ.
  logic km_sk_consumed = 1'b0, km_sk_irq_cleared = 1'b0;
  // Share words written with a non-zero value (cp_nx_share_read).
  logic [255:0] km_nx_written = '0;
  // eFuse remap: upper address bits seen per map.
  logic [19:0] km_remap_hi = '0;
  logic [2:0] km_remap_seen = '0;
  logic km_remap_bad = 1'b0;
  // Pass label of the KM decode points of the crossbar owner (written by
  // set_km_xbar_pass of env/sep_fcov_gate.py): [127:0] offset cells, [151:128]
  // windows 0 to 23, [157:152] cp_if_decode_outcome values, [159:158]
  // cp_if_vrom_outcome values (and the vrom bin of cp_if_window), [161:160]
  // cp_if_efuse_remap values, [173:162] cp_efw_read_class values. Each
  // sampler holds its seen cells and samples them on km_xbar_rise only.
  logic [173:0] km_xbar_pass = '0;
  logic km_xbar_pass_q = 1'b0;
  wire km_xbar_rise = km_own_xbar && (km_xbar_pass != '0) && !km_xbar_pass_q;
  logic [1:0] km_remap_ok = '0;
  initial begin
    for (int s = 0; s < 64; s++) begin
      km_tr_wmask[s] = '0;
      km_tr_have[s] = '0;
      for (int w = 0; w < 16; w++) km_tr_val[s][w] = '0;
    end
  end

  // KPV address decode: slot and word of a key-word address, slot of a CTRL
  // address.
  function automatic logic km_kpv_key(logic [31:0] a);
    return km_in(a, KmKpvBase, 32'h1000);
  endfunction
  function automatic logic km_kpv_ctl(logic [31:0] a);
    return km_in(a, KmKpvCtrl0, 32'h100);
  endfunction
  function automatic logic [5:0] km_kpv_slot(logic [31:0] a);
    return km_kpv_key(a) ? 6'((a - KmKpvBase) >> 6) : 6'((a - KmKpvCtrl0) >> 2);
  endfunction
  // Slot state of a CTRL value {seal, erase, lock_use, lock_write}: 0 free,
  // 1 write-locked, 2 read-locked, 3 both, 4 sealed, 5 retired, 7 other.
  function automatic logic [2:0] km_slot_state(logic [3:0] c);
    if (c[3] && c[1] && c[0]) return 3'd5;
    if (c[3] && !c[1]) return 3'd4;
    if (c[3]) return 3'd7;
    case (c[1:0])
      2'b00: return 3'd0;
      2'b01: return 3'd1;
      2'b10: return 3'd2;
      default: return 3'd3;
    endcase
  endfunction

  always @(posedge clk_i) begin
    logic [3:0] pre_c, post_c, b;
    logic [5:0] s;
    logic [3:0] w;
    logic [8:0] ow;
    logic [2:0] st;
    int unsigned nchg;
    if (!km_rst_cold_n) begin
      km_scr_resident <= 1'b0;
      km_lock_en0_pend <= 1'b0;
      km_key_prev_v <= 1'b0;
      km_key_prev2_v <= 1'b0;
    end
    if (!km_rst_warm_n || !km_rst_cold_n) begin
      km_region_set <= '0;
      km_entry_written <= 1'b0;
      km_rep_cnt <= '0;
      km_ret_rerased <= '0;
      km_ret_rd_ref0 <= '0;
      km_ret_wr_ref0 <= '0;
      km_ret_rd_ref1 <= '0;
      km_ret_wr_ref1 <= '0;
      km_race_armed <= '0;
      km_race_seen <= '0;
      km_tr_erased <= '0;
      km_tr_wrote <= '0;
      km_scr_last_v <= 1'b0;
      km_bank_ctrl_written <= '0;
      km_sk_consumed <= 1'b0;
      km_sk_irq_cleared <= 1'b0;
      km_nx_written <= '0;
    end
    if ((km_sram_if_i[0] === 1'b1) && (km_sram_if_i[1] === 1'b1) && (km_sram_if_i[2] === 1'b1) &&
        (km_scr_en_i === 1'b1)) begin
      km_scr_resident <= 1'b1;
      if (km_lock_en0_pend && (km_own_scr || km_own_br))
        u_sep_km_memory_boot_cg.sample(5'd2, 16'd6);
      km_lock_en0_pend <= 1'b0;
    end

    // ---- register writes ----
    if (kw_ev) begin
      // KMCSR IRQ_STATUS: W1C, write 0, W1C of other bits (12 sources).
      if ((kw_addr == KmCsrIrqStatus) && km_own_csr) begin
        for (int i = 0; i < 12; i++) begin
          if (kwp_irq_status[i]) begin
            if (kw_data[i] && (km_irq_status_i[i] === 1'b0))
              u_sep_km_kmcsr_status_cg.sample(5'd2, 16'({4'(i), 2'd0}));
            else if ((kw_data[11:0] == 12'h0) && (km_irq_status_i[i] === 1'b1))
              u_sep_km_kmcsr_status_cg.sample(5'd2, 16'({4'(i), 2'd1}));
            else if (!kw_data[i] && (kw_data[11:0] != 12'h0) && (km_irq_status_i[i] === 1'b1))
              u_sep_km_kmcsr_status_cg.sample(5'd2, 16'({4'(i), 2'd2}));
          end
        end
      end
      // IRQ_ENTRY_ADDR and IRQ_ENTRY_LOCK.
      if (kw_addr == KmCsrEntryAddr) begin
        km_entry_written <= 1'b1;
        if (km_own_csr && !kwp_entry_lock && (km_irq_entry_addr_i === kw_data)) begin
          u_sep_km_kmcsr_status_cg.sample(5'd6, 16'd0);
          if (kw_data == 32'hFFFF_FFFF) u_sep_km_kmcsr_status_cg.sample(5'd5, 16'd3);
          else if (kw_data[1:0] != 2'b00) u_sep_km_kmcsr_status_cg.sample(5'd5, 16'd2);
          else if (kw_data != KmEntryReset) u_sep_km_kmcsr_status_cg.sample(5'd5, 16'd1);
        end
        if (km_own_csr && kwp_entry_lock && (kw_data != kwp_entry_addr) &&
            (km_irq_entry_addr_i === kwp_entry_addr))
          u_sep_km_kmcsr_status_cg.sample(5'd6, 16'd3);
      end
      if ((kw_addr == KmCsrEntryLock) && km_own_csr) begin
        if (!kwp_entry_lock && kw_data[0] && (km_irq_entry_lock_i === 1'b1))
          u_sep_km_kmcsr_status_cg.sample(5'd6, 16'd1);
        if (kwp_entry_lock && !kw_data[0] && (km_irq_entry_lock_i === 1'b1))
          u_sep_km_kmcsr_status_cg.sample(5'd6, 16'd2);
      end
      // SCRAMBLER_KEY (cp_mem_scr_key_access, cp_km_scr_key).
      if (kw_addr == KmCsrScrKey) begin
        if (!kwp_scr_lock && (km_scr_key_i === kw_data) && (km_own_csr || km_own_scr))
          u_sep_km_memory_boot_cg.sample(5'd1, 16'd0);
        if (kwp_scr_lock && (km_scr_key_i === kwp_scr_key) && (km_own_csr || km_own_scr))
          u_sep_km_memory_boot_cg.sample(5'd1, 16'd2);
        if (km_own_scr) begin
          if (!kwp_scr_lock && kwp_scr_en && km_scr_resident)
            u_sep_km_memory_boot_cg.sample(5'd5, 16'd0);
          if (!kwp_scr_lock && km_key_prev2_v && (kw_data == km_key_prev2) &&
              (kw_data != kwp_scr_key))
            u_sep_km_memory_boot_cg.sample(5'd5, 16'd1);
          if (kwp_scr_lock) u_sep_km_memory_boot_cg.sample(5'd5, 16'd2);
        end
        if (!kwp_scr_lock) begin
          km_key_prev2 <= kwp_scr_key;
          km_key_prev2_v <= km_key_prev_v;
          km_key_prev <= kw_data;
          km_key_prev_v <= 1'b1;
        end
      end
      // SCRAMBLER_CTRL {lock, enable} (cp_mem_scr_ctrl).
      if (kw_addr == KmCsrScrCtrl) begin
        if (!kwp_scr_lock && !kw_data[1] && !kw_data[0] && (km_scr_ctrl_i[0] === 1'b0) &&
            (km_own_csr || km_own_scr))
          u_sep_km_memory_boot_cg.sample(5'd2, 16'd0);
        if (km_own_scr || km_own_br) begin
          if (!kwp_scr_lock && !kw_data[1] && kw_data[0] && (km_scr_ctrl_i[0] === 1'b1))
            u_sep_km_memory_boot_cg.sample(5'd2, 16'd1);
          if (!kwp_scr_lock && (kw_data[1:0] == 2'b11) && (km_scr_ctrl_i === 2'b11))
            u_sep_km_memory_boot_cg.sample(5'd2, 16'd2);
          if (kwp_scr_lock && !kw_data[1] && (km_scr_ctrl_i[1] === 1'b1))
            u_sep_km_memory_boot_cg.sample(5'd2, 16'd3);
        end
        if (!kwp_scr_lock && (kw_data[1:0] == 2'b10)) km_lock_en0_pend <= 1'b1;
      end
      // SRAM_LOCK (cp_km_sram_region): set by a write of 1, kept by a 0.
      if (kw_addr == KmCsrSramLock) begin
        for (int r = 1; r < 32; r++) begin
          if (kw_data[r] && !kwp_sram_lock[r] && (km_sram_lock_i[r] === 1'b1))
            km_region_set[r] <= 1'b1;
          if (!kw_data[r] && km_region_set[r] && (km_sram_lock_i[r] === 1'b1) && km_own_csr)
            u_sep_km_memory_boot_cg.sample(5'd3, 16'(r));
        end
      end
      // SRAM_EXEC_MODE (cp_ex_mode_enable, cp_ex_lockout_irreversible).
      if ((kw_addr == KmCsrExecMode) && km_own_cpu) begin
        if (kw_data[0] && !kwp_exec && (km_sram_exec_mode_i === 1'b1))
          u_sep_km_exec_protection_cg.sample(5'd1, 16'd0);
        if (!kw_data[0] && kwp_exec && (km_sram_exec_mode_i === 1'b1)) begin
          u_sep_km_exec_protection_cg.sample(5'd1, 16'd1);
          if (kwp_engaged) u_sep_km_exec_protection_cg.sample(5'd4, 16'd0);
        end
      end
      // OTP_READ_LOCK and OTP_READ_LOCK_COLD (cp_otp_lock_reg).
      if ((kw_addr == KmCsrReadLock) || (kw_addr == KmCsrReadLockCold)) begin
        logic [8:0] pre_l, post_l;
        logic cold_reg;
        cold_reg = (kw_addr == KmCsrReadLockCold);
        pre_l = cold_reg ? kwp_rlock_cold : kwp_rlock;
        post_l = cold_reg ? km_otp_rlock_cold_i : km_otp_rlock_i;
        if (km_own_otp || km_own_ho) begin
          if (|(kw_data[8:0] & ~pre_l) && ((post_l & kw_data[8:0]) == kw_data[8:0]))
            u_sep_km_otp_readout_cg.sample(5'd5, cold_reg ? 16'd1 : 16'd0);
          if ((pre_l != 9'h0) && ((kw_data[8:0] & pre_l) != pre_l) && ((post_l & pre_l) == pre_l))
            u_sep_km_otp_readout_cg.sample(5'd5, 16'd2);
          if ((km_rep_cnt == 2'd2) && (km_rep_addr == kw_addr) && (km_rep_data == kw_data) &&
              (post_l === km_rep_lock_post) && (kw_data[8:0] != 9'h0))
            u_sep_km_otp_readout_cg.sample(5'd5, 16'd5);
        end
      end
      // OTP_CHANGE_STATUS W1C (cp_otp_change).
      if ((kw_addr == KmCsrChgStatus) && km_own_otp) begin
        if (|(kw_data[8:0] & kwp_chg & ~km_otp_chg_i)) u_sep_km_otp_readout_cg.sample(5'd3, 16'd12);
      end
      // KPV CTRL[s] (cp_kpv_ctrl_write, cp_kpv_lock_write, cp_kpv_lock_use,
      // cp_kpv_seal, cp_kpv_erase, cp_kpv_locked_write, cp_kpv_state_x_op).
      if (km_kpv_ctl(kw_addr)) begin
        s = km_kpv_slot(kw_addr);
        pre_c = kwp_kpv_ctrl[4*s+:4];
        post_c = km_kpv_ctrl_i[4*s+:4];
        st = km_slot_state(pre_c);
        // Field order of cp_kpv_ctrl_write: 0 lock_write, 1 lock_use, 2
        // erase, 3 seal.
        if (km_own_kpv || km_own_ho) begin
          for (int f = 0; f < 4; f++) begin
            if (kw_data[f] && !pre_c[f] && post_c[f])
              u_sep_km_kpv_slot_cg.sample(5'd3, 16'({2'(f), 2'd0}));
            // A write of 0 keeps a set lock bit; it starts no erase.
            if ((kw_data[3:0] == 4'h0) && ((f == 2) ? !post_c[f] : (pre_c[f] && post_c[f])))
              u_sep_km_kpv_slot_cg.sample(5'd3, 16'({2'(f), 2'd1}));
            if (kw_data[f] && (km_rep_cnt == 2'd2) && (km_rep_addr == kw_addr) &&
                (km_rep_data == kw_data) && (post_c == km_rep_post))
              u_sep_km_kpv_slot_cg.sample(5'd3, 16'({2'(f), 2'd2}));
          end
        end
        if (km_own_kpv) begin
          u_sep_km_kpv_slot_cg.sample(5'd0, 16'(s));
          if (kw_data[0] && !pre_c[0] && post_c[0]) u_sep_km_kpv_slot_cg.sample(5'd4, 16'd0);
          if (pre_c[0] && (|(kw_data[3:1] & ~pre_c[3:1] & post_c[3:1])))
            u_sep_km_kpv_slot_cg.sample(5'd4, 16'd2);
          if (pre_c[3] && post_c[0]) u_sep_km_kpv_slot_cg.sample(5'd4, 16'd5);
          if (kw_data[1] && !pre_c[1] && post_c[1]) u_sep_km_kpv_slot_cg.sample(5'd5, 16'd0);
          if (kw_data[3] && !pre_c[3] && post_c[3] && post_c[0])
            u_sep_km_kpv_slot_cg.sample(5'd7, 16'd0);
          if (!kw_data[3] && pre_c[3] && post_c[3]) u_sep_km_kpv_slot_cg.sample(5'd7, 16'd2);
          if (kw_data[2] && (pre_c[3] || pre_c[1] || pre_c[0]) && post_c[2])
            u_sep_km_kpv_slot_cg.sample(5'd6, 16'd3);
          if (pre_c[0] && !kw_data[0] && post_c[0])
            u_sep_km_kpv_locked_access_cg.sample(5'd1, 16'd1);
          if (pre_c[0] && !pre_c[3] && kw_data[1] && !pre_c[1] && post_c[1])
            u_sep_km_kpv_locked_access_cg.sample(5'd1, 16'd2);
          if (kw_data[2] && (st != 3'd7) && !((st == 3'd1)))
            u_sep_km_kpv_locked_access_cg.sample(5'd0, 16'({st, 2'd2}));
          if ((s == 6'd0) || (s == 6'd63)) begin
            if (st inside {3'd1, 3'd2, 3'd3})
              u_sep_km_kpv_locked_access_cg.sample(5'd4, 16'({2'd0, s == 6'd63}));
            if (st == 3'd4) u_sep_km_kpv_locked_access_cg.sample(5'd4, 16'({2'd1, s == 6'd63}));
            if (st == 3'd5) u_sep_km_kpv_locked_access_cg.sample(5'd4, 16'({2'd2, s == 6'd63}));
          end
        end
        // A repeated erase of a retired slot, and a seal written while the
        // erase of the slot is in flight.
        if (kw_data[2] && (st == 3'd5)) km_ret_rerased[s] <= 1'b1;
        if (kw_data[3] && pre_c[2]) km_race_armed[s] <= 1'b1;
        if (kw_data[2]) begin
          km_tr_erased[s] <= 1'b0;
          km_tr_wrote[s] <= 1'b0;
        end
      end
      // KPV key word (cp_kpv_word_index, cp_kpv_lock_write, cp_kpv_lock_use,
      // cp_kpv_state_x_op, cp_kpv_locked_write, cp_kpv_retired,
      // cp_kpv_scramble_mode, cp_kpv_trailing).
      if (km_kpv_key(kw_addr)) begin
        s = km_kpv_slot(kw_addr);
        w = 4'(kw_addr[5:2]);
        pre_c = kwp_kpv_ctrl[4*s+:4];
        st = km_slot_state(pre_c);
        if (km_own_kpv) begin
          u_sep_km_kpv_slot_cg.sample(5'd0, 16'(s));
          u_sep_km_kpv_slot_cg.sample(5'd1, 16'(w));
          if (!pre_c[0] && !pre_c[3] && (kw_resp == KmOkay))
            u_sep_km_kpv_slot_cg.sample(5'd4, 16'd1);
          if (pre_c[1] && !pre_c[0] && !pre_c[3] && (kw_resp == KmOkay))
            u_sep_km_kpv_slot_cg.sample(5'd5, 16'd4);
          if ((st != 3'd7) && (st != 3'd1))
            u_sep_km_kpv_locked_access_cg.sample(5'd0, 16'({st, 2'd1}));
          if (pre_c[0] && (kw_resp == KmSlverr) && (km_irq_status_i[4] === 1'b1))
            u_sep_km_kpv_locked_access_cg.sample(5'd1, 16'd0);
          if ((s == 6'd0) || (s == 6'd63)) begin
            if (st inside {3'd1, 3'd2, 3'd3})
              u_sep_km_kpv_locked_access_cg.sample(5'd4, 16'({2'd0, s == 6'd63}));
            if (st == 3'd4) u_sep_km_kpv_locked_access_cg.sample(5'd4, 16'({2'd1, s == 6'd63}));
            if (st == 3'd5) u_sep_km_kpv_locked_access_cg.sample(5'd4, 16'({2'd2, s == 6'd63}));
          end
          // Scrambler: with enable 1, two writes of different data to one
          // cell change exactly one stored word.
          if (kwp_kpv_scr[0] == 1'b0) u_sep_km_kpv_slot_cg.sample(5'd8, 16'd0);
          if (kwp_kpv_scr[0] && km_scr_last_v && (km_scr_last_addr == kw_addr) &&
              (km_scr_last_data != kw_data) && (kw_resp == KmOkay)) begin
            nchg = 0;
            for (int i = 0; i < 1024; i++)
            if (km_kpv_words_i[32*i+:32] !== kwp_kpv_words[32*i+:32]) nchg++;
            if (nchg == 1) u_sep_km_kpv_slot_cg.sample(5'd8, 16'd1);
          end
        end
        if (st == 3'd5 && (kw_resp == KmSlverr)) begin
          if (km_ret_rerased[s]) km_ret_wr_ref1[s] <= 1'b1;
          else km_ret_wr_ref0[s] <= 1'b1;
        end
        km_scr_last_addr <= kw_addr;
        km_scr_last_data <= kw_data;
        km_scr_last_v <= (kw_resp == KmOkay);
        if (km_tr_erased[s] && (kw_resp == KmOkay)) begin
          km_tr_wrote[s] <= 1'b1;
          km_tr_wmask[s][w] <= 1'b1;
        end
      end
      // Engine key banks (cp_sd_key_valid_semantics, cp_nx_share_read).
      b = km_bank(kw_addr);
      if (b != 4'hF) begin
        logic [31:0] off;
        off = kw_addr - km_bank_base(b);
        if (off == km_bank_ctl_off(b)) begin
          km_bank_ctrl_written[b] <= 1'b1;
          if (km_own_bank) begin
            if (kw_data[0] && !kwp_key_valid[b] && (km_key_valid_i[b] === 1'b1))
              u_sep_km_sideload_delivery_cg.sample(5'd0, 16'd1);
            if (kw_data[0] && kwp_key_valid[b] && (km_key_valid_i[b] === 1'b1))
              u_sep_km_sideload_delivery_cg.sample(5'd0, 16'd2);
            if (!kw_data[0] && kwp_key_valid[b] && (km_key_valid_i[b] === 1'b0))
              u_sep_km_sideload_delivery_cg.sample(5'd0, 16'd3);
          end
        end else if ((off < km_bank_ctl_off(b)) && (kw_resp == KmOkay) && (kw_data != 0)) begin
          km_nx_written[{b[2:0], off[2+:5]}] <= 1'b1;
        end
      end
      // ABR shared key (cp_sk_delivery_state, cp_sk_write_dir,
      // cp_sk_interrupt).
      if ((kw_addr == KmSkKeyCtrl) && km_own_bank) begin
        if (!kw_data[0] && (kw_resp == KmOkay) && (km_sk_valid_i === 1'b0))
          u_sep_km_abr_shared_key_cg.sample(5'd1, 16'd0);
        if (kw_data[0] && !kwp_sk_valid && (km_sk_valid_i === 1'b0))
          u_sep_km_abr_shared_key_cg.sample(5'd1, 16'd1);
        if (!kw_data[0] && kwp_sk_valid && (km_sk_valid_i === 1'b0) && (km_sk_key_i === '0)) begin
          u_sep_km_abr_shared_key_cg.sample(5'd0, 16'd2);
          km_sk_consumed <= 1'b1;
        end
      end
      if ((kw_addr == KmSkIrqStatus) && km_own_bank) begin
        if (kw_data[0] && kwp_sk_irq && (km_sk_irq_status_i === 1'b0)) begin
          u_sep_km_abr_shared_key_cg.sample(5'd2, 16'd3);
          km_sk_irq_cleared <= 1'b1;
        end
        if (!kw_data[0] && kwp_sk_irq && (km_sk_irq_status_i === 1'b1))
          u_sep_km_abr_shared_key_cg.sample(5'd2, 16'd4);
      end
      // KM mailbox sticky bits written by the KM (cp_mbf_sticky_clear).
      if ((kw_addr == KmMbxIrqStatus) && km_own_mbx) begin
        for (int i = 0; i < 3; i++) begin
          // Point bit order: 0 inbound underflow, 1 outbound overflow, 2
          // flushed_by_sep; KM_IRQ_STATUS[4:2] is {flushed_by_sep,
          // inbound_underflow, outbound_overflow}.
          logic [1:0] pb;
          pb = (i == 0) ? 2'd1 : (i == 1) ? 2'd0 : 2'd2;
          if (kwp_mbx_km_irq[i] && kw_data[2+i] && (km_mbx_km_irq_i[i] === 1'b0))
            u_sep_km_mailbox_fault_cg.sample(5'd2, 16'({pb, 2'd0}));
          if (kwp_mbx_km_irq[i] && !kw_data[2+i] && (km_mbx_km_irq_i[i] === 1'b1))
            u_sep_km_mailbox_fault_cg.sample(5'd2, 16'({pb, 2'd1}));
        end
      end
      // DRBG sampler STATUS writes (cp_smp_count_good, cp_smp_count_bad,
      // cp_df_status_clear).
      if ((kw_addr == KmSmpStatus) && km_own_smp) begin
        if ((kw_data[31:16] != 16'h0) && (kwp_good != 16'h0) && (km_smp_count_good_i === 16'h0))
          u_sep_km_drbg_sampler_cg.sample(5'd6, 16'd5);
        if ((kw_data[31:16] == 16'h0) && (kwp_good != 16'h0) && (km_smp_count_good_i === kwp_good))
          u_sep_km_drbg_sampler_cg.sample(5'd6, 16'd6);
        if ((kw_data[15:8] != 8'h0) && (kwp_bad != 8'h0) && (km_smp_count_bad_i === 8'h0))
          u_sep_km_drbg_sampler_cg.sample(5'd7, 16'd4);
        if ((kw_data[15:8] == 8'h0) && (kwp_bad != 8'h0) && (km_smp_count_bad_i === kwp_bad))
          u_sep_km_drbg_sampler_cg.sample(5'd7, 16'd5);
        // One sticky bit at a time: TIMEOUT_ERR is bit 2, STREAM_ERR bit 3.
        if (kwp_smp_sticky[0] && !kw_data[3]) begin
          if (kw_data[2] && (km_smp_sticky_i[0] === 1'b0))
            u_sep_km_drbg_fault_cg.sample(5'd5, 16'd0);
          if (!kw_data[2] && (km_smp_sticky_i[0] === 1'b1))
            u_sep_km_drbg_fault_cg.sample(5'd5, 16'd1);
        end
        if (kwp_smp_sticky[1] && !kw_data[2]) begin
          if (kw_data[3] && (km_smp_sticky_i[1] === 1'b0))
            u_sep_km_drbg_fault_cg.sample(5'd5, 16'd2);
          if (!kw_data[3] && (km_smp_sticky_i[1] === 1'b1))
            u_sep_km_drbg_fault_cg.sample(5'd5, 16'd3);
        end
      end
      // Repeat tracker for identical consecutive writes. The IRQ_STATUS
      // clear that the image writes before an op does not break a run.
      if (kw_addr == KmCsrIrqStatus) begin
      end else if ((kw_addr == km_rep_addr) && (kw_data == km_rep_data)) begin
        if (km_rep_cnt != 2'd3) km_rep_cnt <= km_rep_cnt + 2'd1;
      end else begin
        km_rep_cnt <= 2'd1;
        km_rep_addr <= kw_addr;
        km_rep_data <= kw_data;
        km_rep_post <= km_kpv_ctl(kw_addr) ? km_kpv_ctrl_i[4*km_kpv_slot(kw_addr)+:4] : 4'h0;
        km_rep_lock_post <= (kw_addr == KmCsrReadLockCold) ? km_otp_rlock_cold_i : km_otp_rlock_i;
      end
    end

    // ---- register reads ----
    if (kr_ev) begin
      if ((kr_addr == KmCsrVersion) && (kr_resp == KmOkay) && (kr_data == KmVersionReset) && km_own_csr)
        u_sep_km_kmcsr_status_cg.sample(5'd0, 16'd1);
      if ((kr_addr == KmCsrDebug) && (kr_data == KmDebugMagic) && km_own_csr)
        u_sep_km_kmcsr_status_cg.sample(5'd7, 16'd0);
      if ((kr_addr == KmCsrCtrl) && (kr_resp == KmOkay) && (kr_data == 32'h0) && km_own_csr)
        u_sep_km_kmcsr_status_cg.sample(5'd7, 16'd1);
      if ((kr_addr == KmCsrEntryAddr) && !km_entry_written && (kr_data == KmEntryReset) && km_own_csr)
        u_sep_km_kmcsr_status_cg.sample(5'd5, 16'd0);
      if ((kr_addr == KmCsrScrKey) && (km_own_csr || km_own_scr)) begin
        if (!krp_scr_lock && (kr_data == km_scr_key_i)) u_sep_km_memory_boot_cg.sample(5'd1, 16'd1);
        if (krp_scr_lock && (kr_data == 32'h0)) u_sep_km_memory_boot_cg.sample(5'd1, 16'd3);
      end
      if ((kr_addr == KmCsrScrCtrl) && !krp_scr_lock && (kr_resp == KmOkay) &&
          (km_own_csr || km_own_scr || (km_own_br && kr_data[0])))
        u_sep_km_memory_boot_cg.sample(5'd2, kr_data[0] ? 16'd1 : 16'd0);
      // OTP readout (cp_otp_field, cp_otp_word_index, cp_otp_lock_matrix,
      // cp_otp_read_through, cp_otp_secure_tm, cp_nx_epoch_secret).
      ow = km_otp_word(kr_addr);
      if ((ow[8:5] != 4'hF) && (kr_resp == KmOkay)) begin
        logic [3:0] fld;
        logic lw, lc;
        fld = ow[8:5];
        lw = krp_rlock[fld];
        lc = krp_rlock_cold[fld];
        if (km_own_otp) begin
          u_sep_km_otp_readout_cg.sample(5'd0, 16'(fld));
          u_sep_km_otp_readout_cg.sample(5'd1, 16'(ow));
          if (!(lw || lc) || (kr_data == 32'h0))
            u_sep_km_otp_readout_cg.sample(5'd4, 16'({fld, lc, lw}));
          if ((fld == 4'd0) && !(lw || lc) && (kr_data[7:0] === km_otp_data_i.life_cycle)) begin
            if (km_otp_data_i.life_cycle[3:0] == 4'h0) u_sep_km_otp_readout_cg.sample(5'd2, 16'd0);
            if (km_otp_data_i.life_cycle[3:0] == 4'h1) u_sep_km_otp_readout_cg.sample(5'd2, 16'd1);
          end
          if ((fld == 4'd1) && !(lw || lc) &&
              (kr_data[3:0] === {km_otp_data_i.demotion_state_2, km_otp_data_i.demotion_state_1}))
            u_sep_km_otp_readout_cg.sample(5'd2, km_dem_changed ? 16'd3 : 16'd2);
          if ((fld inside {[4'd2 : 4'd5]}) && !(lw || lc)) begin
            if (!krp_secure_tm && !ow[3] && (kr_data != 32'h0))
              u_sep_km_otp_readout_cg.sample(5'd6, 16'd0);
            if (krp_secure_tm && !krp_sigint && (km_irq_status_i[9] === 1'b0) &&
                ((!ow[3] && (kr_data == 32'h0)) || (ow[3] && (kr_data == 32'hFFFF_FFFF))))
              u_sep_km_otp_readout_cg.sample(5'd6, 16'd1);
            if ((ow[3:0] == 4'd0) && (kr_data != 32'h0))
              u_sep_km_secret_nonexposure_cg.sample(5'd1, 16'(fld - 4'd2));
          end
        end
      end
      // Engine key-bank reads (cp_nx_share_read, cp_sd_key_valid_semantics).
      b = km_bank(kr_addr);
      if ((b != 4'hF) && km_own_bank) begin
        logic [31:0] off;
        off = kr_addr - km_bank_base(b);
        if ((off == km_bank_ctl_off(
                b
            )) && !km_bank_ctrl_written[b] && (kr_data == 32'h0) && (kr_resp == KmOkay))
          u_sep_km_sideload_delivery_cg.sample(5'd0, 16'd0);
        if ((off < km_bank_ctl_off(
                b
            )) && (kr_data == 32'h0) && km_nx_written[{b[2:0], off[2+:5]}]) begin
          logic [3:0] wi;
          logic sh;
          sh = (off[6:2] >= km_bank_words(b));
          wi = 4'(sh ? (off[6:2] - km_bank_words(b)) : off[6:2]);
          u_sep_km_secret_nonexposure_cg.sample(5'd0, 16'({b[2:0], sh, wi}));
        end
      end
      if ((kr_addr == KmSkKeyCtrl) && (kr_data[0] == 1'b0) && (kr_resp == KmOkay) && km_own_bank &&
          !km_sk_consumed)
        u_sep_km_abr_shared_key_cg.sample(5'd0, 16'd0);
      // KPV reads (cp_kpv_slot_index, cp_kpv_word_index, cp_kpv_lock_use,
      // cp_kpv_seal, cp_kpv_state_x_op, cp_kpv_locked_read, cp_kpv_retired,
      // cp_kpv_boundary, cp_kpv_trailing).
      if (km_kpv_key(kr_addr) || km_kpv_ctl(kr_addr)) begin
        s = km_kpv_slot(kr_addr);
        pre_c = krp_kpv_ctrl[4*s+:4];
        st = km_slot_state(pre_c);
        if (km_own_kpv) begin
          u_sep_km_kpv_slot_cg.sample(5'd0, 16'(s));
          if ((s == 6'd0) || (s == 6'd63)) begin
            if (st inside {3'd1, 3'd2, 3'd3})
              u_sep_km_kpv_locked_access_cg.sample(5'd4, 16'({2'd0, s == 6'd63}));
            if (st == 3'd4) u_sep_km_kpv_locked_access_cg.sample(5'd4, 16'({2'd1, s == 6'd63}));
            if (st == 3'd5) u_sep_km_kpv_locked_access_cg.sample(5'd4, 16'({2'd2, s == 6'd63}));
          end
        end
        if (km_kpv_ctl(kr_addr) && km_race_armed[s]) begin
          km_race_armed[s] <= 1'b0;
          km_race_seen[s] <= kr_data[2];
        end
        if (km_kpv_key(kr_addr)) begin
          w = 4'(kr_addr[5:2]);
          if (km_own_kpv) begin
            u_sep_km_kpv_slot_cg.sample(5'd1, 16'(w));
            if (!pre_c[1] && (kr_resp == KmOkay)) u_sep_km_kpv_slot_cg.sample(5'd5, 16'd1);
            if (st == 3'd4 && (kr_resp == KmOkay)) u_sep_km_kpv_slot_cg.sample(5'd7, 16'd1);
            if (st != 3'd7) u_sep_km_kpv_locked_access_cg.sample(5'd0, 16'({st, 2'd0}));
            if (pre_c[1] && (kr_resp == KmSlverr) && (kr_data == 32'h0))
              u_sep_km_kpv_locked_access_cg.sample(5'd2, 16'd0);
            // Trailing words: an unwritten word since the erase.
            if (km_tr_erased[s] && km_tr_wrote[s] && !km_tr_wmask[s][w]) begin
              if (!pre_c[1] && km_tr_have[s][w] && (kr_data == km_tr_val[s][w]))
                u_sep_km_kpv_slot_cg.sample(5'd9, 16'd0);
              if (pre_c[1] && (kr_data == 32'h0)) u_sep_km_kpv_slot_cg.sample(5'd9, 16'd1);
            end
          end
          if (st == 3'd5 && (kr_resp == KmSlverr)) begin
            if (km_ret_rerased[s]) km_ret_rd_ref1[s] <= 1'b1;
            else km_ret_rd_ref0[s] <= 1'b1;
          end
          if (km_tr_erased[s] && !km_tr_wrote[s] && (kr_resp == KmOkay)) begin
            km_tr_val[s][w] <= kr_data;
            km_tr_have[s][w] <= 1'b1;
          end
        end
      end
      // DRBG sampler reads (cp_smp_count_good, cp_smp_count_bad,
      // cp_smp_ready).
      if ((kr_addr == KmSmpStatus) && km_own_smp) begin
        if (kr_data[31:16] == 16'h0) u_sep_km_drbg_sampler_cg.sample(5'd6, 16'd0);
        if (kr_data[31:16] == 16'h1) u_sep_km_drbg_sampler_cg.sample(5'd6, 16'd1);
        if (kr_data[31:16] == 16'hFFFF) u_sep_km_drbg_sampler_cg.sample(5'd6, 16'd2);
        if (kr_data[15:8] == 8'h0) u_sep_km_drbg_sampler_cg.sample(5'd7, 16'd0);
        if (kr_data[15:8] == 8'h1) u_sep_km_drbg_sampler_cg.sample(5'd7, 16'd1);
        if (kr_data[15:8] == 8'hFF) u_sep_km_drbg_sampler_cg.sample(5'd7, 16'd2);
        if (kr_data[0] == krp_tvalid) u_sep_km_drbg_sampler_cg.sample(5'd9, 16'(kr_data[0]));
      end
    end

    // ---- per-slot KPV edges (cp_kpv_erase, cp_kpv_lock_use, cp_kpv_seal,
    // cp_kpv_locked_read) ----
    for (int i = 0; i < 64; i++) begin
      if (km_ctrl_q[4*i+2] && (km_kpv_ctrl_i[4*i+2] === 1'b0) && km_rst_warm_n && km_rst_cold_n) begin
        km_tr_erased[i] <= 1'b1;
        km_tr_wrote[i] <= 1'b0;
        km_tr_wmask[i] <= '0;
        km_tr_have[i] <= '0;
        if (km_own_kpv) begin
          u_sep_km_kpv_slot_cg.sample(5'd6, 16'd0);
          if (!km_ctrl_q[4*i+3] && (km_kpv_ctrl_i[4*i+:4] === 4'h0))
            u_sep_km_kpv_slot_cg.sample(5'd6, 16'd1);
          if (km_ctrl_q[4*i+3] && (km_kpv_ctrl_i[4*i+:4] === 4'hB)) begin
            u_sep_km_kpv_slot_cg.sample(5'd6, 16'd2);
            if (km_race_seen[i]) u_sep_km_kpv_slot_cg.sample(5'd7, 16'd4);
          end
          if (!km_ctrl_q[4*i+1] && (km_kpv_ctrl_i[4*i+1] === 1'b1) && km_ctrl_q[4*i+3]) begin
            u_sep_km_kpv_slot_cg.sample(5'd5, 16'd2);
            u_sep_km_kpv_locked_access_cg.sample(5'd2, 16'd1);
          end
        end
        km_race_seen[i] <= 1'b0;
      end
      if (km_own_kpv && km_ret_rd_ref0[i] && km_ret_wr_ref0[i])
        u_sep_km_kpv_locked_access_cg.sample(5'd3, 16'd0);
      if (km_own_kpv && km_ret_rd_ref1[i] && km_ret_wr_ref1[i])
        u_sep_km_kpv_locked_access_cg.sample(5'd3, 16'd1);
    end
    if (km_ret_rd_ref0 & km_ret_wr_ref0) begin
      km_ret_rd_ref0 <= km_ret_rd_ref0 & ~(km_ret_rd_ref0 & km_ret_wr_ref0);
      km_ret_wr_ref0 <= km_ret_wr_ref0 & ~(km_ret_rd_ref0 & km_ret_wr_ref0);
    end
    if (km_ret_rd_ref1 & km_ret_wr_ref1) begin
      km_ret_rd_ref1 <= km_ret_rd_ref1 & ~(km_ret_rd_ref1 & km_ret_wr_ref1);
      km_ret_wr_ref1 <= km_ret_wr_ref1 & ~(km_ret_rd_ref1 & km_ret_wr_ref1);
    end

    // ---- eFuse remap at the KM eFuse master (cp_if_efuse_remap) ----
    // A value is held as seen and samples only on km_xbar_rise with its bit
    // [160 + value] set, after CHK-REMAP-BUS passes.
    if (km_xbar_rise) begin
      for (int i = 0; i < 2; i++)
      if (km_remap_ok[i] && km_xbar_pass[160+i]) u_sep_km_integrity_fault_cg.sample(5'd3, 16'(i));
      km_remap_ok <= '0;
    end
    // The eFuse AR handshake can complete in the KM AR start cycle (no
    // latency in the KM crossbar), before kx_rbusy and kx_raddr update.
    if ((km_efuse_req_i.ar_valid === 1'b1) && (km_efuse_resp_i.ar_ready === 1'b1) &&
        (kx_rbusy || kx_rstart) && km_own_xbar) begin
      logic [31:0] ea, ka;
      logic [1:0] m;
      ea = 32'(km_efuse_req_i.ar.addr);
      ka = kx_rstart ? 32'(km_axi_req_i.ar.addr) : kx_raddr;
      m = km_in(ka, KmEfMapBase, 32'(key_manager_addrmap_pkg::KEY_MANAGER_OTP_EFUSE_MAP_SIZE)) ? 2'd0 :
          km_in(ka, KmEfCtrlBase, 32'h100) ? 2'd1 : 2'd2;
      if (ea[11:0] == ka[11:0]) km_remap_ok[0] <= 1'b1;
      if ((km_remap_seen != 3'b000) && (ea[31:12] != km_remap_hi)) km_remap_bad <= 1'b1;
      km_remap_hi <= ea[31:12];
      km_remap_seen[m] <= 1'b1;
      if (((km_remap_seen | (3'b001 << m)) == 3'b111) && !km_remap_bad &&
          ((km_remap_seen == 3'b000) || (ea[31:12] == km_remap_hi)))
        km_remap_ok[1] <= 1'b1;
    end
  end

  // ---------------------------------------------------------------------
  // KM memory-map rows and windows (memory_map.adoc). Row order of
  // cp_if_offset_class: 0 ROM, 1 SRAM, 2 mailbox, 3 eFuse map, 4 eFuse
  // control, 5 eFuse token, 6 KPV, 7 KMCSR, 8 DRBG, 9 OTBN, 10 AES, 11 KMAC,
  // 12 HMAC, 13 ABR. Span: the decoded aperture of the row, from the RDL
  // size where the aperture equals it, else the RDL ocah_aperture_size
  // (key_manager.rdl), which the address-map package does not export.
  // Extent: the RDL size. Hole: the first word inside the decoded extent
  // that no register decodes (KMCSR after SRAM_EXEC_MODE, ABR after
  // MLDSA_SEED); 0 when the row has none.
  // ---------------------------------------------------------------------
  localparam int unsigned KmRows = 14;
  localparam logic [31:0] KmRowBase[KmRows] = '{
      KmRomBase,
      KmSramBase,
      KmMbxBase,
      KmEfMapBase,
      KmEfCtrlBase,
      KmEfMmrBase,
      KmKpvBase,
      KmCsrBase,
      KmSmpBase,
      KmOtbnBase,
      KmAesBase,
      KmKmacBase,
      KmHmacBase,
      KmAbrBase
  };
  localparam logic [31:0] KmRowSpan[KmRows] = '{
      32'(key_manager_addrmap_pkg::KEY_MANAGER_ROM_SIZE),
      32'(key_manager_addrmap_pkg::KEY_MANAGER_SRAM_SIZE),
      32'h20,
      32'(key_manager_addrmap_pkg::KEY_MANAGER_OTP_EFUSE_MAP_SIZE),
      32'h100,
      32'h100,
      32'h2000,
      32'h800,
      32'(key_manager_addrmap_pkg::KEY_MANAGER_DRBG_SAMPLER_SIZE),
      32'h80,
      32'h80,
      32'h80,
      32'h80,
      32'h800
  };
  localparam logic [31:0] KmRowExt[KmRows] = '{
      32'(key_manager_addrmap_pkg::KEY_MANAGER_ROM_SIZE),
      32'(key_manager_addrmap_pkg::KEY_MANAGER_SRAM_SIZE),
      32'(key_manager_addrmap_pkg::KEY_MANAGER_MAILBOX_KM_SIZE),
      32'(key_manager_addrmap_pkg::KEY_MANAGER_OTP_EFUSE_MAP_SIZE),
      32'(key_manager_addrmap_pkg::KEY_MANAGER_OTP_EFUSE_CTRL_SIZE),
      32'(key_manager_addrmap_pkg::KEY_MANAGER_OTP_EFUSE_MMR_SIZE),
      32'(key_manager_addrmap_pkg::KEY_MANAGER_KPV_SIZE),
      32'(key_manager_addrmap_pkg::KEY_MANAGER_KMCSR_SIZE),
      32'(key_manager_addrmap_pkg::KEY_MANAGER_DRBG_SAMPLER_SIZE),
      32'(key_manager_addrmap_pkg::KEY_MANAGER_OTBN_WRAPPER_KEY_SIZE),
      32'(key_manager_addrmap_pkg::KEY_MANAGER_AES_WRAPPER_KEY_SIZE),
      32'(key_manager_addrmap_pkg::KEY_MANAGER_KMAC_WRAPPER_KEY_SIZE),
      32'(key_manager_addrmap_pkg::KEY_MANAGER_HMAC_WRAPPER_KEY_SIZE),
      32'(key_manager_addrmap_pkg::KEY_MANAGER_ABR_WRAPPER_KEY_SIZE)
  };
  localparam logic [31:0] KmRowHole[KmRows] = '{
      32'h0,
      32'h0,
      32'h0,
      32'h0,
      32'h0,
      32'h0,
      32'h0,
      32'(km_csr_addrmap_pkg::KM_CSR_SRAM_EXEC_MODE_BASE_ADDR) + 32'd4,
      32'h0,
      32'h0,
      32'h0,
      32'h0,
      32'h0,
      32'(abr_wrapper_key_addrmap_pkg::ABR_WRAPPER_KEY_MLDSA_SEED_SIZE)
  };
  // Hole ends: the next decoded register after the hole.
  localparam logic [31:0] KmCsrHoleEnd = 32'(km_csr_addrmap_pkg::KM_CSR_IRQ_ENTRY_ADDR_BASE_ADDR);
  localparam logic [31:0] KmAbrHoleEnd =
      32'(abr_wrapper_key_addrmap_pkg::ABR_WRAPPER_KEY_MLKEM_SHARED_KEY_BASE_ADDR);

  // True when a is in [lo, hi).
  function automatic logic km_rng(logic [31:0] a, logic [31:0] lo, logic [31:0] hi);
    return (a >= lo) && (a < hi);
  endfunction

  function automatic logic [3:0] km_row(logic [31:0] a);
    for (int r = 0; r < KmRows; r++) if (km_in(a, KmRowBase[r], KmRowSpan[r])) return 4'(r);
    return 4'hF;
  endfunction

  // Window index of cp_if_window; 5'h1F outside the KM map.
  function automatic logic [4:0] km_window(logic [31:0] a);
    logic [3:0] r;
    r = km_row(a);
    case (r)
      4'd0: return 5'd0;
      4'd1: return 5'd2;
      4'd2: return 5'd3;
      4'd3: return 5'd5;
      4'd4: return 5'd6;
      4'd5: return 5'd7;
      4'd6: return 5'd9;
      4'd7: return 5'd10;
      4'd8: return 5'd12;
      4'd9: return 5'd14;
      4'd10: return 5'd15;
      4'd11: return 5'd16;
      4'd12: return 5'd17;
      4'd13: return 5'd18;
      default: ;
    endcase
    // Reserved windows: from the end of the span of one row to the base of
    // the next. The KM aperture end has no package symbol.
    if (km_rng(a, KmRomBase + KmRowSpan[0], KmSramBase)) return 5'd1;
    if (km_rng(a, KmMbxBase + KmRowSpan[2], KmEfMapBase)) return 5'd4;
    if (km_rng(a, KmEfMmrBase + KmRowSpan[5], KmKpvBase)) return 5'd8;
    if (km_rng(a, KmCsrBase + KmRowSpan[7], KmSmpBase)) return 5'd11;
    if (km_rng(a, KmSmpBase + KmRowSpan[8], KmOtbnBase)) return 5'd13;
    if (km_rng(a, KmOtbnBase + KmRowSpan[9], KmAesBase)) return 5'd19;
    if (km_rng(a, KmAesBase + KmRowSpan[10], KmKmacBase)) return 5'd20;
    if (km_rng(a, KmKmacBase + KmRowSpan[11], KmHmacBase)) return 5'd21;
    if (km_rng(a, KmHmacBase + KmRowSpan[12], KmAbrBase)) return 5'd22;
    if (km_in(a, KmAbrBase + KmRowSpan[13], 32'h800)) return 5'd23;
    return 5'h1F;
  endfunction

  function automatic logic km_rsv_window(logic [4:0] w);
    return w inside {5'd1, 5'd4, 5'd11, 5'd13, 5'd19, 5'd20, 5'd21, 5'd22, 5'd23};
  endfunction

  // eFuse gap of an address: 1 0x1141C to 0x114FF, 2 0x11574 to 0x115FF,
  // 3 0x11600 to 0x11FFF, 0 none.
  function automatic logic [1:0] km_ef_gap(logic [31:0] a);
    if (km_rng(a, KmEfCtrlBase + KmRowExt[4], KmEfMmrBase)) return 2'd1;
    if (km_rng(a, KmEfMmrBase + KmRowExt[5], KmEfMmrBase + KmRowSpan[5])) return 2'd2;
    if (km_rng(a, KmEfMmrBase + KmRowSpan[5], KmKpvBase)) return 2'd3;
    return 2'd0;
  endfunction

  // Past-extent or hole address of a non-eFuse decoded row.
  function automatic logic km_past(logic [31:0] a);
    logic [3:0] r;
    logic [31:0] o;
    r = km_row(a);
    if ((r == 4'hF) || (r inside {4'd0, 4'd1, 4'd3, 4'd4, 4'd5})) return 1'b0;
    o = a - KmRowBase[r];
    if (o >= KmRowExt[r]) return 1'b1;
    // KMCSR and ABR holes inside the extent (register maps of km_csr.adoc
    // and abr_wrapper_key.adoc).
    if ((r == 4'd7) && (o >= KmRowHole[7]) && (o < KmCsrHoleEnd)) return 1'b1;
    if ((r == 4'd13) && (o[7:0] >= KmRowHole[13][7:0]) && (o < KmAbrHoleEnd)) return 1'b1;
    return 1'b0;
  endfunction

  // Offset classes of offset o in row r of cp_if_offset_class: bit c is set
  // when o is in class c.
  function automatic logic [4:0] km_cls(logic [3:0] r, logic [31:0] o);
    logic [4:0] c;
    c[0] = (o == 32'h0);
    c[1] = (o == KmRowExt[r] - 32'd4);
    c[2] = (KmRowHole[r] != 32'h0) && (o == KmRowHole[r]);
    c[3] = (KmRowExt[r] < KmRowSpan[r]) && (o == KmRowExt[r]);
    c[4] = (o == KmRowSpan[r] - 32'd4);
    return c;
  endfunction

  // ---------------------------------------------------------------------
  // Window, offset class and decode outcome (cp_if_window,
  // cp_if_offset_class, cp_if_decode_outcome, cp_efw_read_class).
  //
  // Window and offset class: a cell is seen when a KM data access completes
  // in the owner window with the response that the owner grades for its
  // address: DECERR in a reserved window outside the eFuse window, SLVERR
  // with 0xBADCAB1E on a read in an eFuse gap, SLVERR with 0x0 on a read in
  // a hole or past the extent of a non-eFuse row, OKAY at any other decoded
  // word, and the completion on the KM CPU memory bus for ROM and SRAM. A
  // seen cell samples only when the pass label km_xbar_pass rises inside
  // the owner window, and only when the label holds the bit of that cell:
  // sep_km_crossbar_efuse_window_rand_test writes 0 before its decode walk
  // and, after CHK-XBAR, CHK-XBAR-RSV, CHK-XBAR-EFUSE and CHK-XBAR-SIZE pass,
  // bit {row, class} of each graded offset cell in [127:0] and bit 128 + w
  // of each graded window w in [151:128]. So housekeeping traffic of the
  // owner (result words, IRQ_STATUS, status polls) fills no cell that the
  // walk does not grade. The rise clears the seen cells. The label gates a
  // sample; it is never a bin value and drives nothing.
  //
  // Decode outcome and eFuse read class: a value is seen at its DUT event
  // (the response, then the IRQ_STATUS bit for the decode outcome), and
  // samples only on the same rise with bit 152 + value
  // (cp_if_decode_outcome) or 162 + value (cp_efw_read_class) set. The owner
  // sets these bits only for the outcomes and read classes of the cells and
  // reads that CHK-XBAR, CHK-XBAR-RSV, CHK-XBAR-EFUSE and CHK-EFW-RD graded;
  // the rise comes after those checks, CHK-XBAR-SIZE and CHK-REMAP-BUS pass.
  // The VROM bin and cp_if_vrom_outcome use bits [159:158], and
  // cp_if_efuse_remap bits [161:160], in the same way (below and above).
  // ---------------------------------------------------------------------
  logic km_dec_pend = 1'b0;
  logic [1:0] km_dec_cls = '0;
  logic km_dec_wr = 1'b0;
  logic [127:0] km_xb_cell_seen = '0;
  logic [23:0] km_xb_win_seen = '0;
  logic [7:0] km_dec_ok = '0;
  logic [15:0] km_rc_ok = '0;
  always @(posedge clk_i) begin
    logic [3:0] r;
    logic [31:0] a;
    logic [4:0] win, cm;
    logic [1:0] gap, rsp;
    logic ok;
    km_dec_pend <= 1'b0;
    km_xbar_pass_q <= (km_xbar_pass != '0);
    if (km_xbar_rise) begin
      for (int w = 0; w < 24; w++)
      if (km_xb_win_seen[w] && km_xbar_pass[128+w])
        u_sep_km_integrity_fault_cg.sample(5'd0, 16'(w));
      for (int i = 0; i < 128; i++)
      if (km_xb_cell_seen[i] && km_xbar_pass[i]) u_sep_km_integrity_fault_cg.sample(5'd2, 16'(i));
      for (int i = 0; i < 6; i++)
      if (km_dec_ok[i] && km_xbar_pass[152+i]) u_sep_km_integrity_fault_cg.sample(5'd1, 16'(i));
      for (int i = 0; i < 12; i++)
      if (km_rc_ok[i] && km_xbar_pass[162+i]) u_sep_km_otp_readout_cg.sample(5'd7, 16'(i));
      km_xb_cell_seen <= '0;
      km_xb_win_seen <= '0;
      km_dec_ok <= '0;
      km_rc_ok <= '0;
    end
    // ROM and SRAM: a data access that completes on the KM CPU memory bus.
    if (km_mb_v && km_mb_rdy && !km_mb_instr && (km_mb_rom || km_mb_sram) && km_own_xbar &&
        km_rst_warm_n) begin
      a = km_mem_addr_i;
      win = km_window(a);
      r = km_row(a);
      km_xb_win_seen[win] <= 1'b1;
      cm = km_cls(r, a - KmRowBase[r]);
      for (int c = 0; c < 5; c++) if (cm[c]) km_xb_cell_seen[{r, 3'(c)}] <= 1'b1;
    end
    // Other windows: a KM AXI access that completes with the graded response.
    if ((kw_ev || kr_ev) && km_own_xbar) begin
      a = kw_ev ? kw_addr : kr_addr;
      rsp = kw_ev ? kw_resp : kr_resp;
      win = km_window(a);
      gap = km_ef_gap(a);
      r = km_row(a);
      if (km_rsv_window(win)) ok = (rsp == KmDecerr);
      else if (gap != 2'd0) ok = (rsp == KmSlverr) && (kw_ev || (kr_data == KmBadcab));
      else if (km_past(a)) ok = (rsp == KmSlverr) && (kw_ev || (kr_data == 32'h0));
      else ok = (rsp == KmOkay);
      if (ok && (win != 5'h1F) && !(r inside {4'd0, 4'd1})) begin
        km_xb_win_seen[win] <= 1'b1;
        if (r != 4'hF) begin
          cm = km_cls(r, a - KmRowBase[r]);
          for (int c = 0; c < 5; c++) if (cm[c]) km_xb_cell_seen[{r, 3'(c)}] <= 1'b1;
        end
      end
    end
    // Decode outcome of a completed KM AXI access; the IRQ_STATUS bit is
    // checked one clock later.
    if ((kw_ev || kr_ev) && km_own_xbar) begin
      a = kw_ev ? kw_addr : kr_addr;
      win = km_window(a);
      gap = km_ef_gap(a);
      if (km_rsv_window(win) && ((kw_ev ? kw_resp : kr_resp) == KmDecerr)) begin
        km_dec_pend <= 1'b1;
        km_dec_cls <= 2'd0;
        km_dec_wr <= kw_ev;
      end else if ((gap != 2'd0) && ((kw_ev ? kw_resp : kr_resp) == KmSlverr) &&
                   (kw_ev || (kr_data == KmBadcab))) begin
        km_dec_pend <= 1'b1;
        km_dec_cls <= 2'd2;
        km_dec_wr <= kw_ev;
      end else if (km_past(
              a
          ) && ((kw_ev ? kw_resp : kr_resp) == KmSlverr) && (kw_ev || (kr_data == 32'h0))) begin
        km_dec_pend <= 1'b1;
        km_dec_cls <= 2'd1;
        km_dec_wr <= kw_ev;
      end
    end
    if (km_dec_pend && km_own_xbar &&
        (((km_dec_cls == 2'd0) && (km_irq_status_i[5] === 1'b1)) ||
         ((km_dec_cls != 2'd0) && (km_irq_status_i[4] === 1'b1))))
      km_dec_ok[{km_dec_cls, km_dec_wr}] <= 1'b1;
    // eFuse read class.
    if (kr_ev && km_own_xbar && km_rng(kr_addr, KmEfMapBase, KmKpvBase)) begin
      logic [2:0] cls;
      logic ok_rsp;
      gap = km_ef_gap(kr_addr);
      cls = km_in(kr_addr, KmEfMapBase, KmRowSpan[3]) ? 3'd0 :
            (gap == 2'd1) ? 3'd3 : (gap == 2'd2) ? 3'd4 : (gap == 2'd3) ? 3'd5 :
            km_in(kr_addr, KmEfCtrlBase, KmRowSpan[4]) ? 3'd1 : 3'd2;
      ok_rsp = (kr_resp == KmOkay);
      if (ok_rsp) km_rc_ok[{cls, 1'b0}] <= 1'b1;
      else if ((kr_resp == KmSlverr) && (kr_data == KmBadcab)) km_rc_ok[{cls, 1'b1}] <= 1'b1;
    end
  end

  // ---------------------------------------------------------------------
  // Memory interface, SRAM stores, ROM and fetch protection.
  // ---------------------------------------------------------------------
  wire km_sram_rd = (km_sram_if_i[0] === 1'b1) && (km_sram_if_i[1] === 1'b0) &&
      (km_sram_if_i[2] === 1'b1);
  wire km_sram_wr = (km_sram_if_i[0] === 1'b1) && (km_sram_if_i[1] === 1'b1) &&
      (km_sram_if_i[2] === 1'b1);
  logic [3:0] km_st_cnt = '0;
  logic [4:0] km_st_region = '0;
  logic [12:0] km_st_word = '0;
  logic km_st_locked = 1'b0, km_st_we = 1'b0, km_st_viol = 1'b0;
  // Fetch outcome window (cp_ex_mode_x_target) and the ROM store after the
  // lockout (cp_if_rom_write).
  logic [2:0] km_fx_cnt = '0;
  logic [3:0] km_fx_cell = '0;
  logic [1:0] km_fx_out = '0;
  logic [2:0] km_rw_cnt = '0;
  logic km_rw_err = 1'b0, km_rw_rav = 1'b0;
  wire km_fx_exec = (km_err_flags_i[3] === 1'b1);
  wire km_fx_rav = (km_err_flags_i[4] === 1'b1);
  always @(posedge clk_i) begin
    logic [2:0] tgt;
    logic tgt_v;
    if (km_rst_cold_n && (km_own_csr || km_own_cpu || km_own_scr)) begin
      if (km_rom_req_i === 1'b1) u_sep_km_memory_boot_cg.sample(5'd0, 16'd0);
      if (km_sram_rd) u_sep_km_memory_boot_cg.sample(5'd0, 16'd1);
      if (km_sram_wr) u_sep_km_memory_boot_cg.sample(5'd0, 16'd2);
      if (km_mb_start && km_mb_rom && km_mb_wr) u_sep_km_memory_boot_cg.sample(5'd0, 16'd3);
    end
    // SRAM store: dropped and flagged in a locked region, landed in an
    // unlocked one. With the scrambler off the macro word address is the
    // logical word index.
    if (km_st_cnt != 4'd0) begin
      if (km_sram_wr && ((km_scr_en_i === 1'b1) || (km_sram_addr_i === km_st_word)))
        km_st_we <= 1'b1;
      if (km_sram_viol_pulse_i[km_st_region] === 1'b1) km_st_viol <= 1'b1;
      if (km_st_cnt == 4'(KmStoreWin)) begin
        km_st_cnt <= '0;
        if (km_own_csr && (km_st_region != 5'd0)) begin
          if (km_st_locked && !km_st_we && km_st_viol && (km_irq_status_i[3] === 1'b1) &&
              (km_sram_viol_i[km_st_region] === 1'b1)) begin
            u_sep_km_integrity_fault_cg.sample(5'd4, 16'({km_st_region, 1'b0}));
            if (km_st_region == 5'd31) u_sep_km_memory_boot_cg.sample(5'd4, 16'd0);
          end
          if (!km_st_locked && km_st_we && !km_st_viol) begin
            u_sep_km_integrity_fault_cg.sample(5'd4, 16'({km_st_region, 1'b1}));
            if (km_st_region == 5'd31) u_sep_km_memory_boot_cg.sample(5'd4, 16'd1);
          end
        end
      end else km_st_cnt <= km_st_cnt + 4'd1;
    end
    if (km_mb_start && km_mb_sram && km_mb_wr && !km_mb_instr && km_rst_warm_n) begin
      km_st_cnt <= 4'd1;
      km_st_region <= km_mb_region;
      km_st_word <= 13'((km_mem_addr_i - KmSramBase) >> 2);
      km_st_locked <= (km_sram_lock_i[km_mb_region] === 1'b1);
      km_st_we <= km_sram_wr && (km_sram_addr_i === 13'((km_mem_addr_i - KmSramBase) >> 2));
      km_st_viol <= (km_sram_viol_pulse_i[km_mb_region] === 1'b1);
    end
    // Fetch target by SRAM_EXEC_MODE.enable and its outcome.
    if (km_fx_cnt != 3'd0) begin
      if (km_fx_exec) km_fx_out <= 2'd1;
      else if (km_fx_rav && (km_fx_out == 2'd0)) km_fx_out <= 2'd2;
      if (km_fx_cnt == 3'd4) begin
        km_fx_cnt <= '0;
        if (km_own_cpu) u_sep_km_exec_protection_cg.sample(5'd0, 16'({km_fx_cell, km_fx_out}));
      end else km_fx_cnt <= km_fx_cnt + 3'd1;
    end
    tgt_v = 1'b1;
    tgt = 3'd0;
    if (km_mb_rom) tgt = 3'd0;
    else if (km_mb_sram) tgt = (km_sram_lock_i[km_mb_region] === 1'b1) ? 3'd1 : 3'd2;
    else if (km_in(km_mem_addr_i, KmMbxBase, 32'hD000)) tgt = 3'd3;
    else if (km_in(km_mem_addr_i, KmVromBase, 32'h10000)) tgt = 3'd4;
    else tgt_v = 1'b0;
    if (km_mb_start && km_mb_instr && tgt_v && km_rst_warm_n && ((km_fx_cnt == 3'd0) || !km_mb_rom)) begin
      km_fx_cnt <= 3'd1;
      km_fx_cell <= {(km_sram_exec_mode_i === 1'b1), tgt};
      km_fx_out <= km_fx_exec ? 2'd1 : km_fx_rav ? 2'd2 : 2'd0;
    end
    // ROM access by lockout state.
    if (km_mb_start && km_mb_rom && km_own_cpu && km_rst_warm_n) begin
      logic [1:0] ls, acc;
      ls = (km_sram_exec_mode_i !== 1'b1) ? 2'd0 : km_engaged ? 2'd2 : 2'd1;
      acc = km_mb_instr ? 2'd0 : km_mb_wr ? 2'd2 : 2'd1;
      if (!((acc == 2'd2) && (ls != 2'd2)))
        u_sep_km_exec_protection_cg.sample(5'd2, 16'({ls, acc}));
      if ((acc == 2'd2) && km_engaged) begin
        km_rw_cnt <= 3'd1;
        km_rw_err <= (km_err_flags_i[2] === 1'b1);
        km_rw_rav <= km_fx_rav;
      end
    end
    if (km_rw_cnt != 3'd0) begin
      if (km_err_flags_i[2] === 1'b1) km_rw_err <= 1'b1;
      if (km_fx_rav) km_rw_rav <= 1'b1;
      if (km_rw_cnt == 3'd4) begin
        km_rw_cnt <= '0;
        if (km_own_cpu && km_rw_err && !km_rw_rav) u_sep_km_integrity_fault_cg.sample(5'd6, 16'd1);
      end else km_rw_cnt <= km_rw_cnt + 3'd1;
    end
  end

  // ---------------------------------------------------------------------
  // KMCSR interrupt sources, enable and aggregate (cp_csr_irq_source,
  // cp_csr_src_x_en, cp_csr_aggregate).
  // ---------------------------------------------------------------------
  logic [11:0] km_irqs_q = '0, km_rise_q = '0, km_rise_en_q = '0, km_mask_q = '0;
  logic km_cpu_irq_q = 1'b0;
  always @(posedge clk_i) begin
    logic [11:0] st, en, rise;
    for (int i = 0; i < 12; i++) begin
      st[i] = (km_irq_status_i[i] === 1'b1);
      en[i] = (km_irq_enable_i[i] === 1'b1);
    end
    rise = st & ~km_irqs_q;
    km_irqs_q <= st;
    km_rise_q <= km_rst_cold_n && km_rst_warm_n ? rise : '0;
    km_rise_en_q <= en;
    km_mask_q <= st & en;
    km_cpu_irq_q <= (km_cpu_irq_i === 1'b1);
    if ((km_own_csr || km_own_fi) && km_rst_cold_n && km_rst_warm_n)
      for (int i = 0; i < 12; i++) if (rise[i]) u_sep_km_kmcsr_status_cg.sample(5'd1, 16'(i));
    if (km_own_csr && km_rst_cold_n && km_rst_warm_n) begin
      for (int i = 0; i < 12; i++) begin
        if (km_rise_q[i]) begin
          if (km_rise_en_q[i] && (km_cpu_irq_i === 1'b1))
            u_sep_km_kmcsr_status_cg.sample(5'd3, 16'({4'(i), 1'b1}));
          if (!km_rise_en_q[i] && ((st & en) == 12'h0) && (km_cpu_irq_i === 1'b0))
            u_sep_km_kmcsr_status_cg.sample(5'd3, 16'({4'(i), 1'b0}));
        end
      end
      if (!km_cpu_irq_q && (km_cpu_irq_i === 1'b1) && ((st & en) != 12'h0))
        u_sep_km_kmcsr_status_cg.sample(5'd4, 16'd0);
      if (km_cpu_irq_q && (km_cpu_irq_i === 1'b0) && (km_mask_q != 12'h0) && ((st & en) == 12'h0) &&
          (en == km_rise_en_q))
        u_sep_km_kmcsr_status_cg.sample(5'd4, 16'd1);
    end
    if (km_own_csr && km_rel_ev && (km_irq_enable_i === 12'h0))
      u_sep_km_kmcsr_status_cg.sample(5'd4, 16'd2);
  end

  // ---------------------------------------------------------------------
  // Reset-domain points that compare the pre-reset record with the value
  // KmSettle clocks after the release.
  // ---------------------------------------------------------------------
  logic [6:0] km_wrong_cnt = '0;
  logic [31:0] km_wrong_code = '0;
  logic [4:0] km_hold_d = '0;
  logic km_hold_v = 1'b0, km_hold_seen = 1'b0;
  logic [4:0] km_hold_cnt = '0;
  logic km_hold_rel = 1'b0;
  logic [2:0] km_soft_iso_seen = '0;
  logic km_in_soft = 1'b0;
  wire km_lsu_aw_start = (lsu_aw_valid_i === 1'b1) && (lsu_aw_addr_i == SEP_RESET_CTRL_SW_RESET_N_REG_ADDR);
  always @(posedge clk_i) begin
    logic warm;
    logic [255:0] lw_mask, lu_mask, seal_mask;
    warm = !km_rel_cold;
    for (int i = 0; i < 64; i++) begin
      lw_mask[4*i+:4] = 4'b0001;
      lu_mask[4*i+:4] = 4'b0010;
      seal_mask[4*i+:4] = 4'b1000;
    end
    if (km_rel_ev) begin
      // Scrambler (cp_mem_scr_ctrl).
      if ((km_own_scr || km_own_br) && warm && (km_rst_pre_scr_ctrl == 2'b11) &&
          (km_scr_ctrl_i === 2'b11))
        u_sep_km_memory_boot_cg.sample(5'd2, 16'd4);
      if ((km_own_scr || km_own_br) && !warm && (km_rst_pre_scr_ctrl != 2'b00) &&
          (km_scr_ctrl_i === 2'b00))
        u_sep_km_memory_boot_cg.sample(5'd2, 16'd5);
      // KPV CTRL and scrambler.
      if (km_own_kpv) begin
        if ((km_rst_pre_ctrl != '0) && (km_kpv_ctrl_i === '0))
          u_sep_km_kpv_slot_cg.sample(5'd2, 16'(warm));
        if (((km_rst_pre_ctrl & lw_mask) != '0) && ((km_kpv_ctrl_i & lw_mask) === '0))
          u_sep_km_kpv_slot_cg.sample(5'd4, warm ? 16'd3 : 16'd4);
        if (warm && ((km_rst_pre_ctrl & lu_mask) != '0) && ((km_kpv_ctrl_i & lu_mask) === '0))
          u_sep_km_kpv_slot_cg.sample(5'd5, 16'd3);
        if (warm && ((km_rst_pre_ctrl & seal_mask) != '0) && ((km_kpv_ctrl_i & seal_mask) === '0))
          u_sep_km_kpv_slot_cg.sample(5'd7, 16'd3);
        if (warm && (km_rst_pre_kpv_scr != 2'b00) && (km_kpv_scr_ctrl_i === km_rst_pre_kpv_scr))
          u_sep_km_kpv_slot_cg.sample(5'd8, 16'd2);
        if (!warm && (km_rst_pre_kpv_scr != 2'b00) && (km_kpv_scr_ctrl_i === 2'b00))
          u_sep_km_kpv_slot_cg.sample(5'd8, 16'd3);
      end
      // OTP lock registers (cp_otp_lock_reg; the reset bins also belong to
      // the KMCSR reset test).
      if (km_own_otp || km_own_csr) begin
        if (warm && (km_rst_pre_rlock != 9'h0) && (km_rst_pre_rlock_cold != 9'h0) &&
            (km_otp_rlock_i === 9'h0) && (km_otp_rlock_cold_i === km_rst_pre_rlock_cold))
          u_sep_km_otp_readout_cg.sample(5'd5, 16'd3);
        if (!warm && ((km_rst_pre_rlock | km_rst_pre_rlock_cold) != 9'h0) &&
            (km_otp_rlock_i === 9'h0) && (km_otp_rlock_cold_i === 9'h0))
          u_sep_km_otp_readout_cg.sample(5'd5, 16'd4);
      end
      // SRAM_EXEC_MODE and the lockout (cp_ex_mode_enable,
      // cp_ex_lockout_irreversible).
      if (km_own_cpu && km_rst_pre_exec && (km_sram_exec_mode_i === 1'b0)) begin
        u_sep_km_exec_protection_cg.sample(5'd1, warm ? 16'd2 : 16'd3);
        if (km_rst_pre_engaged) u_sep_km_exec_protection_cg.sample(5'd4, 16'd1);
      end
      // Reset-domain matrix and COLD_BOOT_DONE history.
      if (km_own_csr) begin
        if (!warm) begin
          if ((km_rst_pre_sram_lock != '0) && (km_sram_lock_i === '0))
            u_sep_km_reset_domain_cg.sample(5'd2, 16'(3'b00_0));
          if ((km_rst_pre_rlock != '0) && (km_otp_rlock_i === '0))
            u_sep_km_reset_domain_cg.sample(5'd2, 16'(3'b01_0));
          if ((km_rst_pre_rlock_cold != '0) && (km_otp_rlock_cold_i === '0))
            u_sep_km_reset_domain_cg.sample(5'd2, 16'(3'b10_0));
          if (km_rst_pre_cbd && (km_cold_boot_done_i === 1'b0))
            u_sep_km_reset_domain_cg.sample(5'd2, 16'(3'b11_0));
        end else begin
          if ((km_rst_pre_sram_lock != '0) && (km_sram_lock_i === '0))
            u_sep_km_reset_domain_cg.sample(5'd2, 16'(3'b00_1));
          if ((km_rst_pre_rlock != '0) && (km_otp_rlock_i === '0))
            u_sep_km_reset_domain_cg.sample(5'd2, 16'(3'b01_1));
          if ((km_rst_pre_rlock_cold != '0) && (km_otp_rlock_cold_i === km_rst_pre_rlock_cold))
            u_sep_km_reset_domain_cg.sample(5'd2, 16'(3'b10_1));
          if (km_rst_pre_cbd && (km_cold_boot_done_i === 1'b1))
            u_sep_km_reset_domain_cg.sample(5'd2, 16'(3'b11_1));
        end
      end
      if (km_own_csr || km_own_br) begin
        if (!warm && (km_cold_boot_done_i === 1'b0)) u_sep_km_reset_domain_cg.sample(5'd3, 16'd0);
        if (!warm && km_rst_pre_cbd && (km_cold_boot_done_i === 1'b0))
          u_sep_km_reset_domain_cg.sample(5'd3, 16'd3);
        if (warm && km_warm_soft && km_rst_pre_cbd && (km_cold_boot_done_i === 1'b1))
          u_sep_km_reset_domain_cg.sample(5'd3, 16'd2);
      end
      // Sampler CFG defaults (cp_smp_reset_defaults).
      if ((km_own_smp || km_own_csr) && (km_smp_cfg_i === KmSmpCfgReset))
        u_sep_km_drbg_sampler_cg.sample(5'd8, 16'(warm));
    end
    // COLD_BOOT_DONE set by the ROM.
    if ((km_own_csr || km_own_br) && !km_cbd_q && (km_cold_boot_done_i === 1'b1) && km_rst_cold_n)
      u_sep_km_reset_domain_cg.sample(5'd3, 16'd1);
    // Reset source.
    if (km_own_csr || km_own_br) begin
      if (km_swrst_q && !km_swrst_n && km_warm_q && km_rst_cold_n)
        u_sep_km_reset_domain_cg.sample(5'd0, 16'd0);
      if (km_cold_fall) u_sep_km_reset_domain_cg.sample(5'd0, 16'd1);
      if (km_soft_q && !km_soft_n && km_rst_cold_n) u_sep_km_reset_domain_cg.sample(5'd0, 16'd2);
    end
    // A wrong SOFT_RST_CODE takes no reset over the quiet window.
    if (kw_ev && (kw_addr == KmCsrSoftRst) && (kw_data != KmSoftRstCode)) begin
      km_wrong_cnt <= 7'd1;
      km_wrong_code <= kw_data;
    end else if (km_wrong_cnt != 7'd0) begin
      if (!km_soft_n || !km_rst_warm_n || !km_rst_cold_n) km_wrong_cnt <= '0;
      else if (km_wrong_cnt == 7'(KmQuietWin)) begin
        km_wrong_cnt <= '0;
        if (km_own_csr) begin
          if (km_wrong_code == 32'h0) u_sep_km_reset_domain_cg.sample(5'd1, 16'd0);
          else if (km_wrong_code == 32'hFFFF_FFFF) u_sep_km_reset_domain_cg.sample(5'd1, 16'd1);
          else if ($countones(km_wrong_code ^ KmSoftRstCode) == 1)
            u_sep_km_reset_domain_cg.sample(5'd1, 16'd2);
        end
      end else km_wrong_cnt <= km_wrong_cnt + 7'd1;
    end
    // Hold: W = clocks from the km_sw_rst_n fall to AWVALID of the next
    // SW_RESET_N write; the warm reset rises at least 10 clocks after
    // km_sw_rst_n rises.
    if (km_swrst_q && !km_swrst_n) begin
      km_hold_d <= '0;
      km_hold_v <= 1'b1;
      km_hold_seen <= 1'b0;
    end else if (km_hold_v && !km_hold_seen) begin
      if (km_lsu_aw_start) km_hold_seen <= 1'b1;
      else if (km_hold_d != 5'h1F) km_hold_d <= km_hold_d + 5'd1;
    end
    if (!km_swrst_q && km_swrst_n && km_hold_v) begin
      km_hold_rel <= 1'b1;
      km_hold_cnt <= 5'd1;
    end else if (km_hold_rel) begin
      if (km_rst_warm_n) begin
        km_hold_rel <= 1'b0;
        km_hold_v <= 1'b0;
        if (km_own_csr && km_hold_seen && (km_hold_cnt >= 5'd10))
          u_sep_km_reset_domain_cg.sample(5'd4, 16'(km_hold_d + 5'd1));
      end else if (km_hold_cnt != 5'h1F) km_hold_cnt <= km_hold_cnt + 5'd1;
    end
    // Isolation probes during a soft reset.
    if (km_soft_q && !km_soft_n && km_rst_cold_n) begin
      km_in_soft <= 1'b1;
      km_soft_iso_seen <= '0;
    end else if (km_in_soft) begin
      for (int i = 0; i < 3; i++) if (km_iso_i[i] !== 1'b0) km_soft_iso_seen[i] <= 1'b1;
      if (!km_warm_q && km_rst_warm_n) begin
        km_in_soft <= 1'b0;
        if (km_own_csr)
          for (int i = 0; i < 3; i++)
          if (!km_soft_iso_seen[i] && (km_iso_i[i] === 1'b0))
            u_sep_km_reset_domain_cg.sample(5'd5, 16'(i));
      end
    end
  end

  // ---------------------------------------------------------------------
  // km_unrecoverable_err_o, the trap cause and the lockout order
  // (cp_fr_err_out, cp_km_trap_cause, cp_ex_lockout_order).
  // ---------------------------------------------------------------------
  logic [12:0] km_err_hi_cnt = '0;
  logic [10:0] km_run_cnt = '0;
  logic km_run_done = 1'b0;
  logic km_trap_q = 1'b0, km_rav_q = 1'b0, km_rav_seen = 1'b0;
  always @(posedge clk_i) begin
    logic unrec, trap_rise;
    logic [31:0] f;
    unrec = (km_unrec_err_i === 1'b1);
    km_trap_q <= (km_trap_i === 1'b1);
    km_rav_q <= (km_irq_status_i[11] === 1'b1);
    trap_rise = !km_trap_q && (km_trap_i === 1'b1);
    if (!km_rst_warm_n || !km_rst_cold_n) begin
      km_run_cnt <= '0;
      km_run_done <= 1'b0;
      km_rav_seen <= 1'b0;
    end else begin
      if (!km_rav_q && (km_irq_status_i[11] === 1'b1)) km_rav_seen <= 1'b1;
      if (!unrec && !km_run_done) begin
        if (km_run_cnt == 11'(KmRunWin)) begin
          km_run_done <= 1'b1;
          if (km_own_cpu || km_own_ho || km_own_fi) u_sep_km_fault_report_cg.sample(5'd0, 16'd0);
        end else km_run_cnt <= km_run_cnt + 11'd1;
      end
    end
    if (unrec) begin
      if (km_err_hi_cnt != 13'h1FFF) km_err_hi_cnt <= km_err_hi_cnt + 13'd1;
    end else km_err_hi_cnt <= '0;
    if (km_own_cpu || km_own_ho || km_own_fi) begin
      if (!km_unrec_q && unrec && (km_trap_i === 1'b1))
        u_sep_km_fault_report_cg.sample(5'd0, 16'd1);
      if (km_unrec_q && !unrec && (!km_rst_warm_n || !km_rst_cold_n || !km_warm_q || !km_cold_q)) begin
        if (km_err_hi_cnt >= 13'(KmErrHoldWin)) u_sep_km_fault_report_cg.sample(5'd0, 16'd2);
        u_sep_km_fault_report_cg.sample(5'd0, (!km_rst_cold_n || !km_cold_q) ? 16'd4 : 16'd3);
      end
    end
    if (km_own_cpu) begin
      if (trap_rise) begin
        // The opcode of the instruction that traps. The last fetch is the
        // prefetched next word, not the trapping one.
        f = km_insn_opcode_i;
        if (km_rav_seen) u_sep_km_exec_protection_cg.sample(5'd3, 16'd1);
        if ((f == 32'h0010_0073) || (f[15:0] == 16'h9002) || (f[31:16] == 16'h9002))
          u_sep_km_fault_report_cg.sample(5'd1, (km_irq_active_i === 1'b1) ? 16'd3 : 16'd0);
        else if ((f[6:0] == 7'h0B) && (f[31:25] == 7'h2C) && (f[14:12] >= 3'd3))
          u_sep_km_fault_report_cg.sample(5'd1, 16'd5);
        else if ((f[6:0] == 7'h03) || (f[6:0] == 7'h23) ||
                 ((f[1:0] == 2'b00) && ((f[15:13] == 3'b010) || (f[15:13] == 3'b110)) &&
                  (f[15:0] != 16'h0)))
          u_sep_km_fault_report_cg.sample(5'd1, 16'd2);
        else u_sep_km_fault_report_cg.sample(5'd1, (km_irq_active_i === 1'b1) ? 16'd4 : 16'd1);
      end
    end
  end

  // ---------------------------------------------------------------------
  // KM mailbox (sep_km_mailbox_fault_cg, sep_km_mailbox_transport_cg).
  // KM side only; the SEP-side cells are added with their owner.
  // ---------------------------------------------------------------------
  logic [3:0] km_mbx_err_q = '0;
  logic [1:0] km_mbx_flush_q = '0;
  logic [1:0] km_fl_fill = '0;
  logic km_fl_init_km = 1'b0, km_fl_on = 1'b0;
  logic [4:0] km_in_d_q = '0, km_out_d_q = '0;
  logic [3:0] km_flags_q = '0;
  logic km_in_stable = 1'b0, km_out_stable = 1'b0;
  logic km_sep_in_q = 1'b0, km_sep_out_q = 1'b0;  // separator words popped per direction
  logic km_both_dir_done = 1'b0;
  logic km_sepset_q = 1'b0, km_sep_sepset_q = 1'b0;
  logic km_push_q = 1'b0, km_sep_push_q = 1'b0;
  logic [4:0] km_src_q = '0, km_rise5_q = '0, km_en5_q = '0, km_mask5_q = '0;
  logic km_mbox_irq_q = 1'b0;
  logic [3:0] km_mbx_w1c_age = '0;
  logic km_sep_irq_pre = 1'b0;
  // Sources in KM_IRQ_ENABLE bit order: 0 data available, 1 write space, 2
  // outbound overflow, 3 inbound underflow, 4 flushed by SEP.
  function automatic logic [2:0] km_src_pt(int unsigned e);
    case (e)
      0: return 3'd0;
      1: return 3'd1;
      2: return 3'd3;
      3: return 3'd2;
      default: return 3'd4;
    endcase
  endfunction
  always @(posedge clk_i) begin
    logic [4:0] src, en, rise;
    logic in_e, in_f, out_e, out_f;
    logic [3:0] hs;
    hs = km_mbx_hs_i;
    in_e = (km_mbx_flags_i[0] === 1'b1);
    in_f = (km_mbx_flags_i[1] === 1'b1);
    out_e = (km_mbx_flags_i[2] === 1'b1);
    out_f = (km_mbx_flags_i[3] === 1'b1);
    km_mbx_err_q <= km_mbx_err_i;
    km_mbx_flush_q <= km_mbx_flush_i;
    km_in_d_q <= km_mbx_in_depth_i;
    km_out_d_q <= km_mbx_out_depth_i;
    km_flags_q <= km_mbx_flags_i;
    km_sepset_q <= (km_mbx_km_sepset_i === 1'b1);
    km_sep_sepset_q <= (km_mbx_sep_sepset_i === 1'b1);
    km_push_q <= (hs[2] === 1'b1);
    km_sep_push_q <= (hs[0] === 1'b1);
    if (!km_rst_cold_n) begin
      km_sep_in_q <= 1'b0;
      km_sep_out_q <= 1'b0;
      km_both_dir_done <= 1'b0;
      km_fl_on <= 1'b0;
    end
    if (km_own_mbx && km_rst_cold_n) begin
      // Error conditions and their response bits.
      if (km_mbx_err_q[1] && (km_mbx_km_irq_i[1] === 1'b1))
        u_sep_km_mailbox_fault_cg.sample(5'd0, 16'd0);
      if (km_mbx_err_q[0] && (km_mbx_km_irq_i[0] === 1'b1))
        u_sep_km_mailbox_fault_cg.sample(5'd0, 16'd1);
      if (km_mbx_err_i[1] === 1'b1)
        u_sep_km_mailbox_fault_cg.sample(5'd1, 16'({1'b0, km_mbx_km_ctrl_i[1] === 1'b1}));
      if (km_mbx_err_i[0] === 1'b1)
        u_sep_km_mailbox_fault_cg.sample(5'd1, 16'({1'b1, km_mbx_km_ctrl_i[0] === 1'b1}));
      // Access by requester.
      if (hs[0] === 1'b1) u_sep_km_mailbox_transport_cg.sample(5'd0, 16'(2'b00));
      if (hs[3] === 1'b1) u_sep_km_mailbox_transport_cg.sample(5'd0, 16'(2'b01));
      if (hs[2] === 1'b1) u_sep_km_mailbox_transport_cg.sample(5'd0, 16'(2'b10));
      if (hs[1] === 1'b1) u_sep_km_mailbox_transport_cg.sample(5'd0, 16'(2'b11));
      // Occupancy, sampled when depth and flags hold for two clocks.
      if (km_in_stable) begin
        if ((km_mbx_in_depth_i == 5'd0) != in_e)
          u_sep_km_mailbox_transport_cg.sample(5'd1, 16'(4'b0_100));
        else if ((km_mbx_in_depth_i == 5'd16) != in_f)
          u_sep_km_mailbox_transport_cg.sample(5'd1, 16'(4'b0_100));
        else if (km_mbx_in_depth_i == 5'd0)
          u_sep_km_mailbox_transport_cg.sample(5'd1, 16'(4'b0_000));
        else if (km_mbx_in_depth_i == 5'd1)
          u_sep_km_mailbox_transport_cg.sample(5'd1, 16'(4'b0_001));
        else if (km_mbx_in_depth_i == 5'd15)
          u_sep_km_mailbox_transport_cg.sample(5'd1, 16'(4'b0_010));
        else if (km_mbx_in_depth_i == 5'd16)
          u_sep_km_mailbox_transport_cg.sample(5'd1, 16'(4'b0_011));
      end
      if (km_out_stable) begin
        if ((km_mbx_out_depth_i == 5'd0) != out_e)
          u_sep_km_mailbox_transport_cg.sample(5'd1, 16'(4'b1_100));
        else if ((km_mbx_out_depth_i == 5'd16) != out_f)
          u_sep_km_mailbox_transport_cg.sample(5'd1, 16'(4'b1_100));
        else if (km_mbx_out_depth_i == 5'd0)
          u_sep_km_mailbox_transport_cg.sample(5'd1, 16'(4'b1_000));
        else if (km_mbx_out_depth_i == 5'd1)
          u_sep_km_mailbox_transport_cg.sample(5'd1, 16'(4'b1_001));
        else if (km_mbx_out_depth_i == 5'd15)
          u_sep_km_mailbox_transport_cg.sample(5'd1, 16'(4'b1_010));
        else if (km_mbx_out_depth_i == 5'd16)
          u_sep_km_mailbox_transport_cg.sample(5'd1, 16'(4'b1_011));
      end
      // Separator.
      if (hs[0] === 1'b1)
        u_sep_km_mailbox_transport_cg.sample(5'd2, (km_mbx_sep_i[0] === 1'b1) ? 16'd0 : 16'd1);
      if (hs[2] === 1'b1)
        u_sep_km_mailbox_transport_cg.sample(5'd2, (km_mbx_sep_i[2] === 1'b1) ? 16'd0 : 16'd1);
      if (hs[1] === 1'b1)
        u_sep_km_mailbox_transport_cg.sample(5'd2, (km_mbx_sep_i[1] === 1'b1) ? 16'd2 : 16'd3);
      if (hs[3] === 1'b1)
        u_sep_km_mailbox_transport_cg.sample(5'd2, (km_mbx_sep_i[3] === 1'b1) ? 16'd2 : 16'd3);
      if ((km_push_q && km_sepset_q && (km_mbx_km_sepset_i === 1'b0)) ||
          (km_sep_push_q && km_sep_sepset_q && (km_mbx_sep_sepset_i === 1'b0)))
        u_sep_km_mailbox_transport_cg.sample(5'd2, 16'd5);
      if (km_sep_in_q && km_sep_out_q && !km_both_dir_done) begin
        km_both_dir_done <= 1'b1;
        u_sep_km_mailbox_transport_cg.sample(5'd2, 16'd4);
      end
    end
    if ((hs[1] === 1'b1) && (km_mbx_sep_i[1] === 1'b1)) km_sep_in_q <= 1'b1;
    if ((hs[3] === 1'b1) && (km_mbx_sep_i[3] === 1'b1)) km_sep_out_q <= 1'b1;
    km_in_stable <= (km_mbx_in_depth_i === km_in_d_q) && (km_mbx_flags_i[1:0] === km_flags_q[1:0]);
    km_out_stable <= (km_mbx_out_depth_i === km_out_d_q) &&
        (km_mbx_flags_i[3:2] === km_flags_q[3:2]);
    // Flush: initiator and pre-flush fill at the rise, the result at the
    // self-clear.
    if (!km_mbx_flush_q[0] && (km_mbx_flush_i[0] === 1'b1)) begin
      km_fl_on <= 1'b1;
      km_fl_init_km <= 1'b1;
      km_fl_fill <= 2'((km_mbx_in_depth_i != 5'd0) + (km_mbx_out_depth_i != 5'd0));
    end else if (!km_mbx_flush_q[1] && (km_mbx_flush_i[1] === 1'b1)) begin
      km_fl_on <= 1'b1;
      km_fl_init_km <= 1'b0;
      km_fl_fill <= 2'((km_mbx_in_depth_i != 5'd0) + (km_mbx_out_depth_i != 5'd0));
    end
    if (km_fl_on && (km_mbx_flush_i[0] !== 1'b1) && (km_mbx_flush_i[1] !== 1'b1)) begin
      km_fl_on <= 1'b0;
      if (km_own_mbx || km_own_cp) begin
        if (km_fl_init_km && in_e && out_e)
          u_sep_km_mailbox_fault_cg.sample(5'd3, 16'({1'b1, km_fl_fill}));
        if (!km_fl_init_km && out_e)
          u_sep_km_mailbox_fault_cg.sample(5'd3, 16'({1'b0, km_fl_fill}));
      end
    end
    // Sticky persistence after the cause, read by the KM.
    if (kr_ev && (kr_addr == KmMbxIrqStatus) && km_own_mbx) begin
      if (kr_data[3] && !km_mbx_err_q[1] && (km_mbx_err_i[1] !== 1'b1))
        u_sep_km_mailbox_fault_cg.sample(5'd2, 16'({2'd0, 2'd2}));
      if (kr_data[2] && !km_mbx_err_q[0] && (km_mbx_err_i[0] !== 1'b1))
        u_sep_km_mailbox_fault_cg.sample(5'd2, 16'({2'd1, 2'd2}));
      if (kr_data[4] && (km_mbx_flush_i[1] !== 1'b1))
        u_sep_km_mailbox_fault_cg.sample(5'd2, 16'({2'd2, 2'd2}));
    end
    // SEP flushed_by_km, written and read by the host.
    if ((lsu_aw_valid_i === 1'b1) && (lsu_aw_ready_i === 1'b1) &&
        (lsu_aw_addr_i == KM_MAILBOX_SEP_SEP_IRQ_STATUS_REG_ADDR))
      km_sep_irq_pre <= (km_mbx_sep_irq_i[2] === 1'b1);
    if (km_own_mbx && wr_ev && (aw_addr_q == KM_MAILBOX_SEP_SEP_IRQ_STATUS_REG_ADDR) && km_sep_irq_pre) begin
      if (wr_data[4] && (km_mbx_sep_irq_i[2] === 1'b0))
        u_sep_km_mailbox_fault_cg.sample(5'd2, 16'({2'd3, 2'd0}));
      if (!wr_data[4] && (km_mbx_sep_irq_i[2] === 1'b1))
        u_sep_km_mailbox_fault_cg.sample(5'd2, 16'({2'd3, 2'd1}));
    end
    if (km_own_mbx && rd_ev && (ar_addr_q == KM_MAILBOX_SEP_SEP_IRQ_STATUS_REG_ADDR) && rd_data[4] &&
        (km_mbx_flush_i[0] !== 1'b1))
      u_sep_km_mailbox_fault_cg.sample(5'd2, 16'({2'd3, 2'd2}));
    // KM-side interrupt sources by enable, and the KM aggregate.
    src = {
      km_mbx_km_irq_i[2] === 1'b1,
      km_mbx_km_irq_i[1] === 1'b1,
      km_mbx_km_irq_i[0] === 1'b1,
      !out_f,
      !in_e
    };
    for (int i = 0; i < 5; i++) en[i] = (km_mbx_km_en_i[i] === 1'b1);
    rise = src & ~km_src_q;
    km_src_q <= src;
    km_rise5_q <= km_rst_cold_n ? rise : '0;
    km_en5_q <= en;
    km_mask5_q <= src & en;
    km_mbox_irq_q <= (km_cpu_mbox_irq_i === 1'b1);
    // The W1C commits at the W handshake; the aggregate falls on the next clock.
    if (kx_w_hs && ((kx_wstart ? 32'(km_axi_req_i.aw.addr) : kx_waddr) == KmMbxIrqStatus))
      km_mbx_w1c_age <= 4'd1;
    else if ((km_mbx_w1c_age != 4'd0) && (km_mbx_w1c_age != 4'd4))
      km_mbx_w1c_age <= km_mbx_w1c_age + 4'd1;
    else km_mbx_w1c_age <= '0;
    if (km_own_mbx && km_rst_cold_n) begin
      for (int i = 0; i < 5; i++) begin
        if (km_rise5_q[i]) begin
          if (km_en5_q[i] && (km_cpu_mbox_irq_i === 1'b1))
            u_sep_km_mailbox_transport_cg.sample(5'd3, 16'({km_src_pt(i), 1'b1}));
          if (!km_en5_q[i] && ((src & en) == 5'h0) && (km_cpu_mbox_irq_i === 1'b0))
            u_sep_km_mailbox_transport_cg.sample(5'd3, 16'({km_src_pt(i), 1'b0}));
        end
      end
      if (!km_mbox_irq_q && (km_cpu_mbox_irq_i === 1'b1) && ((src & en) != 5'h0))
        u_sep_km_mailbox_transport_cg.sample(5'd4, 16'd0);
      if (km_mbox_irq_q && (km_cpu_mbox_irq_i === 1'b0) && ((src & en) == 5'h0) && (en == km_en5_q)) begin
        if ((km_mask5_q != 5'h0) && ((km_mask5_q & 5'b11100) == 5'h0))
          u_sep_km_mailbox_transport_cg.sample(5'd4, 16'd1);
        if ((km_mask5_q != 5'h0) && ((km_mask5_q & 5'b00011) == 5'h0) && (km_mbx_w1c_age != 4'd0))
          u_sep_km_mailbox_transport_cg.sample(5'd4, 16'd2);
      end
    end
  end

  // ---------------------------------------------------------------------
  // KM DRBG sampler (sep_km_drbg_sampler_cg, sep_km_drbg_fault_cg). The
  // sink TVALID is the sampler input after the HK-STRM inject.
  // ---------------------------------------------------------------------
  logic [2:0] km_smp_st_q = '0;
  logic km_tv_q = 1'b0, km_tr_q = 1'b0;
  logic km_pf_q = 1'b0;
  logic [15:0] km_good_q = '0;
  logic [7:0] km_bad_q = '0;
  logic [1:0] km_sticky_q = '0;
  logic km_wait_req = 1'b0;  // a DATA read started with no prefetched word
  logic km_prev_data_ok = 1'b0;
  logic [15:0] km_hs_since = '0;
  logic km_pf_read_done = 1'b0;  // a DATA read completed with prefetch 1
  logic [3:0] km_pf_dis_cnt = '0;
  logic km_pf_dis_word = 1'b0;  // prefetch disabled with a word held
  logic [17:0] km_stall_cnt = '0;
  logic km_stall_done = 1'b0;
  logic [31:0] km_pf_val = '0;
  logic km_pf_val_v = 1'b0, km_pf_prev_rd = 1'b0;
  logic [31:0] km_pf_prev_val = '0;
  logic [3:0] km_to_cnt = '0;
  logic [7:0] km_to_bad = '0;
  logic km_to_slv = 1'b0;
  logic [3:0] km_se_cnt = '0;
  logic km_se_active = 1'b0, km_se_rd_pend = 1'b0;
  logic [7:0] km_se_bad = '0;
  // Pass label of cp_df_offset_race and of the first-active-cycle bin of
  // cp_df_stream_violation: sep_km_drbg_sampler_rand_test writes 0 through
  // the u_sep_fcov handle at the start of a stream-error case and 1 after
  // CHK-SMP-STRM passes on it. A first-active-cycle withdrawal whose read ends
  // with SLVERR, data 0, STREAM_ERR 1, IRQ_STATUS.drbg_err 1 and a COUNT_BAD
  // increment is held as pending and samples only when the label rises. The
  // next withdrawal or a KM reset drops a pending case. It gates a sample; it
  // is never a bin value and drives nothing.
  int unsigned km_strm_pass = 0;
  logic km_strm_pass_q = 1'b0;
  logic km_or_race_v = 1'b0, km_or_race = 1'b0;  // timeout 1 or 2 at the withdrawal
  logic km_or_pend_v = 1'b0, km_or_pend = 1'b0;  // its read ended as graded; waits for the label
  logic km_sv_pend_v = 1'b0;  // first-active-cycle withdrawal ended as graded; waits for the label
  logic km_trng_armed = 1'b0;
  wire km_tv = (km_smp_tvalid_i === 1'b1);
  wire km_tr = (km_smp_tready_i === 1'b1);
  wire km_smp_hs = km_tv && km_tr;
  // Withdrawal: TVALID high with TREADY low, then TVALID low.
  wire km_withdraw = km_tv_q && !km_tr_q && !km_tv && km_rst_warm_n && km_rst_cold_n;
  wire km_data_rd = kr_ev && (kr_addr == KmSmpData);
  always @(posedge clk_i) begin
    logic [2:0] st;
    st = km_smp_state_i;
    km_smp_st_q <= st;
    km_tv_q <= km_tv;
    km_tr_q <= km_tr;
    km_pf_q <= (km_smp_prefetched_i === 1'b1);
    km_good_q <= km_smp_count_good_i;
    km_bad_q <= km_smp_count_bad_i;
    km_sticky_q <= km_smp_sticky_i;
    km_strm_pass_q <= (km_strm_pass != 0);
    if (!km_rst_warm_n || !km_rst_cold_n) begin
      km_wait_req <= 1'b0;
      km_prev_data_ok <= 1'b0;
      km_pf_read_done <= 1'b0;
      km_pf_dis_word <= 1'b0;
      km_pf_val_v <= 1'b0;
      km_pf_prev_rd <= 1'b0;
      km_to_cnt <= '0;
      km_se_cnt <= '0;
      km_se_rd_pend <= 1'b0;
      km_or_race_v <= 1'b0;
      km_or_pend_v <= 1'b0;
      km_sv_pend_v <= 1'b0;
      km_stall_cnt <= '0;
      km_stall_done <= 1'b0;
    end else if (km_own_smp) begin
      // Read service and the arrival of TVALID at the read start.
      if (kx_rstart && (32'(km_axi_req_i.ar.addr) == KmSmpData)) begin
        if (km_smp_prefetched_i === 1'b1) u_sep_km_drbg_sampler_cg.sample(5'd0, 16'd0);
        else km_wait_req <= 1'b1;
        // cp_smp_prefetch_mode PREFETCH 0 and 1: CFG.PREFETCH at a DATA read
        // start.
        if (km_smp_cfg_i[0] === 1'b0) u_sep_km_drbg_sampler_cg.sample(5'd4, 16'd0);
        if (km_smp_cfg_i[0] === 1'b1) u_sep_km_drbg_sampler_cg.sample(5'd4, 16'd1);
      end
      if ((km_smp_st_q == KmStIdle) && (st == KmStRequest)) begin
        if (km_wait_req && km_tr) u_sep_km_drbg_sampler_cg.sample(5'd0, 16'd1);
        km_wait_req <= 1'b0;
        if (km_tv) u_sep_km_drbg_sampler_cg.sample(5'd1, 16'd1);
      end
      if (km_smp_hs && ((st == KmStRequest) || (st == 3'd2)))
        u_sep_km_drbg_sampler_cg.sample(5'd2, 16'(km_smp_tstrb_i));
      // Freshness: a sink handshake between two OKAY DATA reads.
      if (km_smp_hs && (km_hs_since != 16'hFFFF)) km_hs_since <= km_hs_since + 16'd1;
      if (km_data_rd) begin
        if ((kr_resp == KmOkay) && km_prev_data_ok && ((km_hs_since != 16'd0) || km_smp_hs))
          u_sep_km_drbg_sampler_cg.sample(5'd3, 16'd1);
        km_prev_data_ok <= (kr_resp == KmOkay);
        km_hs_since <= '0;
        if ((kr_resp == KmOkay) && (km_smp_cfg_i[0] === 1'b1)) km_pf_read_done <= 1'b1;
        // PREFETCH_DATA mirror: the next DATA read returns the mirrored word.
        if (km_pf_val_v && (kr_resp == KmOkay) && (kr_data == km_pf_val))
          u_sep_km_drbg_sampler_cg.sample(5'd5, 16'd0);
        km_pf_val_v <= 1'b0;
        km_pf_prev_rd <= 1'b0;
        // Good-side saturation: an OKAY read at 0xFFFF keeps 0xFFFF.
        if ((kr_resp == KmOkay) && (km_good_q == 16'hFFFF) && (km_smp_count_good_i === 16'hFFFF))
          u_sep_km_drbg_sampler_cg.sample(5'd6, 16'd3);
      end
      if (kr_ev && (kr_addr == KmSmpPfData)) begin
        if (krp_pf && (kr_resp == KmOkay)) begin
          km_pf_val <= kr_data;
          km_pf_val_v <= 1'b1;
          if (km_pf_prev_rd && (kr_data == km_pf_prev_val))
            u_sep_km_drbg_sampler_cg.sample(5'd5, 16'd1);
          km_pf_prev_rd <= 1'b1;
          km_pf_prev_val <= kr_data;
        end
        if (km_pf_dis_word && (km_smp_cfg_i[0] === 1'b0) && (kr_data == 32'h0))
          u_sep_km_drbg_sampler_cg.sample(5'd5, 16'd2);
      end
      // Prefetch: a word held after a read, cleared when disabled.
      if (!km_pf_q && (km_smp_prefetched_i === 1'b1)) begin
        if (km_pf_read_done) u_sep_km_drbg_sampler_cg.sample(5'd4, 16'd2);
        km_pf_read_done <= 1'b0;
        if (km_smp_count_good_i === km_good_q) u_sep_km_drbg_sampler_cg.sample(5'd6, 16'd4);
      end
      if (km_smp_cfg_q[0] && (km_smp_cfg_i[0] === 1'b0) && km_pf_q) km_pf_dis_cnt <= 4'd1;
      else if (km_pf_dis_cnt != 4'd0) begin
        if (km_smp_prefetched_i === 1'b0) begin
          km_pf_dis_cnt <= '0;
          km_pf_dis_word <= 1'b1;
          u_sep_km_drbg_sampler_cg.sample(5'd4, 16'd3);
        end else if (km_pf_dis_cnt == 4'd4) km_pf_dis_cnt <= '0;
        else km_pf_dis_cnt <= km_pf_dis_cnt + 4'd1;
      end
      if ((km_smp_cfg_i[0] === 1'b1) && !km_smp_cfg_q[0]) km_pf_dis_word <= 1'b0;
      // A stalled prefetch: prefetch 1, no word, no TVALID, longer than the
      // timeout, with no timeout and no bad count.
      if ((km_smp_cfg_i[0] === 1'b1) && (km_smp_prefetched_i === 1'b0) && !km_tv && (st == KmStIdle) &&
          (km_smp_sticky_i[0] === km_sticky_q[0]) && (km_smp_count_bad_i === km_bad_q)) begin
        if (km_stall_cnt != 18'h3FFFF) km_stall_cnt <= km_stall_cnt + 18'd1;
        if (!km_stall_done && (km_smp_cfg_i[16:1] != 16'h0) &&
            (km_stall_cnt > {2'b00, km_smp_cfg_i[16:1]} + 18'd16) && (km_smp_sticky_i[0] === 1'b0)) begin
          km_stall_done <= 1'b1;
          u_sep_km_drbg_sampler_cg.sample(5'd4, 16'd4);
        end
      end else begin
        km_stall_cnt <= '0;
        km_stall_done <= 1'b0;
      end
      // Timeout entry and its outcome.
      if ((st == KmStTimeout) && (km_smp_st_q != KmStTimeout)) begin
        if (km_smp_cfg_i[16:1] == 16'd1) u_sep_km_drbg_fault_cg.sample(5'd0, 16'd0);
        if (km_smp_cfg_i[16:1] == 16'hFFFF) u_sep_km_drbg_fault_cg.sample(5'd0, 16'd1);
        if (km_smp_st_q == KmStRequest) u_sep_km_drbg_fault_cg.sample(5'd1, 16'd0);
        km_to_cnt <= 4'd1;
        km_to_bad <= km_bad_q;
        km_to_slv <= 1'b0;
        if ((km_smp_sticky_i[0] === 1'b1) && !km_sticky_q[0])
          u_sep_km_drbg_fault_cg.sample(5'd2, 16'd1);
        // IRQ_STATUS.DRBG_ERR sets on the same edge as the TIMEOUT entry.
        if (!km_irqs_q[6] && (km_irq_status_i[6] === 1'b1))
          u_sep_km_drbg_fault_cg.sample(5'd2, 16'd3);
      end else if (km_to_cnt != 4'd0) begin
        if (!km_sticky_q[0] && (km_smp_sticky_i[0] === 1'b1))
          u_sep_km_drbg_fault_cg.sample(5'd2, 16'd1);
        if ((km_bad_q == km_to_bad) && (km_smp_count_bad_i === km_to_bad + 8'd1))
          u_sep_km_drbg_fault_cg.sample(5'd2, 16'd2);
        if ((km_to_bad == 8'hFF) && (km_to_cnt == 4'd8) && (km_smp_count_bad_i === 8'hFF))
          u_sep_km_drbg_sampler_cg.sample(5'd7, 16'd3);
        if (!km_irqs_q[6] && (km_irq_status_i[6] === 1'b1))
          u_sep_km_drbg_fault_cg.sample(5'd2, 16'd3);
        km_to_cnt <= (km_to_cnt == 4'd8) ? 4'd0 : km_to_cnt + 4'd1;
      end
      if (km_data_rd && (kr_resp == KmSlverr) && (kr_data == 32'h0) && (km_to_cnt != 4'd0))
        u_sep_km_drbg_fault_cg.sample(5'd2, 16'd0);
      // Withdrawal with no read active and in the first active cycle.
      if (km_withdraw) begin
        km_se_bad <= km_bad_q;
        km_or_race_v <= 1'b0;
        km_or_pend_v <= 1'b0;
        km_sv_pend_v <= 1'b0;
        if ((st == KmStIdle) && (km_smp_st_q == KmStIdle)) begin
          km_se_active <= 1'b0;
          km_se_cnt <= 4'd1;
        end else if ((st == KmStRequest) && (km_smp_st_q == KmStIdle)) begin
          km_se_active <= 1'b1;
          km_se_rd_pend <= 1'b1;
          km_se_cnt <= 4'd1;
          km_or_race_v <= (km_smp_cfg_i[16:1] == 16'd1) || (km_smp_cfg_i[16:1] == 16'd2);
          km_or_race <= (km_smp_cfg_i[16:1] == 16'd2);
        end
      end else if (km_se_cnt != 4'd0) begin
        if (!km_se_active && (km_se_cnt == 4'd4) && (km_smp_sticky_i[1] === 1'b1) &&
            (km_smp_count_bad_i === km_se_bad + 8'd1) && (km_irq_status_i[6] === 1'b1))
          u_sep_km_drbg_fault_cg.sample(5'd3, 16'd0);
        km_se_cnt <= (km_se_cnt == 4'd4) ? 4'd0 : km_se_cnt + 4'd1;
      end
      if (km_data_rd && km_se_rd_pend) begin
        km_se_rd_pend <= 1'b0;
        km_or_race_v <= 1'b0;
        if ((kr_resp == KmSlverr) && (kr_data == 32'h0) && (km_smp_sticky_i[1] === 1'b1) &&
            (km_irq_status_i[6] === 1'b1) && (km_smp_count_bad_i > km_se_bad)) begin
          km_sv_pend_v <= 1'b1;
          km_or_pend_v <= km_or_race_v;
          km_or_pend <= km_or_race;
        end
      end
      // The first-active-cycle withdrawal and the offset race sample only
      // when CHK-SMP-STRM passed on their case.
      if ((km_strm_pass != 0) && !km_strm_pass_q && km_sv_pend_v) begin
        u_sep_km_drbg_fault_cg.sample(5'd3, 16'd1);
        km_sv_pend_v <= 1'b0;
      end
      if ((km_strm_pass != 0) && !km_strm_pass_q && km_or_pend_v) begin
        u_sep_km_drbg_fault_cg.sample(5'd4, 16'(km_or_pend));
        km_or_pend_v <= 1'b0;
      end
    end
    // A TRNG reset while the KM is held, then the first DATA read.
    if ((trng_rst_i === 1'b1) && (km_rst_i[0] === 1'b0)) km_trng_armed <= 1'b1;
    if (km_data_rd && km_trng_armed) begin
      km_trng_armed <= 1'b0;
      if (km_own_smp && (kr_resp == KmOkay) && (km_smp_sticky_i[1] === 1'b0))
        u_sep_km_drbg_fault_cg.sample(5'd6, 16'd1);
    end
  end

  // ---------------------------------------------------------------------
  // KM OTP input: change status, dual-rail integrity and the secure test
  // strap (cp_otp_change, cp_if_otp_dual_rail, cp_otp_secure_tm).
  // ---------------------------------------------------------------------
  km_intf_pkg::km_otp_data_t km_otp_q;
  logic [8:0] km_chg_q = '0, km_chg_rise_q = '0;
  logic [1:0] km_dr_cls[9];
  logic [2:0] km_dr_cnt[9];
  logic [3:0] km_dem_base = '0;
  logic [6:0] km_quiet_cnt = '0;
  logic km_quiet_armed = 1'b0, km_quiet_warm = 1'b0;
  logic km_strap_at_rel = 1'b0, km_strap_bad = 1'b0, km_strap_done = 1'b0;
  logic [10:0] km_strap_cnt = '0;
  initial begin
    km_otp_q = '0;
    for (int f = 0; f < 9; f++) begin
      km_dr_cls[f] = '0;
      km_dr_cnt[f] = '0;
    end
  end
  // Value and complement rail of field f: 0 life cycle {~raw, raw}, 1 the
  // two demotion groups {~d, d}, 2 to 8 the 256-bit fields {~v, v}.
  function automatic logic [511:0] km_otp_rails(km_intf_pkg::km_otp_data_t d, int unsigned f);
    case (f)
      0: return {252'h0, d.life_cycle[7:4], 252'h0, d.life_cycle[3:0]};
      1: return {254'h0, d.demotion_state_2[1], d.demotion_state_1[1],
                 254'h0, d.demotion_state_2[0], d.demotion_state_1[0]};
      2: return d.chiplet_uid;
      3: return d.sip_uid;
      4: return d.sys_uid;
      5: return d.class_key;
      6: return d.sep_chiplet_id;
      7: return d.sep_sip_id;
      default: return d.sep_sys_id;
    endcase
  endfunction
  function automatic logic [255:0] km_rail_mask(int unsigned f);
    return (f == 0) ? 256'hF : (f == 1) ? 256'h3 : '1;
  endfunction
  always @(posedge clk_i) begin
    logic [511:0] now, prev;
    logic [255:0] m;
    logic dv, dc, cons;
    logic [8:0] rise;
    logic [3:0] dem;
    km_otp_q <= km_otp_data_i;
    km_chg_q <= km_otp_chg_i;
    dem = {km_otp_data_i.demotion_state_2, km_otp_data_i.demotion_state_1};
    if (km_rel_ev && km_rel_cold) begin
      km_dem_base <= dem;
      km_dem_changed <= 1'b0;
    end else if (km_rst_cold_n && (dem !== km_dem_base)) km_dem_changed <= 1'b1;
    for (int f = 0; f < 9; f++) begin
      now = km_otp_rails(km_otp_data_i, f);
      prev = km_otp_rails(km_otp_q, f);
      m = km_rail_mask(f);
      dv = ((now[255:0] ^ prev[255:0]) & m) != '0;
      dc = ((now[511:256] ^ prev[511:256]) & m) != '0;
      cons = ((now[255:0] ^ now[511:256]) & m) == m;
      if (km_dr_cnt[f] != 3'd0) begin
        if (km_dr_cnt[f] == 3'd4) begin
          km_dr_cnt[f] <= '0;
          if (km_own_otp && ((km_dr_cls[f] == 2'd0) || (km_irq_status_i[9] === 1'b1)))
            u_sep_km_integrity_fault_cg.sample(5'd5, 16'({4'(f), km_dr_cls[f]}));
        end else km_dr_cnt[f] <= km_dr_cnt[f] + 3'd1;
      end
      if (km_rst_cold_n && (dv || dc) && !$isunknown(now)) begin
        km_dr_cnt[f] <= 3'd1;
        km_dr_cls[f] <= (dv && dc && cons) ? 2'd0 : (dv && !dc) ? 2'd1 : (dc && !dv) ? 2'd2 : 2'd3;
      end
    end
    // Change status: per-field rise with both rails consistent and
    // IRQ_STATUS.otp_change set; several fields in one clock.
    for (int f = 0; f < 9; f++) rise[f] = !km_chg_q[f] && (km_otp_chg_i[f] === 1'b1);
    km_chg_rise_q <= km_rst_cold_n ? rise : '0;
    if (km_own_otp && km_rst_cold_n) begin
      for (int f = 0; f < 9; f++) begin
        now = km_otp_rails(km_otp_data_i, f);
        m = km_rail_mask(f);
        if (km_chg_rise_q[f] && (((now[255:0] ^ now[511:256]) & m) == m) &&
            (km_irq_status_i[8] === 1'b1))
          u_sep_km_otp_readout_cg.sample(5'd3, 16'(f));
      end
      if ($countones(rise) >= 2) u_sep_km_otp_readout_cg.sample(5'd3, 16'd11);
    end
    // Quiet windows: after a cold release (stable value) and after a warm
    // release with the demotion state changed since the boot.
    if (km_rel_ev) begin
      km_quiet_armed <= 1'b1;
      km_quiet_warm <= !km_rel_cold;
      km_quiet_cnt <= '0;
    end else if (km_quiet_armed) begin
      if ((km_otp_data_i !== km_otp_q) || (km_otp_chg_i !== 9'h0) || (km_irq_status_i[8] !== 1'b0) ||
          !km_rst_warm_n)
        km_quiet_armed <= 1'b0;
      else if (km_quiet_cnt == 7'(KmQuietWin)) begin
        km_quiet_armed <= 1'b0;
        if (km_own_otp) begin
          if (!km_quiet_warm) u_sep_km_otp_readout_cg.sample(5'd3, 16'd9);
          if (km_quiet_warm && km_dem_changed) u_sep_km_otp_readout_cg.sample(5'd3, 16'd10);
        end
      end else km_quiet_cnt <= km_quiet_cnt + 7'd1;
    end
    // The strap stays at its value from before the cold reset while the KM
    // runs.
    if (km_rel_ev && km_rel_cold) begin
      km_strap_at_rel <= (km_strap_i === 1'b1);
      km_strap_bad <= 1'b0;
      km_strap_done <= 1'b0;
      km_strap_cnt <= '0;
    end else if (km_rst_cold_n && km_rst_warm_n && !km_strap_done) begin
      if ((km_strap_i === 1'b1) != km_strap_at_rel) km_strap_bad <= 1'b1;
      if (km_strap_cnt == 11'(KmRunWin)) begin
        km_strap_done <= 1'b1;
        if (km_own_otp && !km_strap_bad && ((km_secure_tm_i === 1'b1) == km_strap_at_rel))
          u_sep_km_otp_readout_cg.sample(5'd6, 16'd2);
      end else km_strap_cnt <= km_strap_cnt + 11'd1;
    end
  end

  // ---------------------------------------------------------------------
  // eFuse program by path (cp_efw_program): the class is the strap at the
  // go, else the write-lock state of the target field in the sensed shadow at
  // the go. Every cell is held as pending and samples only when its pass
  // label rises inside the owner window; the label rise clears the pending
  // cells of that label. A non-strap KM cell is held only when the program
  // interface is idle again with the result that the class states: a program
  // of an unlocked spare field shows program_busy, ends with program_busy 0
  // and raises no efuse_req_err, and a program of a write-locked field raises
  // it (efuse_interface_ctrl.adoc, EFUSE_INTERFACE_CTRL_STATUS.efuse_req_error:
  // the request was blocked by a program lock). A blocked KM program of a
  // write-locked field shows no program_busy, so its wait ends when
  // efuse_req_err rises with no busy seen, and the cell needs efuse_req_err
  // clear at the start of the go write (the bit is sticky, so a bit left from
  // an earlier request fills no cell). The end of the KmPgWin program window
  // holds no cell. The non-strap label is km_efw_prog_pass:
  // sep_km_crossbar_efuse_window_rand_test writes bit 0 after CHK-EFW-PROG
  // passes (the KM program landed, efuse_req_error 0) and bit 1 after
  // CHK-EFW-DENY passes (efuse_req_error 1 and the OTP word equal to the
  // staged word), each written alone and then 0. A strap cell is held from
  // its go write under the strap, and the label is km_efw_tm_pass: the leaf
  // writes 0 before its secure test programs and 1 after CHK-EFW-TM passes
  // (equal KM and host results, no fuse change and a zero read word). A label
  // gates a sample; it is never a bin value and drives nothing.
  // ---------------------------------------------------------------------
  // Write-lock target of a program (cp_efw_program). Field n of the shadow map
  // spans the OTP bits from 8 times its REG_OFFSET to the next field, and its
  // write lock is the <FIELD>_WRITE_LOCK bit of LOCKS or LOCKS_SPARE
  // (sep_efuse_map.adoc). The lock vector is the sensed shadow from OTP bit
  // 8 * LOCKS REG_OFFSET.
  localparam int unsigned KmEfFields = 41;
  localparam int unsigned KmEfSpareLockOfs =
      (SEP_EFUSE_MAP_LOCKS_SPARE_REG_OFFSET - SEP_EFUSE_MAP_LOCKS_REG_OFFSET) * 8;
  localparam int unsigned KmEfFieldOff[KmEfFields+1] = '{
      SEP_EFUSE_MAP_LC_STATE_REG_OFFSET,
      SEP_EFUSE_MAP_SBOOT_DIS_REG_OFFSET,
      SEP_EFUSE_MAP_TRANSIENT_RMA_EN_REG_OFFSET,
      SEP_EFUSE_MAP_SIP_DIS_REG_OFFSET,
      SEP_EFUSE_MAP_SYS_DIS_REG_OFFSET,
      SEP_EFUSE_MAP_RMA_SIP_TOKEN_DIGEST_REG_OFFSET,
      SEP_EFUSE_MAP_RMA_CHIPLET_TOKEN_DIGEST_REG_OFFSET,
      SEP_EFUSE_MAP_CLASS_KEY_REG_OFFSET,
      SEP_EFUSE_MAP_CHIPLET_PUBK_REVOKE_REG_OFFSET,
      SEP_EFUSE_MAP_BL1_VERSION_REG_OFFSET,
      SEP_EFUSE_MAP_BL2_VERSION_REG_OFFSET,
      SEP_EFUSE_MAP_CHIPLET_UID_REG_OFFSET,
      SEP_EFUSE_MAP_SIP_PUBK_HASH0_REG_OFFSET,
      SEP_EFUSE_MAP_SIP_UID_REG_OFFSET,
      SEP_EFUSE_MAP_SYS_PUBK_HASH_REG_OFFSET,
      SEP_EFUSE_MAP_SYS_UID_REG_OFFSET,
      SEP_EFUSE_MAP_STATUS_RPT_REG_OFFSET,
      SEP_EFUSE_MAP_ROM_CTL_REG_OFFSET,
      SEP_EFUSE_MAP_SYSCLK_FREQ_MHZ_REG_OFFSET,
      SEP_EFUSE_MAP_CHIPLET_PUBK_HASH0_REG_OFFSET,
      SEP_EFUSE_MAP_CHIPLET_PUBK_HASH1_REG_OFFSET,
      SEP_EFUSE_MAP_REQUIRED_SIGNERS_REG_OFFSET,
      SEP_EFUSE_MAP_REQUIRED_ALGS_REG_OFFSET,
      SEP_EFUSE_MAP_CHIPLET_PUBK_PQC_HASH0_REG_OFFSET,
      SEP_EFUSE_MAP_CHIPLET_PUBK_PQC_HASH1_REG_OFFSET,
      SEP_EFUSE_MAP_SIP_PUBK_PQC_HASH0_REG_OFFSET,
      SEP_EFUSE_MAP_SYS_PUBK_PQC_HASH_REG_OFFSET,
      SEP_EFUSE_MAP_SIP_PUBK_HASH1_REG_OFFSET,
      SEP_EFUSE_MAP_SIP_PUBK_PQC_HASH1_REG_OFFSET,
      SEP_EFUSE_MAP_SEP_CHIPLET_ID_REG_OFFSET,
      SEP_EFUSE_MAP_SEP_SIP_ID_REG_OFFSET,
      SEP_EFUSE_MAP_SEP_SYS_ID_REG_OFFSET,
      SEP_EFUSE_MAP_SPARE0_REG_OFFSET,
      SEP_EFUSE_MAP_SPARE1_REG_OFFSET,
      SEP_EFUSE_MAP_SPARE2_REG_OFFSET,
      SEP_EFUSE_MAP_SPARE3_REG_OFFSET,
      SEP_EFUSE_MAP_SPARE4_REG_OFFSET,
      SEP_EFUSE_MAP_SPARE5_REG_OFFSET,
      SEP_EFUSE_MAP_SPARE6_REG_OFFSET,
      SEP_EFUSE_MAP_SPARE7_REG_OFFSET,
      SEP_EFUSE_MAP_SPARE8_REG_OFFSET,
      SEP_EFUSE_MAP_SPARE8_REG_OFFSET + SpareStrideB
  };
  localparam int unsigned KmEfFieldWlock[KmEfFields] = '{
      SEP_EFUSE_MAP_LOCKS_LC_STATE_WRITE_LOCK_SHIFT,
      SEP_EFUSE_MAP_LOCKS_SBOOT_DIS_WRITE_LOCK_SHIFT,
      SEP_EFUSE_MAP_LOCKS_TRANSIENT_RMA_EN_WRITE_LOCK_SHIFT,
      SEP_EFUSE_MAP_LOCKS_SIP_DIS_WRITE_LOCK_SHIFT,
      SEP_EFUSE_MAP_LOCKS_SYS_DIS_WRITE_LOCK_SHIFT,
      SEP_EFUSE_MAP_LOCKS_RMA_SIP_TOKEN_DIGEST_WRITE_LOCK_SHIFT,
      SEP_EFUSE_MAP_LOCKS_RMA_CHIPLET_TOKEN_DIGEST_WRITE_LOCK_SHIFT,
      SEP_EFUSE_MAP_LOCKS_CLASS_KEY_WRITE_LOCK_SHIFT,
      SEP_EFUSE_MAP_LOCKS_CHIPLET_PUBK_REVOKE_WRITE_LOCK_SHIFT,
      SEP_EFUSE_MAP_LOCKS_BL1_VERSION_WRITE_LOCK_SHIFT,
      SEP_EFUSE_MAP_LOCKS_BL2_VERSION_WRITE_LOCK_SHIFT,
      SEP_EFUSE_MAP_LOCKS_CHIPLET_UID_WRITE_LOCK_SHIFT,
      SEP_EFUSE_MAP_LOCKS_SIP_PUBK_HASH0_WRITE_LOCK_SHIFT,
      SEP_EFUSE_MAP_LOCKS_SIP_UID_WRITE_LOCK_SHIFT,
      SEP_EFUSE_MAP_LOCKS_SYS_PUBK_HASH_WRITE_LOCK_SHIFT,
      SEP_EFUSE_MAP_LOCKS_SYS_UID_WRITE_LOCK_SHIFT,
      SEP_EFUSE_MAP_LOCKS_STATUS_RPT_WRITE_LOCK_SHIFT,
      SEP_EFUSE_MAP_LOCKS_ROM_CTL_WRITE_LOCK_SHIFT,
      SEP_EFUSE_MAP_LOCKS_SYSCLK_FREQ_MHZ_WRITE_LOCK_SHIFT,
      SEP_EFUSE_MAP_LOCKS_CHIPLET_PUBK_HASH0_WRITE_LOCK_SHIFT,
      SEP_EFUSE_MAP_LOCKS_CHIPLET_PUBK_HASH1_WRITE_LOCK_SHIFT,
      SEP_EFUSE_MAP_LOCKS_REQUIRED_SIGNERS_WRITE_LOCK_SHIFT,
      SEP_EFUSE_MAP_LOCKS_REQUIRED_ALGS_WRITE_LOCK_SHIFT,
      SEP_EFUSE_MAP_LOCKS_CHIPLET_PUBK_PQC_HASH0_WRITE_LOCK_SHIFT,
      SEP_EFUSE_MAP_LOCKS_CHIPLET_PUBK_PQC_HASH1_WRITE_LOCK_SHIFT,
      SEP_EFUSE_MAP_LOCKS_SIP_PUBK_PQC_HASH0_WRITE_LOCK_SHIFT,
      SEP_EFUSE_MAP_LOCKS_SYS_PUBK_PQC_HASH_WRITE_LOCK_SHIFT,
      SEP_EFUSE_MAP_LOCKS_SIP_PUBK_HASH1_WRITE_LOCK_SHIFT,
      SEP_EFUSE_MAP_LOCKS_SIP_PUBK_PQC_HASH1_WRITE_LOCK_SHIFT,
      SEP_EFUSE_MAP_LOCKS_SEP_CHIPLET_ID_WRITE_LOCK_SHIFT,
      SEP_EFUSE_MAP_LOCKS_SEP_SIP_ID_WRITE_LOCK_SHIFT,
      SEP_EFUSE_MAP_LOCKS_SEP_SYS_ID_WRITE_LOCK_SHIFT,
      KmEfSpareLockOfs + SEP_EFUSE_MAP_LOCKS_SPARE_SPARE0_WRITE_LOCK_SHIFT,
      KmEfSpareLockOfs + SEP_EFUSE_MAP_LOCKS_SPARE_SPARE1_WRITE_LOCK_SHIFT,
      KmEfSpareLockOfs + SEP_EFUSE_MAP_LOCKS_SPARE_SPARE2_WRITE_LOCK_SHIFT,
      KmEfSpareLockOfs + SEP_EFUSE_MAP_LOCKS_SPARE_SPARE3_WRITE_LOCK_SHIFT,
      KmEfSpareLockOfs + SEP_EFUSE_MAP_LOCKS_SPARE_SPARE4_WRITE_LOCK_SHIFT,
      KmEfSpareLockOfs + SEP_EFUSE_MAP_LOCKS_SPARE_SPARE5_WRITE_LOCK_SHIFT,
      KmEfSpareLockOfs + SEP_EFUSE_MAP_LOCKS_SPARE_SPARE6_WRITE_LOCK_SHIFT,
      KmEfSpareLockOfs + SEP_EFUSE_MAP_LOCKS_SPARE_SPARE7_WRITE_LOCK_SHIFT,
      KmEfSpareLockOfs + SEP_EFUSE_MAP_LOCKS_SPARE_SPARE8_WRITE_LOCK_SHIFT
  };
  localparam int unsigned KmEfFirstSpare = KmEfFields - SpareCount;
  // {field found, spare field, write lock set} of the field that holds OTP bit
  // b, from the sensed lock vector. LC_STATE ignores its lock bits
  // (otp_fuse_controller.adoc, Shadow Register and JTAG Access Control), so it
  // is no target class.
  function automatic logic [2:0] km_ef_target(logic [15:0] b, logic [95:0] locks);
    for (int unsigned f = 1; f < KmEfFields; f++)
    if ((32'(b) >= KmEfFieldOff[f] * 8) && (32'(b) < KmEfFieldOff[f+1] * 8))
      return {1'b1, (f >= KmEfFirstSpare), (locks[KmEfFieldWlock[f]] === 1'b1)};
    return 3'b000;
  endfunction
  logic [13:0] km_pg_cnt = '0;
  logic km_pg_host = 1'b0, km_pg_tm = 1'b0, km_pg_busy_seen = 1'b0;
  logic [2:0] km_pg_tgt = '0;
  logic km_pg_err_seen = 1'b0;
  logic km_pg_err_aw = 1'b0;  // efuse_req_err at the start of the last KM write
  logic km_pg_err0 = 1'b0;  // efuse_req_err at the start of the go write
  int unsigned km_efw_tm_pass = 0;
  logic km_efw_tm_pass_q = 1'b0;
  logic [1:0] km_pg_tm_pend = '0;  // {host, KM} strap program go seen; waits for the label
  int unsigned km_efw_prog_pass = 0;  // bit 0 CHK-EFW-PROG, bit 1 CHK-EFW-DENY passed
  logic km_efw_prog_pass_q = 1'b0;
  logic [1:0] km_pg_np_pend = '0;  // {write-locked, unlocked spare} KM cell; waits for the label
  always @(posedge clk_i) begin
    logic pg_idle, pg_blocked;
    km_efw_tm_pass_q <= (km_efw_tm_pass != 0);
    if (km_own_xbar && (km_efw_tm_pass != 0) && !km_efw_tm_pass_q) begin
      if (km_pg_tm_pend[0]) u_sep_km_otp_readout_cg.sample(5'd8, 16'(3'b0_10));
      if (km_pg_tm_pend[1]) u_sep_km_otp_readout_cg.sample(5'd8, 16'(3'b1_10));
      km_pg_tm_pend <= '0;
    end
    km_efw_prog_pass_q <= (km_efw_prog_pass != 0);
    if (km_own_xbar && (km_efw_prog_pass != 0) && !km_efw_prog_pass_q) begin
      if (km_pg_np_pend[0] && km_efw_prog_pass[0])
        u_sep_km_otp_readout_cg.sample(5'd8, 16'(3'b0_00));
      if (km_pg_np_pend[1] && km_efw_prog_pass[1])
        u_sep_km_otp_readout_cg.sample(5'd8, 16'(3'b0_01));
      km_pg_np_pend <= '0;
    end
    if (kx_wstart) km_pg_err_aw <= (req_err_i === 1'b1);
    if (km_pg_cnt != 14'd0) begin
      if (km_efuse_pg_busy_i === 1'b1) km_pg_busy_seen <= 1'b1;
      if (req_err_i === 1'b1) km_pg_err_seen <= 1'b1;
      pg_idle = km_pg_busy_seen && (km_efuse_pg_busy_i === 1'b0) && (km_pg_cnt > 14'd2);
      pg_blocked = !km_pg_host && !km_pg_tm && km_pg_tgt[2] && km_pg_tgt[0] && !km_pg_err0 &&
          !km_pg_busy_seen && (km_efuse_pg_busy_i !== 1'b1) && (req_err_i === 1'b1);
      if (pg_idle || pg_blocked || (km_pg_cnt == 14'(KmPgWin))) begin
        km_pg_cnt <= '0;
        if (km_own_xbar && (km_efw_prog_pass == 0) && !km_pg_host && !km_pg_tm && km_pg_tgt[2] &&
            (pg_idle || pg_blocked)) begin
          if (km_pg_tgt[0] && !km_pg_err0 && (km_pg_err_seen || (req_err_i === 1'b1)))
            km_pg_np_pend[1] <= 1'b1;
          else if (pg_idle && !km_pg_tgt[0] && km_pg_tgt[1] && !km_pg_err_seen && (req_err_i !== 1'b1))
            km_pg_np_pend[0] <= 1'b1;
        end
      end else km_pg_cnt <= km_pg_cnt + 14'd1;
    end
    if (kw_ev && (kw_addr == KmEfCtrlBase + (KmEfPgCtrl - EFUSE_INTERFACE_CTRL_REG_MAP_BASE_ADDR)) &&
        |(kw_data & KmEfPgGo)) begin
      km_pg_cnt <= 14'd1;
      km_pg_host <= 1'b0;
      km_pg_tm <= (km_secure_tm_i === 1'b1);
      if (km_own_xbar && (km_secure_tm_i === 1'b1) && (km_efw_tm_pass == 0))
        km_pg_tm_pend[0] <= 1'b1;
      km_pg_busy_seen <= 1'b0;
      km_pg_err_seen <= 1'b0;
      km_pg_err0 <= km_pg_err_aw;
      km_pg_tgt <= km_ef_target(16'((kw_data & EFUSE_INTERFACE_CTRL_EFUSE_PROGRAM_CTRL_EFUSE_ADDR_MASK) >>
                                    EFUSE_INTERFACE_CTRL_EFUSE_PROGRAM_CTRL_EFUSE_ADDR_SHIFT),
                                {ef_locks_sp, ef_locks});
    end else if (wr_ev && (aw_addr_q == KmEfPgCtrl) && |(wr_data & KmEfPgGo)) begin
      km_pg_cnt <= 14'd1;
      km_pg_host <= 1'b1;
      km_pg_tm <= (km_secure_tm_i === 1'b1);
      if (km_own_xbar && (km_secure_tm_i === 1'b1) && (km_efw_tm_pass == 0))
        km_pg_tm_pend[1] <= 1'b1;
      km_pg_busy_seen <= 1'b0;
      km_pg_err_seen <= 1'b0;
      km_pg_tgt <= '0;
    end
  end

  // ---------------------------------------------------------------------
  // Vault wipe (sep_km_vault_wipe_cg).
  // ---------------------------------------------------------------------
  logic km_wipe_q = 1'b0;
  logic km_wp_sep = 1'b0, km_wp_trap = 1'b0;
  logic [1:0] km_wp_cnt = '0;
  logic km_wp_had_seal = 1'b0, km_wp_had_scr = 1'b0;
  logic [3:0] km_wp_sram_wr = '0;
  logic [98*32-1:0] km_wp_probe_q = '0, km_wp_probe_pre = '0;
  logic [4:0] km_wp_in_d = '0;
  logic [7:0] km_wp_valid = '0;
  logic [10:0] km_wp_run = '0;
  logic km_wp_run_on = 1'b0;
  logic [7:0] km_wipe_hi_cnt = '0;
  logic [7:0] km_wipe_pulses = '0;
  logic km_wipe_seen = 1'b0, km_wipe_fell = 1'b0;
  logic [4:0] km_w1h_cnt = '0;
  logic km_w1h_pulse = 1'b0;
  always @(posedge clk_i) begin
    logic pulse, lvl;
    int unsigned nz, nsr;
    logic any_seal, any_ret;
    pulse = (km_wipe_i[1] === 1'b1);
    lvl = (km_wipe_i[0] === 1'b1);
    km_wipe_q <= lvl;
    km_wp_probe_q <= km_sram_probe_i;
    if (km_wp_sram_wr != 4'd0) km_wp_sram_wr <= km_wp_sram_wr - 4'd1;
    if (km_sram_wr) km_wp_sram_wr <= 4'd3;
    if (!km_rst_cold_n) begin
      km_wipe_seen <= 1'b0;
      km_wipe_fell <= 1'b0;
    end
    if (pulse && km_rst_cold_n) begin
      // Vault at the wipe: the regfile and CTRL clear on the next edge.
      nz = 0;
      nsr = 0;
      any_seal = 1'b0;
      any_ret = 1'b0;
      for (int i = 0; i < 1024; i++) if (km_kpv_words_i[32*i+:32] != 32'h0) nz++;
      for (int s = 0; s < 64; s++) begin
        if (km_slot_state(km_kpv_ctrl_i[4*s+:4]) == 3'd4) begin
          any_seal = 1'b1;
          nsr++;
        end
        if (km_slot_state(km_kpv_ctrl_i[4*s+:4]) == 3'd5) begin
          any_ret = 1'b1;
          nsr++;
        end
      end
      if (km_own_kpv || km_own_cpu || km_own_fi) begin
        if ((nz == 0) && (km_kpv_ctrl_i === '0)) u_sep_km_vault_wipe_cg.sample(5'd0, 16'd0);
        if (nz > 16 * nsr) u_sep_km_vault_wipe_cg.sample(5'd0, 16'd1);
        if (any_seal) u_sep_km_vault_wipe_cg.sample(5'd0, 16'd2);
        if (any_ret) u_sep_km_vault_wipe_cg.sample(5'd0, 16'd3);
        if (km_kpv_scr_ctrl_i[1] === 1'b1) u_sep_km_vault_wipe_cg.sample(5'd0, 16'd4);
      end
      km_wp_cnt <= 2'd1;
      km_wp_trap <= (km_trap_i === 1'b1);
      km_wp_sep <= lvl && (km_trap_i !== 1'b1);
      km_wp_had_seal <= any_seal || any_ret;
      km_wp_had_scr <= (km_kpv_scr_ctrl_i !== 2'b00) || (km_kpv_scr_key_i !== 32'h0);
      km_wp_probe_pre <= km_wp_probe_q;
      km_wp_in_d <= km_mbx_in_depth_i;
      km_wp_valid <= km_key_valid_i;
      // Edge protocol of the SEP bit.
      if (lvl && (km_trap_i !== 1'b1)) begin
        if (km_own_kpv || km_own_fi) begin
          u_sep_km_vault_wipe_cg.sample(5'd2, 16'd4);
          if (km_wipe_seen && km_wipe_fell) u_sep_km_vault_wipe_cg.sample(5'd2, 16'd1);
        end
        km_wipe_seen <= 1'b1;
        km_wipe_fell <= 1'b0;
        km_wp_run <= '0;
        km_wp_run_on <= 1'b1;
      end
    end
    // The clock after the wipe edge.
    if (km_wp_cnt == 2'd1) begin
      km_wp_cnt <= '0;
      if ((km_kpv_words_i === '0) && (km_kpv_ctrl_i === '0)) begin
        if (km_wp_sep && km_wp_had_seal && (km_own_kpv || km_own_fi))
          u_sep_km_vault_wipe_cg.sample(5'd1, 16'd0);
        if (km_wp_trap && km_own_cpu) u_sep_km_vault_wipe_cg.sample(5'd1, 16'd2);
      end
      if (km_wp_sep && km_wp_had_scr && (km_kpv_scr_ctrl_i === 2'b00) && (km_kpv_scr_key_i === 32'h0)) begin
        if (km_own_kpv || km_own_fi) u_sep_km_vault_wipe_cg.sample(5'd1, 16'd1);
        if (km_own_kpv) u_sep_km_kpv_slot_cg.sample(5'd8, 16'd4);
      end
      // Scope of an SEP wipe.
      if (km_wp_sep && km_own_kpv) begin
        if ((km_wp_sram_wr == 4'd0) && !km_sram_wr && (km_sram_probe_i === km_wp_probe_pre) &&
            (km_wp_probe_pre != '0))
          u_sep_km_vault_wipe_cg.sample(5'd3, 16'd1);
        if ((km_wp_in_d != 5'd0) && (km_mbx_in_depth_i === km_wp_in_d))
          u_sep_km_vault_wipe_cg.sample(5'd3, 16'd2);
        // The pulse clears KEY_VALID of every accelerator sideload register
        // block (hw/ip/key_manager/doc/architecture.adoc:506-510): at least
        // one KEY_VALID bit set before the wipe, and every bit 0 after it.
        if ((km_wp_valid != 8'h00) && !$isunknown(km_wp_valid) && (km_key_valid_i === 8'h00))
          u_sep_km_vault_wipe_cg.sample(5'd3, 16'd3);
      end
    end
    // The CPU keeps running after an SEP wipe: a KM bus access completes
    // with no trap.
    if (km_wp_run_on) begin
      if ((km_trap_i === 1'b1) || !km_rst_warm_n || (km_wp_run == 11'h7FF)) km_wp_run_on <= 1'b0;
      else begin
        km_wp_run <= km_wp_run + 11'd1;
        if ((km_wp_run > 11'd2) && (kw_ev || kr_ev)) begin
          km_wp_run_on <= 1'b0;
          if (km_own_kpv) u_sep_km_vault_wipe_cg.sample(5'd3, 16'd0);
        end
      end
    end
    // Level held high: one wipe over KmLevelWin clocks, and the bit left
    // high after the rise.
    if (km_wipe_q && !lvl) km_wipe_fell <= 1'b1;
    if (!lvl) begin
      km_wipe_hi_cnt <= '0;
      km_wipe_pulses <= '0;
    end else begin
      if (km_wipe_hi_cnt != 8'hFF) km_wipe_hi_cnt <= km_wipe_hi_cnt + 8'd1;
      if (pulse && (km_wipe_pulses != 8'hFF)) km_wipe_pulses <= km_wipe_pulses + 8'd1;
      if ((km_own_kpv || km_own_fi) && (km_wipe_hi_cnt == 8'd8) && (km_wipe_pulses == 8'd1))
        u_sep_km_vault_wipe_cg.sample(5'd2, 16'd0);
      if ((km_own_kpv || km_own_fi) && (km_wipe_hi_cnt == 8'(KmLevelWin)) && (km_wipe_pulses == 8'd1))
        u_sep_km_vault_wipe_cg.sample(5'd2, 16'd3);
    end
    // A write of 1 to KM_WIPE_CTRL while the bit is high gives no second
    // wipe.
    if (km_wipe && km_wipe_q && lvl) begin
      km_w1h_cnt <= 5'd1;
      km_w1h_pulse <= 1'b0;
    end else if (km_w1h_cnt != 5'd0) begin
      if (pulse) km_w1h_pulse <= 1'b1;
      if (!lvl) km_w1h_cnt <= '0;
      else if (km_w1h_cnt == 5'd16) begin
        km_w1h_cnt <= '0;
        if (km_own_kpv && !km_w1h_pulse && !pulse) u_sep_km_vault_wipe_cg.sample(5'd2, 16'd2);
      end else km_w1h_cnt <= km_w1h_cnt + 5'd1;
    end
  end

  // ---------------------------------------------------------------------
  // ABR shared key hardware events (cp_sk_delivery_state, cp_sk_interrupt).
  // ---------------------------------------------------------------------
  logic km_skv_q = 1'b0, km_ski_q = 1'b0;
  logic [1:0] km_sk_line_st = 2'b11;
  always @(posedge clk_i) begin
    logic v, i, e;
    logic [1:0] ls;
    v = (km_sk_valid_i === 1'b1);
    i = (km_sk_irq_status_i === 1'b1);
    e = (km_sk_irq_enable_i === 1'b1);
    km_skv_q <= v;
    km_ski_q <= i;
    if (km_own_bank && km_rst_cold_n) begin
      if (!km_skv_q && v) begin
        u_sep_km_abr_shared_key_cg.sample(5'd0, 16'd1);
        if (km_sk_consumed) u_sep_km_abr_shared_key_cg.sample(5'd0, 16'd3);
      end
      if (!km_ski_q && i && !(kw_ev && (kw_addr == KmSkIrqStatus))) begin
        u_sep_km_abr_shared_key_cg.sample(5'd2, 16'd0);
        if (km_sk_irq_cleared) u_sep_km_abr_shared_key_cg.sample(5'd2, 16'd5);
      end
      ls = {i, e};
      if (ls != km_sk_line_st) begin
        if ((ls == 2'b10) && (km_cpu_sk_irq_i === 1'b0))
          u_sep_km_abr_shared_key_cg.sample(5'd2, 16'd1);
        if ((ls == 2'b11) && (km_cpu_sk_irq_i === 1'b1))
          u_sep_km_abr_shared_key_cg.sample(5'd2, 16'd2);
      end
    end
    km_sk_line_st <= {i, e};
  end

  // =====================================================================
  // Key Manager points of the 7.22 to 7.28 owners (docs/SEP_FCOV.adoc, Key
  // Manager groups, "Decoders in the sampler"). The host mailbox stream is
  // decoded from the host LSU bus: cmd_decode and crc_check classify each
  // command frame at its separator word, seq_model holds the next expected
  // command sequence, and rsp_decode reads every outbound frame with its own
  // word index. A RESP_CMD is paired with the oldest command frame that has
  // no response yet, and only when it echoes the sequence and the ID of that
  // frame. A frame class only selects a cell: every cell also needs the DUT
  // response or the DUT net that the point names, so a wrong response fills
  // no cell. Only the bins of checks that the owners implement are declared;
  // docs/SEP_FCOV.adoc lists the others as blocked or parked.
  // =====================================================================

  // One command frame, classified at its separator word.
  typedef struct packed {
    logic [7:0]  id;
    logic [7:0]  seq;
    logic [7:0]  plen;
    logic [7:0]  e;         // seq_model value at the frame end
    // Faults present: {dispatch length, payload CRC, wire length, command
    // ID, sequence, header CRC}.
    logic [5:0]  flt;
    logic        recov;     // km_recoverable_err at the frame end
    logic [7:0]  hcrc;      // received HEADER_CRC8
    logic [31:0] pcrc;      // received last word (PAYLOAD_CRC32)
    logic [31:0] p0;        // payload word 0
    logic [31:0] p1;        // payload word 1
    logic        flip;      // HK-KPV armed at the frame end
    logic [9:0]  flip_idx;  // logical KPV word index that HK-KPV arms
  } kq_frame_t;

  localparam logic [7:0] KqRespReady = 8'h55;
  localparam logic [7:0] KqRespSkReady = 8'h56;
  localparam logic [7:0] KqRespRec = 8'hFE;
  localparam logic [7:0] KqRespUnrec = 8'hFF;
  // Signed 8-bit return codes of RESP_CMD (firmware.adoc, RESP_CMD).
  localparam logic [7:0] KqRcFail = 8'hFF;
  localparam logic [7:0] KqRcHdr = 8'hFE;
  localparam logic [7:0] KqRcSeq = 8'hFD;
  localparam logic [7:0] KqRcId = 8'hFC;
  localparam logic [7:0] KqRcLen = 8'hFB;
  localparam logic [7:0] KqRcPcrc = 8'hFA;
  localparam logic [7:0] KqRcArg = 8'hF9;
  localparam logic [7:0] KqCmdStat = 8'h03;
  localparam logic [7:0] KqCmdRevoke = 8'h23;
  localparam logic [7:0] KqCmdShred = 8'h25;
  localparam logic [7:0] KqCmdLoad = 8'h26;
  // The SRAM has 8192 words (architecture.adoc, Parameters): an SRAM shred
  // writes at least that many words.
  localparam int unsigned KqShredWords = 8192;

  // CRC-8/ROHC over {PAYLOAD_LEN, COMMAND_ID, CMD_SEQ_NUM}, least significant
  // byte first (firmware.adoc, CRC Function Library): poly 0x07 reflected,
  // init 0xFF, no final XOR.
  function automatic logic [7:0] kq_crc8_rohc(logic [23:0] hdr);
    logic [7:0] c;
    logic fb;
    c = 8'hFF;
    for (int i = 0; i < 24; i++) begin
      fb = c[0] ^ hdr[i];
      c = c >> 1;
      if (fb) c = c ^ 8'hE0;
    end
    return c;
  endfunction

  // CRC-32C running remainder over one little-endian word: poly 0x1EDC6F41
  // reflected, init 0xFFFFFFFF; the CRC is the inverted remainder.
  function automatic logic [31:0] kq_crc32c_upd(logic [31:0] c, logic [31:0] w);
    logic [31:0] r;
    logic fb;
    r = c;
    for (int i = 0; i < 32; i++) begin
      fb = r[0] ^ w[i];
      r = r >> 1;
      if (fb) r = r ^ 32'h82F6_3B78;
    end
    return r;
  endfunction

  // The 15 command IDs (firmware.adoc, Key Manager command summary).
  function automatic logic kq_id_valid(logic [7:0] id);
    return (id <= 8'h04) || ((id >= 8'h10) && (id <= 8'h12)) || ((id >= 8'h22) && (id <= 8'h28));
  endfunction

  // Commands that the recovery gate refuses (firmware.adoc, Error Recovery).
  function automatic logic kq_id_gated(logic [7:0] id);
    return kq_id_valid(id) && (id >= 8'h10);
  endfunction

  // plen_table: the PAYLOAD_LEN that a command requires. CMD_KEY_LOAD takes
  // KEY_SIZE + 3 words and checks it as an argument, so it has no fixed
  // length (8'hFF).
  function automatic logic [7:0] kq_req_len(logic [7:0] id);
    case (id)
      8'h11, 8'h23, 8'h25, 8'h27, 8'h28: return 8'd1;
      8'h22, 8'h24: return 8'd2;
      8'h26: return 8'hFF;
      default: return 8'd0;
    endcase
  endfunction

  // Index of a valid command ID in the order of cp_cmd_x_outcome.
  function automatic logic [3:0] kq_id_idx(logic [7:0] id);
    if (id <= 8'h04) return 4'(id);
    if (id <= 8'h12) return 4'(id - 8'h10 + 8'd5);
    return 4'(id - 8'h22 + 8'd8);
  endfunction

  // cmd_decode and crc_check of one frame of L wire words. A payload CRC
  // fault counts on a frame whose PAYLOAD_LEN matches the wire, and on a
  // frame whose PAYLOAD_LEN contradicts the wire when the wire payload has
  // the length that the command requires (the CRC word is then where the
  // command puts it). The dispatch length fault needs a self-consistent
  // frame.
  function automatic kq_frame_t kq_classify(logic [31:0] hdr, logic [8:0] l, logic [31:0] crc_calc,
                                            logic [31:0] last, logic [31:0] p0, logic [31:0] p1,
                                            logic [7:0] e, logic recov);
    kq_frame_t r;
    logic [7:0] rq;
    logic wire_ok, idv;
    r = '0;
    r.plen = hdr[23:16];
    r.id = hdr[15:8];
    r.seq = hdr[7:0];
    r.e = e;
    r.recov = recov;
    r.hcrc = hdr[31:24];
    r.pcrc = last;
    r.p0 = p0;
    r.p1 = p1;
    wire_ok = (r.plen == 8'd0) ? (l == 9'd1) : (l == (9'(r.plen) + 9'd2));
    rq = kq_req_len(r.id);
    idv = kq_id_valid(r.id);
    r.flt[0] = (kq_crc8_rohc(hdr[23:0]) != hdr[31:24]);
    r.flt[1] = (r.seq != e);
    r.flt[2] = !idv;
    r.flt[3] = !wire_ok;
    if (wire_ok) r.flt[4] = (r.plen != 8'd0) && (crc_calc != last);
    else
      r.flt[4] = (l >= 9'd3) && idv && (rq != 8'hFF) && ((9'(rq) + 9'd2) == l) && (crc_calc != last);
    r.flt[5] = wire_ok && idv && (rq != 8'hFF) && (r.plen != rq);
    return r;
  endfunction

  // The first failing check in the order of the incoming message handler:
  // 0 header CRC, 1 sequence, 2 command ID, 3 length, 4 payload CRC, 5 the
  // recovery gate, 6 the handler. The dispatch length check follows the gate
  // and reports the length code, so it is class 3.
  function automatic logic [2:0] kq_first(kq_frame_t f);
    if (f.flt[0]) return 3'd0;
    if (f.flt[1]) return 3'd1;
    if (f.flt[2]) return 3'd2;
    if (f.flt[3]) return 3'd3;
    if (f.flt[4]) return 3'd4;
    if (f.recov && kq_id_gated(f.id)) return 3'd5;
    if (f.flt[5]) return 3'd3;
    return 3'd6;
  endfunction

  function automatic logic [7:0] kq_first_code(logic [2:0] c);
    case (c)
      3'd0: return KqRcHdr;
      3'd1: return KqRcSeq;
      3'd2: return KqRcId;
      3'd3: return KqRcLen;
      3'd4: return KqRcPcrc;
      default: return KqRcFail;
    endcase
  endfunction

  // The fault pair of cp_fv_pair_order: the first two faults in check order
  // {header CRC, sequence, command ID, wire length, payload CRC, dispatch
  // length}; 4'hF when the frame has fewer than two faults or no pair bin.
  function automatic logic [3:0] kq_pair(logic [5:0] flt);
    int a, b;
    logic [5:0] ab;
    a = -1;
    b = -1;
    for (int i = 0; i < 6; i++) begin
      if (flt[i] && (a < 0)) a = i;
      else if (flt[i] && (b < 0)) b = i;
    end
    if (b < 0) return 4'hF;
    ab = {3'(a), 3'(b)};
    case (ab)
      {3'd0, 3'd1} : return 4'd0;
      {3'd0, 3'd2} : return 4'd1;
      {3'd0, 3'd3} : return 4'd2;
      {3'd0, 3'd4} : return 4'd3;
      {3'd1, 3'd2} : return 4'd4;
      {3'd1, 3'd3} : return 4'd5;
      {3'd1, 3'd4} : return 4'd6;
      {3'd2, 3'd3} : return 4'd7;
      {3'd2, 3'd4} : return 4'd8;
      {3'd3, 3'd4} : return 4'd9;
      {3'd0, 3'd5} : return 4'd10;
      {3'd1, 3'd5} : return 4'd11;
      {3'd4, 3'd5} : return 4'd12;
      default: return 4'hF;
    endcase
  endfunction

  // IRQ_STATUS bit of the fatal source at priority rank r (firmware.adoc,
  // Interrupt Priority): wipe_state, rom_parity, sram_parity, rom_write,
  // sram_write_lock, axi_decerr, drbg_err, axi_slverr, otp_sigint, exec,
  // rom_access (km_csr.adoc, IRQ_STATUS bit order).
  function automatic logic [3:0] kq_rank_bit(logic [3:0] r);
    case (r)
      4'd0: return 4'd7;
      4'd1: return 4'd0;
      4'd2: return 4'd1;
      4'd3: return 4'd2;
      4'd4: return 4'd3;
      4'd5: return 4'd5;
      4'd6: return 4'd6;
      4'd7: return 4'd4;
      4'd8: return 4'd9;
      4'd9: return 4'd10;
      default: return 4'd11;
    endcase
  endfunction

  // Rank of an unrecoverable fault code (firmware.adoc, unrecoverable-fault
  // codes); 4'hF for a code with no IRQ_STATUS source.
  function automatic logic [3:0] kq_code_rank(logic [7:0] c);
    case (c)
      8'hFF: return 4'd0;
      8'hFE: return 4'd1;
      8'hFD: return 4'd2;
      8'hFC: return 4'd3;
      8'hFB: return 4'd4;
      8'hFA: return 4'd5;
      8'hF8: return 4'd6;
      8'hF9: return 4'd7;
      8'hF3: return 4'd8;
      8'hEF: return 4'd9;
      8'hEE: return 4'd10;
      default: return 4'hF;
    endcase
  endfunction

  // Engine bank of a KM-BUS key-path write, in DEST_VALID order: port 0
  // OTBN, 1 AES, 2 HMAC, 3 KMAC, 4 Adams Bridge, whose seed and message
  // windows are 0x100 apart (abr_wrapper_key.adoc); 4'hF elsewhere.
  function automatic logic [3:0] kq_key_bank(int unsigned port, logic [31:0] a);
    case (port)
      0: return 4'd3;
      1: return 4'd2;
      2: return 4'd0;
      3: return 4'd1;
      default: return (a[11:10] == 2'b00) ? {2'b01, a[9:8]} : 4'hF;
    endcase
  endfunction

  function automatic logic [63:0] kq_lock_write(logic [255:0] c);
    logic [63:0] r;
    for (int s = 0; s < 64; s++) r[s] = (c[4*s] === 1'b1);
    return r;
  endfunction

  function automatic logic [5:0] kq_lowest(logic [63:0] m);
    logic [5:0] r;
    r = '0;
    for (int s = 63; s >= 0; s--) if (m[s]) r = 6'(s);
    return r;
  endfunction

  // --- cmd_decode, rsp_decode, seq_model and handle_table ----------------
  wire kq_held = !km_rst_warm_n || !km_rst_cold_n || !km_swrst_n;
  wire kq_wr_data = wr_ev && (aw_addr_q == KM_MAILBOX_SEP_SEP_WRITE_DATA_REG_ADDR);
  wire kq_wr_sep = wr_ev && (aw_addr_q == KM_MAILBOX_SEP_SEP_WRITE_SEPARATOR_REG_ADDR) && wr_data[0];
  wire kq_rd_data = rd_ev && (ar_addr_q == KM_MAILBOX_SEP_SEP_READ_DATA_REG_ADDR);
  wire kq_unrec = (km_unrec_err_i === 1'b1);
  wire kq_recov = (km_recov_err_i === 1'b1);
  kq_frame_t kq_q[16];
  logic [3:0] kq_rp = '0, kq_wp = '0;
  logic [4:0] kq_cnt = '0;
  logic [8:0] kq_cn = '0;  // words of the inbound frame so far
  logic [31:0] kq_chdr = '0, kq_cp0 = '0, kq_cp1 = '0;
  logic [31:0] kq_ccrc = 32'hFFFF_FFFF;
  logic kq_carm = 1'b0;  // SEP_WRITE_SEPARATOR.set written for the next word
  logic [9:0] kq_nosep = '0;  // inbound words since the last frame end
  logic [7:0] kq_e = '0;  // seq_model: next expected command sequence
  logic [16:0] kq_raw = '0;  // image words and trailer still to come
  logic [31:0] kq_icrc = 32'hFFFF_FFFF;
  logic kq_img_bad = 1'b0;  // the trailer differs from the CRC-32C of the image
  logic kq_quiet = 1'b0;  // inbound words after an image stream are not frames
  logic kq_roff = 1'b0;  // outbound words after SRAM execution starts are not frames
  logic [8:0] kq_ri = '0;  // outbound word index in the frame (0: header)
  logic [7:0] kq_rrid = '0, kq_rseq = '0, kq_rplen = '0;
  logic [31:0] kq_rw0 = '0, kq_rw1 = '0, kq_rw2 = '0, kq_rw3 = '0;
  logic [255:0] kq_hv = '0;  // handle_table: handle valid
  logic [7:0] kq_hsize[256];  // key words
  logic [7:0] kq_hpol[256];  // stored DEST_VALID policy
  logic [5:0] kq_hslot[256];  // first slot of the run
  logic [63:0] kq_lw_q = '0, kq_lw_rise = '0;  // CTRL lock_write rises since the frame end
  logic [8:0] kq_kv_q = '0;  // {shared key, engine key_valid[7:0]}
  logic kq_kv_rise = 1'b0;  // a key_valid rose since the frame end
  // Events, one clock after the host access.
  logic kq_ev_hdr = 1'b0;
  logic [7:0] kq_ev_hrid = '0, kq_ev_hseq = '0;
  logic kq_ev_done = 1'b0;
  logic [7:0] kq_ev_rid = '0, kq_ev_seq = '0, kq_ev_plen = '0;
  logic [31:0] kq_ev_w0 = '0, kq_ev_w1 = '0, kq_ev_w2 = '0, kq_ev_w3 = '0;
  logic kq_ev_mv = 1'b0;  // the RESP_CMD pairs with kq_ev_m
  kq_frame_t kq_ev_m = '0;
  logic kq_ev_kvr = 1'b0;
  logic [9:0] kq_ev_nosep = '0;
  logic kq_ev_fend = 1'b0;  // a command frame ended
  logic kq_ev_fend_unrec = 1'b0;
  kq_frame_t kq_ev_f = '0;  // the frame that ended
  logic kq_ev_img = 1'b0;  // the image trailer arrived
  initial begin
    for (int i = 0; i < 256; i++) begin
      kq_hsize[i] = '0;
      kq_hpol[i] = '0;
      kq_hslot[i] = '0;
    end
    for (int i = 0; i < 16; i++) kq_q[i] = '0;
  end

  always @(posedge clk_i) begin
    logic [31:0] w;
    logic [8:0] n1;
    logic [63:0] lw;
    logic [8:0] kv;
    kq_frame_t f, h;
    logic push, pop, clr_q, clr_all, done, mv;
    logic [7:0] rid, rseq, rplen, rc, hx;
    logic [31:0] w0, w1, w2, w3;
    lw = kq_lock_write(km_kpv_ctrl_i);
    for (int i = 0; i < 8; i++) kv[i] = (km_key_valid_i[i] === 1'b1);
    kv[8] = (km_sk_valid_i === 1'b1);
    push = 1'b0;
    pop = 1'b0;
    clr_q = 1'b0;
    clr_all = 1'b0;
    done = 1'b0;
    mv = 1'b0;
    h = '0;
    rid = '0;
    rseq = '0;
    rplen = '0;
    kq_lw_q <= lw;
    kq_kv_q <= kv;
    kq_lw_rise <= kq_lw_rise | (lw & ~kq_lw_q);
    if ((kv & ~kq_kv_q) != 9'h0) kq_kv_rise <= 1'b1;
    kq_ev_hdr <= 1'b0;
    kq_ev_done <= 1'b0;
    kq_ev_fend <= 1'b0;
    kq_ev_img <= 1'b0;
    if (km_sram_exec_mode_i === 1'b1) kq_roff <= 1'b1;
    if (kq_held) begin
      // A KM reset restarts both counters and drops every frame in flight
      // (firmware.adoc, Boot Sequence); the handle table is not kept.
      kq_cn <= '0;
      kq_carm <= 1'b0;
      kq_nosep <= '0;
      kq_e <= '0;
      kq_raw <= '0;
      kq_quiet <= 1'b0;
      kq_roff <= 1'b0;
      kq_ri <= '0;
      kq_rp <= '0;
      kq_wp <= '0;
      kq_cnt <= '0;
      kq_hv <= '0;
    end else begin
      // ---- inbound: command frames, or the raw image after a confirmed
      // CMD_SRAM_LOAD_EXEC (FW_WORDS words and a CRC-32C trailer) ----
      if (kq_wr_sep) kq_carm <= 1'b1;
      if (kq_wr_data) begin
        w = wr_data;
        kq_carm <= 1'b0;
        if (kq_raw != '0) begin
          kq_raw <= kq_raw - 17'd1;
          if (kq_raw == 17'd1) begin
            kq_img_bad <= (~kq_icrc != w);
            kq_ev_img <= 1'b1;
            kq_quiet <= 1'b1;
          end else kq_icrc <= kq_crc32c_upd(kq_icrc, w);
        end else if (!kq_quiet) begin
          n1 = kq_cn + 9'd1;
          if (kq_nosep != 10'h3FF) kq_nosep <= kq_nosep + 10'd1;
          if (kq_cn == 9'd0) kq_chdr <= w;
          if (kq_cn == 9'd0) kq_ccrc <= 32'hFFFF_FFFF;
          else kq_ccrc <= kq_crc32c_upd(kq_ccrc, w);
          if (kq_cn == 9'd1) kq_cp0 <= w;
          if (kq_cn == 9'd2) kq_cp1 <= w;
          if (kq_carm) begin
            // The separator word ends the frame. kq_ccrc holds the
            // remainder over words 1 to L-2.
            f = kq_classify((kq_cn == 9'd0) ? w : kq_chdr, n1, (kq_cn == 9'd0) ? 32'h0 : ~kq_ccrc, w,
                            (kq_cn == 9'd1) ? w : kq_cp0, (kq_cn == 9'd2) ? w : kq_cp1, kq_e, kq_recov);
            f.flip = (km_kpv_flip_en_i === 1'b1);
            f.flip_idx = km_kpv_flip_idx_i;
            // seq_model: the header CRC and sequence rejections keep the
            // expected number; every other frame advances it.
            if (!f.flt[0] && !f.flt[1]) kq_e <= kq_e + 8'd1;
            if (kq_cnt != 5'd16) begin
              kq_q[kq_wp] <= f;
              push = 1'b1;
            end
            kq_cn <= '0;
            kq_nosep <= '0;
            kq_lw_rise <= '0;
            kq_kv_rise <= 1'b0;
            kq_ev_fend <= 1'b1;
            kq_ev_fend_unrec <= kq_unrec;
            kq_ev_f <= f;
          end else if (kq_cn != 9'h1FF) kq_cn <= n1;
        end
      end
      // ---- outbound: rsp_decode ----
      if (kq_rd_data && !kq_roff) begin
        w = rd_data;
        if (kq_ri == 9'd0) begin
          kq_rrid <= w[15:8];
          kq_rseq <= w[7:0];
          kq_rplen <= w[23:16];
          kq_ev_hdr <= 1'b1;
          kq_ev_hrid <= w[15:8];
          kq_ev_hseq <= w[7:0];
          if (w[23:16] == 8'd0) begin
            done = 1'b1;
            rid = w[15:8];
            rseq = w[7:0];
          end else kq_ri <= 9'd1;
        end else if (kq_ri <= 9'(kq_rplen)) begin
          if (kq_ri == 9'd1) kq_rw0 <= w;
          if (kq_ri == 9'd2) kq_rw1 <= w;
          if (kq_ri == 9'd3) kq_rw2 <= w;
          if (kq_ri == 9'd4) kq_rw3 <= w;
          kq_ri <= kq_ri + 9'd1;
        end else begin
          // The PAYLOAD_CRC32 word ends the frame.
          done = 1'b1;
          rid = kq_rrid;
          rseq = kq_rseq;
          rplen = kq_rplen;
          kq_ri <= '0;
        end
      end
      if (done) begin
        w0 = (rplen >= 8'd1) ? kq_rw0 : 32'h0;
        w1 = (rplen >= 8'd2) ? kq_rw1 : 32'h0;
        w2 = (rplen >= 8'd3) ? kq_rw2 : 32'h0;
        w3 = (rplen >= 8'd4) ? kq_rw3 : 32'h0;
        rc = w2[7:0];
        if ((rid == KmRespCmd) && ((rplen == 8'd3) || (rplen == 8'd4)) && (kq_cnt != 5'd0)) begin
          h = kq_q[kq_rp];
          pop = 1'b1;
          if ((h.seq == w0[7:0]) && (h.id == w1[7:0])) mv = 1'b1;
          else clr_q = 1'b1;
        end
        // A ready message and a fault that flushes the mailbox restart both
        // counters and the message buffers (firmware.adoc, Error Recovery).
        if ((rid == KqRespReady) ||
            ((rid == KqRespRec) && (rplen != 8'd0) && (w0[7:0] inside {8'hFE, 8'hFD, 8'hFC, 8'hFB})))
          clr_all = 1'b1;
        // handle_table, from the RESP_CMD arguments of the paired frame.
        if (mv && (rc == 8'h00)) begin
          if (((h.id == KqCmdLoad) || (h.id == KmCmdGenerate)) && (rplen == 8'd4)) begin
            hx = w3[7:0];
            kq_hv[hx] <= 1'b1;
            kq_hsize[hx] <= {1'b0, w3[14:8]} + 8'd1;
            kq_hpol[hx] <= w3[23:16];
            kq_hslot[hx] <= kq_lowest(kq_lw_rise);
          end
          if (h.id == KqCmdRevoke) kq_hv[h.p0[7:0]] <= 1'b0;
          if (h.id == KmCmdSramLoadExec) begin
            kq_raw <= 17'(h.p0[15:0]) + 17'd1;
            kq_icrc <= 32'hFFFF_FFFF;
          end
        end
        kq_ev_done <= 1'b1;
        kq_ev_rid <= rid;
        kq_ev_seq <= rseq;
        kq_ev_plen <= rplen;
        kq_ev_w0 <= w0;
        kq_ev_w1 <= w1;
        kq_ev_w2 <= w2;
        kq_ev_w3 <= w3;
        kq_ev_mv <= mv;
        kq_ev_m <= h;
        kq_ev_kvr <= kq_kv_rise;
        kq_ev_nosep <= kq_nosep;
      end
      if (push) kq_wp <= kq_wp + 4'd1;
      if (clr_all) begin
        kq_rp <= kq_wp;
        kq_cnt <= '0;
        kq_cn <= '0;
        kq_carm <= 1'b0;
        kq_nosep <= '0;
        kq_e <= '0;
      end else if (clr_q) begin
        kq_rp <= kq_wp;
        kq_cnt <= '0;
      end else begin
        if (pop) kq_rp <= kq_rp + 4'd1;
        kq_cnt <= kq_cnt + 5'(push) - 5'(pop);
      end
    end
  end

  // --- covergroups of the 7.22 to 7.28 points ----------------------------
  covergroup sep_km_frame_validation_cg with function sample (logic [4:0] pt, logic [15:0] v);
    option.per_instance = 1;
    option.name = "sep_km_frame_validation_cg";
    // The first failing check of a frame whose RESP_CMD carries the code of
    // that check: 0 header CRC, 1 sequence, 2 command ID, 3 length, 4 payload
    // CRC, 5 the gate with RECOVERABLE_ERR set, 6 the handler.
    cp_fv_first_fail: coverpoint v[2:0] iff (pt == 5'd0) {
      bins header_crc = {3'd0};
      bins sequence_number = {3'd1};
      bins command_id = {3'd2};
      bins length = {3'd3};
      bins payload_crc = {3'd4};
      bins admission_gate = {3'd5};
      bins handler_reached = {3'd6};
    }
    // The 13 ordered fault pairs of kq_pair(), with the code of the earlier
    // check.
    cp_fv_pair_order: coverpoint v[3:0] iff (pt == 5'd1) {
      bins hdr_seq = {4'd0};
      bins hdr_id = {4'd1};
      bins hdr_len = {4'd2};
      bins hdr_pcrc = {4'd3};
      bins seq_id = {4'd4};
      bins seq_len = {4'd5};
      bins seq_pcrc = {4'd6};
      bins id_len = {4'd7};
      bins id_pcrc = {4'd8};
      bins len_pcrc = {4'd9};
      bins hdr_dispatch_len = {4'd10};
      bins seq_dispatch_len = {4'd11};
      bins pcrc_dispatch_len = {4'd12};
    }
    // 0 equal, 3 the frame with sequence 0 after the frame with 0xFF, 4 a
    // mismatch other than plus or minus one, refused with -3. The plus-one
    // and minus-one cells are blocked (docs/SEP_FCOV.adoc).
    cp_fv_seq: coverpoint v[2:0] iff (pt == 5'd2) {
      bins equal = {3'd0}; bins rollover_ff_to_00 = {3'd3}; bins other_mismatch = {3'd4};
    }
    cp_km_seq_wrap: coverpoint v[0] iff (pt == 5'd3) {
      bins command_counter_255_to_0 = {1'b0}; bins response_counter_255_to_0 = {1'b1};
    }
    // {cause (0 SEP flush, 1 receive overflow, 2 warm reset), 0 first
    // response sequence 0 / 1 first accepted command sequence 0}.
    cp_fv_counter_reset: coverpoint v[2:0] iff (pt == 5'd4) {
      bins flush_first_resp_seq0 = {3'b00_0};
      bins flush_first_cmd_seq0 = {3'b00_1};
      bins oflow_first_resp_seq0 = {3'b01_0};
      bins oflow_first_cmd_seq0 = {3'b01_1};
      bins warm_first_resp_seq0 = {3'b10_0};
      bins warm_first_cmd_seq0 = {3'b10_1};
    }
    cp_fv_arg_kind: coverpoint v[1:0] iff (pt == 5'd5) {
      bins len_arg_is_received_length = {2'd0};
      bins seq_arg_is_expected = {2'd1};
      bins hdr_crc_arg_differs = {2'd2};
      bins pcrc_arg_differs = {2'd3};
    }
    // The accepted 257-word frame is blocked (docs/SEP_FCOV.adoc).
    cp_fv_rx_buffer: coverpoint v[0] iff (pt == 5'd6) {
      bins no_separator_257_overflow = {1'b1};
    }
    // The first failing check of a rejected frame whose RESP_CMD carries that
    // code, when the next paired frame is accepted at the predicted sequence:
    // the expected sequence kept (header CRC, sequence) or advanced by one
    // (command ID, length, payload CRC, the gate).
    cp_fv_seq_after_reject: coverpoint v[2:0] iff (pt == 5'd7) {
      bins hdr_crc_kept = {3'd0};
      bins noseq_kept = {3'd1};
      bins invalid_cmd_advanced = {3'd2};
      bins len_advanced = {3'd3};
      bins pcrc_advanced = {3'd4};
      bins gate_advanced = {3'd5};
    }
  endgroup

  covergroup sep_km_cmd_reject_cg with function sample (logic [4:0] pt, logic [15:0] v);
    option.per_instance = 1;
    option.name = "sep_km_cmd_reject_cg";
    // {class (0 admitted, 1 gated), RECOVERABLE_ERR}.
    cp_gate: coverpoint v[1:0] iff (pt == 5'd0) {
      bins admitted_gate0 = {2'b0_0};
      bins admitted_gate1 = {2'b0_1};
      bins gated_gate0 = {2'b1_0};
      bins gated_gate1 = {2'b1_1};
    }
    cp_gate_cmd: coverpoint v[7:0] iff (pt == 5'd1) {
      bins exec_rom = {8'h10};
      bins sram_load_exec = {8'h11};
      bins sram_exec = {8'h12};
      bins key_generate = {8'h22};
      bins key_revoke = {8'h23};
      bins key_transfer = {8'h24};
      bins engine_shred = {8'h25};
      bins key_load = {8'h26};
      bins otp_read_lock_cold = {8'h28};
    }
    cp_transfer_policy: coverpoint v[0] iff (pt == 5'd2) {
      bins subset_allowed = {1'b0}; bins mixed_refused_no_key_valid = {1'b1};
    }
    // HK-KPV word class against the slot run: 0 first used, 1 interior, 2
    // last used, 3 residue after the key end.
    cp_transfer_integrity: coverpoint v[1:0] iff (pt == 5'd3) {
      bins first_used = {2'd0};
      bins interior = {2'd1};
      bins last_used = {2'd2};
      bins residue_success = {2'd3};
    }
    cp_image_bounds: coverpoint v[1:0] iff (pt == 5'd4) {
      bins zero_rejected = {2'd0}; bins at_or_above_8192_rejected = {2'd1}; bins accepted = {2'd2};
    }
    // 0: a successful CMD_KEY_TRANSFER of two or more banks writes each bank on
    // its key path after every lower DEST_VALID bank; 1: the same with all
    // eight banks; 2: after a key-path write to an isolated bank of the
    // transfer, no higher bank of the mask takes a write before PIC vector bit
    // 30 rises.
    cp_transfer_order: coverpoint v[1:0] iff (pt == 5'd5) {
      bins multi_bank_in_bit_order = {2'd0};
      bins all_eight_in_order = {2'd1};
      bins stop_after_first_fail = {2'd2};
    }
  endgroup

  covergroup sep_km_command_cg with function sample (logic [4:0] pt, logic [15:0] v);
    option.per_instance = 1;
    option.name = "sep_km_command_cg";
    // {command index (kq_id_idx), non-success}. Blocked: (CMD_ROM_VER,
    // non-success), (CMD_RECOV_ACK, non-success) and (CMD_ABR_SK_TRANSFER,
    // success) (docs/SEP_FCOV.adoc).
    cp_cmd_x_outcome: coverpoint v[4:0] iff (pt == 5'd0) {
      bins hw_ver[] = {5'b0000_0, 5'b0000_1};
      bins rom_ver_success = {5'b0001_0};
      bins sram_ver_nonsuccess = {5'b0010_1};
      bins stat[] = {5'b0011_0, 5'b0011_1};
      bins recov_ack_success = {5'b0100_0};
      bins exec_rom[] = {5'b0101_0, 5'b0101_1};
      bins sram_load_exec[] = {5'b0110_0, 5'b0110_1};
      bins sram_exec[] = {5'b0111_0, 5'b0111_1};
      bins key_generate[] = {5'b1000_0, 5'b1000_1};
      bins key_revoke[] = {5'b1001_0, 5'b1001_1};
      bins key_transfer[] = {5'b1010_0, 5'b1010_1};
      bins engine_shred[] = {5'b1011_0, 5'b1011_1};
      bins key_load[] = {5'b1100_0, 5'b1100_1};
      bins abr_sk_transfer_nonsuccess = {5'b1101_1};
      bins otp_read_lock_cold[] = {5'b1110_0, 5'b1110_1};
      ignore_bins sram_ver_success = {5'b0010_0};
    }
    cp_ret_code: coverpoint v[7:0] iff (pt == 5'd1) {
      bins success = {8'h00};
      bins failure = {8'hFF};
      bins header_crc = {8'hFE};
      bins cmd_noseq = {8'hFD};
      bins invalid_cmd = {8'hFC};
      bins invalid_len = {8'hFB};
      bins payload_crc = {8'hFA};
      bins invalid_arg = {8'hF9};
    }
    // The 0x56 frame is blocked (docs/SEP_FCOV.adoc).
    cp_resp_shape: coverpoint v[2:0] iff (pt == 5'd2) {
      bins resp_cmd_3 = {3'd0};
      bins resp_cmd_4 = {3'd1};
      bins recoverable_fault_1 = {3'd2};
      bins unrecoverable_fault_1 = {3'd3};
      bins km_ready_0 = {3'd4};
    }
    cp_stat_recov: coverpoint v[0] iff (pt == 5'd3) {
      bins recov_fault0 = {1'b0}; bins recov_fault1 = {1'b1};
    }
  endgroup

  covergroup sep_km_handover_cg with function sample (logic [4:0] pt, logic [15:0] v);
    option.per_instance = 1;
    option.name = "sep_km_handover_cg";
    cp_ho_entry_path: coverpoint v[0] iff (pt == 5'd0) {
      bins sram_load_exec = {1'b0}; bins sram_exec = {1'b1};
    }
    // The refusal after an interrupted load is blocked (docs/SEP_FCOV.adoc).
    cp_ho_fwsize: coverpoint v[0] iff (pt == 5'd1) {
      bins refused_after_cold_boot = {1'b0};
    }
    // The confirmation before the stream is blocked (docs/SEP_FCOV.adoc).
    cp_ho_image_state: coverpoint v[1:0] iff (pt == 5'd2) {
      bins no_second_resp_cmd = {2'd1}; bins trailer_mismatch_fault = {2'd2};
    }
    cp_ho_state_at_jump: coverpoint v[1:0] iff (pt == 5'd3) {
      bins kmcsr_irq_enable0 = {2'd0};
      bins km_irq_enable0 = {2'd1};
      bins entry_addr_0x10 = {2'd2};
      bins entry_lock0 = {2'd3};
    }
    // The confirmation cells are blocked (docs/SEP_FCOV.adoc).
    cp_ho_mailbox_flush: coverpoint v[1:0] iff (pt == 5'd4) {
      bins both_fifos_empty = {2'd0}; bins inbound_residue_erased = {2'd1};
    }
    // CMD_EXEC_ROM inhibit: 0 the first CMD_EXEC_ROM of a reset epoch
    // succeeds; 1 a later CMD_EXEC_ROM, CMD_SRAM_LOAD_EXEC or CMD_SRAM_EXEC of
    // that epoch returns failure; 2 after a warm reset of an inhibited epoch
    // CMD_EXEC_ROM succeeds.
    cp_ho_inhibit: coverpoint v[1:0] iff (pt == 5'd5) {
      bins first_exec_rom_success = {2'd0};
      bins later_handover_cmd_failure = {2'd1};
      bins cleared_by_warm_reset = {2'd2};
    }
    // Between the handover command and the jump every SRAM word outside the
    // write-locked regions takes a write.
    cp_ho_scramble: coverpoint v[0] iff (pt == 5'd6) {
      bins every_unlocked_word_written = {1'b1};
    }
  endgroup

  sep_km_frame_validation_cg u_sep_km_frame_validation_cg = new();
  sep_km_cmd_reject_cg       u_sep_km_cmd_reject_cg       = new();
  sep_km_command_cg          u_sep_km_command_cg          = new();
  sep_km_handover_cg         u_sep_km_handover_cg         = new();

  // --- sampler state --------------------------------------------------
  logic kq_prev_ff = 1'b0;  // the last frame that passed the sequence check had 0xFF
  logic [7:0] kq_prev_hseq = '0;  // the last RESP_CMD header sequence
  logic kq_prev_hv = 1'b0;
  logic kq_boot_cold = 1'b1;  // the KM reset in progress or last released is a cold reset
  logic kq_rel_first = 1'b0;  // no outbound header read since the KM release
  logic [7:0] kq_scr_wr = '0;  // SCRAMBLER_KEY writes since the KM release
  logic kq_cr_arm = 1'b0;  // a counter-reset cause waits for its first accepted command
  logic [1:0] kq_cr_c = '0;
  logic kq_fe_pend = 1'b0;  // the last frame was a recoverable fault
  logic [7:0] kq_fe_code = '0;
  logic kq_rh_on = 1'b0, kq_rh_c = 1'b0, kq_rh_s2 = 1'b0, kq_rh_ack = 1'b0, kq_rh_s3 = 1'b0;
  logic kq_rec_q = 1'b0, kq_rec_pre = 1'b0;
  logic [1:0] kq_rec_cnt = '0;
  logic kq_loaded = 1'b0;  // a CMD_SRAM_LOAD_EXEC confirmed since the last cold release
  logic kq_ho_arm = 1'b0;  // a handover command frame waits for its response
  logic kq_ho_pend = 1'b0, kq_ho_path = 1'b0, kq_ho_rcmd = 1'b0, kq_ho_fl = 1'b0;
  logic kq_ho_res = 1'b0, kq_ho_sk0 = 1'b0, kq_ho_ff = 1'b0;
  logic [7:0] kq_ho_kv0 = '0;
  logic [7:0] kq_ho_aw[8];  // key-path writes per bank since the handover command
  logic [7:0] kq_ho_ctl1 = '0;  // the first of them was the KEY_CTRL write
  logic [1:0] kq_mbx_fl_q = '0;
  logic kq_par_q = 1'b0;
  logic [6:0] kq_par_win = '0;
  logic kq_par_mem = 1'b0;
  logic [1:0] kq_par_lane = '0;
  logic [3:0] kq_par_rstrb = '0;
  logic [1:0] kq_par_st_q = '0;
  logic [31:0] kq_lat_done_q = '0;
  logic [7:0] kq_lat_prev = '0;
  // Sub-window of cp_km_sram_latency: sep_km_fault_inject_rand_test writes 1
  // through the u_sep_fcov handle while its latency watcher grades the fixed
  // and the random runs, and 0 before the watcher stops. It gates a sample;
  // it is never a bin value and drives nothing.
  int unsigned km_lat_graded = 0;
  logic [10:0] kq_sil = '0;  // clocks of silence after a frame sent while bit 30 is high
  logic kq_unrec_q = 1'b0;
  logic [11:0] kq_st_q = '0;
  // Fatal episode: a wipe edge or a fatal IRQ_STATUS rise, to the bit 30
  // rise.
  logic kq_ep_on = 1'b0, kq_ep_wipe = 1'b0, kq_ep_kvclr = 1'b0, kq_ep_fl = 1'b0;
  logic kq_ep_rep = 1'b0, kq_ep_kv_rep = 1'b0, kq_ep_fl_rep = 1'b0;
  logic [8:0] kq_ep_kv0 = '0;
  logic [15:0] kq_ep_sr_pre = '0, kq_ep_sr = '0;
  initial for (int i = 0; i < 8; i++) kq_ho_aw[i] = '0;

  // Key-path AW handshakes by bank of DEST_VALID order: {the write is to
  // KEY_CTRL of the bank, a write}. KEY_CTRL follows the two shares (8
  // words each, 12 for OTBN) in every bank window.
  function automatic logic [15:0] kq_bank_aw(logic [4:0] v, logic [4:0] r, logic [159:0] a);
    logic [15:0] m;
    logic [3:0] b;
    m = '0;
    for (int p = 0; p < 5; p++) begin
      if ((v[p] === 1'b1) && (r[p] === 1'b1)) begin
        b = kq_key_bank(p, a[32*p+:32]);
        if (b != 4'hF) begin
          m[b[2:0]] = 1'b1;
          m[8+b[2:0]] = (a[32*p+:8] == ((b == 4'd3) ? 8'h60 : 8'h40));
        end
      end
    end
    return m;
  endfunction

  always @(posedge clk_i) begin
    logic [7:0] rc, id, msk, pol, sz, wid;
    logic [31:0] arg;
    logic has_arg, valid, rcmd, jump, lat_new, gw, ofd;
    logic [2:0] ff, cls;
    logic [3:0] pr, r, rb;
    logic [11:0] st, hi_m, lo_m, ranked;
    logic [8:0] kv;
    logic [7:0] aw, awc;
    logic [9:0] off;
    kq_frame_t m;
    for (int i = 0; i < 12; i++) st[i] = (km_irq_status_i[i] === 1'b1);
    for (int i = 0; i < 8; i++) kv[i] = (km_key_valid_i[i] === 1'b1);
    kv[8] = (km_sk_valid_i === 1'b1);
    ranked = 12'hEFF;  // every IRQ_STATUS source but otp_change
    {awc, aw} = kq_bank_aw(km_key_aw_valid_i, km_key_aw_ready_i, km_key_aw_addr_i);
    kq_unrec_q <= kq_unrec;
    kq_st_q <= st;
    kq_rec_q <= kq_recov;
    kq_mbx_fl_q <= km_mbx_flush_i;
    jump = 1'b0;
    ofd = (km_outfifo_depth_i != 9'd0) && !$isunknown(km_outfifo_depth_i);

    // ---- KM reset and release bookkeeping ----
    if (!km_rst_cold_n) begin
      kq_boot_cold <= 1'b1;
      kq_loaded <= 1'b0;
    end else if (!km_rst_warm_n) kq_boot_cold <= 1'b0;
    if (km_warm_fall) kq_rec_pre <= kq_rec_q;
    if (kq_held) begin
      kq_rel_first <= 1'b1;
      kq_scr_wr <= '0;
      kq_prev_ff <= 1'b0;
      kq_prev_hv <= 1'b0;
      kq_cr_arm <= 1'b0;
      kq_fe_pend <= 1'b0;
      kq_rh_on <= 1'b0;
      kq_ho_arm <= 1'b0;
      kq_ho_pend <= 1'b0;
      kq_ep_on <= 1'b0;
      kq_sil <= '0;
    end
    if (kw_ev && (kw_addr == KmCsrScrKey) && (kq_scr_wr != 8'hFF)) kq_scr_wr <= kq_scr_wr + 8'd1;

    // ---- outbound headers (cp_mem_boot_order, cp_mem_boot_type,
    // cp_km_seq_wrap) ----
    if (kq_ev_hdr) begin
      kq_rel_first <= 1'b0;
      if ((kq_ev_hrid == KqRespReady) && kq_rel_first && km_own_br) begin
        if (kq_boot_cold && (km_cold_boot_done_i === 1'b1))
          u_sep_km_memory_boot_cg.sample(5'd6, 16'd0);
        if (kq_ev_hseq == 8'd0) u_sep_km_memory_boot_cg.sample(5'd6, 16'd1);
        if (kq_boot_cold && (kq_scr_wr != 8'd0)) u_sep_km_memory_boot_cg.sample(5'd7, 16'd0);
        if (!kq_boot_cold && (kq_scr_wr == 8'd0)) u_sep_km_memory_boot_cg.sample(5'd7, 16'd1);
      end
      if (kq_ev_hrid == KmRespCmd) begin
        if (km_own_cp && kq_prev_hv && (kq_prev_hseq == 8'hFF) && (kq_ev_hseq == 8'h00))
          u_sep_km_frame_validation_cg.sample(5'd3, 16'd1);
        kq_prev_hseq <= kq_ev_hseq;
        kq_prev_hv <= 1'b1;
      end else kq_prev_hv <= 1'b0;
    end

    // ---- complete outbound frames ----
    if (kq_ev_done) begin
      rc = kq_ev_w2[7:0];
      arg = kq_ev_w3;
      has_arg = (kq_ev_plen == 8'd4);
      rcmd = (kq_ev_rid == KmRespCmd) && ((kq_ev_plen == 8'd3) || (kq_ev_plen == 8'd4));
      m = kq_ev_m;
      valid = (m.flt[4:0] == 5'h0);
      // A gated command that the gate shows: CMD_ABR_SK_TRANSFER with no key
      // pending fails in both gate states.
      gw = kq_id_gated(m.id) && (m.id != 8'h27);
      id = kq_ev_w1[7:0];
      // Response shape (cp_resp_shape).
